(function(){if(!window.__hermes_register_book)return;window.__hermes_register_book("thucydides-1-e", [{"sp": "HDR", "t": "Ἱστορίαι (Αʹ–Βʹ)"}, {"sp": "HDR", "t": "Βιβλίον Αʹ", "st": "1"}, {"sp": "N", "t": "Θουκυδίδης Ἀθηναῖος ξυνέγραψε τὸν πόλεμον τῶν Πελοποννησίων καὶ Ἀθηναίων, ὡς ἐπολέμησαν πρὸς ἀλλήλους, ἀρξάμενος εὐθὺς καθισταμένου καὶ ἐλπίσας μέγαν τε ἔσεσθαι καὶ ἀξιολογώτατον τῶν προγεγενημένων, τεκμαιρόμενος ὅτι ἀκμάζοντές τε ᾖσαν ἐς αὐτὸν ἀμφότεροι παρασκευῇ τῇ πάσῃ καὶ τὸ ἄλλο Ἑλληνικὸν ὁρῶν ξυνιστάμενον πρὸς ἑκατέρους, τὸ μὲν εὐθύς, τὸ δὲ καὶ διανοούμενον. κίνησις γὰρ αὕτη μεγίστη δὴ τοῖς Ἕλλησιν ἐγένετο καὶ μέρει τινὶ τῶν βαρβάρων, ὡς δὲ εἰπεῖν καὶ ἐπὶ πλεῖστον ἀνθρώπων. τὰ γὰρ πρὸ αὐτῶν καὶ τὰ ἔτι παλαίτερα σαφῶς μὲν εὑρεῖν διὰ χρόνου πλῆθος ἀδύνατα ἦν, ἐκ δὲ τεκμηρίων ὧν ἐπὶ μακρότατον σκοποῦντί μοι πιστεῦσαι ξυμβαίνει οὐ μεγάλα νομίζω γενέσθαι οὔτε κατὰ τοὺς πολέμους οὔτε ἐς τὰ ἄλλα.", "st": "1.1"}, {"sp": "N", "t": "φαίνεται γὰρ ἡ νῦν Ἑλλὰς καλουμένη οὐ πάλαι βεβαίως οἰκουμένη, ἀλλὰ μεταναστάσεις τε οὖσαι τὰ πρότερα καὶ ῥᾳδίως ἕκαστοι τὴν ἑαυτῶν ἀπολείποντες βιαζόμενοι ὑπό τινων αἰεὶ πλειόνων. τῆς γὰρ ἐμπορίας οὐκ οὔσης, οὐδ’ ἐπιμειγνύντες ἀδεῶς ἀλλήλοις οὔτε κατὰ γῆν οὔτε διὰ θαλάσσης, νεμόμενοί τε τὰ αὑτῶν ἕκαστοι ὅσον ἀποζῆν καὶ περιουσίαν χρημάτων οὐκ ἔχοντες οὐδὲ γῆν φυτεύοντες, ἄδηλον ὂν ὁπότε τις ἐπελθὼν καὶ ἀτειχίστων ἅμα ὄντων ἄλλος ἀφαιρήσεται, τῆς τε καθ’ ἡμέραν ἀναγκαίου τροφῆς πανταχοῦ ἂν ἡγούμενοι ἐπικρατεῖν, οὐ χαλεπῶς ἀπανίσταντο, καὶ δι’ αὐτὸ οὔτε μεγέθει πόλεων ἴσχυον οὔτε τῇ ἄλλῃ παρασκευῇ. μάλιστα δὲ τῆς γῆς ἡ ἀρίστη αἰεὶ τὰς μεταβολὰς τῶν οἰκητόρων εἶχεν, ἥ τε νῦν Θεσσαλία καλουμένη καὶ Βοιωτία Πελοποννήσου τε τὰ πολλὰ πλὴν Ἀρκαδίας, τῆς τε ἄλλης ὅσα ἦν κράτιστα. διὰ γὰρ ἀρετὴν γῆς αἵ τε δυνάμεις τισὶ μείζους ἐγγιγνόμεναι στάσεις ἐνεποίουν ἐξ ὧν ἐφθείροντο, καὶ ἅμα ὑπὸ ἀλλοφύλων μᾶλλον ἐπεβουλεύοντο. τὴν γοῦν Ἀττικὴν ἐκ τοῦ ἐπὶ πλεῖστον διὰ τὸ λεπτόγεων ἀστασίαστον οὖσαν ἄνθρωποι ᾤκουν οἱ αὐτοὶ αἰεί. καὶ παράδειγμα τόδε τοῦ λόγου οὐκ ἐλάχιστόν ἐστι διὰ τὰς μετοικίας ἐς τὰ ἄλλα μὴ ὁμοίως αὐξηθῆναι· ἐκ γὰρ τῆς ἄλλης Ἑλλάδος οἱ πολέμῳ ἢ στάσει ἐκπίπτοντες παρ’ Ἀθηναίους οἱ δυνατώτατοι ὡς βέβαιον ὂν ἀνεχώρουν, καὶ πολῖται γιγνόμενοι εὐθὺς ἀπὸ παλαιοῦ μείζω ἔτι ἐποίησαν πλήθει ἀνθρώπων τὴν πόλιν, ὥστε καὶ ἐς Ἰωνίαν ὕστερον ὡς οὐχ ἱκανῆς οὔσης τῆς Ἀττικῆς ἀποικίας ἐξέπεμψαν.", "st": "1.2"}, {"sp": "N", "t": "δηλοῖ δέ μοι καὶ τόδε τῶν παλαιῶν ἀσθένειαν οὐχ ἥκιστα· πρὸ γὰρ τῶν Τρωικῶν οὐδὲν φαίνεται πρότερον κοινῇ ἐργασαμένη ἡ Ἑλλάς· δοκεῖ δέ μοι, οὐδὲ τοὔνομα τοῦτο ξύμπασά πω εἶχεν, ἀλλὰ τὰ μὲν πρὸ Ἕλληνος τοῦ Δευκαλίωνος καὶ πάνυ οὐδὲ εἶναι ἡ ἐπίκλησις αὕτη, κατὰ ἔθνη δὲ ἄλλα τε καὶ τὸ Πελασγικὸν ἐπὶ πλεῖστον ἀφ’ ἑαυτῶν τὴν ἐπωνυμίαν παρέχεσθαι, Ἕλληνος δὲ καὶ τῶν παίδων αὐτοῦ ἐν τῇ Φθιώτιδι ἰσχυσάντων, καὶ ἐπαγομένων αὐτοὺς ἐπ’ ὠφελίᾳ ἐς τὰς ἄλλας πόλεις, καθ’ ἑκάστους μὲν ἤδη τῇ ὁμιλίᾳ μᾶλλον καλεῖσθαι Ἕλληνας, οὐ μέντοι πολλοῦ γε χρόνου [ἐδύνατο] καὶ ἅπασιν ἐκνικῆσαι. τεκμηριοῖ δὲ μάλιστα Ὅμηρος· πολλῷ γὰρ ὕστερον ἔτι καὶ τῶν Τρωικῶν γενόμενος οὐδαμοῦ τοὺς ξύμπαντας ὠνόμασεν, οὐδ’ ἄλλους ἢ τοὺς μετ’ Ἀχιλλέως ἐκ τῆς Φθιώτιδος, οἵπερ καὶ πρῶτοι Ἕλληνες ἦσαν, Δαναοὺς δὲ ἐν τοῖς ἔπεσι καὶ Ἀργείους καὶ Ἀχαιοὺς ἀνακαλεῖ. οὐ μὴν οὐδὲ βαρβάρους εἴρηκε διὰ τὸ μηδὲ Ἕλληνάς πω, ὡς ἐμοὶ δοκεῖ, ἀντίπαλον ἐς ἓν ὄνομα ἀποκεκρίσθαι. οἱ δ’ οὖν ὡς ἕκαστοι Ἕλληνες κατὰ πόλεις τε ὅσοι ἀλλήλων ξυνίεσαν καὶ ξύμπαντες ὕστερον κληθέντες οὐδὲν πρὸ τῶν Τρωικῶν δι’ ἀσθένειαν καὶ ἀμειξίαν ἀλλήλων ἁθρόοι ἔπραξαν. ἀλλὰ καὶ ταύτην τὴν στρατείαν θαλάσσῃ ἤδη πλείω χρώμενοι ξυνεξῆλθον.", "st": "1.3"}, {"sp": "N", "t": "Μίνως γὰρ παλαίτατος ὧν ἀκοῇ ἴσμεν ναυτικὸν ἐκτήσατο καὶ τῆς νῦν Ἑλληνικῆς θαλάσσης ἐπὶ πλεῖστον ἐκράτησε καὶ τῶν Κυκλάδων νήσων ἦρξέ τε καὶ οἰκιστὴς πρῶτος τῶν πλείστων ἐγένετο, Κᾶρας ἐξελάσας καὶ τοὺς ἑαυτοῦ παῖδας ἡγεμόνας ἐγκαταστήσας· τό τε λῃστικόν, ὡς εἰκός, καθῄρει ἐκ τῆς θαλάσσης ἐφ’ ὅσον ἐδύνατο, τοῦ τὰς προσόδους μᾶλλον ἰέναι αὐτῷ.", "st": "1.4"}, {"sp": "N", "t": "οἱ γὰρ Ἕλληνες τὸ πάλαι καὶ τῶν βαρβάρων οἵ τε ἐν τῇ ἠπείρῳ παραθαλάσσιοι καὶ ὅσοι νήσους εἶχον, ἐπειδὴ ἤρξαντο μᾶλλον περαιοῦσθαι ναυσὶν ἐπ’ ἀλλήλους, ἐτράποντο πρὸς λῃστείαν, ἡγουμένων ἀνδρῶν οὐ τῶν ἀδυνατωτάτων κέρδους τοῦ σφετέρου αὐτῶν ἕνεκα καὶ τοῖς ἀσθενέσι τροφῆς, καὶ προσπίπτοντες πόλεσιν ἀτειχίστοις καὶ κατὰ κώμας οἰκουμέναις ἥρπαζον καὶ τὸν πλεῖστον τοῦ βίου ἐντεῦθεν ἐποιοῦντο, οὐκ ἔχοντός πω αἰσχύνην τούτου τοῦ ἔργου, φέροντος δέ τι καὶ δόξης μᾶλλον· δηλοῦσι δὲ τῶν τε ἠπειρωτῶν τινὲς ἔτι καὶ νῦν, οἷς κόσμος καλῶς τοῦτο δρᾶν, καὶ οἱ παλαιοὶ τῶν ποιητῶν τὰς πύστεις τῶν καταπλεόντων πανταχοῦ ὁμοίως ἐρωτῶντες εἰ λῃσταί εἰσιν, ὡς οὔτε ὧν πυνθάνονται ἀπαξιούντων τὸ ἔργον, οἷς τε ἐπιμελὲς εἴη εἰδέναι οὐκ ὀνειδιζόντων. ἐλῄζοντο δὲ καὶ κατ’ ἤπειρον ἀλλήλους. καὶ μέχρι τοῦδε πολλὰ τῆς Ἑλλάδος τῷ παλαιῷ τρόπῳ νέμεται περί τε Λοκροὺς τοὺς Ὀζόλας καὶ Αἰτωλοὺς καὶ Ἀκαρνᾶνας καὶ τὴν ταύτῃ ἤπειρον. τό τε σιδηροφορεῖσθαι τούτοις τοῖς ἠπειρώταις ἀπὸ τῆς παλαιᾶς λῃστείας ἐμμεμένηκεν·", "st": "1.5"}, {"sp": "N", "t": "πᾶσα γὰρ ἡ Ἑλλὰς ἐσιδηροφόρει διὰ τὰς ἀφάρκτους τε οἰκήσεις καὶ οὐκ ἀσφαλεῖς παρ’ ἀλλήλους ἐφόδους, καὶ ξυνήθη τὴν δίαιταν μεθ’ ὅπλων ἐποιήσαντο ὥσπερ οἱ βάρβαροι. σημεῖον δ’ ἐστὶ ταῦτα τῆς Ἑλλάδος ἔτι οὕτω νεμόμενα τῶν ποτὲ καὶ ἐς πάντας ὁμοίων διαιτημάτων.", "st": "1.6"}, {"sp": "N", "t": "ἐν τοῖς πρῶτοι δὲ Ἀθηναῖοι τόν τε σίδηρον κατέθεντο καὶ ἀνειμένῃ τῇ διαίτῃ ἐς τὸ τρυφερώτερον μετέστησαν. καὶ οἱ πρεσβύτεροι αὐτοῖς τῶν εὐδαιμόνων διὰ τὸ ἁβροδίαιτον οὐ πολὺς χρόνος ἐπειδὴ χιτῶνάς τε λινοῦς ἐπαύσαντο φοροῦντες καὶ χρυσῶν τεττίγων ἐνέρσει κρωβύλον ἀναδούμενοι τῶν ἐν τῇ κεφαλῇ τριχῶν· ἀφ’ οὗ καὶ Ἰώνων τοὺς πρεσβυτέρους κατὰ τὸ ξυγγενὲς ἐπὶ πολὺ αὕτη ἡ σκευὴ κατέσχεν. μετρίᾳ δ’ αὖ ἐσθῆτι καὶ ἐς τὸν νῦν τρόπον πρῶτοι Λακεδαιμόνιοι ἐχρήσαντο καὶ ἐς τὰ ἄλλα πρὸς τοὺς πολλοὺς οἱ τὰ μείζω κεκτημένοι ἰσοδίαιτοι μάλιστα κατέστησαν. ἐγυμνώθησάν τε πρῶτοι καὶ ἐς τὸ φανερὸν ἀποδύντες λίπα μετὰ τοῦ γυμνάζεσθαι ἠλείψαντο· τὸ δὲ πάλαι καὶ ἐν τῷ Ὀλυμπικῷ ἀγῶνι διαζώματα ἔχοντες περὶ τὰ αἰδοῖα οἱ ἀθληταὶ ἠγωνίζοντο, καὶ οὐ πολλὰ ἔτη ἐπειδὴ πέπαυται. ἔτι δὲ καὶ ἐν τοῖς βαρβάροις ἔστιν οἷς νῦν, καὶ μάλιστα τοῖς Ἀσιανοῖς, πυγμῆς καὶ πάλης ἆθλα τίθεται, καὶ διεζωμένοι τοῦτο δρῶσιν. πολλὰ δ’ ἂν καὶ ἄλλα τις ἀποδείξειε τὸ παλαιὸν Ἑλληνικὸν ὁμοιότροπα τῷ νῦν βαρβαρικῷ διαιτώμενον.", "st": "1.6"}, {"sp": "N", "t": "τῶν δὲ πόλεων ὅσαι μὲν νεώτατα ᾠκίσθησαν καὶ ἤδη πλωιμωτέρων ὄντων, περιουσίας μᾶλλον ἔχουσαι χρημάτων ἐπ’ αὐτοῖς τοῖς αἰγιαλοῖς τείχεσιν ἐκτίζοντο καὶ τοὺς ἰσθμοὺς ἀπελάμβανον ἐμπορίας τε ἕνεκα καὶ τῆς πρὸς τοὺς προσοίκους ἕκαστοι ἰσχύος· αἱ δὲ παλαιαὶ διὰ τὴν λῃστείαν ἐπὶ πολὺ ἀντίσχουσαν ἀπὸ θαλάσσης μᾶλλον ᾠκίσθησαν, αἵ τε ἐν ταῖς νήσοις καὶ ἐν ταῖς ἠπείροις (ἔφερον γὰρ ἀλλήλους τε καὶ τῶν ἄλλων ὅσοι ὄντες οὐ θαλάσσιοι κάτω ᾤκουν), καὶ μέχρι τοῦδε ἔτι ἀνῳκισμένοι εἰσίν.", "st": "1.7"}, {"sp": "N", "t": "καὶ οὐχ ἧσσον λῃσταὶ ἦσαν οἱ νησιῶται, Κᾶρές τε ὄντες καὶ Φοίνικες· οὗτοι γὰρ δὴ τὰς πλείστας τῶν νήσων ᾤκησαν. μαρτύριον δέ· Δήλου γὰρ καθαιρομένης ὑπὸ Ἀθηναίων ἐν τῷδε τῷ πολέμῳ καὶ τῶν θηκῶν ἀναιρεθεισῶν ὅσαι ἦσαν τῶν τεθνεώτων ἐν τῇ νήσῳ, ὑπὲρ ἥμισυ Κᾶρες ἐφάνησαν, γνωσθέντες τῇ τε σκευῇ τῶν ὅπλων ξυντεθαμμένῃ καὶ τῷ τρόπῳ ᾧ νῦν ἔτι θάπτουσιν. καταστάντος δὲ τοῦ Μίνω ναυτικοῦ πλωιμώτερα ἐγένετο παρ’ ἀλλήλους (οἱ γὰρ ἐκ τῶν νήσων κακοῦργοι ἀνέστησαν ὑπ’ αὐτοῦ, ὅτεπερ καὶ τὰς πολλὰς αὐτῶν κατῴκιζε), καὶ οἱ παρὰ θάλασσαν ἄνθρωποι μᾶλλον ἤδη τὴν κτῆσιν τῶν χρημάτων ποιούμενοι βεβαιότερον ᾤκουν, καί τινες καὶ τείχη περιεβάλλοντο ὡς πλουσιώτεροι ἑαυτῶν γιγνόμενοι· ἐφιέμενοι γὰρ τῶν κερδῶν οἵ τε ἥσσους ὑπέμενον τὴν τῶν κρεισσόνων δουλείαν, οἵ τε δυνατώτεροι περιουσίας ἔχοντες προσεποιοῦντο ὑπηκόους τὰς ἐλάσσους πόλεις. καὶ ἐν τούτῳ τῷ τρόπῳ μᾶλλον ἤδη ὄντες ὕστερον χρόνῳ ἐπὶ Τροίαν ἐστράτευσαν.", "st": "1.8"}, {"sp": "N", "t": "Ἀγαμέμνων τέ μοι δοκεῖ τῶν τότε δυνάμει προύχων καὶ οὐ τοσοῦτον τοῖς Τυνδάρεω ὅρκοις κατειλημμένους τοὺς Ἑλένης μνηστῆρας ἄγων τὸν στόλον ἀγεῖραι. λέγουσι δὲ καὶ οἱ τὰ σαφέστατα Πελοποννησίων μνήμῃ παρὰ τῶν πρότερον δεδεγμένοι Πέλοπά τε πρῶτον πλήθει χρημάτων, ἃ ἦλθεν ἐκ τῆς Ἀσίας ἔχων ἐς ἀνθρώπους ἀπόρους, δύναμιν περιποιησάμενον τὴν ἐπωνυμίαν τῆς χώρας ἔπηλυν ὄντα ὅμως σχεῖν, καὶ ὕστερον τοῖς ἐκγόνοις ἔτι μείζω ξυνενεχθῆναι, Εὐρυσθέως μὲν ἐν τῇ Ἀττικῇ ὑπὸ Ἡρακλειδῶν ἀποθανόντος, Ἀτρέως δὲ μητρὸς ἀδελφοῦ ὄντος αὐτῷ, καὶ ἐπιτρέψαντος Εὐρυσθέως, ὅτ’ ἐστράτευε, Μυκήνας τε καὶ τὴν ἀρχὴν κατὰ τὸ οἰκεῖον Ἀτρεῖ (τυγχάνειν δὲ αὐτὸν φεύγοντα τὸν πατέρα διὰ τὸν Χρυσίππου θάνατον), καὶ ὡς οὐκέτι ἀνεχώρησεν Εὐρυσθεύς, βουλομένων καὶ τῶν Μυκηναίων φόβῳ τῶν Ἡρακλειδῶν καὶ ἅμα δυνατὸν δοκοῦντα εἶναι καὶ τὸ πλῆθος τεθεραπευκότα τῶν Μυκηναίων τε καὶ ὅσων Εὐρυσθεὺς ἦρχε τὴν βασιλείαν Ἀτρέα παραλαβεῖν, καὶ τῶν Περσειδῶν τοὺς Πελοπίδας μείζους καταστῆναι. ἅ μοι δοκεῖ Ἀγαμέμνων παραλαβὼν καὶ ναυτικῷ [τε] ἅμα ἐπὶ πλέον τῶν ἄλλων ἰσχύσας, τὴν στρατείαν οὐ χάριτι τὸ πλέον ἢ φόβῳ ξυναγαγὼν ποιήσασθαι. φαίνεται γὰρ ναυσί τε πλείσταις αὐτὸς ἀφικόμενος καὶ Ἀρκάσι προσπαρασχών, ὡς Ὅμηρος τοῦτο δεδήλωκεν, εἴ τῳ ἱκανὸς τεκμηριῶσαι. καὶ ἐν τοῦ σκήπτρου ἅμα τῇ παραδόσει εἴρηκεν αὐτὸν<br>πολλῇσι νήσοισι καὶ Ἄργεϊ παντὶ ἀνάσσειν·<br>οὐκ ἂν οὖν νήσων ἔξω τῶν περιοικίδων (αὗται δὲ οὐκ ἂν πολλαὶ εἶεν) ἠπειρώτης ὢν ἐκράτει, εἰ μή τι καὶ ναυτικὸν εἶχεν. εἰκάζειν δὲ χρὴ καὶ ταύτῃ τῇ στρατείᾳ οἷα ἦν τὰ πρὸ αὐτῆς.", "st": "1.9"}, {"sp": "N", "t": "καὶ ὅτι μὲν Μυκῆναι μικρὸν ἦν, ἢ εἴ τι τῶν τότε πόλισμα νῦν μὴ ἀξιόχρεων δοκεῖ εἶναι, οὐκ ἀκριβεῖ ἄν τις σημείῳ χρώμενος ἀπιστοίη μὴ γενέσθαι τὸν στόλον τοσοῦτον ὅσον οἵ τε ποιηταὶ εἰρήκασι καὶ ὁ λόγος κατέχει. Λακεδαιμονίων γὰρ εἰ ἡ πόλις ἐρημωθείη, λειφθείη δὲ τά τε ἱερὰ καὶ τῆς κατασκευῆς τὰ ἐδάφη, πολλὴν ἂν οἶμαι ἀπιστίαν τῆς δυνάμεως προελθόντος πολλοῦ χρόνου τοῖς ἔπειτα πρὸς τὸ κλέος αὐτῶν εἶναι (καίτοι Πελοποννήσου τῶν πέντε τὰς δύο μοίρας νέμονται, τῆς τε ξυμπάσης ἡγοῦνται καὶ τῶν ἔξω ξυμμάχων πολλῶν· ὅμως δὲ οὔτε ξυνοικισθείσης πόλεως οὔτε ἱεροῖς καὶ κατασκευαῖς πολυτελέσι χρησαμένης, κατὰ κώμας δὲ τῷ παλαιῷ τῆς Ἑλλάδος τρόπῳ οἰκισθείσης, φαίνοιτ’ ἂν ὑποδεεστέρα), Ἀθηναίων δὲ τὸ αὐτὸ τοῦτο παθόντων διπλασίαν ἂν τὴν δύναμιν εἰκάζεσθαι ἀπὸ τῆς φανερᾶς ὄψεως τῆς πόλεως ἢ ἔστιν. οὔκουν ἀπιστεῖν εἰκός, οὐδὲ τὰς ὄψεις τῶν πόλεων μᾶλλον σκοπεῖν ἢ τὰς δυνάμεις, νομίζειν δὲ τὴν στρατείαν ἐκείνην μεγίστην μὲν γενέσθαι τῶν πρὸ αὑτῆς, λειπομένην δὲ τῶν νῦν, τῇ Ὁμήρου αὖ ποιήσει εἴ τι χρὴ κἀνταῦθα πιστεύειν, ἣν εἰκὸς ἐπὶ τὸ μεῖζον μὲν ποιητὴν ὄντα κοσμῆσαι, ὅμως δὲ φαίνεται καὶ οὕτως ἐνδεεστέρα. πεποίηκε γὰρ χιλίων καὶ διακοσίων νεῶν τὰς μὲν Βοιωτῶν εἴκοσι καὶ ἑκατὸν ἀνδρῶν, τὰς δὲ Φιλοκτήτου πεντήκοντα, δηλῶν, ὡς ἐμοὶ δοκεῖ, τὰς μεγίστας καὶ ἐλαχίστας· ἄλλων γοῦν μεγέθους πέρι ἐν νεῶν καταλόγῳ οὐκ ἐμνήσθη. αὐτερέται δὲ ὅτι ἦσαν καὶ μάχιμοι πάντες, ἐν ταῖς Φιλοκτήτου ναυσὶ δεδήλωκεν· τοξότας γὰρ πάντας πεποίηκε τοὺς προσκώπους. περίνεως δὲ οὐκ εἰκὸς πολλοὺς ξυμπλεῖν ἔξω τῶν βασιλέων καὶ τῶν μάλιστα ἐν τέλει, ἄλλως τε καὶ μέλλοντας πέλαγος περαιώσεσθαι μετὰ σκευῶν πολεμικῶν, οὐδ’ αὖ τὰ πλοῖα κατάφαρκτα ἔχοντας, ἀλλὰ τῷ παλαιῷ τρόπῳ λῃστικώτερον παρεσκευασμένα. πρὸς τὰς μεγίστας δ’ οὖν καὶ ἐλαχίστας ναῦς τὸ μέσον σκοποῦντι οὐ πολλοὶ φαίνονται ἐλθόντες, ὡς ἀπὸ πάσης τῆς Ἑλλάδος κοινῇ πεμπόμενοι.", "st": "1.10"}, {"sp": "N", "t": "αἴτιον δ’ ἦν οὐχ ἡ ὀλιγανθρωπία τοσοῦτον ὅσον ἡ ἀχρηματία. τῆς γὰρ τροφῆς ἀπορίᾳ τόν τε στρατὸν ἐλάσσω ἤγαγον καὶ ὅσον ἤλπιζον αὐτόθεν πολεμοῦντα βιοτεύσειν, ἐπειδὴ δὲ ἀφικόμενοι μάχῃ ἐκράτησαν (δῆλον δέ· τὸ γὰρ ἔρυμα τῷ στρατοπέδῳ οὐκ ἂν ἐτειχίσαντο), φαίνονται δ’ οὐδ’ ἐνταῦθα πάσῃ τῇ δυνάμει χρησάμενοι, ἀλλὰ πρὸς γεωργίαν τῆς Χερσονήσου τραπόμενοι καὶ λῃστείαν τῆς τροφῆς ἀπορίᾳ. ᾗ καὶ μᾶλλον οἱ Τρῶες αὐτῶν διεσπαρμένων τὰ δέκα ἔτη ἀντεῖχον βίᾳ, τοῖς αἰεὶ ὑπολειπομένοις ἀντίπαλοι ὄντες. περιουσίαν δὲ εἰ ἦλθον ἔχοντες τροφῆς καὶ ὄντες ἁθρόοι ἄνευ λῃστείας καὶ γεωργίας ξυνεχῶς τὸν πόλεμον διέφερον, ῥᾳδίως ἂν μάχῃ κρατοῦντες εἷλον, οἵ γε καὶ οὐχ ἁθρόοι, ἀλλὰ μέρει τῷ αἰεὶ παρόντι ἀντεῖχον, πολιορκίᾳ δ’ ἂν προσκαθεζόμενοι ἐν ἐλάσσονί τε χρόνῳ καὶ ἀπονώτερον τὴν Τροίαν εἷλον. ἀλλὰ δι’ ἀχρηματίαν τά τε πρὸ τούτων ἀσθενῆ ἦν καὶ αὐτά γε δὴ ταῦτα, ὀνομαστότατα τῶν πρὶν γενόμενα, δηλοῦται τοῖς ἔργοις ὑποδεέστερα ὄντα τῆς φήμης καὶ τοῦ νῦν περὶ αὐτῶν διὰ τοὺς ποιητὰς λόγου κατεσχηκότος·", "st": "1.11"}, {"sp": "N", "t": "ἐπεὶ καὶ μετὰ τὰ Τρωικὰ ἡ Ἑλλὰς ἔτι μετανίστατό τε καὶ κατῳκίζετο, ὥστε μὴ ἡσυχάσασαν αὐξηθῆναι. ἥ τε γὰρ ἀναχώρησις τῶν Ἑλλήνων ἐξ Ἰλίου χρονία γενομένη πολλὰ ἐνεόχμωσε, καὶ στάσεις ἐν ταῖς πόλεσιν ὡς ἐπὶ πολὺ ἐγίγνοντο, ἀφ’ ὧν ἐκπίπτοντες τὰς πόλεις ἔκτιζον. Βοιωτοί τε γὰρ οἱ νῦν ἑξηκοστῷ ἔτει μετὰ Ἰλίου ἅλωσιν ἐξ Ἄρνης ἀναστάντες ὑπὸ Θεσσαλῶν τὴν νῦν μὲν Βοιωτίαν, πρότερον δὲ Καδμηίδα γῆν καλουμένην ᾤκισαν (ἦν δὲ αὐτῶν καὶ ἀποδασμὸς πρότερον ἐν τῇ γῇ ταύτῃ, ἀφ’ ὧν καὶ ἐς Ἴλιον ἐστράτευσαν), Δωριῆς τε ὀγδοηκοστῷ ἔτει ξὺν Ἡρακλείδαις Πελοπόννησον ἔσχον. μόλις τε ἐν πολλῷ χρόνῳ ἡσυχάσασα ἡ Ἑλλὰς βεβαίως καὶ οὐκέτι ἀνισταμένη ἀποικίας ἐξέπεμψε, καὶ Ἴωνας μὲν Ἀθηναῖοι καὶ νησιωτῶν τοὺς πολλοὺς ᾤκισαν, Ἰταλίας δὲ καὶ Σικελίας τὸ πλεῖστον Πελοποννήσιοι τῆς τε ἄλλης Ἑλλάδος ἔστιν ἃ χωρία. πάντα δὲ ταῦτα ὕστερον τῶν Τρωικῶν ἐκτίσθη.", "st": "1.12"}, {"sp": "N", "t": "δυνατωτέρας δὲ γιγνομένης τῆς Ἑλλάδος καὶ τῶν χρημάτων τὴν κτῆσιν ἔτι μᾶλλον ἢ πρότερον ποιουμένης τὰ πολλὰ τυραννίδες ἐν ταῖς πόλεσι καθίσταντο, τῶν προσόδων μειζόνων γιγνομένων (πρότερον δὲ ἦσαν ἐπὶ ῥητοῖς γέρασι πατρικαὶ βασιλεῖαι), ναυτικά τε ἐξηρτύετο ἡ Ἑλλάς, καὶ τῆς θαλάσσης μᾶλλον ἀντείχοντο. πρῶτοι δὲ Κορίνθιοι λέγονται ἐγγύτατα τοῦ νῦν τρόπου μεταχειρίσαι τὰ περὶ τὰς ναῦς, καὶ τριήρεις ἐν Κορίνθῳ πρῶτον τῆς Ἑλλάδος ναυπηγηθῆναι. φαίνεται δὲ καὶ Σαμίοις Ἀμεινοκλῆς Κορίνθιος ναυπηγὸς ναῦς ποιήσας τέσσαρας· ἔτη δ’ ἐστὶ μάλιστα τριακόσια ἐς τὴν τελευτὴν τοῦδε τοῦ πολέμου ὅτε Ἀμεινοκλῆς Σαμίοις ἦλθεν. ναυμαχία τε παλαιτάτη ὧν ἴσμεν γίγνεται Κορινθίων πρὸς Κερκυραίους· ἔτη δὲ μάλιστα καὶ ταύτῃ ἑξήκοντα καὶ διακόσιά ἐστι μέχρι τοῦ αὐτοῦ χρόνου. οἰκοῦντες γὰρ τὴν πόλιν οἱ Κορίνθιοι ἐπὶ τοῦ Ἰσθμοῦ αἰεὶ δή ποτε ἐμπόριον εἶχον, τῶν Ἑλλήνων τὸ πάλαι κατὰ γῆν τὰ πλείω ἢ κατὰ θάλασσαν, τῶν τε ἐντὸς Πελοποννήσου καὶ τῶν ἔξω, διὰ τῆς ἐκείνων παρ’ ἀλλήλους ἐπιμισγόντων, χρήμασί τε δυνατοὶ ἦσαν, ὡς καὶ τοῖς παλαιοῖς ποιηταῖς δεδήλωται· ἀφνειὸν γὰρ ἐπωνόμασαν τὸ χωρίον. ἐπειδή τε οἱ Ἕλληνες μᾶλλον ἔπλῳζον, τὰς ναῦς κτησάμενοι τὸ λῃστικὸν καθῄρουν, καὶ ἐμπόριον παρέχοντες ἀμφότερα δυνατὴν ἔσχον χρημάτων προσόδῳ τὴν πόλιν. καὶ Ἴωσιν ὕστερον πολὺ γίγνεται ναυτικὸν ἐπὶ Κύρου Περσῶν πρώτου βασιλεύοντος καὶ Καμβύσου τοῦ υἱέος αὐτοῦ, τῆς τε καθ’ ἑαυτοὺς θαλάσσης Κύρῳ πολεμοῦντες ἐκράτησάν τινα χρόνον. καὶ Πολυκράτης Σάμου τυραννῶν ἐπὶ Καμβύσου ναυτικῷ ἰσχύων ἄλλας τε τῶν νήσων ὑπηκόους ἐποιήσατο καὶ Ῥήνειαν ἑλὼν ἀνέθηκε τῷ Ἀπόλλωνι τῷ Δηλίῳ. Φωκαῆς τε Μασσαλίαν οἰκίζοντες Καρχηδονίους ἐνίκων ναυμαχοῦντες·", "st": "1.13"}, {"sp": "N", "t": "δυνατώτατα γὰρ ταῦτα τῶν ναυτικῶν ἦν. φαίνεται δὲ καὶ ταῦτα πολλαῖς γενεαῖς ὕστερα γενόμενα τῶν Τρωικῶν τριήρεσι μὲν ὀλίγαις χρώμενα, πεντηκοντόροις δ’ ἔτι καὶ πλοίοις μακροῖς ἐξηρτυμένα ὥσπερ ἐκεῖνα. ὀλίγον τε πρὸ τῶν Μηδικῶν καὶ τοῦ Δαρείου θανάτου, ὃς μετὰ Καμβύσην Περσῶν ἐβασίλευσε, τριήρεις περί τε Σικελίαν τοῖς τυράννοις ἐς πλῆθος ἐγένοντο καὶ Κερκυραίοις· ταῦτα γὰρ τελευταῖα πρὸ τῆς Ξέρξου στρατείας ναυτικὰ ἀξιόλογα ἐν τῇ Ἑλλάδι κατέστη. Αἰγινῆται γὰρ καὶ Ἀθηναῖοι, καὶ εἴ τινες ἄλλοι, βραχέα ἐκέκτηντο, καὶ τούτων τὰ πολλὰ πεντηκοντόρους· ὀψέ τε ἀφ’ οὗ Ἀθηναίους Θεμιστοκλῆς ἔπεισεν Αἰγινήταις πολεμοῦντας, καὶ ἅμα τοῦ βαρβάρου προσδοκίμου ὄντος, τὰς ναῦς ποιήσασθαι αἷσπερ καὶ ἐναυμάχησαν· καὶ αὗται οὔπω εἶχον διὰ πάσης καταστρώματα.", "st": "1.14"}, {"sp": "N", "t": "τὰ μὲν οὖν ναυτικὰ τῶν Ἑλλήνων τοιαῦτα ἦν, τά τε παλαιὰ καὶ τὰ ὕστερον γενόμενα. ἰσχὺν δὲ περιεποιήσαντο ὅμως οὐκ ἐλαχίστην οἱ προσσχόντες αὐτοῖς χρημάτων τε προσόδῳ καὶ ἄλλων ἀρχῇ· ἐπιπλέοντες γὰρ τὰς νήσους κατεστρέφοντο, καὶ μάλιστα ὅσοι μὴ διαρκῆ εἶχον χώραν. κατὰ γῆν δὲ πόλεμος, ὅθεν τις καὶ δύναμις παρεγένετο, οὐδεὶς ξυνέστη· πάντες δὲ ἦσαν, ὅσοι καὶ ἐγένοντο, πρὸς ὁμόρους τοὺς σφετέρους ἑκάστοις, καὶ ἐκδήμους στρατείας πολὺ ἀπὸ τῆς ἑαυτῶν ἐπ’ ἄλλων καταστροφῇ οὐκ ἐξῇσαν οἱ Ἕλληνες. οὐ γὰρ ξυνειστήκεσαν πρὸς τὰς μεγίστας πόλεις ὑπήκοοι, οὐδ’ αὖ αὐτοὶ ἀπὸ τῆς ἴσης κοινὰς στρατείας ἐποιοῦντο, κατ’ ἀλλήλους δὲ μᾶλλον ὡς ἕκαστοι οἱ ἀστυγείτονες ἐπολέμουν. μάλιστα δὲ ἐς τὸν πάλαι ποτὲ γενόμενον πόλεμον Χαλκιδέων καὶ Ἐρετριῶν καὶ τὸ ἄλλο Ἑλληνικὸν ἐς ξυμμαχίαν ἑκατέρων διέστη.", "st": "1.15"}, {"sp": "N", "t": "ἐπεγένετο δὲ ἄλλοις τε ἄλλοθι κωλύματα μὴ αὐξηθῆναι, καὶ Ἴωσι προχωρησάντων ἐπὶ μέγα τῶν πραγμάτων Κῦρος καὶ ἡ Περσικὴ βασιλεία Κροῖσον καθελοῦσα καὶ ὅσα ἐντὸς Ἅλυος ποταμοῦ πρὸς θάλασσαν ἐπεστράτευσε καὶ τὰς ἐν τῇ ἠπείρῳ πόλεις ἐδούλωσε, Δαρεῖός τε ὕστερον τῷ Φοινίκων ναυτικῷ κρατῶν καὶ τὰς νήσους.", "st": "1.16"}, {"sp": "N", "t": "τύραννοί τε ὅσοι ἦσαν ἐν ταῖς Ἑλληνικαῖς πόλεσι, τὸ ἐφ’ ἑαυτῶν μόνον προορώμενοι ἔς τε τὸ σῶμα καὶ ἐς τὸ τὸν ἴδιον οἶκον αὔξειν δι’ ἀσφαλείας ὅσον ἐδύναντο μάλιστα τὰς πόλεις ᾤκουν, ἐπράχθη δὲ οὐδὲν ἀπ’ αὐτῶν ἔργον ἀξιόλογον, εἰ μὴ εἴ τι πρὸς περιοίκους τοὺς αὐτῶν ἑκάστοις· οἱ γὰρ ἐν Σικελίᾳ ἐπὶ πλεῖστον ἐχώρησαν δυνάμεως. οὕτω πανταχόθεν ἡ Ἑλλὰς ἐπὶ πολὺν χρόνον κατείχετο μήτε κοινῇ φανερὸν μηδὲν κατεργάζεσθαι, κατὰ πόλεις τε ἀτολμοτέρα εἶναι.", "st": "1.17"}, {"sp": "N", "t": "ἐπειδὴ δὲ οἵ τε Ἀθηναίων τύραννοι καὶ οἱ ἐκ τῆς ἄλλης Ἑλλάδος ἐπὶ πολὺ καὶ πρὶν τυραννευθείσης οἱ πλεῖστοι καὶ τελευταῖοι πλὴν τῶν ἐν Σικελίᾳ ὑπὸ Λακεδαιμονίων κατελύθησαν (ἡ γὰρ Λακεδαίμων μετὰ τὴν κτίσιν τῶν νῦν ἐνοικούντων αὐτὴν Δωριῶν ἐπὶ πλεῖστον ὧν ἴσμεν χρόνον στασιάσασα ὅμως ἐκ παλαιτάτου καὶ ηὐνομήθη καὶ αἰεὶ ἀτυράννευτος ἦν· ἔτη γάρ ἐστι μάλιστα τετρακόσια καὶ ὀλίγῳ πλείω ἐς τὴν τελευτὴν τοῦδε τοῦ πολέμου ἀφ’ οὗ Λακεδαιμόνιοι τῇ αὐτῇ πολιτείᾳ χρῶνται, καὶ δι’ αὐτὸ δυνάμενοι καὶ τὰ ἐν ταῖς ἄλλαις πόλεσι καθίστασαν), μετὰ δὲ τὴν τῶν τυράννων κατάλυσιν ἐκ τῆς Ἑλλάδος οὐ πολλοῖς ἔτεσιν ὕστερον καὶ ἡ ἐν Μαραθῶνι μάχη Μήδων πρὸς Ἀθηναίους ἐγένετο. δεκάτῳ δὲ ἔτει μετ’ αὐτὴν αὖθις ὁ βάρβαρος τῷ μεγάλῳ στόλῳ ἐπὶ τὴν Ἑλλάδα δουλωσόμενος ἦλθεν. καὶ μεγάλου κινδύνου ἐπικρεμασθέντος οἵ τε Λακεδαιμόνιοι τῶν ξυμπολεμησάντων Ἑλλήνων ἡγήσαντο δυνάμει προύχοντες, καὶ οἱ Ἀθηναῖοι ἐπιόντων τῶν Μήδων διανοηθέντες ἐκλιπεῖν τὴν πόλιν καὶ ἀνασκευασάμενοι ἐς τὰς ναῦς ἐσβάντες ναυτικοὶ ἐγένοντο. κοινῇ τε ἀπωσάμενοι τὸν βάρβαρον, ὕστερον οὐ πολλῷ διεκρίθησαν πρός τε Ἀθηναίους καὶ Λακεδαιμονίους οἵ τε ἀποστάντες βασιλέως Ἕλληνες καὶ οἱ ξυμπολεμήσαντες. δυνάμει γὰρ ταῦτα μέγιστα διεφάνη· ἴσχυον γὰρ οἱ μὲν κατὰ γῆν, οἱ δὲ ναυσίν. καὶ ὀλίγον μὲν χρόνον ξυνέμεινεν ἡ ὁμαιχμία, ἔπειτα διενεχθέντες οἱ Λακεδαιμόνιοι καὶ Ἀθηναῖοι ἐπολέμησαν μετὰ τῶν ξυμμάχων πρὸς ἀλλήλους· καὶ τῶν ἄλλων Ἑλλήνων εἴ τινές που διασταῖεν, πρὸς τούτους ἤδη ἐχώρουν. ὥστε ἀπὸ τῶν Μηδικῶν ἐς τόνδε αἰεὶ τὸν πόλεμον τὰ μὲν σπενδόμενοι, τὰ δὲ πολεμοῦντες ἢ ἀλλήλοις ἢ τοῖς ἑαυτῶν ξυμμάχοις ἀφισταμένοις εὖ παρεσκευάσαντο τὰ πολέμια καὶ ἐμπειρότεροι ἐγένοντο μετὰ κινδύνων τὰς μελέτας ποιούμενοι.", "st": "1.18"}, {"sp": "N", "t": "καὶ οἱ μὲν Λακεδαιμόνιοι οὐχ ὑποτελεῖς ἔχοντες φόρου τοὺς ξυμμάχους ἡγοῦντο, κατ’ ὀλιγαρχίαν δὲ σφίσιν αὐτοῖς μόνον ἐπιτηδείως ὅπως πολιτεύσουσι θεραπεύοντες, Ἀθηναῖοι δὲ ναῦς τε τῶν πόλεων τῷ χρόνῳ παραλαβόντες πλὴν Χίων καὶ Λεσβίων, καὶ χρήματα τοῖς πᾶσι τάξαντες φέρειν. καὶ ἐγένετο αὐτοῖς ἐς τόνδε τὸν πόλεμον ἡ ἰδία παρασκευὴ μείζων ἢ ὡς τὰ κράτιστά ποτε μετὰ ἀκραιφνοῦς τῆς ξυμμαχίας ἤνθησαν.", "st": "1.19"}, {"sp": "N", "t": "τὰ μὲν οὖν παλαιὰ τοιαῦτα ηὗρον, χαλεπὰ ὄντα παντὶ ἑξῆς τεκμηρίῳ πιστεῦσαι. οἱ γὰρ ἄνθρωποι τὰς ἀκοὰς τῶν προγεγενημένων, καὶ ἢν ἐπιχώρια σφίσιν ᾖ, ὁμοίως ἀβασανίστως παρ’ ἀλλήλων δέχονται. Ἀθηναίων γοῦν τὸ πλῆθος Ἵππαρχον οἴονται ὑφ’ Ἁρμοδίου καὶ Ἀριστογείτονος τύραννον ὄντα ἀποθανεῖν, καὶ οὐκ ἴσασιν ὅτι Ἱππίας μὲν πρεσβύτατος ὢν ἦρχε τῶν Πεισιστράτου υἱέων, Ἵππαρχος δὲ καὶ Θεσσαλὸς ἀδελφοὶ ἦσαν αὐτοῦ, ὑποτοπήσαντες δέ τι ἐκείνῃ τῇ ἡμέρᾳ καὶ παραχρῆμα Ἁρμόδιος καὶ Ἀριστογείτων ἐκ τῶν ξυνειδότων σφίσιν Ἱππίᾳ μεμηνῦσθαι τοῦ μὲν ἀπέσχοντο ὡς προειδότος, βουλόμενοι δὲ πρὶν ξυλληφθῆναι δράσαντές τι καὶ κινδυνεῦσαι, τῷ Ἱππάρχῳ περιτυχόντες περὶ τὸ Λεωκόρειον καλούμενον τὴν Παναθηναϊκὴν πομπὴν διακοσμοῦντι ἀπέκτειναν. πολλὰ δὲ καὶ ἄλλα ἔτι καὶ νῦν ὄντα καὶ οὐ χρόνῳ ἀμνηστούμενα καὶ οἱ ἄλλοι Ἕλληνες οὐκ ὀρθῶς οἴονται, ὥσπερ τούς τε Λακεδαιμονίων βασιλέας μὴ μιᾷ ψήφῳ προστίθεσθαι ἑκάτερον, ἀλλὰ δυοῖν, καὶ τὸν Πιτανάτην λόχον αὐτοῖς εἶναι, ὃς οὐδ’ ἐγένετο πώποτε. οὕτως ἀταλαίπωρος τοῖς πολλοῖς ἡ ζήτησις τῆς ἀληθείας, καὶ ἐπὶ τὰ ἑτοῖμα μᾶλλον τρέπονται.", "st": "1.20"}, {"sp": "N", "t": "ἐκ δὲ τῶν εἰρημένων τεκμηρίων ὅμως τοιαῦτα ἄν τις νομίζων μάλιστα ἃ διῆλθον οὐχ ἁμαρτάνοι, καὶ οὔτε ὡς ποιηταὶ ὑμνήκασι περὶ αὐτῶν ἐπὶ τὸ μεῖζον κοσμοῦντες μᾶλλον πιστεύων, οὔτε ὡς λογογράφοι ξυνέθεσαν ἐπὶ τὸ προσαγωγότερον τῇ ἀκροάσει ἢ ἀληθέστερον, ὄντα ἀνεξέλεγκτα καὶ τὰ πολλὰ ὑπὸ χρόνου αὐτῶν ἀπίστως ἐπὶ τὸ μυθῶδες ἐκνενικηκότα, ηὑρῆσθαι δὲ ἡγησάμενος ἐκ τῶν ἐπιφανεστάτων σημείων ὡς παλαιὰ εἶναι ἀποχρώντως. καὶ ὁ πόλεμος οὗτος, καίπερ τῶν ἀνθρώπων ἐν ᾧ μὲν ἂν πολεμῶσι τὸν παρόντα αἰεὶ μέγιστον κρινόντων, παυσαμένων δὲ τὰ ἀρχαῖα μᾶλλον θαυμαζόντων, ἀπ’ αὐτῶν τῶν ἔργων σκοποῦσι δηλώσει ὅμως μείζων γεγενημένος αὐτῶν.", "st": "1.21"}, {"sp": "N", "t": "καὶ ὅσα μὲν λόγῳ εἶπον ἕκαστοι ἢ μέλλοντες πολεμήσειν ἢ ἐν αὐτῷ ἤδη ὄντες, χαλεπὸν τὴν ἀκρίβειαν αὐτὴν τῶν λεχθέντων διαμνημονεῦσαι ἦν ἐμοί τε ὧν αὐτὸς ἤκουσα καὶ τοῖς ἄλλοθέν ποθεν ἐμοὶ ἀπαγγέλλουσιν· ὡς δ’ ἂν ἐδόκουν ἐμοὶ ἕκαστοι περὶ τῶν αἰεὶ παρόντων τὰ δέοντα μάλιστ’ εἰπεῖν, ἐχομένῳ ὅτι ἐγγύτατα τῆς ξυμπάσης γνώμης τῶν ἀληθῶς λεχθέντων, οὕτως εἴρηται. τὰ δ’ ἔργα τῶν πραχθέντων ἐν τῷ πολέμῳ οὐκ ἐκ τοῦ παρατυχόντος πυνθανόμενος ἠξίωσα γράφειν, οὐδ’ ὡς ἐμοὶ ἐδόκει, ἀλλ’ οἷς τε αὐτὸς παρῆν καὶ παρὰ τῶν ἄλλων ὅσον δυνατὸν ἀκριβείᾳ περὶ ἑκάστου ἐπεξελθών. ἐπιπόνως δὲ ηὑρίσκετο, διότι οἱ παρόντες τοῖς ἔργοις ἑκάστοις οὐ ταὐτὰ περὶ τῶν αὐτῶν ἔλεγον, ἀλλ’ ὡς ἑκατέρων τις εὐνοίας ἢ μνήμης ἔχοι. καὶ ἐς μὲν ἀκρόασιν ἴσως τὸ μὴ μυθῶδες αὐτῶν ἀτερπέστερον φανεῖται· ὅσοι δὲ βουλήσονται τῶν τε γενομένων τὸ σαφὲς σκοπεῖν καὶ τῶν μελλόντων ποτὲ αὖθις κατὰ τὸ ἀνθρώπινον τοιούτων καὶ παραπλησίων ἔσεσθαι, ὠφέλιμα κρίνειν αὐτὰ ἀρκούντως ἕξει. κτῆμά τε ἐς αἰεὶ μᾶλλον ἢ ἀγώνισμα ἐς τὸ παραχρῆμα ἀκούειν ξύγκειται.", "st": "1.22"}, {"sp": "N", "t": "τῶν δὲ πρότερον ἔργων μέγιστον ἐπράχθη τὸ Μηδικόν, καὶ τοῦτο ὅμως δυοῖν ναυμαχίαιν καὶ πεζομαχίαιν ταχεῖαν τὴν κρίσιν ἔσχεν. τούτου δὲ τοῦ πολέμου μῆκός τε μέγα προύβη, παθήματά τε ξυνηνέχθη γενέσθαι ἐν αὐτῷ τῇ Ἑλλάδι οἷα οὐχ ἕτερα ἐν ἴσῳ χρόνῳ. οὔτε γὰρ πόλεις τοσαίδε ληφθεῖσαι ἠρημώθησαν, αἱ μὲν ὑπὸ βαρβάρων, αἱ δ’ ὑπὸ σφῶν αὐτῶν ἀντιπολεμούντων (εἰσὶ δ’ αἳ καὶ οἰκήτορας μετέβαλον ἁλισκόμεναι), οὔτε φυγαὶ τοσαίδε ἀνθρώπων καὶ φόνος, ὁ μὲν κατ’ αὐτὸν τὸν πόλεμον, ὁ δὲ διὰ τὸ στασιάζειν. τά τε πρότερον ἀκοῇ μὲν λεγόμενα, ἔργῳ δὲ σπανιώτερον βεβαιούμενα οὐκ ἄπιστα κατέστη, σεισμῶν τε πέρι, οἳ ἐπὶ πλεῖστον ἅμα μέρος γῆς καὶ ἰσχυρότατοι οἱ αὐτοὶ ἐπέσχον, ἡλίου τε ἐκλείψεις, αἳ πυκνότεραι παρὰ τὰ ἐκ τοῦ πρὶν χρόνου μνημονευόμενα ξυνέβησαν, αὐχμοί τε ἔστι παρ’ οἷς μεγάλοι καὶ ἀπ’ αὐτῶν καὶ λιμοὶ καὶ ἡ οὐχ ἥκιστα βλάψασα καὶ μέρος τι φθείρασα ἡ λοιμώδης νόσος· ταῦτα γὰρ πάντα μετὰ τοῦδε τοῦ πολέμου ἅμα ξυνεπέθετο. ἤρξαντο δὲ αὐτοῦ Ἀθηναῖοι καὶ Πελοποννήσιοι λύσαντες τὰς τριακοντούτεις σπονδὰς αἳ αὐτοῖς ἐγένοντο μετὰ Εὐβοίας ἅλωσιν. διότι δ’ ἔλυσαν, τὰς αἰτίας προύγραψα πρῶτον καὶ τὰς διαφοράς, τοῦ μή τινα ζητῆσαί ποτε ἐξ ὅτου τοσοῦτος πόλεμος τοῖς Ἕλλησι κατέστη. τὴν μὲν γὰρ ἀληθεστάτην πρόφασιν, ἀφανεστάτην δὲ λόγῳ, τοὺς Ἀθηναίους ἡγοῦμαι μεγάλους γιγνομένους καὶ φόβον παρέχοντας τοῖς Λακεδαιμονίοις ἀναγκάσαι ἐς τὸ πολεμεῖν· αἱ δ’ ἐς τὸ φανερὸν λεγόμεναι αἰτίαι αἵδ’ ἦσαν ἑκατέρων, ἀφ’ ὧν λύσαντες τὰς σπονδὰς ἐς τὸν πόλεμον κατέστησαν.", "st": "1.23"}, {"sp": "N", "t": "Ἐπίδαμνός ἐστι πόλις ἐν δεξιᾷ ἐσπλέοντι ἐς τὸν Ἰόνιον κόλπον· προσοικοῦσι δ’ αὐτὴν Ταυλάντιοι βάρβαροι, Ἰλλυρικὸν ἔθνος. ταύτην ἀπῴκισαν μὲν Κερκυραῖοι, οἰκιστὴς δ’ ἐγένετο Φαλίος Ἐρατοκλείδου Κορίνθιος γένος τῶν ἀφ’ Ἡρακλέους, κατὰ δὴ τὸν παλαιὸν νόμον ἐκ τῆς μητροπόλεως κατακληθείς. ξυνῴκισαν δὲ καὶ Κορινθίων τινὲς καὶ τοῦ ἄλλου Δωρικοῦ γένους. προελθόντος δὲ τοῦ χρόνου ἐγένετο ἡ τῶν Ἐπιδαμνίων δύναμις μεγάλη καὶ πολυάνθρωπος· στασιάσαντες δὲ ἐν ἀλλήλοις ἔτη πολλά, ὡς λέγεται, ἀπὸ πολέμου τινὸς τῶν προσοίκων βαρβάρων ἐφθάρησαν καὶ τῆς δυνάμεως τῆς πολλῆς ἐστερήθησαν. τὰ δὲ τελευταῖα πρὸ τοῦδε τοῦ πολέμου ὁ δῆμος αὐτῶν ἐξεδίωξε τοὺς δυνατούς, οἱ δὲ ἐπελθόντες μετὰ τῶν βαρβάρων ἐλῄζοντο τοὺς ἐν τῇ πόλει κατά τε γῆν καὶ κατὰ θάλασσαν. οἱ δὲ ἐν τῇ πόλει ὄντες Ἐπιδάμνιοι ἐπειδὴ ἐπιέζοντο, πέμπουσιν ἐς τὴν Κέρκυραν πρέσβεις ὡς μητρόπολιν οὖσαν, δεόμενοι μὴ σφᾶς περιορᾶν φθειρομένους, ἀλλὰ τούς τε φεύγοντας ξυναλλάξαι σφίσι καὶ τὸν τῶν βαρβάρων πόλεμον καταλῦσαι. ταῦτα δὲ ἱκέται καθεζόμενοι ἐς τὸ Ἥραιον ἐδέοντο. οἱ δὲ Κερκυραῖοι τὴν ἱκετείαν οὐκ ἐδέξαντο, ἀλλ’ ἀπράκτους ἀπέπεμψαν.", "st": "1.24"}, {"sp": "N", "t": "γνόντες δὲ οἱ Ἐπιδάμνιοι οὐδεμίαν σφίσιν ἀπὸ Κερκύρας τιμωρίαν οὖσαν ἐν ἀπόρῳ εἴχοντο θέσθαι τὸ παρόν, καὶ πέμψαντες ἐς Δελφοὺς τὸν θεὸν ἐπήροντο εἰ παραδοῖεν Κορινθίοις τὴν πόλιν ὡς οἰκισταῖς καὶ τιμωρίαν τινὰ πειρῷντ’ ἀπ’ αὐτῶν ποιεῖσθαι. ὁ δ’ αὐτοῖς ἀνεῖλε παραδοῦναι καὶ ἡγεμόνας ποιεῖσθαι. ἐλθόντες δὲ οἱ Ἐπιδάμνιοι ἐς τὴν Κόρινθον κατὰ τὸ μαντεῖον παρέδοσαν τὴν ἀποικίαν, τόν τε οἰκιστὴν ἀποδεικνύντες σφῶν ἐκ Κορίνθου ὄντα καὶ τὸ χρηστήριον δηλοῦντες, ἐδέοντό τε μὴ σφᾶς περιορᾶν φθειρομένους, ἀλλ’ ἐπαμῦναι. Κορίνθιοι δὲ κατά τε τὸ δίκαιον ὑπεδέξαντο τὴν τιμωρίαν, νομίζοντες οὐχ ἧσσον ἑαυτῶν εἶναι τὴν ἀποικίαν ἢ Κερκυραίων, ἅμα δὲ καὶ μίσει τῶν Κερκυραίων, ὅτι αὐτῶν παρημέλουν ὄντες ἄποικοι· οὔτε γὰρ ἐν πανηγύρεσι ταῖς κοιναῖς διδόντες γέρα τὰ νομιζόμενα οὔτε Κορινθίῳ ἀνδρὶ προκαταρχόμενοι τῶν ἱερῶν ὥσπερ αἱ ἄλλαι ἀποικίαι, περιφρονοῦντες δὲ αὐτοὺς καὶ χρημάτων δυνάμει ὄντες κατ’ ἐκεῖνον τὸν χρόνον ὁμοῖα τοῖς Ἑλλήνων πλουσιωτάτοις καὶ τῇ ἐς πόλεμον παρασκευῇ δυνατώτεροι, ναυτικῷ δὲ καὶ πολὺ προύχειν ἔστιν ὅτε ἐπαιρόμενοι καὶ κατὰ τὴν Φαιάκων προενοίκησιν τῆς Κερκύρας κλέος ἐχόντων τὰ περὶ τὰς ναῦς (ᾗ καὶ μᾶλλον ἐξηρτύοντο τὸ ναυτικὸν καὶ ἦσαν οὐκ ἀδύνατοι· τριήρεις γὰρ εἴκοσι καὶ ἑκατὸν ὑπῆρχον αὐτοῖς ὅτε ἤρχοντο πολεμεῖν),", "st": "1.25"}, {"sp": "N", "t": "πάντων οὖν τούτων ἐγκλήματα ἔχοντες οἱ Κορίνθιοι ἔπεμπον ἐς τὴν Ἐπίδαμνον ἄσμενοι τὴν ὠφελίαν, οἰκήτορά τε τὸν βουλόμενον ἰέναι κελεύοντες καὶ Ἀμπρακιωτῶν καὶ Λευκαδίων καὶ ἑαυτῶν φρουρούς. ἐπορεύθησαν δὲ πεζῇ ἐς Ἀπολλωνίαν, Κορινθίων οὖσαν ἀποικίαν, δέει τῶν Κερκυραίων μὴ κωλύωνται ὑπ’ αὐτῶν κατὰ θάλασσαν περαιούμενοι.", "st": "1.26"}, {"sp": "N", "t": "Κερκυραῖοι δὲ ἐπειδὴ ᾔσθοντο τούς τε οἰκήτορας καὶ φρουροὺς ἥκοντας ἐς τὴν Ἐπίδαμνον τήν τε ἀποικίαν Κορινθίοις δεδομένην, ἐχαλέπαινον· καὶ πλεύσαντες εὐθὺς πέντε καὶ εἴκοσι ναυσὶ καὶ ὕστερον ἑτέρῳ στόλῳ τούς τε φεύγοντας ἐκέλευον κατ’ ἐπήρειαν δέχεσθαι αὐτούς (ἦλθον γὰρ ἐς τὴν Κέρκυραν οἱ τῶν Ἐπιδαμνίων φυγάδες, τάφους τε ἀποδεικνύντες καὶ ξυγγένειαν, ἣν προϊσχόμενοι ἐδέοντο σφᾶς κατάγειν) τούς τε φρουροὺς οὓς Κορίνθιοι ἔπεμψαν καὶ τοὺς οἰκήτορας ἀποπέμπειν. οἱ δὲ Ἐπιδάμνιοι οὐδὲν αὐτῶν ὑπήκουσαν, ἀλλὰ στρατεύουσιν ἐπ’ αὐτοὺς οἱ Κερκυραῖοι τεσσαράκοντα ναυσὶ μετὰ τῶν φυγάδων ὡς κατάξοντες, καὶ τοὺς Ἰλλυριοὺς προσλαβόντες. προσκαθεζόμενοι δὲ τὴν πόλιν προεῖπον Ἐπιδαμνίων τε τὸν βουλόμενον καὶ τοὺς ξένους ἀπαθεῖς ἀπιέναι· εἰ δὲ μή, ὡς πολεμίοις χρήσεσθαι. ὡς δ’ οὐκ ἐπείθοντο, οἱ μὲν Κερκυραῖοι (ἔστι δ’ ἰσθμὸς τὸ χωρίον) ἐπολιόρκουν τὴν πόλιν,", "st": "1.26"}, {"sp": "N", "t": "Κορίνθιοι δ’, ὡς αὐτοῖς ἐκ τῆς Ἐπιδάμνου ἦλθον ἄγγελοι ὅτι πολιορκοῦνται, παρεσκευάζοντο στρατείαν, καὶ ἅμα ἀποικίαν ἐς τὴν Ἐπίδαμνον ἐκήρυσσον ἐπὶ τῇ ἴσῃ καὶ ὁμοίᾳ τὸν βουλόμενον ἰέναι· εἰ δέ τις τὸ παραυτίκα μὲν μὴ ἐθέλει ξυμπλεῖν, μετέχειν δὲ βούλεται τῆς ἀποικίας, πεντήκοντα δραχμὰς καταθέντα Κορινθίας μένειν. ἦσαν δὲ καὶ οἱ πλέοντες πολλοὶ καὶ οἱ τἀργύριον καταβάλλοντες. ἐδεήθησαν δὲ καὶ τῶν Μεγαρέων ναυσὶ σφᾶς ξυμπροπέμψαι, εἰ ἄρα κωλύοιντο ὑπὸ Κερκυραίων πλεῖν· οἱ δὲ παρεσκευάζοντο αὐτοῖς ὀκτὼ ναυσὶ ξυμπλεῖν, καὶ Παλῆς Κεφαλλήνων τέσσαρσιν. καὶ Ἐπιδαυρίων ἐδεήθησαν, οἳ παρέσχον πέντε, Ἑρμιονῆς δὲ μίαν καὶ Τροιζήνιοι δύο, Λευκάδιοι δὲ δέκα καὶ Ἀμπρακιῶται ὀκτώ. Θηβαίους δὲ χρήματα ᾔτησαν καὶ Φλειασίους, Ἠλείους δὲ ναῦς τε κενὰς καὶ χρήματα. αὐτῶν δὲ Κορινθίων νῆες παρεσκευάζοντο τριάκοντα καὶ τρισχίλιοι ὁπλῖται.", "st": "1.27"}, {"sp": "N", "t": "ἐπειδὴ δὲ ἐπύθοντο οἱ Κερκυραῖοι τὴν παρασκευήν, ἐλθόντες ἐς Κόρινθον μετὰ Λακεδαιμονίων καὶ Σικυωνίων πρέσβεων, οὓς παρέλαβον, ἐκέλευον Κορινθίους τοὺς ἐν Ἐπιδάμνῳ φρουρούς τε καὶ οἰκήτορας ἀπάγειν, ὡς οὐ μετὸν αὐτοῖς Ἐπιδάμνου. εἰ δέ τι ἀντιποιοῦνται, δίκας ἤθελον δοῦναι ἐν Πελοποννήσῳ παρὰ πόλεσιν αἷς ἂν ἀμφότεροι ξυμβῶσιν· ὁποτέρων δ’ ἂν δικασθῇ εἶναι τὴν ἀποικίαν, τούτους κρατεῖν. ἤθελον δὲ καὶ τῷ ἐν Δελφοῖς μαντείῳ ἐπιτρέψαι. πόλεμον δὲ οὐκ εἴων ποιεῖν· εἰ δὲ μή, καὶ αὐτοὶ ἀναγκασθήσεσθαι ἔφασαν, ἐκείνων βιαζομένων, φίλους ποιεῖσθαι οὓς οὐ βούλονται ἑτέρους τῶν νῦν ὄντων μᾶλλον ὠφελίας ἕνεκα. οἱ δὲ Κορίνθιοι ἀπεκρίναντο αὐτοῖς, ἢν τάς τε ναῦς καὶ τοὺς βαρβάρους ἀπὸ Ἐπιδάμνου ἀπαγάγωσι, βουλεύσεσθαι· πρότερον δ’ οὐ καλῶς ἔχειν τοὺς μὲν πολιορκεῖσθαι, αὐτοὺς δὲ δικάζεσθαι. Κερκυραῖοι δὲ ἀντέλεγον, ἢν καὶ ἐκεῖνοι τοὺς ἐν Ἐπιδάμνῳ ἀπαγάγωσι, ποιήσειν ταῦτα· ἑτοῖμοι δὲ εἶναι καὶ ὥστε ἀμφοτέρους μένειν κατὰ χώραν, σπονδὰς δὲ ποιήσασθαι ἕως ἂν ἡ δίκη γένηται.", "st": "1.28"}, {"sp": "N", "t": "Κορίνθιοι δὲ οὐδὲν τούτων ὑπήκουον, ἀλλ’ ἐπειδὴ πλήρεις αὐτοῖς ἦσαν αἱ νῆες καὶ οἱ ξύμμαχοι παρῆσαν, προπέμψαντες κήρυκα πρότερον πόλεμον προεροῦντα Κερκυραίοις, ἄραντες ἑβδομήκοντα ναυσὶ καὶ πέντε δισχιλίοις τε ὁπλίταις ἔπλεον ἐπὶ τὴν Ἐπίδαμνον Κερκυραίοις ἐναντία πολεμήσοντες· ἐστρατήγει δὲ τῶν μὲν νεῶν Ἀριστεὺς ὁ Πελλίχου καὶ Καλλικράτης ὁ Καλλίου καὶ Τιμάνωρ ὁ Τιμάνθους, τοῦ δὲ πεζοῦ Ἀρχέτιμός τε ὁ Εὐρυτίμου καὶ Ἰσαρχίδας ὁ Ἰσάρχου. ἐπειδὴ δ’ ἐγένοντο ἐν Ἀκτίῳ τῆς Ἀνακτορίας γῆς, οὗ τὸ ἱερὸν τοῦ Ἀπόλλωνός ἐστιν, ἐπὶ τῷ στόματι τοῦ Ἀμπρακικοῦ κόλπου, οἱ Κερκυραῖοι κήρυκά τε προύπεμψαν αὐτοῖς ἐν ἀκατίῳ ἀπεροῦντα μὴ πλεῖν ἐπὶ σφᾶς καὶ τὰς ναῦς ἅμα ἐπλήρουν, ζεύξαντές τε τὰς παλαιὰς ὥστε πλωίμους εἶναι καὶ τὰς ἄλλας ἐπισκευάσαντες. ὡς δὲ ὁ κῆρύξ τε ἀπήγγειλεν οὐδὲν εἰρηναῖον παρὰ τῶν Κορινθίων καὶ αἱ νῆες αὐτοῖς ἐπεπλήρωντο οὖσαι ὀγδοήκοντα (τεσσαράκοντα γὰρ Ἐπίδαμνον ἐπολιόρκουν), ἀνταναγαγόμενοι καὶ παραταξάμενοι ἐναυμάχησαν· καὶ ἐνίκησαν οἱ Κερκυραῖοι παρὰ πολὺ καὶ ναῦς πέντε καὶ δέκα διέφθειραν τῶν Κορινθίων. τῇ δὲ αὐτῇ ἡμέρᾳ αὐτοῖς ξυνέβη καὶ τοὺς τὴν Ἐπίδαμνον πολιορκοῦντας παραστήσασθαι ὁμολογίᾳ ὥστε τοὺς μὲν ἐπήλυδας ἀποδόσθαι, Κορινθίους δὲ δήσαντας ἔχειν ἕως ἂν ἄλλο τι δόξῃ.", "st": "1.29"}, {"sp": "N", "t": "μετὰ δὲ τὴν ναυμαχίαν οἱ Κερκυραῖοι τροπαῖον στήσαντες ἐπὶ τῇ Λευκίμμῃ τῆς Κερκυραίας ἀκρωτηρίῳ τοὺς μὲν ἄλλους οὓς ἔλαβον αἰχμαλώτους ἀπέκτειναν, Κορινθίους δὲ δήσαντες εἶχον. ὕστερον δέ, ἐπειδὴ οἱ Κορίνθιοι καὶ οἱ ξύμμαχοι ἡσσημένοι ταῖς ναυσὶν ἀνεχώρησαν ἐπ’ οἴκου, τῆς θαλάσσης ἁπάσης ἐκράτουν τῆς κατ’ ἐκεῖνα τὰ χωρία οἱ Κερκυραῖοι, καὶ πλεύσαντες ἐς Λευκάδα τὴν Κορινθίων ἀποικίαν τῆς γῆς ἔτεμον καὶ Κυλλήνην τὸ Ἠλείων ἐπίνειον ἐνέπρησαν, ὅτι ναῦς καὶ χρήματα παρέσχον Κορινθίοις. τοῦ τε χρόνου τὸν πλεῖστον μετὰ τὴν ναυμαχίαν ἐπεκράτουν τῆς θαλάσσης καὶ τοὺς τῶν Κορινθίων ξυμμάχους ἐπιπλέοντες ἔφθειρον, μέχρι οὗ Κορίνθιοι περιιόντι τῷ θέρει πέμψαντες ναῦς καὶ στρατιάν, ἐπεὶ σφῶν οἱ ξύμμαχοι ἐπόνουν, ἐστρατοπεδεύοντο ἐπὶ Ἀκτίῳ καὶ περὶ τὸ Χειμέριον τῆς Θεσπρωτίδος φυλακῆς ἕνεκα τῆς τε Λευκάδος καὶ τῶν ἄλλων πόλεων ὅσαι σφίσι φίλιαι ἦσαν. ἀντεστρατοπεδεύοντο δὲ καὶ οἱ Κερκυραῖοι ἐπὶ τῇ Λευκίμμῃ ναυσί τε καὶ πεζῷ. ἐπέπλεον δὲ οὐδέτεροι ἀλλήλοις, ἀλλὰ τὸ θέρος τοῦτο ἀντικαθεζόμενοι χειμῶνος ἤδη ἀνεχώρησαν ἐπ’ οἴκου ἑκάτεροι.", "st": "1.30"}, {"sp": "N", "t": "τὸν δ’ ἐνιαυτὸν πάντα τὸν μετὰ τὴν ναυμαχίαν καὶ τὸν ὕστερον οἱ Κορίνθιοι ὀργῇ φέροντες τὸν πρὸς Κερκυραίους πόλεμον ἐναυπηγοῦντο καὶ παρεσκευάζοντο τὰ κράτιστα νεῶν στόλον, ἔκ τε αὐτῆς Πελοποννήσου ἀγείροντες καὶ τῆς ἄλλης Ἑλλάδος ἐρέτας, μισθῷ πείθοντες. πυνθανόμενοι δὲ οἱ Κερκυραῖοι τὴν παρασκευὴν αὐτῶν ἐφοβοῦντο, καί (ἦσαν γὰρ οὐδενὸς Ἑλλήνων ἔνσπονδοι οὐδὲ ἐσεγράψαντο ἑαυτοὺς οὔτε ἐς τὰς Ἀθηναίων σπονδὰς οὔτε ἐς τὰς Λακεδαιμονίων) ἔδοξεν αὐτοῖς ἐλθοῦσιν ὡς τοὺς Ἀθηναίους ξυμμάχους γενέσθαι καὶ ὠφελίαν τινὰ πειρᾶσθαι ἀπ’ αὐτῶν εὑρίσκεσθαι. οἱ δὲ Κορίνθιοι πυθόμενοι ταῦτα ἦλθον καὶ αὐτοὶ ἐς τὰς Ἀθήνας πρεσβευσόμενοι, ὅπως μὴ σφίσι πρὸς τῷ Κερκυραίων ναυτικῷ καὶ τὸ αὐτῶν προσγενόμενον ἐμπόδιον γένηται θέσθαι τὸν πόλεμον ᾗ βούλονται. καταστάσης δὲ ἐκκλησίας ἐς ἀντιλογίαν ἦλθον, καὶ οἱ μὲν Κερκυραῖοι ἔλεξαν τοιάδε.", "st": "1.31"}, {"sp": "N", "t": "‘Δίκαιον, ὦ Ἀθηναῖοι, τοὺς μήτε εὐεργεσίας μεγάλης μήτε ξυμμαχίας προυφειλομένης ἥκοντας παρὰ τοὺς πέλας ἐπικουρίας, ὥσπερ καὶ ἡμεῖς νῦν, δεησομένους ἀναδιδάξαι πρῶτον, μάλιστα μὲν ὡς καὶ ξύμφορα δέονται, εἰ δὲ μή, ὅτι γε οὐκ ἐπιζήμια, ἔπειτα δὲ ὡς καὶ τὴν χάριν βέβαιον ἕξουσιν· εἰ δὲ τούτων μηδὲν σαφὲς καταστήσουσι, μὴ ὀργίζεσθαι ἢν ἀτυχῶσιν. Κερκυραῖοι δὲ μετὰ τῆς ξυμμαχίας τῆς αἰτήσεως καὶ ταῦτα πιστεύοντες ἐχυρὰ ὑμῖν παρέξεσθαι ἀπέστειλαν ἡμᾶς. τετύχηκε δὲ τὸ αὐτὸ ἐπιτήδευμα πρός τε ὑμᾶς ἐς τὴν χρείαν ἡμῖν ἄλογον καὶ ἐς τὰ ἡμέτερα αὐτῶν ἐν τῷ παρόντι ἀξύμφορον. ξύμμαχοί τε γὰρ οὐδενός πω ἐν τῷ πρὸ τοῦ χρόνῳ ἑκούσιοι γενόμενοι νῦν ἄλλων τοῦτο δεησόμενοι ἥκομεν, καὶ ἅμα ἐς τὸν παρόντα πόλεμον Κορινθίων ἐρῆμοι δι’ αὐτὸ καθέσταμεν. καὶ περιέστηκεν ἡ δοκοῦσα ἡμῶν πρότερον σωφροσύνη, τὸ μὴ ἐν ἀλλοτρίᾳ ξυμμαχίᾳ τῇ τοῦ πέλας γνώμῃ ξυγκινδυνεύειν, νῦν ἀβουλία καὶ ἀσθένεια φαινομένη. τὴν μὲν οὖν γενομένην ναυμαχίαν αὐτοὶ κατὰ μόνας ἀπεωσάμεθα Κορινθίους· ἐπειδὴ δὲ μείζονι παρασκευῇ ἀπὸ Πελοποννήσου καὶ τῆς ἄλλης Ἑλλάδος ἐφ’ ἡμᾶς ὥρμηνται καὶ ἡμεῖς ἀδύνατοι ὁρῶμεν ὄντες τῇ οἰκείᾳ μόνον δυνάμει περιγενέσθαι, καὶ ἅμα μέγας ὁ κίνδυνος εἰ ἐσόμεθα ὑπ’ αὐτοῖς, ἀνάγκη καὶ ὑμῶν καὶ ἄλλου παντὸς ἐπικουρίας δεῖσθαι, καὶ ξυγγνώμη εἰ μὴ μετὰ κακίας, δόξης δὲ μᾶλλον ἁμαρτίᾳ τῇ πρότερον ἀπραγμοσύνῃ ἐναντία τολμῶμεν.", "st": "1.32"}, {"sp": "N", "t": "‘γενήσεται δὲ ὑμῖν πειθομένοις καλὴ ἡ ξυντυχία κατὰ πολλὰ τῆς ἡμετέρας χρείας, πρῶτον μὲν ὅτι ἀδικουμένοις καὶ οὐχ ἑτέρους βλάπτουσι τὴν ἐπικουρίαν ποιήσεσθε, ἔπειτα περὶ τῶν μεγίστων κινδυνεύοντας δεξάμενοι ὡς ἂν μάλιστα μετ’ αἰειμνήστου μαρτυρίου τὴν χάριν καταθήσεσθε· ναυτικόν τε κεκτήμεθα πλὴν τοῦ παρ’ ὑμῖν πλεῖστον. καὶ σκέψασθε· τίς εὐπραξία σπανιωτέρα ἢ τίς τοῖς πολεμίοις λυπηροτέρα, εἰ ἣν ὑμεῖς ἂν πρὸ πολλῶν χρημάτων καὶ χάριτος ἐτιμήσασθε δύναμιν ὑμῖν προσγενέσθαι, αὕτη πάρεστιν αὐτεπάγγελτος ἄνευ κινδύνων καὶ δαπάνης διδοῦσα ἑαυτήν, καὶ προσέτι φέρουσα ἐς μὲν τοὺς πολλοὺς ἀρετήν, οἷς δὲ ἐπαμυνεῖτε χάριν, ὑμῖν δ’ αὐτοῖς ἰσχύν· ἃ ἐν τῷ παντὶ χρόνῳ ὀλίγοις δὴ ἅμα πάντα ξυνέβη, καὶ ὀλίγοι ξυμμαχίας δεόμενοι οἷς ἐπικαλοῦνται ἀσφάλειαν καὶ κόσμον οὐχ ἧσσον διδόντες ἢ ληψόμενοι παραγίγνονται. τὸν δὲ πόλεμον, δι’ ὅνπερ χρήσιμοι ἂν εἶμεν, εἴ τις ὑμῶν μὴ οἴεται ἔσεσθαι, γνώμης ἁμαρτάνει καὶ οὐκ αἰσθάνεται τοὺς Λακεδαιμονίους φόβῳ τῷ ὑμετέρῳ πολεμησείοντας καὶ τοὺς Κορινθίους δυναμένους παρ’ αὐτοῖς καὶ ὑμῖν ἐχθροὺς ὄντας καὶ προκαταλαμβάνοντας ἡμᾶς νῦν ἐς τὴν ὑμετέραν ἐπιχείρησιν, ἵνα μὴ τῷ κοινῷ ἔχθει κατ’ αὐτοὺς μετ’ ἀλλήλων στῶμεν μηδὲ δυοῖν φθάσαι ἁμάρτωσιν, ἢ κακῶσαι ἡμᾶς ἢ σφᾶς αὐτοὺς βεβαιώσασθαι. ἡμέτερον δέ γ’ αὖ ἔργον προτερῆσαι, τῶν μὲν διδόντων, ὑμῶν δὲ δεξαμένων τὴν ξυμμαχίαν, καὶ προεπιβουλεύειν αὐτοῖς μᾶλλον ἢ ἀντεπιβουλεύειν.", "st": "1.33"}, {"sp": "N", "t": "‘ἢν δὲ λέγωσιν ὡς οὐ δίκαιον τοὺς σφετέρους ἀποίκους ὑμᾶς δέχεσθαι, μαθόντων ὡς πᾶσα ἀποικία εὖ μὲν πάσχουσα τιμᾷ τὴν μητρόπολιν, ἀδικουμένη δὲ ἀλλοτριοῦται· οὐ γὰρ ἐπὶ τῷ δοῦλοι, ἀλλ’ ἐπὶ τῷ ὁμοῖοι τοῖς λειπομένοις εἶναι ἐκπέμπονται. ὡς δὲ ἠδίκουν σαφές ἐστιν· προκληθέντες γὰρ περὶ Ἐπιδάμνου ἐς κρίσιν πολέμῳ μᾶλλον ἢ τῷ ἴσῳ ἐβουλήθησαν τὰ ἐγκλήματα μετελθεῖν. καὶ ὑμῖν ἔστω τι τεκμήριον ἃ πρὸς ἡμᾶς τοὺς ξυγγενεῖς δρῶσιν, ὥστε ἀπάτῃ τε μὴ παράγεσθαι ὑπ’ αὐτῶν δεομένοις τε ἐκ τοῦ εὐθέος μὴ ὑπουργεῖν· ὁ γὰρ ἐλαχίστας τὰς μεταμελείας ἐκ τοῦ χαρίζεσθαι τοῖς ἐναντίοις λαμβάνων ἀσφαλέστατος ἂν διατελοίη.", "st": "1.34"}, {"sp": "N", "t": "λύσετε δὲ οὐδὲ τὰς Λακεδαιμονίων σπονδὰς δεχόμενοι ἡμᾶς μηδετέρων ὄντας ξυμμάχους· εἴρηται γὰρ ἐν αὐταῖς, τῶν Ἑλληνίδων πόλεων ἥτις μηδαμοῦ ξυμμαχεῖ, ἐξεῖναι παρ’ ὁποτέρους ἂν ἀρέσκηται ἐλθεῖν. καὶ δεινὸν εἰ τοῖσδε μὲν ἀπό τε τῶν ἐνσπόνδων ἔσται πληροῦν τὰς ναῦς καὶ προσέτι καὶ ἐκ τῆς ἄλλης Ἑλλάδος καὶ οὐχ ἥκιστα ἀπὸ τῶν ὑμετέρων ὑπηκόων, ἡμᾶς δὲ ἀπὸ τῆς προκειμένης τε ξυμμαχίας εἴρξουσι καὶ ἀπὸ τῆς ἄλλοθέν ποθεν ὠφελίας, εἶτα ἐν ἀδικήματι θήσονται πεισθέντων ὑμῶν ἃ δεόμεθα. πολὺ δὲ ἐν πλέονι αἰτίᾳ ἡμεῖς μὴ πείσαντες ὑμᾶς ἕξομεν· ἡμᾶς μὲν γὰρ κινδυνεύοντας καὶ οὐκ ἐχθροὺς ὄντας ἀπώσεσθε, τῶνδε δὲ οὐχ ὅπως κωλυταὶ ἐχθρῶν ὄντων καὶ ἐπιόντων γενήσεσθε, ἀλλὰ καὶ ἀπὸ τῆς ὑμετέρας ἀρχῆς δύναμιν προσλαβεῖν περιόψεσθε· ἣν οὐ δίκαιον, ἀλλ’ ἢ κἀκείνων κωλύειν τοὺς ἐκ τῆς ὑμετέρας μισθοφόρους ἢ καὶ ἡμῖν πέμπειν καθ’ ὅτι ἂν πεισθῆτε ὠφελίαν, μάλιστα δὲ ἀπὸ τοῦ προφανοῦς δεξαμένους βοηθεῖν. πολλὰ δέ, ὥσπερ ἐν ἀρχῇ ὑπείπομεν, τὰ ξυμφέροντα ἀποδείκνυμεν, καὶ μέγιστον ὅτι οἵ τε αὐτοὶ πολέμιοι ἡμῖν ἦσαν, ὅπερ σαφεστάτη πίστις, καὶ οὗτοι οὐκ ἀσθενεῖς, ἀλλ’ ἱκανοὶ τοὺς μεταστάντας βλάψαι· καὶ ναυτικῆς καὶ οὐκ ἠπειρώτιδος τῆς ξυμμαχίας διδομένης οὐχ ὁμοία ἡ ἀλλοτρίωσις, ἀλλὰ μάλιστα μέν, εἰ δύνασθε, μηδένα ἄλλον ἐᾶν κεκτῆσθαι ναῦς, εἰ δὲ μή, ὅστις ἐχυρώτατος, τοῦτον φίλον ἔχειν.", "st": "1.35"}, {"sp": "N", "t": "‘καὶ ὅτῳ τάδε ξυμφέροντα μὲν δοκεῖ λέγεσθαι, φοβεῖται δὲ μὴ δι’ αὐτὰ πειθόμενος τὰς σπονδὰς λύσῃ, γνώτω τὸ μὲν δεδιὸς αὐτοῦ ἰσχὺν ἔχον τοὺς ἐναντίους μᾶλλον φοβῆσον, τὸ δὲ θαρσοῦν μὴ δεξαμένου ἀσθενὲς ὂν πρὸς ἰσχύοντας τοὺς ἐχθροὺς ἀδεέστερον ἐσόμενον, καὶ ἅμα οὐ περὶ τῆς Κερκύρας νῦν τὸ πλέον ἢ καὶ τῶν Ἀθηνῶν βουλευόμενος, καὶ οὐ τὰ κράτιστα αὐταῖς προνοῶν, ὅταν ἐς τὸν μέλλοντα καὶ ὅσον οὐ παρόντα πόλεμον τὸ αὐτίκα περισκοπῶν ἐνδοιάζῃ χωρίον προσλαβεῖν ὃ μετὰ μεγίστων καιρῶν οἰκειοῦταί τε καὶ πολεμοῦται. τῆς τε γὰρ Ἰταλίας καὶ Σικελίας καλῶς παράπλου κεῖται, ὥστε μήτε ἐκεῖθεν ναυτικὸν ἐᾶσαι Πελοποννησίοις ἐπελθεῖν τό τε ἐνθένδε πρὸς τἀκεῖ παραπέμψαι, καὶ ἐς τἆλλα ξυμφορώτατόν ἐστιν. βραχυτάτῳ δ’ ἂν κεφαλαίῳ, τοῖς τε ξύμπασι καὶ καθ’ ἕκαστον, τῷδ’ ἂν μὴ προέσθαι ἡμᾶς μάθοιτε· τρία μὲν ὄντα λόγου ἄξια τοῖς Ἕλλησι ναυτικά, τὸ παρ’ ὑμῖν καὶ τὸ ἡμέτερον καὶ τὸ Κορινθίων· τούτων δὲ εἰ περιόψεσθε τὰ δύο ἐς ταὐτὸν ἐλθεῖν καὶ Κορίνθιοι ἡμᾶς προκαταλήψονται, Κερκυραίοις τε καὶ Πελοποννησίοις ἅμα ναυμαχήσετε, δεξάμενοι δὲ ἡμᾶς ἕξετε πρὸς αὐτοὺς πλείοσι ναυσὶ ταῖς ἡμετέραις ἀγωνίζεσθαι.’ τοιαῦτα μὲν οἱ Κερκυραῖοι εἶπον· οἱ δὲ Κορίνθιοι μετ’ αὐτοὺς τοιάδε.", "st": "1.36"}, {"sp": "N", "t": "‘ἀναγκαῖον Κερκυραίων τῶνδε οὐ μόνον περὶ τοῦ δέξασθαι σφᾶς τὸν λόγον ποιησαμένων, ἀλλ’ ὡς καὶ ἡμεῖς τε ἀδικοῦμεν καὶ αὐτοὶ οὐκ εἰκότως πολεμοῦνται, μνησθέντας πρῶτον καὶ ἡμᾶς περὶ ἀμφοτέρων οὕτω καὶ ἐπὶ τὸν ἄλλον λόγον ἰέναι, ἵνα τὴν ἀφ’ ἡμῶν τε ἀξίωσιν ἀσφαλέστερον προειδῆτε καὶ τὴν τῶνδε χρείαν μὴ ἀλογίστως ἀπώσησθε.", "st": "1.37"}, {"sp": "N", "t": "‘φασὶ δὲ ξυμμαχίαν διὰ τὸ σῶφρον οὐδενός πω δέξασθαι· τὸ δ’ ἐπὶ κακουργίᾳ καὶ οὐκ ἀρετῇ ἐπετήδευσαν, ξύμμαχόν τε οὐδένα βουλόμενοι πρὸς τἀδικήματα οὐδὲ μάρτυρα ἔχειν οὔτε παρακαλοῦντες αἰσχύνεσθαι. καὶ ἡ πόλις αὐτῶν ἅμα αὐτάρκη θέσιν κειμένη παρέχει αὐτοὺς δικαστὰς ὧν βλάπτουσί τινα μᾶλλον ἢ κατὰ ξυνθήκας γίγνεσθαι, διὰ τὸ ἥκιστα ἐπὶ τοὺς πέλας ἐκπλέοντας μάλιστα τοὺς ἄλλους ἀνάγκῃ καταίροντας δέχεσθαι. καὶ τοῦτο τὸ εὐπρεπὲς ἄσπονδον οὐχ ἵνα μὴ ξυναδικῶσιν ἑτέροις προβέβληνται, ἀλλ’ ὅπως κατὰ μόνας ἀδικῶσι καὶ ὅπως ἐν ᾧ μὲν ἂν κρατῶσι βιάζωνται, οὗ δ’ ἂν λάθωσι πλέον ἔχωσιν, ἢν δέ πού τι προσλάβωσιν ἀναισχυντῶσιν· καίτοι εἰ ἦσαν ἄνδρες, ὥσπερ φασίν, ἀγαθοί, ὅσῳ ἀληπτότεροι ἦσαν τοῖς πέλας, τόσῳ δὲ φανερωτέραν ἐξῆν αὐτοῖς τὴν ἀρετὴν διδοῦσι καὶ δεχομένοις τὰ δίκαια δεικνύναι.", "st": "1.37"}, {"sp": "N", "t": "ἀλλ’ οὔτε πρὸς τοὺς ἄλλους οὔτε ἐς ἡμᾶς τοιοίδε εἰσίν, ἄποικοι δ’ ὄντες ἀφεστᾶσί τε διὰ παντὸς καὶ νῦν πολεμοῦσι, λέγοντες ὡς οὐκ ἐπὶ τῷ κακῶς πάσχειν ἐκπεμφθεῖεν. ἡμεῖς δὲ οὐδ’ αὐτοί φαμεν ἐπὶ τῷ ὑπὸ τούτων ὑβρίζεσθαι κατοικίσαι, ἀλλ’ ἐπὶ τῷ ἡγεμόνες τε εἶναι καὶ τὰ εἰκότα θαυμάζεσθαι. αἱ γοῦν ἄλλαι ἀποικίαι τιμῶσιν ἡμᾶς, καὶ μάλιστα ὑπὸ ἀποίκων στεργόμεθα· καὶ δῆλον ὅτι, εἰ τοῖς πλέοσιν ἀρέσκοντές ἐσμεν, τοῖσδ’ ἂν μόνοις οὐκ ὀρθῶς ἀπαρέσκοιμεν, οὐδ’ ἐπιστρατεύομεν ἐκπρεπῶς μὴ καὶ διαφερόντως τι ἀδικούμενοι. καλὸν δ’ ἦν, εἰ καὶ ἡμαρτάνομεν, τοῖσδε μὲν εἶξαι τῇ ἡμετέρᾳ ὀργῇ, ἡμῖν δὲ αἰσχρὸν βιάσασθαι τὴν τούτων μετριότητα· ὕβρει δὲ καὶ ἐξουσίᾳ πλούτου πολλὰ ἐς ἡμᾶς ἄλλα τε ἡμαρτήκασι καὶ Ἐπίδαμνον ἡμετέραν οὖσαν κακουμένην μὲν οὐ προσεποιοῦντο, ἐλθόντων δὲ ἡμῶν ἐπὶ τιμωρίᾳ ἑλόντες βίᾳ ἔχουσιν.", "st": "1.38"}, {"sp": "N", "t": "‘καὶ φασὶ δὴ δίκῃ πρότερον ἐθελῆσαι κρίνεσθαι, ἥν γε οὐ τὸν προύχοντα καὶ ἐκ τοῦ ἀσφαλοῦς προκαλούμενον λέγειν τι δοκεῖν δεῖ, ἀλλὰ τὸν ἐς ἴσον τά τε ἔργα ὁμοίως καὶ τοὺς λόγους πρὶν διαγωνίζεσθαι καθιστάντα. οὗτοι δὲ οὐ πρὶν πολιορκεῖν τὸ χωρίον, ἀλλ’ ἐπειδὴ ἡγήσαντο ἡμᾶς οὐ περιόψεσθαι, τότε καὶ τὸ εὐπρεπὲς τῆς δίκης παρέσχοντο. καὶ δεῦρο ἥκουσιν οὐ τἀκεῖ μόνον αὐτοὶ ἁμαρτόντες, ἀλλὰ καὶ ὑμᾶς νῦν ἀξιοῦντες οὐ ξυμμαχεῖν, ἀλλὰ ξυναδικεῖν καὶ διαφόρους ὄντας ἡμῖν δέχεσθαι σφᾶς· οὓς χρῆν, ὅτε ἀσφαλέστατοι ἦσαν, τότε προσιέναι, καὶ μὴ ἐν ᾧ ἡμεῖς μὲν ἠδικήμεθα, οὗτοι δὲ κινδυνεύουσι, μηδ’ ἐν ᾧ ὑμεῖς τῆς τε δυνάμεως αὐτῶν τότε οὐ μεταλαβόντες τῆς ὠφελίας νῦν μεταδώσετε καὶ τῶν ἁμαρτημάτων ἀπογενόμενοι τῆς ἀφ’ ἡμῶν αἰτίας τὸ ἴσον ἕξετε, πάλαι δὲ κοινώσαντας τὴν δύναμιν κοινὰ καὶ τὰ ἀποβαίνοντα ἔχειν.", "st": "1.39"}, {"sp": "N", "t": "‘ὡς μὲν οὖν αὐτοί τε μετὰ προσηκόντων ἐγκλημάτων ἐρχόμεθα καὶ οἵδε βίαιοι καὶ πλεονέκται εἰσὶ δεδήλωται· ὡς δὲ οὐκ ἂν δικαίως αὐτοὺς δέχοισθε μαθεῖν χρή. εἰ γὰρ εἴρηται ἐν ταῖς σπονδαῖς ἐξεῖναι παρ’ ὁποτέρους τις βούλεται τῶν ἀγράφων πόλεων ἐλθεῖν, οὐ τοῖς ἐπὶ βλάβῃ ἑτέρων ἰοῦσιν ἡ ξυνθήκη ἐστίν, ἀλλ’ ὅστις μὴ ἄλλου ἑαυτὸν ἀποστερῶν ἀσφαλείας δεῖται καὶ ὅστις μὴ τοῖς δεξαμένοις, εἰ σωφρονοῦσι, πόλεμον ἀντ’ εἰρήνης ποιήσει· ὃ νῦν ὑμεῖς μὴ πειθόμενοι ἡμῖν πάθοιτε ἄν. οὐ γὰρ τοῖσδε μόνον ἐπίκουροι ἂν γένοισθε, ἀλλὰ καὶ ἡμῖν ἀντὶ ἐνσπόνδων πολέμιοι· ἀνάγκη γάρ, εἰ ἴτε μετ’ αὐτῶν, καὶ ἀμύνεσθαι μὴ ἄνευ ὑμῶν τούτους. καίτοι δίκαιοί γ’ ἐστὲ μάλιστα μὲν ἐκποδὼν στῆναι ἀμφοτέροις, εἰ δὲ μή, τοὐναντίον ἐπὶ τούτους μεθ’ ἡμῶν ἰέναι (Κορινθίοις μέν γε ἔνσπονδοί ἐστε, Κερκυραίοις δὲ οὐδὲ δι’ ἀνοκωχῆς πώποτ’ ἐγένεσθε), καὶ τὸν νόμον μὴ καθιστάναι ὥστε τοὺς ἑτέρων ἀφισταμένους δέχεσθαι. οὐδὲ γὰρ ἡμεῖς Σαμίων ἀποστάντων ψῆφον προσεθέμεθα ἐναντίαν ὑμῖν, τῶν ἄλλων Πελοποννησίων δίχα ἐψηφισμένων εἰ χρὴ αὐτοῖς ἀμύνειν, φανερῶς δὲ ἀντείπομεν τοὺς προσήκοντας ξυμμάχους αὐτόν τινα κολάζειν. εἰ γὰρ τοὺς κακόν τι δρῶντας δεχόμενοι τιμωρήσετε, φανεῖται καὶ ἃ τῶν ὑμετέρων οὐκ ἐλάσσω ἡμῖν πρόσεισι, καὶ τὸν νόμον ἐφ’ ὑμῖν αὐτοῖς μᾶλλον ἢ ἐφ’ ἡμῖν θήσετε.", "st": "1.40"}, {"sp": "N", "t": "‘δικαιώματα μὲν οὖν τάδε πρὸς ὑμᾶς ἔχομεν ἱκανὰ κατὰ τοὺς Ἑλλήνων νόμους, παραίνεσιν δὲ καὶ ἀξίωσιν χάριτος τοιάνδε, ἣν οὐκ ἐχθροὶ ὄντες ὥστε βλάπτειν οὐδ’ αὖ φίλοι ὥστ’ ἐπιχρῆσθαι, ἀντιδοθῆναι ἡμῖν ἐν τῷ παρόντι φαμὲν χρῆναι. νεῶν γὰρ μακρῶν σπανίσαντές ποτε πρὸς τὸν Αἰγινητῶν ὑπὲρ τὰ Μηδικὰ πόλεμον παρὰ Κορινθίων εἴκοσι ναῦς ἐλάβετε· καὶ ἡ εὐεργεσία αὕτη τε καὶ ἡ ἐς Σαμίους, τὸ δι’ ἡμᾶς Πελοποννησίους αὐτοῖς μὴ βοηθῆσαι, παρέσχεν ὑμῖν Αἰγινητῶν μὲν ἐπικράτησιν, Σαμίων δὲ κόλασιν, καὶ ἐν καιροῖς τοιούτοις ἐγένετο οἷς μάλιστα ἄνθρωποι ἐπ’ ἐχθροὺς τοὺς σφετέρους ἰόντες τῶν ἁπάντων ἀπερίοπτοί εἰσι παρὰ τὸ νικᾶν· φίλον τε γὰρ ἡγοῦνται τὸν ὑπουργοῦντα, ἢν καὶ πρότερον ἐχθρὸς ᾖ, πολέμιόν τε τὸν ἀντιστάντα, ἢν καὶ τύχῃ φίλος ὤν, ἐπεὶ καὶ τὰ οἰκεῖα χεῖρον τίθενται φιλονικίας ἕνεκα τῆς αὐτίκα.", "st": "1.41"}, {"sp": "N", "t": "‘ὧν ἐνθυμηθέντες καὶ νεώτερός τις παρὰ πρεσβυτέρου αὐτὰ μαθὼν ἀξιούτω τοῖς ὁμοίοις ἡμᾶς ἀμύνεσθαι, καὶ μὴ νομίσῃ δίκαια μὲν τάδε λέγεσθαι, ξύμφορα δέ, εἰ πολεμήσει, ἄλλα εἶναι. τό τε γὰρ ξυμφέρον ἐν ᾧ ἄν τις ἐλάχιστα ἁμαρτάνῃ μάλιστα ἕπεται, καὶ τὸ μέλλον τοῦ πολέμου ᾧ φοβοῦντες ὑμᾶς Κερκυραῖοι κελεύουσιν ἀδικεῖν ἐν ἀφανεῖ ἔτι κεῖται, καὶ οὐκ ἄξιον ἐπαρθέντας αὐτῷ φανερὰν ἔχθραν ἤδη καὶ οὐ μέλλουσαν πρὸς Κορινθίους κτήσασθαι, τῆς δὲ ὑπαρχούσης πρότερον διὰ Μεγαρέας ὑποψίας σῶφρον ὑφελεῖν μᾶλλον (ἡ γὰρ τελευταία χάρις καιρὸν ἔχουσα, κἂν ἐλάσσων ᾖ, δύναται μεῖζον ἔγκλημα λῦσαι), μηδ’ ὅτι ναυτικοῦ ξυμμαχίαν μεγάλην διδόασι, τούτῳ ἐφέλκεσθαι· τὸ γὰρ μὴ ἀδικεῖν τοὺς ὁμοίους ἐχυρωτέρα δύναμις ἢ τῷ αὐτίκα φανερῷ ἐπαρθέντας διὰ κινδύνων τὸ πλέον ἔχειν.", "st": "1.42"}, {"sp": "N", "t": "ἡμεῖς δὲ περιπεπτωκότες οἷς ἐν τῇ Λακεδαίμονι αὐτοὶ προείπομεν, τοὺς σφετέρους ξυμμάχους αὐτόν τινα κολάζειν, νῦν παρ’ ὑμῶν τὸ αὐτὸ ἀξιοῦμεν κομίζεσθαι, καὶ μὴ τῇ ἡμετέρᾳ ψήφῳ ὠφεληθέντας τῇ ὑμετέρᾳ ἡμᾶς βλάψαι. τὸ δὲ ἴσον ἀνταπόδοτε, γνόντες τοῦτον ἐκεῖνον εἶναι τὸν καιρὸν ἐν ᾧ ὅ τε ὑπουργῶν φίλος μάλιστα καὶ ὁ ἀντιστὰς ἐχθρός. καὶ Κερκυραίους τούσδε μήτε ξυμμάχους δέχεσθε βίᾳ ἡμῶν μήτε ἀμύνετε αὐτοῖς ἀδικοῦσιν. καὶ τάδε ποιοῦντες τὰ προσήκοντά τε δράσετε καὶ τὰ ἄριστα βουλεύσεσθε ὑμῖν αὐτοῖς.’", "st": "1.43"}, {"sp": "N", "t": "τοιαῦτα δὲ καὶ οἱ Κορίνθιοι εἶπον. Ἀθηναῖοι δὲ ἀκούσαντες ἀμφοτέρων, γενομένης καὶ δὶς ἐκκλησίας, τῇ μὲν προτέρᾳ οὐχ ἧσσον τῶν Κορινθίων ἀπεδέξαντο τοὺς λόγους, ἐν δὲ τῇ ὑστεραίᾳ μετέγνωσαν Κερκυραίοις ξυμμαχίαν μὲν μὴ ποιήσασθαι ὥστε τοὺς αὐτοὺς ἐχθροὺς καὶ φίλους νομίζειν (εἰ γὰρ ἐπὶ Κόρινθον ἐκέλευον σφίσιν οἱ Κερκυραῖοι ξυμπλεῖν, ἐλύοντ’ ἂν αὐτοῖς αἱ πρὸς Πελοποννησίους σπονδαί), ἐπιμαχίαν δ’ ἐποιήσαντο τῇ ἀλλήλων βοηθεῖν, ἐάν τις ἐπὶ Κέρκυραν ἴῃ ἢ Ἀθήνας ἢ τοὺς τούτων ξυμμάχους. ἐδόκει γὰρ ὁ πρὸς Πελοποννησίους πόλεμος καὶ ὣς ἔσεσθαι αὐτοῖς, καὶ τὴν Κέρκυραν ἐβούλοντο μὴ προέσθαι τοῖς Κορινθίοις ναυτικὸν ἔχουσαν τοσοῦτον, ξυγκρούειν δὲ ὅτι μάλιστα αὐτοὺς ἀλλήλοις, ἵνα ἀσθενεστέροις οὖσιν, ἤν τι δέῃ, Κορινθίοις τε καὶ τοῖς ἄλλοις ναυτικὸν ἔχουσιν ἐς πόλεμον καθιστῶνται. ἅμα δὲ τῆς τε Ἰταλίας καὶ Σικελίας καλῶς ἐφαίνετο αὐτοῖς ἡ νῆσος ἐν παράπλῳ κεῖσθαι.", "st": "1.44"}, {"sp": "N", "t": "τοιαύτῃ μὲν γνώμῃ οἱ Ἀθηναῖοι τοὺς Κερκυραίους προσεδέξαντο, καὶ τῶν Κορινθίων ἀπελθόντων οὐ πολὺ ὕστερον δέκα ναῦς αὐτοῖς ἀπέστειλαν βοηθούς· ἐστρατήγει δὲ αὐτῶν Λακεδαιμόνιός τε ὁ Κίμωνος καὶ Διότιμος ὁ Στρομβίχου καὶ Πρωτέας ὁ Ἐπικλέους. προεῖπον δὲ αὐτοῖς μὴ ναυμαχεῖν Κορινθίοις, ἢν μὴ ἐπὶ Κέρκυραν πλέωσι καὶ μέλλωσιν ἀποβαίνειν ἢ ἐς τῶν ἐκείνων τι χωρίων· οὕτω δὲ κωλύειν κατὰ δύναμιν. προεῖπον δὲ ταῦτα τοῦ μὴ λύειν ἕνεκα τὰς σπονδάς.", "st": "1.45"}, {"sp": "N", "t": "αἱ μὲν δὴ νῆες ἀφικνοῦνται ἐς τὴν Κέρκυραν, οἱ δὲ Κορίνθιοι, ἐπειδὴ αὐτοῖς παρεσκεύαστο, ἔπλεον ἐπὶ τὴν Κέρκυραν ναυσὶ πεντήκοντα καὶ ἑκατόν. ἦσαν δὲ Ἠλείων μὲν δέκα, Μεγαρέων δὲ δώδεκα καὶ Λευκαδίων δέκα, Ἀμπρακιωτῶν δὲ ἑπτὰ καὶ εἴκοσι καὶ Ἀνακτορίων μία, αὐτῶν δὲ Κορινθίων ἐνενήκοντα· στρατηγοὶ δὲ τούτων ἦσαν μὲν καὶ κατὰ πόλεις ἑκάστων, Κορινθίων δὲ Ξενοκλείδης ὁ Εὐθυκλέους πέμπτος αὐτός. ἐπειδὴ δὲ προσέμειξαν τῇ κατὰ Κέρκυραν ἠπείρῳ ἀπὸ Λευκάδος πλέοντες, ὁρμίζονται ἐς Χειμέριον τῆς Θεσπρωτίδος γῆς. ἔστι δὲ λιμήν, καὶ πόλις ὑπὲρ αὐτοῦ κεῖται ἀπὸ θαλάσσης ἐν τῇ Ἐλαιάτιδι τῆς Θεσπρωτίδος Ἐφύρη. ἐξίησι δὲ παρ’ αὐτὴν Ἀχερουσία λίμνη ἐς θάλασσαν· διὰ δὲ τῆς Θεσπρωτίδος Ἀχέρων ποταμὸς ῥέων ἐσβάλλει ἐς αὐτήν, ἀφ’ οὗ καὶ τὴν ἐπωνυμίαν ἔχει. ῥεῖ δὲ καὶ Θύαμις ποταμός, ὁρίζων τὴν Θεσπρωτίδα καὶ Κεστρίνην, ὧν ἐντὸς ἡ ἄκρα ἀνέχει τὸ Χειμέριον. οἱ μὲν οὖν Κορίνθιοι τῆς ἠπείρου ἐνταῦθα ὁρμίζονταί τε καὶ στρατόπεδον ἐποιήσαντο.", "st": "1.46"}, {"sp": "N", "t": "οἱ δὲ Κερκυραῖοι ὡς ᾔσθοντο αὐτοὺς προσπλέοντας, πληρώσαντες δέκα καὶ ἑκατὸν ναῦς, ὧν ἦρχε Μικιάδης καὶ Αἰσιμίδης καὶ Εὐρύβατος, ἐστρατοπεδεύσαντο ἐν μιᾷ τῶν νήσων αἳ καλοῦνται Σύβοτα· καὶ αἱ Ἀττικαὶ δέκα παρῆσαν. ἐπὶ δὲ τῇ Λευκίμμῃ αὐτοῖς τῷ ἀκρωτηρίῳ ὁ πεζὸς ἦν καὶ Ζακυνθίων χίλιοι ὁπλῖται βεβοηθηκότες. ἦσαν δὲ καὶ τοῖς Κορινθίοις ἐν τῇ ἠπείρῳ πολλοὶ τῶν βαρβάρων παραβεβοηθηκότες· οἱ γὰρ ταύτῃ ἠπειρῶται αἰεί ποτε αὐτοῖς φίλοι εἰσίν.", "st": "1.47"}, {"sp": "N", "t": "ἐπειδὴ δὲ παρεσκεύαστο τοῖς Κορινθίοις, λαβόντες τριῶν ἡμερῶν σιτία ἀνήγοντο ὡς ἐπὶ ναυμαχίαν ἀπὸ τοῦ Χειμερίου νυκτός, καὶ ἅμα ἕῳ πλέοντες καθορῶσι τὰς τῶν Κερκυραίων ναῦς μετεώρους τε καὶ ἐπὶ σφᾶς πλεούσας. ὡς δὲ κατεῖδον ἀλλήλους, ἀντιπαρετάσσοντο, ἐπὶ μὲν τὸ δεξιὸν κέρας Κερκυραίων αἱ Ἀττικαὶ νῆες, τὸ δὲ ἄλλο αὐτοὶ ἐπεῖχον τρία τέλη ποιήσαντες τῶν νεῶν, ὧν ἦρχε ⟨τῶν⟩ τριῶν στρατηγῶν ἑκάστου εἷς. οὕτω μὲν Κερκυραῖοι ἐτάξαντο, Κορινθίοις δὲ τὸ μὲν δεξιὸν κέρας αἱ Μεγαρίδες νῆες εἶχον καὶ αἱ Ἀμπρακιώτιδες, κατὰ δὲ τὸ μέσον οἱ ἄλλοι ξύμμαχοι ὡς ἕκαστοι· εὐώνυμον δὲ κέρας αὐτοὶ οἱ Κορίνθιοι ταῖς ἄριστα τῶν νεῶν πλεούσαις κατὰ τοὺς Ἀθηναίους καὶ τὸ δεξιὸν τῶν Κερκυραίων εἶχον.", "st": "1.48"}, {"sp": "N", "t": "ξυμμείξαντες δέ, ἐπειδὴ τὰ σημεῖα ἑκατέροις ἤρθη, ἐναυμάχουν, πολλοὺς μὲν ὁπλίτας ἔχοντες ἀμφότεροι ἐπὶ τῶν καταστρωμάτων, πολλοὺς δὲ τοξότας τε καὶ ἀκοντιστάς, τῷ παλαιῷ τρόπῳ ἀπειρότερον ἔτι παρεσκευασμένοι. ἦν τε ἡ ναυμαχία καρτερά, τῇ μὲν τέχνῃ οὐχ ὁμοίως, πεζομαχίᾳ δὲ τὸ πλέον προσφερὴς οὖσα. ἐπειδὴ γὰρ προσβάλοιεν ἀλλήλοις, οὐ ῥᾳδίως ἀπελύοντο ὑπό τε τοῦ πλήθους καὶ ὄχλου τῶν νεῶν, καὶ μᾶλλόν τι πιστεύοντες τοῖς ἐπὶ τοῦ καταστρώματος ὁπλίταις ἐς τὴν νίκην, οἳ καταστάντες ἐμάχοντο ἡσυχαζουσῶν τῶν νεῶν· διέκπλοι δ’ οὐκ ἦσαν, ἀλλὰ θυμῷ καὶ ῥώμῃ τὸ πλέον ἐναυμάχουν ἢ ἐπιστήμῃ. πανταχῇ μὲν οὖν πολὺς θόρυβος καὶ ταραχώδης ἦν ἡ ναυμαχία, ἐν ᾗ αἱ Ἀττικαὶ νῆες παραγιγνόμεναι τοῖς Κερκυραίοις, εἴ πῃ πιέζοιντο, φόβον μὲν παρεῖχον τοῖς ἐναντίοις, μάχης δὲ οὐκ ἦρχον δεδιότες οἱ στρατηγοὶ τὴν πρόρρησιν τῶν Ἀθηναίων. μάλιστα δὲ τὸ δεξιὸν κέρας τῶν Κορινθίων ἐπόνει· οἱ γὰρ Κερκυραῖοι εἴκοσι ναυσὶν αὐτοὺς τρεψάμενοι καὶ καταδιώξαντες σποράδας ἐς τὴν ἤπειρον καὶ μέχρι τοῦ στρατοπέδου πλεύσαντες αὐτῶν καὶ ἐπεκβάντες ἐνέπρησάν τε τὰς σκηνὰς ἐρήμους καὶ τὰ χρήματα διήρπασαν. ταύτῃ μὲν οὖν οἱ Κορίνθιοι καὶ οἱ ξύμμαχοι ἡσσῶντό [τε] καὶ οἱ Κερκυραῖοι ἐπεκράτουν· ᾗ δὲ αὐτοὶ ἦσαν οἱ Κορίνθιοι, ἐπὶ τῷ εὐωνύμῳ, πολὺ ἐνίκων, τοῖς Κερκυραίοις τῶν εἴκοσι νεῶν ἀπὸ ἐλάσσονος πλήθους ἐκ τῆς διώξεως οὐ παρουσῶν. οἱ δὲ Ἀθηναῖοι ὁρῶντες τοὺς Κερκυραίους πιεζομένους μᾶλλον ἤδη ἀπροφασίστως ἐπεκούρουν, τὸ μὲν πρῶτον ἀπεχόμενοι ὥστε μὴ ἐμβάλλειν τινί· ἐπειδὴ δὲ ἡ τροπὴ ἐγίγνετο λαμπρῶς καὶ ἐνέκειντο οἱ Κορίνθιοι, τότε δὴ ἔργου πᾶς εἴχετο ἤδη καὶ διεκέκριτο οὐδὲν ἔτι, ἀλλὰ ξυνέπεσεν ἐς τοῦτο ἀνάγκης ὥστε ἐπιχειρῆσαι ἀλλήλοις τοὺς Κορινθίους καὶ Ἀθηναίους.", "st": "1.49"}, {"sp": "N", "t": "τῆς δὲ τροπῆς γενομένης οἱ Κορίνθιοι τὰ σκάφη μὲν οὐχ εἷλκον ἀναδούμενοι τῶν νεῶν ἃς καταδύσειαν, πρὸς δὲ τοὺς ἀνθρώπους ἐτράποντο φονεύειν διεκπλέοντες μᾶλλον ἢ ζωγρεῖν, τούς τε αὑτῶν φίλους, οὐκ ᾐσθημένοι ὅτι ἥσσηντο οἱ ἐπὶ τῷ δεξιῷ κέρᾳ, ἀγνοοῦντες ἔκτεινον. πολλῶν γὰρ νεῶν οὐσῶν ἀμφοτέρων καὶ ἐπὶ πολὺ τῆς θαλάσσης ἐπεχουσῶν, ἐπειδὴ ξυνέμειξαν ἀλλήλοις, οὐ ῥᾳδίως τὴν διάγνωσιν ἐποιοῦντο ὁποῖοι ἐκράτουν ἢ ἐκρατοῦντο· ναυμαχία γὰρ αὕτη Ἕλλησι πρὸς Ἕλληνας νεῶν πλήθει μεγίστη δὴ τῶν πρὸ αὑτῆς γεγένηται. ἐπειδὴ δὲ κατεδίωξαν τοὺς Κερκυραίους οἱ Κορίνθιοι ἐς τὴν γῆν, πρὸς τὰ ναυάγια καὶ τοὺς νεκροὺς τοὺς σφετέρους ἐτράποντο, καὶ τῶν πλείστων ἐκράτησαν ὥστε προσκομίσαι πρὸς τὰ Σύβοτα, οἷ αὐτοῖς ὁ κατὰ γῆν στρατὸς τῶν βαρβάρων προσεβεβοηθήκει· ἔστι δὲ τὰ Σύβοτα τῆς Θεσπρωτίδος λιμὴν ἐρῆμος. τοῦτο δὲ ποιήσαντες αὖθις ἁθροισθέντες ἐπέπλεον τοῖς Κερκυραίοις. οἱ δὲ ταῖς πλωίμοις καὶ ὅσαι ἦσαν λοιπαὶ μετὰ τῶν Ἀττικῶν νεῶν καὶ αὐτοὶ ἀντεπέπλεον, δείσαντες μὴ ἐς τὴν γῆν σφῶν πειρῶσιν ἀποβαίνειν. ἤδη δὲ ἦν ὀψὲ καὶ ἐπεπαιάνιστο αὐτοῖς ὡς ἐς ἐπίπλουν, καὶ οἱ Κορίνθιοι ἐξαπίνης πρύμναν ἐκρούοντο κατιδόντες εἴκοσι ναῦς Ἀθηναίων προσπλεούσας, ἃς ὕστερον τῶν δέκα βοηθοὺς ἐξέπεμψαν οἱ Ἀθηναῖοι, δείσαντες, ὅπερ ἐγένετο, μὴ νικηθῶσιν οἱ Κερκυραῖοι καὶ αἱ σφέτεραι δέκα νῆες ὀλίγαι ἀμύνειν ὦσιν.", "st": "1.50"}, {"sp": "N", "t": "ταύτας οὖν προϊδόντες οἱ Κορίνθιοι καὶ ὑποτοπήσαντες ἀπ’ Ἀθηνῶν εἶναι οὐχ ὅσας ἑώρων ἀλλὰ πλείους ὑπανεχώρουν. τοῖς δὲ Κερκυραίοις ἐπέπλεον γὰρ μᾶλλον ἐκ τοῦ ἀφανοῦς οὐχ ἑωρῶντο, καὶ ἐθαύμαζον τοὺς Κορινθίους πρύμναν κρουομένους, πρίν τινες ἰδόντες εἶπον ὅτι νῆες ἐκεῖναι ἐπιπλέουσιν. τότε δὲ καὶ αὐτοὶ ἀνεχώρουν· ξυνεσκόταζε γὰρ ἤδη, καὶ οἱ Κορίνθιοι ἀποτραπόμενοι τὴν διάλυσιν ἐποιήσαντο. οὕτω μὲν ἡ ἀπαλλαγὴ ἐγένετο ἀλλήλων, καὶ ἡ ναυμαχία ἐτελεύτα ἐς νύκτα. τοῖς δὲ Κερκυραίοις στρατοπεδευομένοις ἐπὶ τῇ Λευκίμμῃ αἱ εἴκοσι νῆες αἱ ἐκ τῶν Ἀθηνῶν αὗται, ὧν ἦρχε Γλαύκων τε ὁ Λεάγρου καὶ † Ἀνδοκίδης ὁ Λεωγόρου †, διὰ τῶν νεκρῶν καὶ ναυαγίων προσκομισθεῖσαι κατέπλεον ἐς τὸ στρατόπεδον οὐ πολλῷ ὕστερον ἢ ὤφθησαν. οἱ δὲ Κερκυραῖοι (ἦν γὰρ νύξ) ἐφοβήθησαν μὴ πολέμιαι ὦσιν, ἔπειτα δὲ ἔγνωσαν· καὶ ὡρμίσαντο.", "st": "1.51"}, {"sp": "N", "t": "τῇ δὲ ὑστεραίᾳ ἀναγαγόμεναι αἵ τε Ἀττικαὶ τριάκοντα νῆες καὶ τῶν Κερκυραίων ὅσαι πλώιμοι ἦσαν ἐπέπλευσαν ἐπὶ τὸν ἐν τοῖς Συβότοις λιμένα, ἐν ᾧ οἱ Κορίνθιοι ὥρμουν, βουλόμενοι εἰδέναι εἰ ναυμαχήσουσιν. οἱ δὲ τὰς μὲν ναῦς ἄραντες ἀπὸ τῆς γῆς καὶ παραταξάμενοι μετεώρους ἡσύχαζον, ναυμαχίας οὐ διανοούμενοι ἄρχειν ἑκόντες ὁρῶντες προσγεγενημένας τε ναῦς ἐκ τῶν Ἀθηνῶν ἀκραιφνεῖς καὶ σφίσι πολλὰ τὰ ἄπορα ξυμβεβηκότα, αἰχμαλώτων τε περὶ φυλακῆς οὓς ἐν ταῖς ναυσὶν εἶχον, καὶ ἐπισκευὴν οὐκ οὖσαν τῶν νεῶν ἐν χωρίῳ ἐρήμῳ· τοῦ δὲ οἴκαδε πλοῦ μᾶλλον διεσκόπουν ὅπῃ κομισθήσονται, δεδιότες μὴ οἱ Ἀθηναῖοι νομίσαντες λελύσθαι τὰς σπονδάς, διότι ἐς χεῖρας ἦλθον, οὐκ ἐῶσι σφᾶς ἀποπλεῖν.", "st": "1.52"}, {"sp": "N", "t": "ἔδοξεν οὖν αὐτοῖς ἄνδρας ἐς κελήτιον ἐσβιβάσαντας ἄνευ κηρυκείου προσπέμψαι τοῖς Ἀθηναίοις καὶ πεῖραν ποιήσασθαι. πέμψαντές τε ἔλεγον τοιάδε. ‘ἀδικεῖτε, ὦ ἄνδρες Ἀθηναῖοι, πολέμου ἄρχοντες καὶ σπονδὰς λύοντες· ἡμῖν γὰρ πολεμίους τοὺς ἡμετέρους τιμωρουμένοις ἐμποδὼν ἵστασθε ὅπλα ἀνταιρόμενοι. εἰ δ’ ὑμῖν γνώμη ἐστὶ κωλύειν τε ἡμᾶς ἐπὶ Κέρκυραν ἢ ἄλλοσε εἴ ποι βουλόμεθα πλεῖν καὶ τὰς σπονδὰς λύετε, ἡμᾶς τούσδε πρώτους λαβόντες χρήσασθε ὡς πολεμίοις.’ οἱ μὲν δὴ τοιαῦτα εἶπον· τῶν δὲ Κερκυραίων τὸ μὲν στρατόπεδον ὅσον ἐπήκουσεν ἀνεβόησεν εὐθὺς λαβεῖν τε αὐτοὺς καὶ ἀποκτεῖναι, οἱ δὲ Ἀθηναῖοι τοιάδε ἀπεκρίναντο. ‘οὔτε ἄρχομεν πολέμου, ὦ ἄνδρες Πελοποννήσιοι, οὔτε τὰς σπονδὰς λύομεν, Κερκυραίοις δὲ τοῖσδε ξυμμάχοις οὖσι βοηθοὶ ἤλθομεν. εἰ μὲν οὖν ἄλλοσέ ποι βούλεσθε πλεῖν, οὐ κωλύομεν· εἰ δὲ ἐπὶ Κέρκυραν πλευσεῖσθε ἢ ἐς τῶν ἐκείνων τι χωρίων, οὐ περιοψόμεθα κατὰ τὸ δυνατόν.’", "st": "1.53"}, {"sp": "N", "t": "τοιαῦτα τῶν Ἀθηναίων ἀποκριναμένων οἱ μὲν Κορίνθιοι τόν τε πλοῦν τὸν ἐπ’ οἴκου παρεσκευάζοντο καὶ τροπαῖον ἔστησαν ἐν τοῖς ἐν τῇ ἠπείρῳ Συβότοις· οἱ δὲ Κερκυραῖοι τά τε ναυάγια καὶ νεκροὺς ἀνείλοντο τὰ κατὰ σφᾶς ἐξενεχθέντα ὑπό τε τοῦ ῥοῦ καὶ ἀνέμου, ὃς γενόμενος τῆς νυκτὸς διεσκέδασεν αὐτὰ πανταχῇ, καὶ τροπαῖον ἀντέστησαν ἐν τοῖς ἐν τῇ νήσῳ Συβότοις ὡς νενικηκότες. γνώμῃ δὲ τοιᾷδε ἑκάτεροι τὴν νίκην προσεποιήσαντο· Κορίνθιοι μὲν κρατήσαντες τῇ ναυμαχίᾳ μέχρι νυκτός, ὥστε καὶ ναυάγια πλεῖστα καὶ νεκροὺς προσκομίσασθαι, καὶ ἄνδρας ἔχοντες αἰχμαλώτους οὐκ ἐλάσσους χιλίων ναῦς τε καταδύσαντες περὶ ἑβδομήκοντα ἔστησαν τροπαῖον· Κερκυραῖοι δὲ τριάκοντα ναῦς μάλιστα διαφθείραντες, καὶ ἐπειδὴ Ἀθηναῖοι ἦλθον, ἀνελόμενοι τὰ κατὰ σφᾶς αὐτοὺς ναυάγια καὶ νεκρούς, καὶ ὅτι αὐτοῖς τῇ τε προτεραίᾳ πρύμναν κρουόμενοι ὑπεχώρησαν οἱ Κορίνθιοι ἰδόντες τὰς Ἀττικὰς ναῦς, καὶ ἐπειδὴ ἦλθον οἱ Ἀθηναῖοι, οὐκ ἀντεπέπλεον ἐκ τῶν Συβότων, διὰ ταῦτα τροπαῖον ἔστησαν.", "st": "1.54"}, {"sp": "N", "t": "οὕτω μὲν ἑκάτεροι νικᾶν ἠξίουν· οἱ δὲ Κορίνθιοι ἀποπλέοντες ἐπ’ οἴκου Ἀνακτόριον, ὅ ἐστιν ἐπὶ τῷ στόματι τοῦ Ἀμπρακικοῦ κόλπου, εἷλον ἀπάτῃ (ἦν δὲ κοινὸν Κερκυραίων καὶ ἐκείνων) καὶ καταστήσαντες ἐν αὐτῷ Κορινθίους οἰκήτορας ἀνεχώρησαν ἐπ’ οἴκου, καὶ τῶν Κερκυραίων ὀκτακοσίους μὲν οἳ ἦσαν δοῦλοι ἀπέδοντο, πεντήκοντα δὲ καὶ διακοσίους δήσαντες ἐφύλασσον καὶ ἐν θεραπείᾳ εἶχον πολλῇ, ὅπως αὐτοῖς τὴν Κέρκυραν ἀναχωρήσαντες προσποιήσειαν· ἐτύγχανον δὲ καὶ δυνάμει αὐτῶν οἱ πλείους πρῶτοι ὄντες τῆς πόλεως. ἡ μὲν οὖν Κέρκυρα οὕτω περιγίγνεται τῷ πολέμῳ τῶν Κορινθίων, καὶ αἱ νῆες τῶν Ἀθηναίων ἀνεχώρησαν ἐξ αὐτῆς· αἰτία δὲ αὕτη πρώτη ἐγένετο τοῦ πολέμου τοῖς Κορινθίοις ἐς τοὺς Ἀθηναίους, ὅτι σφίσιν ἐν σπονδαῖς μετὰ Κερκυραίων ἐναυμάχουν.", "st": "1.55"}, {"sp": "N", "t": "μετὰ ταῦτα δ’ εὐθὺς καὶ τάδε ξυνέβη γενέσθαι τοῖς Ἀθηναίοις καὶ Πελοποννησίοις διάφορα ἐς τὸ πολεμεῖν. τῶν γὰρ Κορινθίων πρασσόντων ὅπως τιμωρήσονται αὐτούς, ὑποτοπήσαντες τὴν ἔχθραν αὐτῶν οἱ Ἀθηναῖοι Ποτειδεάτας, οἳ οἰκοῦσιν ἐπὶ τῷ ἰσθμῷ τῆς Παλλήνης, Κορινθίων ἀποίκους, ἑαυτῶν δὲ ξυμμάχους φόρου ὑποτελεῖς, ἐκέλευον τὸ ἐς Παλλήνην τεῖχος καθελεῖν καὶ ὁμήρους δοῦναι, τούς τε ἐπιδημιουργοὺς ἐκπέμπειν καὶ τὸ λοιπὸν μὴ δέχεσθαι οὓς κατὰ ἔτος ἕκαστον Κορίνθιοι ἔπεμπον, δείσαντες μὴ ἀποστῶσιν ὑπό τε Περδίκκου πειθόμενοι καὶ Κορινθίων, τούς τε ἄλλους τοὺς ἐπὶ Θρᾴκης ξυναποστήσωσι ξυμμάχους.", "st": "1.56"}, {"sp": "N", "t": "ταῦτα δὲ περὶ τοὺς Ποτειδεάτας οἱ Ἀθηναῖοι προπαρεσκευάζοντο εὐθὺς μετὰ τὴν ἐν Κερκύρᾳ ναυμαχίαν· οἵ τε γὰρ Κορίνθιοι φανερῶς ἤδη διάφοροι ἦσαν, Περδίκκας τε ὁ Ἀλεξάνδρου Μακεδόνων βασιλεὺς ἐπεπολέμωτο ξύμμαχος πρότερον καὶ φίλος ὤν. ἐπολεμώθη δὲ ὅτι Φιλίππῳ τῷ ἑαυτοῦ ἀδελφῷ καὶ Δέρδᾳ κοινῇ πρὸς αὐτὸν ἐναντιουμένοις οἱ Ἀθηναῖοι ξυμμαχίαν ἐποιήσαντο. δεδιώς τε ἔπρασσεν ἔς τε τὴν Λακεδαίμονα πέμπων ὅπως πόλεμος γένηται αὐτοῖς πρὸς Πελοποννησίους, καὶ τοὺς Κορινθίους προσεποιεῖτο τῆς Ποτειδαίας ἕνεκα ἀποστάσεως· προσέφερε δὲ λόγους καὶ τοῖς ἐπὶ Θρᾴκης Χαλκιδεῦσι καὶ Βοττιαίοις ξυναποστῆναι, νομίζων, εἰ ξύμμαχα ταῦτα ἔχοι ὅμορα ὄντα τὰ χωρία, ῥᾷον ἂν τὸν πόλεμον μετ’ αὐτῶν ποιεῖσθαι. ὧν οἱ Ἀθηναῖοι αἰσθόμενοι καὶ βουλόμενοι προκαταλαμβάνειν τῶν πόλεων τὰς ἀποστάσεις (ἔτυχον γὰρ τριάκοντα ναῦς ἀποστέλλοντες καὶ χιλίους ὁπλίτας ἐπὶ τὴν γῆν αὐτοῦ, Ἀρχεστράτου τοῦ Λυκομήδους μετ’ ἄλλων † δέκα † στρατηγοῦντος) ἐπιστέλλουσι τοῖς ἄρχουσι τῶν νεῶν Ποτειδεατῶν τε ὁμήρους λαβεῖν καὶ τὸ τεῖχος καθελεῖν, τῶν τε πλησίον πόλεων φυλακὴν ἔχειν ὅπως μὴ ἀποστήσονται.", "st": "1.57"}, {"sp": "N", "t": "Ποτειδεᾶται δὲ πέμψαντες μὲν καὶ παρ’ Ἀθηναίους πρέσβεις, εἴ πως πείσειαν μὴ σφῶν πέρι νεωτερίζειν μηδέν, ἐλθόντες δὲ καὶ ἐς τὴν Λακεδαίμονα μετὰ Κορινθίων, [ἔπρασσον] ὅπως ἑτοιμάσαιντο τιμωρίαν, ἢν δέῃ, ἐπειδὴ ἔκ τε Ἀθηνῶν ἐκ πολλοῦ πράσσοντες οὐδὲν ηὕροντο ἐπιτήδειον, ἀλλ’ αἱ νῆες αἱ ἐπὶ Μακεδονίαν καὶ ἐπὶ σφᾶς ὁμοίως ἔπλεον, καὶ τὰ τέλη τῶν Λακεδαιμονίων ὑπέσχετο αὐτοῖς, ἢν ἐπὶ Ποτείδαιαν ἴωσιν Ἀθηναῖοι, ἐς τὴν Ἀττικὴν ἐσβαλεῖν, τότε δὴ κατὰ τὸν καιρὸν τοῦτον ἀφίστανται μετὰ Χαλκιδέων καὶ Βοττιαίων κοινῇ ξυνομόσαντες. καὶ Περδίκκας πείθει Χαλκιδέας τὰς ἐπὶ θαλάσσῃ πόλεις ἐκλιπόντας καὶ καταβαλόντας ἀνοικίσασθαι ἐς Ὄλυνθον μίαν τε πόλιν ταύτην ἰσχυρὰν ποιήσασθαι· τοῖς τ’ ἐκλιποῦσι τούτοις τῆς ἑαυτοῦ γῆς τῆς Μυγδονίας περὶ τὴν Βόλβην λίμνην ἔδωκε νέμεσθαι, ἕως ἂν ὁ πρὸς Ἀθηναίους πόλεμος ᾖ. καὶ οἱ μὲν ἀνῳκίζοντό τε καθαιροῦντες τὰς πόλεις καὶ ἐς πόλεμον παρεσκευάζοντο·", "st": "1.58"}, {"sp": "N", "t": "αἱ δὲ τριάκοντα νῆες τῶν Ἀθηναίων ἀφικνοῦνται ἐς τὰ ἐπὶ Θρᾴκης, καὶ καταλαμβάνουσι τήν τε Ποτείδαιαν καὶ τἆλλα ἀφεστηκότα. νομίσαντες δὲ οἱ στρατηγοὶ ἀδύνατα εἶναι πρός τε Περδίκκαν πολεμεῖν τῇ παρούσῃ δυνάμει καὶ τὰ ξυναφεστῶτα χωρία τρέπονται ἐπὶ τὴν Μακεδονίαν, ἐφ’ ὅπερ καὶ τὸ πρῶτον ἐξεπέμποντο, καὶ καταστάντες ἐπολέμουν μετὰ Φιλίππου καὶ τῶν Δέρδου ἀδελφῶν ἄνωθεν στρατιᾷ ἐσβεβληκότων.", "st": "1.59"}, {"sp": "N", "t": "καὶ ἐν τούτῳ οἱ Κορίνθιοι, τῆς Ποτειδαίας ἀφεστηκυίας καὶ τῶν Ἀττικῶν νεῶν περὶ Μακεδονίαν οὐσῶν, δεδιότες περὶ τῷ χωρίῳ καὶ οἰκεῖον τὸν κίνδυνον ἡγούμενοι πέμπουσιν ἑαυτῶν τε ἐθελοντὰς καὶ τῶν ἄλλων Πελοποννησίων μισθῷ πείσαντες ἑξακοσίους καὶ χιλίους τοὺς πάντας ὁπλίτας καὶ ψιλοὺς τετρακοσίους. ἐστρατήγει δὲ αὐτῶν Ἀριστεὺς ὁ Ἀδειμάντου, κατὰ φιλίαν τε αὐτοῦ οὐχ ἥκιστα οἱ πλεῖστοι ἐκ Κορίνθου στρατιῶται ἐθελονταὶ ξυνέσποντο· ἦν γὰρ τοῖς Ποτειδεάταις αἰεί ποτε ἐπιτήδειος. καὶ ἀφικνοῦνται τεσσαρακοστῇ ἡμέρᾳ ὕστερον ἐπὶ Θρᾴκης ἢ Ποτείδαια ἀπέστη.", "st": "1.60"}, {"sp": "N", "t": "ἦλθε δὲ καὶ τοῖς Ἀθηναίοις εὐθὺς ἡ ἀγγελία τῶν πόλεων ὅτι ἀφεστᾶσι, καὶ πέμπουσιν, ὡς ᾔσθοντο καὶ τοὺς μετ’ Ἀριστέως ἐπιπαριόντας, δισχιλίους ἑαυτῶν ὁπλίτας καὶ τεσσαράκοντα ναῦς πρὸς τὰ ἀφεστῶτα, καὶ Καλλίαν τὸν Καλλιάδου πέμπτον αὐτὸν στρατηγόν, οἳ ἀφικόμενοι ἐς Μακεδονίαν πρῶτον καταλαμβάνουσι τοὺς προτέρους χιλίους Θέρμην ἄρτι ᾑρηκότας καὶ Πύδναν πολιορκοῦντας. προσκαθεζόμενοι δὲ καὶ αὐτοὶ τὴν Πύδναν ἐπολιόρκησαν μέν, ἔπειτα δὲ ξύμβασιν ποιησάμενοι καὶ ξυμμαχίαν ἀναγκαίαν πρὸς τὸν Περδίκκαν, ὡς αὐτοὺς κατήπειγεν ἡ Ποτείδαια καὶ ὁ Ἀριστεὺς παρεληλυθώς, ἀπανίστανται ἐκ τῆς Μακεδονίας, καὶ ἀφικόμενοι ἐς Βέροιαν κἀκεῖθεν ἐπὶ Στρέψαν καὶ πειράσαντες πρῶτον τοῦ χωρίου καὶ οὐχ ἑλόντες ἐπορεύοντο κατὰ γῆν πρὸς τὴν Ποτείδαιαν, τρισχιλίοις μὲν ὁπλίταις ἑαυτῶν, χωρὶς δὲ τῶν ξυμμάχων πολλοῖς, ἱππεῦσι δὲ ἑξακοσίοις Μακεδόνων τοῖς μετὰ Φιλίππου καὶ Παυσανίου· ἅμα δὲ νῆες παρέπλεον ἑβδομήκοντα. κατ’ ὀλίγον δὲ προϊόντες τριταῖοι ἀφίκοντο ἐς Γίγωνον καὶ ἐστρατοπεδεύσαντο.", "st": "1.61"}, {"sp": "N", "t": "Ποτειδεᾶται δὲ καὶ οἱ μετὰ Ἀριστέως Πελοποννήσιοι προσδεχόμενοι τοὺς Ἀθηναίους ἐστρατοπεδεύοντο πρὸς Ὀλύνθου ἐν τῷ ἰσθμῷ, καὶ ἀγορὰν ἔξω τῆς πόλεως ἐπεποίηντο. στρατηγὸν μὲν οὖν τοῦ πεζοῦ παντὸς οἱ ξύμμαχοι ᾕρηντο Ἀριστέα, τῆς δὲ ἵππου Περδίκκαν· ἀπέστη γὰρ εὐθὺς πάλιν τῶν Ἀθηναίων καὶ ξυνεμάχει τοῖς Ποτειδεάταις, Ἰόλαον ἀνθ’ αὑτοῦ καταστήσας ἄρχοντα. ἦν δὲ ἡ γνώμη τοῦ Ἀριστέως τὸ μὲν μεθ’ ἑαυτοῦ στρατόπεδον ἔχοντι ἐν τῷ ἰσθμῷ ἐπιτηρεῖν τοὺς Ἀθηναίους, ἢν ἐπίωσι, Χαλκιδέας δὲ καὶ τοὺς ἔξω ἰσθμοῦ ξυμμάχους καὶ τὴν παρὰ Περδίκκου διακοσίαν ἵππον ἐν Ὀλύνθῳ μένειν, καὶ ὅταν Ἀθηναῖοι ἐπὶ σφᾶς χωρῶσι, κατὰ νώτου βοηθοῦντας ἐν μέσῳ ποιεῖν αὑτῶν τοὺς πολεμίους. Καλλίας δ’ αὖ ὁ τῶν Ἀθηναίων στρατηγὸς καὶ οἱ ξυνάρχοντες τοὺς μὲν Μακεδόνας ἱππέας καὶ τῶν ξυμμάχων ὀλίγους ἐπὶ Ὀλύνθου ἀποπέμπουσιν, ὅπως εἴργωσι τοὺς ἐκεῖθεν ἐπιβοηθεῖν, αὐτοὶ δὲ ἀναστήσαντες τὸ στρατόπεδον ἐχώρουν ἐπὶ τὴν Ποτείδαιαν. καὶ ἐπειδὴ πρὸς τῷ ἰσθμῷ ἐγένοντο καὶ εἶδον τοὺς ἐναντίους παρασκευαζομένους ὡς ἐς μάχην, ἀντικαθίσταντο καὶ αὐτοί, καὶ οὐ πολὺ ὕστερον ξυνέμισγον. καὶ αὐτὸ μὲν τὸ τοῦ Ἀριστέως κέρας καὶ ὅσοι περὶ ἐκεῖνον ἦσαν Κορινθίων τε καὶ τῶν ἄλλων λογάδες ἔτρεψαν τὸ καθ’ ἑαυτοὺς καὶ ἐπεξῆλθον διώκοντες ἐπὶ πολύ· τὸ δὲ ἄλλο στρατόπεδον Ποτειδεατῶν καὶ Πελοποννησίων ἡσσᾶτο ὑπὸ τῶν Ἀθηναίων καὶ ἐς τὸ τεῖχος κατέφυγεν.", "st": "1.62"}, {"sp": "N", "t": "ἐπαναχωρῶν δὲ ὁ Ἀριστεὺς ἀπὸ τῆς διώξεως, ὡς ὁρᾷ τὸ ἄλλο στράτευμα ἡσσημένον, ἠπόρησε μὲν ὁποτέρωσε διακινδυνεύσῃ χωρήσας, ἢ ἐπὶ τῆς Ὀλύνθου ἢ ἐς τὴν Ποτείδαιαν· ἔδοξε δ’ οὖν ξυναγαγόντι τοὺς μεθ’ αὑτοῦ ὡς ἐς ἐλάχιστον χωρίον δρόμῳ βιάσασθαι ἐς τὴν Ποτείδαιαν, καὶ παρῆλθε παρὰ τὴν χηλὴν διὰ τῆς θαλάσσης βαλλόμενός τε καὶ χαλεπῶς, ὀλίγους μέν τινας ἀποβαλών, τοὺς δὲ πλείους σώσας. οἱ δ’ ἀπὸ τῆς Ὀλύνθου τοῖς Ποτειδεάταις βοηθοί (ἀπέχει δὲ ἑξήκοντα μάλιστα σταδίους καὶ ἔστι καταφανές), ὡς ἡ μάχη ἐγίγνετο καὶ τὰ σημεῖα ἤρθη, βραχὺ μέν τι προῆλθον ὡς βοηθήσοντες, καὶ οἱ Μακεδόνες ἱππῆς ἀντιπαρετάξαντο ὡς κωλύσοντες· ἐπειδὴ δὲ διὰ τάχους ἡ νίκη τῶν Ἀθηναίων ἐγίγνετο καὶ τὰ σημεῖα κατεσπάσθη, πάλιν ἐπανεχώρουν ἐς τὸ τεῖχος καὶ οἱ Μακεδόνες παρὰ τοὺς Ἀθηναίους· ἱππῆς δ’ οὐδετέροις παρεγένοντο. μετὰ δὲ τὴν μάχην τροπαῖον ἔστησαν οἱ Ἀθηναῖοι καὶ τοὺς νεκροὺς ὑποσπόνδους ἀπέδοσαν τοῖς Ποτειδεάταις· ἀπέθανον δὲ Ποτειδεατῶν μὲν καὶ τῶν ξυμμάχων ὀλίγῳ ἐλάσσους τριακοσίων, Ἀθηναίων δὲ αὐτῶν πεντήκοντα καὶ ἑκατὸν καὶ Καλλίας ὁ στρατηγός.", "st": "1.63"}, {"sp": "N", "t": "τὸ δὲ ἐκ τοῦ ἰσθμοῦ [τεῖχος] εὐθὺς οἱ Ἀθηναῖοι ἀποτειχίσαντες ἐφρούρουν· τὸ δ’ ἐς τὴν Παλλήνην ἀτείχιστον ἦν· οὐ γὰρ ἱκανοὶ ἐνόμιζον εἶναι ἔν τε τῷ ἰσθμῷ φρουρεῖν καὶ ἐς τὴν Παλλήνην διαβάντες τειχίζειν, δεδιότες μὴ σφίσιν οἱ Ποτειδεᾶται καὶ οἱ ξύμμαχοι γενομένοις δίχα ἐπίθωνται. καὶ πυνθανόμενοι οἱ ἐν τῇ πόλει Ἀθηναῖοι τὴν Παλλήνην ἀτείχιστον οὖσαν, χρόνῳ ὕστερον πέμπουσιν ἑξακοσίους καὶ χιλίους ὁπλίτας ἑαυτῶν καὶ Φορμίωνα τὸν Ἀσωπίου στρατηγόν· ὃς ἀφικόμενος ἐς τὴν Παλλήνην καὶ ἐξ Ἀφύτιος ὁρμώμενος προσήγαγε τῇ Ποτειδαίᾳ τὸν στρατὸν κατὰ βραχὺ προϊὼν καὶ κείρων ἅμα τὴν γῆν, ὡς δὲ οὐδεὶς ἐπεξῄει ἐς μάχην, ἀπετείχισε τὸ ἐκ τῆς Παλλήνης [τεῖχος]. καὶ οὕτως ἤδη κατὰ κράτος ἡ Ποτείδαια ἀμφοτέρωθεν ἐπολιορκεῖτο καὶ ἐκ θαλάσσης ναυσὶν ἅμα ἐφορμούσαις.", "st": "1.64"}, {"sp": "N", "t": "Ἀριστεὺς δὲ ἀποτειχισθείσης αὐτῆς καὶ ἐλπίδα οὐδεμίαν ἔχων σωτηρίας, ἢν μή τι ἀπὸ Πελοποννήσου ἢ ἄλλο παρὰ λόγον γίγνηται, ξυνεβούλευε μὲν πλὴν πεντακοσίων ἄνεμον τηρήσασι τοῖς ἄλλοις ἐκπλεῦσαι, ὅπως ἐπὶ πλέον ὁ σῖτος ἀντίσχῃ, καὶ αὐτὸς ἤθελε τῶν μενόντων εἶναι· ὡς δ’ οὐκ ἔπειθε, βουλόμενος τὰ ἐπὶ τούτοις παρασκευάζειν καὶ ὅπως τὰ ἔξωθεν ἕξει ὡς ἄριστα, ἔκπλουν ποιεῖται λαθὼν τὴν φυλακὴν τῶν Ἀθηναίων. καὶ παραμένων ἐν Χαλκιδεῦσι τά τε ἄλλα ξυνεπολέμει καὶ Σερμυλιῶν λοχήσας πρὸς τῇ πόλει πολλοὺς διέφθειρεν, ἔς τε τὴν Πελοπόννησον ἔπρασσεν ὅπῃ ὠφελία τις γενήσεται. μετὰ δὲ τῆς Ποτειδαίας τὴν ἀποτείχισιν Φορμίων μὲν ἔχων τοὺς ἑξακοσίους καὶ χιλίους τὴν Χαλκιδικὴν καὶ Βοττικὴν ἐδῄου καὶ ἔστιν ἃ καὶ πολίσματα εἷλεν.", "st": "1.65"}, {"sp": "N", "t": "τοῖς δ’ Ἀθηναίοις καὶ Πελοποννησίοις αἰτίαι μὲν αὗται προυγεγένηντο ἐς ἀλλήλους, τοῖς μὲν Κορινθίοις ὅτι τὴν Ποτείδαιαν ἑαυτῶν οὖσαν ἀποικίαν καὶ ἄνδρας Κορινθίων τε καὶ Πελοποννησίων ἐν αὐτῇ ὄντας ἐπολιόρκουν, τοῖς δὲ Ἀθηναίοις ἐς τοὺς Πελοποννησίους ὅτι ἑαυτῶν τε πόλιν ξυμμαχίδα καὶ φόρου ὑποτελῆ ἀπέστησαν, καὶ ἐλθόντες σφίσιν ἀπὸ τοῦ προφανοῦς ἐμάχοντο μετὰ Ποτειδεατῶν. οὐ μέντοι ὅ γε πόλεμός πω ξυνερρώγει, ἀλλ’ ἔτι ἀνοκωχὴ ἦν· ἰδίᾳ γὰρ ταῦτα οἱ Κορίνθιοι ἔπραξαν.", "st": "1.66"}, {"sp": "N", "t": "πολιορκουμένης δὲ τῆς Ποτειδαίας οὐχ ἡσύχαζον, ἀνδρῶν τε σφίσιν ἐνόντων καὶ ἅμα περὶ τῷ χωρίῳ δεδιότες· παρεκάλουν τε εὐθὺς ἐς τὴν Λακεδαίμονα τοὺς ξυμμάχους καὶ κατεβόων ἐλθόντες τῶν Ἀθηναίων ὅτι σπονδάς τε λελυκότες εἶεν καὶ ἀδικοῖεν τὴν Πελοπόννησον. Αἰγινῆταί τε φανερῶς μὲν οὐ πρεσβευόμενοι, δεδιότες τοὺς Ἀθηναίους, κρύφα δὲ οὐχ ἥκιστα μετ’ αὐτῶν ἐνῆγον τὸν πόλεμον, λέγοντες οὐκ εἶναι αὐτόνομοι κατὰ τὰς σπονδάς. οἱ δὲ Λακεδαιμόνιοι προσπαρακαλέσαντες τῶν ξυμμάχων τε καὶ εἴ τίς τι ἄλλο ἔφη ἠδικῆσθαι ὑπὸ Ἀθηναίων, ξύλλογον σφῶν αὐτῶν ποιήσαντες τὸν εἰωθότα λέγειν ἐκέλευον. καὶ ἄλλοι τε παριόντες ἐγκλήματα ἐποιοῦντο ὡς ἕκαστοι καὶ Μεγαρῆς, δηλοῦντες μὲν καὶ ἕτερα οὐκ ὀλίγα διάφορα, μάλιστα δὲ λιμένων τε εἴργεσθαι τῶν ἐν τῇ Ἀθηναίων ἀρχῇ καὶ τῆς Ἀττικῆς ἀγορᾶς παρὰ τὰς σπονδάς. παρελθόντες δὲ τελευταῖοι Κορίνθιοι καὶ τοὺς ἄλλους ἐάσαντες πρῶτον παροξῦναι τοὺς Λακεδαιμονίους ἐπεῖπον τοιάδε.", "st": "1.67"}, {"sp": "N", "t": "‘τὸ πιστὸν ὑμᾶς, ὦ Λακεδαιμόνιοι, τῆς καθ’ ὑμᾶς αὐτοὺς πολιτείας καὶ ὁμιλίας ἀπιστοτέρους ἐς τοὺς ἄλλους ἤν τι λέγωμεν καθίστησιν· καὶ ἀπ’ αὐτοῦ σωφροσύνην μὲν ἔχετε, ἀμαθίᾳ δὲ πλέονι πρὸς τὰ ἔξω πράγματα χρῆσθε. πολλάκις γὰρ προαγορευόντων ἡμῶν ἃ ἐμέλλομεν ὑπὸ Ἀθηναίων βλάπτεσθαι, οὐ περὶ ὧν ἐδιδάσκομεν ἑκάστοτε τὴν μάθησιν ἐποιεῖσθε, ἀλλὰ τῶν λεγόντων μᾶλλον ὑπενοεῖτε ὡς ἕνεκα τῶν αὑτοῖς ἰδίᾳ διαφόρων λέγουσιν· καὶ δι’ αὐτὸ οὐ πρὶν πάσχειν, ἀλλ’ ἐπειδὴ ἐν τῷ ἔργῳ ἐσμέν, τοὺς ξυμμάχους τούσδε παρεκαλέσατε, ἐν οἷς προσήκει ἡμᾶς οὐχ ἥκιστα εἰπεῖν, ὅσῳ καὶ μέγιστα ἐγκλήματα ἔχομεν ὑπὸ μὲν Ἀθηναίων ὑβριζόμενοι, ὑπὸ δὲ ὑμῶν ἀμελούμενοι.", "st": "1.68"}, {"sp": "N", "t": "‘καὶ εἰ μὲν ἀφανεῖς που ὄντες ἠδίκουν τὴν Ἑλλάδα, διδασκαλίας ἂν ὡς οὐκ εἰδόσι προσέδει· νῦν δὲ τί δεῖ μακρηγορεῖν, ὧν τοὺς μὲν δεδουλωμένους ὁρᾶτε, τοῖς δὲ ἐπιβουλεύοντας αὐτούς, καὶ οὐχ ἥκιστα τοῖς ἡμετέροις ξυμμάχοις, καὶ ἐκ πολλοῦ προπαρεσκευασμένους, εἴ ποτε ἄρα πολεμήσονται; οὐ γὰρ ἂν Κέρκυράν τε ὑπολαβόντες βίᾳ ἡμῶν εἶχον καὶ Ποτείδαιαν ἐπολιόρκουν, ὧν τὸ μὲν ἐπικαιρότατον χωρίον πρὸς τὰ ἐπὶ Θρᾴκης ἀποχρῆσθαι, ἡ δὲ ναυτικὸν ἂν μέγιστον παρέσχε Πελοποννησίοις.", "st": "1.68"}, {"sp": "N", "t": "καὶ τῶνδε ὑμεῖς αἴτιοι, τό τε πρῶτον ἐάσαντες αὐτοὺς τὴν πόλιν μετὰ τὰ Μηδικὰ κρατῦναι καὶ ὕστερον τὰ μακρὰ στῆσαι τείχη, ἐς τόδε τε αἰεὶ ἀποστεροῦντες οὐ μόνον τοὺς ὑπ’ ἐκείνων δεδουλωμένους ἐλευθερίας, ἀλλὰ καὶ τοὺς ὑμετέρους ἤδη ξυμμάχους· οὐ γὰρ ὁ δουλωσάμενος, ἀλλ’ ὁ δυνάμενος μὲν παῦσαι περιορῶν δὲ ἀληθέστερον αὐτὸ δρᾷ, εἴπερ καὶ τὴν ἀξίωσιν τῆς ἀρετῆς ὡς ἐλευθερῶν τὴν Ἑλλάδα φέρεται. μόλις δὲ νῦν γε ξυνήλθομεν καὶ οὐδὲ νῦν ἐπὶ φανεροῖς. χρῆν γὰρ οὐκ εἰ ἀδικούμεθα ἔτι σκοπεῖν, ἀλλὰ καθ’ ὅτι ἀμυνούμεθα· οἱ γὰρ δρῶντες βεβουλευμένοι πρὸς οὐ διεγνωκότας ἤδη καὶ οὐ μέλλοντες ἐπέρχονται. καὶ ἐπιστάμεθα οἵᾳ ὁδῷ οἱ Ἀθηναῖοι καὶ ὅτι κατ’ ὀλίγον χωροῦσιν ἐπὶ τοὺς πέλας. καὶ λανθάνειν μὲν οἰόμενοι διὰ τὸ ἀναίσθητον ὑμῶν ἧσσον θαρσοῦσι, γνόντες δὲ εἰδότας περιορᾶν ἰσχυρῶς ἐγκείσονται. ἡσυχάζετε γάρ, μόνοι Ἑλλήνων, ὦ Λακεδαιμόνιοι, οὐ τῇ δυνάμει τινά, ἀλλὰ τῇ μελλήσει ἀμυνόμενοι, καὶ μόνοι οὐκ ἀρχομένην τὴν αὔξησιν τῶν ἐχθρῶν διπλασιουμένην δὲ καταλύοντες. καίτοι ἐλέγεσθε ἀσφαλεῖς εἶναι, ὧν ἄρα ὁ λόγος τοῦ ἔργου ἐκράτει. τόν τε γὰρ Μῆδον αὐτοὶ ἴσμεν ἐκ περάτων γῆς πρότερον ἐπὶ τὴν Πελοπόννησον ἐλθόντα ἢ τὰ παρ’ ὑμῶν ἀξίως προαπαντῆσαι, καὶ νῦν τοὺς Ἀθηναίους οὐχ ἑκάς, ὥσπερ ἐκεῖνον, ἀλλ’ ἐγγὺς ὄντας περιορᾶτε, καὶ ἀντὶ τοῦ ἐπελθεῖν αὐτοὶ ἀμύνεσθαι βούλεσθε μᾶλλον ἐπιόντας, καὶ ἐς τύχας πρὸς πολλῷ δυνατωτέρους ἀγωνιζόμενοι καταστῆναι, ἐπιστάμενοι καὶ τὸν βάρβαρον αὐτὸν περὶ αὑτῷ τὰ πλείω σφαλέντα, καὶ πρὸς αὐτοὺς τοὺς Ἀθηναίους πολλὰ ἡμᾶς ἤδη τοῖς ἁμαρτήμασιν αὐτῶν μᾶλλον ἢ τῇ ἀφ’ ὑμῶν τιμωρίᾳ περιγεγενημένους, ἐπεὶ αἵ γε ὑμέτεραι ἐλπίδες ἤδη τινάς που καὶ ἀπαρασκεύους διὰ τὸ πιστεῦσαι ἔφθειραν. καὶ μηδεὶς ὑμῶν ἐπ’ ἔχθρᾳ τὸ πλέον ἢ αἰτίᾳ νομίσῃ τάδε λέγεσθαι· αἰτία μὲν γὰρ φίλων ἀνδρῶν ἐστὶν ἁμαρτανόντων, κατηγορία δὲ ἐχθρῶν ἀδικησάντων.", "st": "1.69"}, {"sp": "N", "t": "‘καὶ ἅμα, εἴπερ τινὲς καὶ ἄλλοι, ἄξιοι νομίζομεν εἶναι τοῖς πέλας ψόγον ἐπενεγκεῖν, ἄλλως τε καὶ μεγάλων τῶν διαφερόντων καθεστώτων, περὶ ὧν οὐκ αἰσθάνεσθαι ἡμῖν γε δοκεῖτε, οὐδ’ ἐκλογίσασθαι πώποτε πρὸς οἵους ὑμῖν Ἀθηναίους ὄντας καὶ ὅσον ὑμῶν καὶ ὡς πᾶν διαφέροντας ὁ ἀγὼν ἔσται. οἱ μέν γε νεωτεροποιοὶ καὶ ἐπινοῆσαι ὀξεῖς καὶ ἐπιτελέσαι ἔργῳ ἃ ἂν γνῶσιν· ὑμεῖς δὲ τὰ ὑπάρχοντά τε σῴζειν καὶ ἐπιγνῶναι μηδὲν καὶ ἔργῳ οὐδὲ τἀναγκαῖα ἐξικέσθαι. αὖθις δὲ οἱ μὲν καὶ παρὰ δύναμιν τολμηταὶ καὶ παρὰ γνώμην κινδυνευταὶ καὶ ἐν τοῖς δεινοῖς εὐέλπιδες· τὸ δὲ ὑμέτερον τῆς τε δυνάμεως ἐνδεᾶ πρᾶξαι τῆς τε γνώμης μηδὲ τοῖς βεβαίοις πιστεῦσαι τῶν τε δεινῶν μηδέποτε οἴεσθαι ἀπολυθήσεσθαι. καὶ μὴν καὶ ἄοκνοι πρὸς ὑμᾶς μελλητὰς καὶ ἀποδημηταὶ πρὸς ἐνδημοτάτους· οἴονται γὰρ οἱ μὲν τῇ ἀπουσίᾳ ἄν τι κτᾶσθαι, ὑμεῖς δὲ τῷ ἐπελθεῖν καὶ τὰ ἑτοῖμα ἂν βλάψαι. κρατοῦντές τε τῶν ἐχθρῶν ἐπὶ πλεῖστον ἐξέρχονται καὶ νικώμενοι ἐπ’ ἐλάχιστον ἀναπίπτουσιν. ἔτι δὲ τοῖς μὲν σώμασιν ἀλλοτριωτάτοις ὑπὲρ τῆς πόλεως χρῶνται, τῇ δὲ γνώμῃ οἰκειοτάτῃ ἐς τὸ πράσσειν τι ὑπὲρ αὐτῆς. καὶ ἃ μὲν ἂν ἐπινοήσαντες μὴ ἐπεξέλθωσιν, οἰκείων στέρεσθαι ἡγοῦνται, ἃ δ’ ἂν ἐπελθόντες κτήσωνται, ὀλίγα πρὸς τὰ μέλλοντα τυχεῖν πράξαντες. ἢν δ’ ἄρα του καὶ πείρᾳ σφαλῶσιν, ἀντελπίσαντες ἄλλα ἐπλήρωσαν τὴν χρείαν· μόνοι γὰρ ἔχουσί τε ὁμοίως καὶ ἐλπίζουσιν ἃ ἂν ἐπινοήσωσι διὰ τὸ ταχεῖαν τὴν ἐπιχείρησιν ποιεῖσθαι ὧν ἂν γνῶσιν. καὶ ταῦτα μετὰ πόνων πάντα καὶ κινδύνων δι’ ὅλου τοῦ αἰῶνος μοχθοῦσι, καὶ ἀπολαύουσιν ἐλάχιστα τῶν ὑπαρχόντων διὰ τὸ αἰεὶ κτᾶσθαι καὶ μήτε ἑορτὴν ἄλλο τι ἡγεῖσθαι ἢ τὸ τὰ δέοντα πρᾶξαι ξυμφοράν τε οὐχ ἧσσον ἡσυχίαν ἀπράγμονα ἢ ἀσχολίαν ἐπίπονον· ὥστε εἴ τις αὐτοὺς ξυνελὼν φαίη πεφυκέναι ἐπὶ τῷ μήτε αὐτοὺς ἔχειν ἡσυχίαν μήτε τοὺς ἄλλους ἀνθρώπους ἐᾶν, ὀρθῶς ἂν εἴποι.", "st": "1.70"}, {"sp": "N", "t": "‘ταύτης μέντοι τοιαύτης ἀντικαθεστηκυίας πόλεως, ὦ Λακεδαιμόνιοι, διαμέλλετε καὶ οἴεσθε τὴν ἡσυχίαν οὐ τούτοις τῶν ἀνθρώπων ἐπὶ πλεῖστον ἀρκεῖν οἳ ἂν τῇ μὲν παρασκευῇ δίκαια πράσσωσι, τῇ δὲ γνώμῃ, ἢν ἀδικῶνται, δῆλοι ὦσι μὴ ἐπιτρέψοντες, ἀλλ’ ἐπὶ τῷ μὴ λυπεῖν τε τοὺς ἄλλους καὶ αὐτοὶ ἀμυνόμενοι μὴ βλάπτεσθαι τὸ ἴσον νέμετε. μόλις δ’ ἂν πόλει ὁμοίᾳ παροικοῦντες ἐτυγχάνετε τούτου· νῦν δ’, ὅπερ καὶ ἄρτι ἐδηλώσαμεν, ἀρχαιότροπα ὑμῶν τὰ ἐπιτηδεύματα πρὸς αὐτούς ἐστιν. ἀνάγκη δὲ ὥσπερ τέχνης αἰεὶ τὰ ἐπιγιγνόμενα κρατεῖν· καὶ ἡσυχαζούσῃ μὲν πόλει τὰ ἀκίνητα νόμιμα ἄριστα, πρὸς πολλὰ δὲ ἀναγκαζομένοις ἰέναι πολλῆς καὶ τῆς ἐπιτεχνήσεως δεῖ. δι’ ὅπερ καὶ τὰ τῶν Ἀθηναίων ἀπὸ τῆς πολυπειρίας ἐπὶ πλέον ὑμῶν κεκαίνωται. μέχρι μὲν οὖν τοῦδε ὡρίσθω ὑμῶν ἡ βραδυτής· νῦν δὲ τοῖς τε ἄλλοις καὶ Ποτειδεάταις, ὥσπερ ὑπεδέξασθε, βοηθήσατε κατὰ τάχος ἐσβαλόντες ἐς τὴν Ἀττικήν, ἵνα μὴ ἄνδρας τε φίλους καὶ ξυγγενεῖς τοῖς ἐχθίστοις προῆσθε καὶ ἡμᾶς τοὺς ἄλλους ἀθυμίᾳ πρὸς ἑτέραν τινὰ ξυμμαχίαν τρέψητε. δρῷμεν δ’ ἂν ἄδικον οὐδὲν οὔτε πρὸς θεῶν τῶν ὁρκίων οὔτε πρὸς ἀνθρώπων τῶν αἰσθανομένων· λύουσι γὰρ σπονδὰς οὐχ οἱ δι’ ἐρημίαν ἄλλοις προσιόντες, ἀλλ’ οἱ μὴ βοηθοῦντες οἷς ἂν ξυνομόσωσιν. βουλομένων δὲ ὑμῶν προθύμων εἶναι μενοῦμεν· οὔτε γὰρ ὅσια ἂν ποιοῖμεν μεταβαλλόμενοι οὔτε ξυνηθεστέρους ἂν ἄλλους εὕροιμεν. πρὸς τάδε βουλεύεσθε εὖ καὶ τὴν Πελοπόννησον πειρᾶσθε μὴ ἐλάσσω ἐξηγεῖσθαι ἢ οἱ πατέρες ὑμῖν παρέδοσαν.’", "st": "1.71"}, {"sp": "N", "t": "τοιαῦτα μὲν οἱ Κορίνθιοι εἶπον. τῶν δὲ Ἀθηναίων ἔτυχε γὰρ πρεσβεία πρότερον ἐν τῇ Λακεδαίμονι περὶ ἄλλων παροῦσα, καὶ ὡς ᾔσθοντο τῶν λόγων, ἔδοξεν αὐτοῖς παριτητέα ἐς τοὺς Λακεδαιμονίους εἶναι, τῶν μὲν ἐγκλημάτων πέρι μηδὲν ἀπολογησομένους ὧν αἱ πόλεις ἐνεκάλουν, δηλῶσαι δὲ περὶ τοῦ παντὸς ὡς οὐ ταχέως αὐτοῖς βουλευτέον εἴη, ἀλλ’ ἐν πλέονι σκεπτέον. καὶ ἅμα τὴν σφετέραν πόλιν ἐβούλοντο σημῆναι ὅση εἴη δύναμιν, καὶ ὑπόμνησιν ποιήσασθαι τοῖς τε πρεσβυτέροις ὧν ᾔδεσαν καὶ τοῖς νεωτέροις ἐξήγησιν ὧν ἄπειροι ἦσαν, νομίζοντες μᾶλλον ἂν αὐτοὺς ἐκ τῶν λόγων πρὸς τὸ ἡσυχάζειν τραπέσθαι ἢ πρὸς τὸ πολεμεῖν. προσελθόντες οὖν τοῖς Λακεδαιμονίοις ἔφασαν βούλεσθαι καὶ αὐτοὶ ἐς τὸ πλῆθος αὐτῶν εἰπεῖν, εἴ τι μὴ ἀποκωλύοι. οἱ δὲ ἐκέλευόν τε παριέναι, καὶ παρελθόντες οἱ Ἀθηναῖοι ἔλεγον τοιάδε.", "st": "1.72"}, {"sp": "N", "t": "‘ἡ μὲν πρέσβευσις ἡμῶν οὐκ ἐς ἀντιλογίαν τοῖς ὑμετέροις ξυμμάχοις ἐγένετο, ἀλλὰ περὶ ὧν ἡ πόλις ἔπεμψεν· αἰσθανόμενοι δὲ καταβοὴν οὐκ ὀλίγην οὖσαν ἡμῶν παρήλθομεν οὐ τοῖς ἐγκλήμασι τῶν πόλεων ἀντεροῦντες (οὐ γὰρ παρὰ δικασταῖς ὑμῖν οὔτε ἡμῶν οὔτε τούτων οἱ λόγοι ἂν γίγνοιντο), ἀλλ’ ὅπως μὴ ῥᾳδίως περὶ μεγάλων πραγμάτων τοῖς ξυμμάχοις πειθόμενοι χεῖρον βουλεύσησθε, καὶ ἅμα βουλόμενοι περὶ τοῦ παντὸς λόγου τοῦ ἐς ἡμᾶς καθεστῶτος δηλῶσαι ὡς οὔτε ἀπεικότως ἔχομεν ἃ κεκτήμεθα, ἥ τε πόλις ἡμῶν ἀξία λόγου ἐστίν.", "st": "1.73"}, {"sp": "N", "t": "‘καὶ τὰ μὲν πάνυ παλαιὰ τί δεῖ λέγειν, ὧν ἀκοαὶ μᾶλλον λόγων μάρτυρες ἢ ὄψις τῶν ἀκουσομένων; τὰ δὲ Μηδικὰ καὶ ὅσα αὐτοὶ ξύνιστε, εἰ καὶ δι’ ὄχλου μᾶλλον ἔσται αἰεὶ προβαλλομένοις, ἀνάγκη λέγειν· καὶ γὰρ ὅτε ἐδρῶμεν, ἐπ’ ὠφελίᾳ ἐκινδυνεύετο, ἧς τοῦ μὲν ἔργου μέρος μετέσχετε, τοῦ δὲ λόγου μὴ παντός, εἴ τι ὠφελεῖ, στερισκώμεθα. ῥηθήσεται δὲ οὐ παραιτήσεως μᾶλλον ἕνεκα ἢ μαρτυρίου καὶ δηλώσεως πρὸς οἵαν ὑμῖν πόλιν μὴ εὖ βουλευομένοις ὁ ἀγὼν καταστήσεται. φαμὲν γὰρ Μαραθῶνί τε μόνοι προκινδυνεῦσαι τῷ βαρβάρῳ καὶ ὅτε τὸ ὕστερον ἦλθεν, οὐχ ἱκανοὶ ὄντες κατὰ γῆν ἀμύνεσθαι, ἐσβάντες ἐς τὰς ναῦς πανδημεὶ ἐν Σαλαμῖνι ξυνναυμαχῆσαι, ὅπερ ἔσχε μὴ κατὰ πόλεις αὐτὸν ἐπιπλέοντα τὴν Πελοπόννησον πορθεῖν, ἀδυνάτων ἂν ὄντων πρὸς ναῦς πολλὰς ἀλλήλοις ἐπιβοηθεῖν. τεκμήριον δὲ μέγιστον αὐτὸς ἐποίησεν· νικηθεὶς γὰρ ταῖς ναυσὶν ὡς οὐκέτι αὐτῷ ὁμοίας οὔσης τῆς δυνάμεως κατὰ τάχος τῷ πλέονι τοῦ στρατοῦ ἀνεχώρησεν.", "st": "1.73"}, {"sp": "N", "t": "τοιούτου μέντοι τούτου ξυμβάντος, καὶ σαφῶς δηλωθέντος ὅτι ἐν ταῖς ναυσὶ τῶν Ἑλλήνων τὰ πράγματα ἐγένετο, τρία τὰ ὠφελιμώτατα ἐς αὐτὸ παρεσχόμεθα, ἀριθμόν τε νεῶν πλεῖστον καὶ ἄνδρα στρατηγὸν ξυνετώτατον καὶ προθυμίαν ἀοκνοτάτην· ναῦς μέν γε ἐς τὰς τετρακοσίας ὀλίγῳ ἐλάσσους τῶν δύο μοιρῶν, Θεμιστοκλέα δὲ ἄρχοντα, ὃς αἰτιώτατος ἐν τῷ στενῷ ναυμαχῆσαι ἐγένετο, ὅπερ σαφέστατα ἔσωσε τὰ πράγματα, καὶ αὐτὸν διὰ τοῦτο ὑμεῖς ἐτιμήσατε μάλιστα δὴ ἄνδρα ξένον τῶν ὡς ὑμᾶς ἐλθόντων· προθυμίαν δὲ καὶ πολὺ τολμηροτάτην ἐδείξαμεν, οἵ γε, ἐπειδὴ ἡμῖν κατὰ γῆν οὐδεὶς ἐβοήθει, τῶν ἄλλων ἤδη μέχρι ἡμῶν δουλευόντων ἠξιώσαμεν ἐκλιπόντες τὴν πόλιν καὶ τὰ οἰκεῖα διαφθείραντες μηδ’ ὣς τὸ τῶν περιλοίπων ξυμμάχων κοινὸν προλιπεῖν μηδὲ σκεδασθέντες ἀχρεῖοι αὐτοῖς γενέσθαι, ἀλλ’ ἐσβάντες ἐς τὰς ναῦς κινδυνεῦσαι καὶ μὴ ὀργισθῆναι ὅτι ἡμῖν οὐ προυτιμωρήσατε. ὥστε φαμὲν οὐχ ἧσσον αὐτοὶ ὠφελῆσαι ὑμᾶς ἢ τυχεῖν τούτου. ὑμεῖς μὲν γὰρ ἀπό τε οἰκουμένων τῶν πόλεων καὶ ἐπὶ τῷ τὸ λοιπὸν νέμεσθαι, ἐπειδὴ ἐδείσατε ὑπὲρ ὑμῶν καὶ οὐχ ἡμῶν τὸ πλέον, ἐβοηθήσατε (ὅτε γοῦν ἦμεν ἔτι σῶοι, οὐ παρεγένεσθε)· ἡμεῖς δὲ ἀπό τε τῆς οὐκ οὔσης ἔτι ὁρμώμενοι καὶ ὑπὲρ τῆς ἐν βραχείᾳ ἐλπίδι οὔσης κινδυνεύοντες ξυνεσώσαμεν ὑμᾶς τε τὸ μέρος καὶ ἡμᾶς αὐτούς. εἰ δὲ προσεχωρήσαμεν πρότερον τῷ Μήδῳ δείσαντες, ὥσπερ καὶ ἄλλοι, περὶ τῇ χώρᾳ, ἢ μὴ ἐτολμήσαμεν ὕστερον ἐσβῆναι ἐς τὰς ναῦς ὡς διεφθαρμένοι, οὐδὲν ἂν ἔδει ἔτι ὑμᾶς μὴ ἔχοντας ναῦς ἱκανὰς ναυμαχεῖν, ἀλλὰ καθ’ ἡσυχίαν ἂν αὐτῷ προυχώρησε τὰ πράγματα ᾗ ἐβούλετο.", "st": "1.74"}, {"sp": "N", "t": "‘ἆρ’ ἄξιοί ἐσμεν, ὦ Λακεδαιμόνιοι, καὶ προθυμίας ἕνεκα τῆς τότε καὶ γνώμης ξυνέσεως ἀρχῆς γε ἧς ἔχομεν τοῖς Ἕλλησι μὴ οὕτως ἄγαν ἐπιφθόνως διακεῖσθαι; καὶ γὰρ αὐτὴν τήνδε ἐλάβομεν οὐ βιασάμενοι, ἀλλ’ ὑμῶν μὲν οὐκ ἐθελησάντων παραμεῖναι πρὸς τὰ ὑπόλοιπα τοῦ βαρβάρου, ἡμῖν δὲ προσελθόντων τῶν ξυμμάχων καὶ αὐτῶν δεηθέντων ἡγεμόνας καταστῆναι· ἐξ αὐτοῦ δὲ τοῦ ἔργου κατηναγκάσθημεν τὸ πρῶτον προαγαγεῖν αὐτὴν ἐς τόδε, μάλιστα μὲν ὑπὸ δέους, ἔπειτα καὶ τιμῆς, ὕστερον καὶ ὠφελίας. καὶ οὐκ ἀσφαλὲς ἔτι ἐδόκει εἶναι τοῖς πολλοῖς ἀπηχθημένους, καί τινων καὶ ἤδη ἀποστάντων κατεστραμμένων, ὑμῶν τε ἡμῖν οὐκέτι ὁμοίως φίλων, ἀλλ’ ὑπόπτων καὶ διαφόρων ὄντων, ἀνέντας κινδυνεύειν· καὶ γὰρ ἂν αἱ ἀποστάσεις πρὸς ὑμᾶς ἐγίγνοντο. πᾶσι δὲ ἀνεπίφθονον τὰ ξυμφέροντα τῶν μεγίστων πέρι κινδύνων εὖ τίθεσθαι.", "st": "1.75"}, {"sp": "N", "t": "ὑμεῖς γοῦν, ὦ Λακεδαιμόνιοι, τὰς ἐν τῇ Πελοποννήσῳ πόλεις ἐπὶ τὸ ὑμῖν ὠφέλιμον καταστησάμενοι ἐξηγεῖσθε· καὶ εἰ τότε ὑπομείναντες διὰ παντὸς ἀπήχθεσθε ἐν τῇ ἡγεμονίᾳ, ὥσπερ ἡμεῖς, εὖ ἴσμεν μὴ ἂν ἧσσον ὑμᾶς λυπηροὺς γενομένους τοῖς ξυμμάχοις καὶ ἀναγκασθέντας ἂν ἢ ἄρχειν ἐγκρατῶς ἢ αὐτοὺς κινδυνεύειν. οὕτως οὐδ’ ἡμεῖς θαυμαστὸν οὐδὲν πεποιήκαμεν οὐδ’ ἀπὸ τοῦ ἀνθρωπείου τρόπου, εἰ ἀρχήν τε διδομένην ἐδεξάμεθα καὶ ταύτην μὴ ἀνεῖμεν ὑπὸ ⟨τριῶν⟩ τῶν μεγίστων νικηθέντες, τιμῆς καὶ δέους καὶ ὠφελίας, οὐδ’ αὖ πρῶτοι τοῦ τοιούτου ὑπάρξαντες, ἀλλ’ αἰεὶ καθεστῶτος τὸν ἥσσω ὑπὸ τοῦ δυνατωτέρου κατείργεσθαι, ἄξιοί τε ἅμα νομίζοντες εἶναι καὶ ὑμῖν δοκοῦντες μέχρι οὗ τὰ ξυμφέροντα λογιζόμενοι τῷ δικαίῳ λόγῳ νῦν χρῆσθε, ὃν οὐδείς πω παρατυχὸν ἰσχύι τι κτήσασθαι προθεὶς τοῦ μὴ πλέον ἔχειν ἀπετράπετο. ἐπαινεῖσθαί τε ἄξιοι οἵτινες χρησάμενοι τῇ ἀνθρωπείᾳ φύσει ὥστε ἑτέρων ἄρχειν δικαιότεροι ἢ κατὰ τὴν ὑπάρχουσαν δύναμιν γένωνται. ἄλλους γ’ ἂν οὖν οἰόμεθα τὰ ἡμέτερα λαβόντας δεῖξαι ἂν μάλιστα εἴ τι μετριάζομεν· ἡμῖν δὲ καὶ ἐκ τοῦ ἐπιεικοῦς ἀδοξία τὸ πλέον ἢ ἔπαινος οὐκ εἰκότως περιέστη.", "st": "1.76"}, {"sp": "N", "t": "‘καὶ ἐλασσούμενοι γὰρ ἐν ταῖς ξυμβολαίαις πρὸς τοὺς ξυμμάχους δίκαις καὶ παρ’ ἡμῖν αὐτοῖς ἐν τοῖς ὁμοίοις νόμοις ποιήσαντες τὰς κρίσεις φιλοδικεῖν δοκοῦμεν. καὶ οὐδεὶς σκοπεῖ αὐτῶν τοῖς καὶ ἄλλοθί που ἀρχὴν ἔχουσι καὶ ἧσσον ἡμῶν πρὸς τοὺς ὑπηκόους μετρίοις οὖσι διότι τοῦτο οὐκ ὀνειδίζεται· βιάζεσθαι γὰρ οἷς ἂν ἐξῇ, δικάζεσθαι οὐδὲν προσδέονται. οἱ δὲ εἰθισμένοι πρὸς ἡμᾶς ἀπὸ τοῦ ἴσου ὁμιλεῖν, ἤν τι παρὰ τὸ μὴ οἴεσθαι χρῆναι ἢ γνώμῃ ἢ δυνάμει τῇ διὰ τὴν ἀρχὴν καὶ ὁπωσοῦν ἐλασσωθῶσιν, οὐ τοῦ πλέονος μὴ στερισκόμενοι χάριν ἔχουσιν, ἀλλὰ τοῦ ἐνδεοῦς χαλεπώτερον φέρουσιν ἢ εἰ ἀπὸ πρώτης ἀποθέμενοι τὸν νόμον φανερῶς ἐπλεονεκτοῦμεν. ἐκείνως δὲ οὐδ’ ἂν αὐτοὶ ἀντέλεγον ὡς οὐ χρεὼν τὸν ἥσσω τῷ κρατοῦντι ὑποχωρεῖν. ἀδικούμενοί τε, ὡς ἔοικεν, οἱ ἄνθρωποι μᾶλλον ὀργίζονται ἢ βιαζόμενοι· τὸ μὲν γὰρ ἀπὸ τοῦ ἴσου δοκεῖ πλεονεκτεῖσθαι, τὸ δ’ ἀπὸ τοῦ κρείσσονος καταναγκάζεσθαι. ὑπὸ γοῦν τοῦ Μήδου δεινότερα τούτων πάσχοντες ἠνείχοντο, ἡ δὲ ἡμετέρα ἀρχὴ χαλεπὴ δοκεῖ εἶναι, εἰκότως· τὸ παρὸν γὰρ αἰεὶ βαρὺ τοῖς ὑπηκόοις. ὑμεῖς γ’ ἂν οὖν εἰ καθελόντες ἡμᾶς ἄρξαιτε, τάχα ἂν τὴν εὔνοιαν ἣν διὰ τὸ ἡμέτερον δέος εἰλήφατε μεταβάλοιτε, εἴπερ οἷα καὶ τότε πρὸς τὸν Μῆδον δι’ ὀλίγου ἡγησάμενοι ὑπεδείξατε, ὁμοῖα καὶ νῦν γνώσεσθε. ἄμεικτα γὰρ τά τε καθ’ ὑμᾶς αὐτοὺς νόμιμα τοῖς ἄλλοις ἔχετε καὶ προσέτι εἷς ἕκαστος ἐξιὼν οὔτε τούτοις χρῆται οὔθ’ οἷς ἡ ἄλλη Ἑλλὰς νομίζει.", "st": "1.77"}, {"sp": "N", "t": "‘βουλεύεσθε οὖν βραδέως ὡς οὐ περὶ βραχέων, καὶ μὴ ἀλλοτρίαις γνώμαις καὶ ἐγκλήμασι πεισθέντες οἰκεῖον πόνον πρόσθησθε. τοῦ δὲ πολέμου τὸν παράλογον, ὅσος ἐστί, πρὶν ἐν αὐτῷ γενέσθαι προδιάγνωτε· μηκυνόμενος γὰρ φιλεῖ ἐς τύχας τὰ πολλὰ περιίστασθαι, ὧν ἴσον τε ἀπέχομεν καὶ ὁποτέρως ἔσται ἐν ἀδήλῳ κινδυνεύεται. ἰόντες τε οἱ ἄνθρωποι ἐς τοὺς πολέμους τῶν ἔργων πρότερον ἔχονται, ἃ χρῆν ὕστερον δρᾶν, κακοπαθοῦντες δὲ ἤδη τῶν λόγων ἅπτονται. ἡμεῖς δὲ ἐν οὐδεμιᾷ πω τοιαύτῃ ἁμαρτίᾳ ὄντες οὔτ’ αὐτοὶ οὔθ’ ὑμᾶς ὁρῶντες λέγομεν ὑμῖν, ἕως ἔτι αὐθαίρετος ἀμφοτέροις ἡ εὐβουλία, σπονδὰς μὴ λύειν μηδὲ παραβαίνειν τοὺς ὅρκους, τὰ δὲ διάφορα δίκῃ λύεσθαι κατὰ τὴν ξυνθήκην. εἰ δὲ μή, θεοὺς τοὺς ὁρκίους μάρτυρας ποιούμενοι πειρασόμεθα ἀμύνεσθαι πολέμου ἄρχοντας ταύτῃ ᾗ ἂν ὑφηγῆσθε.’", "st": "1.78"}, {"sp": "N", "t": "τοιαῦτα δὲ οἱ Ἀθηναῖοι εἶπον. ἐπειδὴ δὲ τῶν τε ξυμμάχων ἤκουσαν οἱ Λακεδαιμόνιοι τὰ ἐγκλήματα τὰ ἐς τοὺς Ἀθηναίους καὶ τῶν Ἀθηναίων ἃ ἔλεξαν, μεταστησάμενοι πάντας ἐβουλεύοντο κατὰ σφᾶς αὐτοὺς περὶ τῶν παρόντων. καὶ τῶν μὲν πλεόνων ἐπὶ τὸ αὐτὸ αἱ γνῶμαι ἔφερον, ἀδικεῖν τε τοὺς Ἀθηναίους ἤδη καὶ πολεμητέα εἶναι ἐν τάχει· παρελθὼν δὲ Ἀρχίδαμος ὁ βασιλεὺς αὐτῶν, ἀνὴρ καὶ ξυνετὸς δοκῶν εἶναι καὶ σώφρων, ἔλεξε τοιάδε.", "st": "1.79"}, {"sp": "N", "t": "‘καὶ αὐτὸς πολλῶν ἤδη πολέμων ἔμπειρός εἰμι, ὦ Λακεδαιμόνιοι, καὶ ὑμῶν τοὺς ἐν τῇ αὐτῇ ἡλικίᾳ ὁρῶ, ὥστε μήτε ἀπειρίᾳ ἐπιθυμῆσαί τινα τοῦ ἔργου, ὅπερ ἂν οἱ πολλοὶ πάθοιεν, μήτε ἀγαθὸν καὶ ἀσφαλὲς νομίσαντα. εὕροιτε δ’ ἂν τόνδε περὶ οὗ νῦν βουλεύεσθε οὐκ ἂν ἐλάχιστον γενόμενον, εἰ σωφρόνως τις αὐτὸν ἐκλογίζοιτο. πρὸς μὲν γὰρ Πελοποννησίους καὶ τοὺς ἀστυγείτονας παρόμοιος ἡμῶν ἡ ἀλκή, καὶ διὰ ταχέων οἷόν τε ἐφ’ ἕκαστα ἐλθεῖν· πρὸς δὲ ἄνδρας οἳ γῆν τε ἑκὰς ἔχουσι καὶ προσέτι θαλάσσης ἐμπειρότατοί εἰσι καὶ τοῖς ἄλλοις ἅπασιν ἄριστα ἐξήρτυνται, πλούτῳ τε ἰδίῳ καὶ δημοσίῳ καὶ ναυσὶ καὶ ἵπποις καὶ ὅπλοις καὶ ὄχλῳ ὅσος οὐκ ἐν ἄλλῳ ἑνί γε χωρίῳ Ἑλληνικῷ ἐστίν, ἔτι δὲ καὶ ξυμμάχους πολλοὺς φόρου ὑποτελεῖς ἔχουσι, πῶς χρὴ πρὸς τούτους ῥᾳδίως πόλεμον ἄρασθαι καὶ τίνι πιστεύσαντας ἀπαρασκεύους ἐπειχθῆναι; πότερον ταῖς ναυσίν; ἀλλ’ ἥσσους ἐσμέν· εἰ δὲ μελετήσομεν καὶ ἀντιπαρασκευασόμεθα, χρόνος ἐνέσται. ἀλλὰ τοῖς χρήμασιν; ἀλλὰ πολλῷ πλέον ἔτι τούτου ἐλλείπομεν καὶ οὔτε ἐν κοινῷ ἔχομεν οὔτε ἑτοίμως ἐκ τῶν ἰδίων φέρομεν.", "st": "1.80"}, {"sp": "N", "t": "τάχ’ ἄν τις θαρσοίη ὅτι τοῖς ὅπλοις αὐτῶν καὶ τῷ πλήθει ὑπερφέρομεν, ὥστε τὴν γῆν δῃοῦν ἐπιφοιτῶντες. τοῖς δὲ ἄλλη γῆ ἐστὶ πολλὴ ἧς ἄρχουσι, καὶ ἐκ θαλάσσης ὧν δέονται ἐπάξονται. εἰ δ’ αὖ τοὺς ξυμμάχους ἀφιστάναι πειρασόμεθα, δεήσει καὶ τούτοις ναυσὶ βοηθεῖν τὸ πλέον οὖσι νησιώταις. τίς οὖν ἔσται ἡμῶν ὁ πόλεμος; εἰ μὴ γὰρ ἢ ναυσὶ κρατήσομεν ἢ τὰς προσόδους ἀφαιρήσομεν ἀφ’ ὧν τὸ ναυτικὸν τρέφουσι, βλαψόμεθα τὰ πλείω. κἀν τούτῳ οὐδὲ καταλύεσθαι ἔτι καλόν, ἄλλως τε καὶ εἰ δόξομεν ἄρξαι μᾶλλον τῆς διαφορᾶς. μὴ γὰρ δὴ ἐκείνῃ γε τῇ ἐλπίδι ἐπαιρώμεθα ὡς ταχὺ παυσθήσεται ὁ πόλεμος, ἢν τὴν γῆν αὐτῶν τέμωμεν. δέδοικα δὲ μᾶλλον μὴ καὶ τοῖς παισὶν αὐτὸν ὑπολίπωμεν· οὕτως εἰκὸς Ἀθηναίους φρονήματι μήτε τῇ γῇ δουλεῦσαι μήτε ὥσπερ ἀπείρους καταπλαγῆναι τῷ πολέμῳ.", "st": "1.81"}, {"sp": "N", "t": "‘οὐ μὴν οὐδὲ ἀναισθήτως αὐτοὺς κελεύω τούς τε ξυμμάχους ἡμῶν ἐᾶν βλάπτειν καὶ ἐπιβουλεύοντας μὴ καταφωρᾶν, ἀλλὰ ὅπλα μὲν μήπω κινεῖν, πέμπειν δὲ καὶ αἰτιᾶσθαι μήτε πόλεμον ἄγαν δηλοῦντας μήθ’ ὡς ἐπιτρέψομεν, κἀν τούτῳ καὶ τὰ ἡμέτερ’ αὐτῶν ἐξαρτύεσθαι ξυμμάχων τε προσαγωγῇ καὶ Ἑλλήνων καὶ βαρβάρων, εἴ ποθέν τινα ἢ ναυτικοῦ ἢ χρημάτων δύναμιν προσληψόμεθα (ἀνεπίφθονον δέ, ὅσοι ὥσπερ καὶ ἡμεῖς ὑπ’ Ἀθηναίων ἐπιβουλευόμεθα, μὴ Ἕλληνας μόνον, ἀλλὰ καὶ βαρβάρους προσλαβόντας διασωθῆναι), καὶ τὰ αὑτῶν ἅμα ἐκποριζώμεθα. καὶ ἢν μὲν ἐσακούωσί τι πρεσβευομένων ἡμῶν, ταῦτα ἄριστα· ἢν δὲ μή, διελθόντων ἐτῶν δύο καὶ τριῶν ἄμεινον ἤδη, ἢν δοκῇ, πεφραγμένοι ἴμεν ἐπ’ αὐτούς. καὶ ἴσως ὁρῶντες ἡμῶν ἤδη τήν τε παρασκευὴν καὶ τοὺς λόγους αὐτῇ ὁμοῖα ὑποσημαίνοντας μᾶλλον ἂν εἴκοιεν, καὶ γῆν ἔτι ἄτμητον ἔχοντες καὶ περὶ παρόντων ἀγαθῶν καὶ οὔπω ἐφθαρμένων βουλευόμενοι. μὴ γὰρ ἄλλο τι νομίσητε τὴν γῆν αὐτῶν ἢ ὅμηρον ἔχειν καὶ οὐχ ἧσσον ὅσῳ ἄμεινον ἐξείργασται· ἧς φείδεσθαι χρὴ ὡς ἐπὶ πλεῖστον, καὶ μὴ ἐς ἀπόνοιαν καταστήσαντας αὐτοὺς ἀληπτοτέρους ἔχειν. εἰ γὰρ ἀπαράσκευοι τοῖς τῶν ξυμμάχων ἐγκλήμασιν ἐπειχθέντες τεμοῦμεν αὐτήν, ὁρᾶτε ὅπως μὴ αἴσχιον καὶ ἀπορώτερον τῇ Πελοποννήσῳ πράξομεν. ἐγκλήματα μὲν γὰρ καὶ πόλεων καὶ ἰδιωτῶν οἷόν τε καταλῦσαι· πόλεμον δὲ ξύμπαντας ἀραμένους ἕνεκα τῶν ἰδίων, ὃν οὐχ ὑπάρχει εἰδέναι καθ’ ὅτι χωρήσει, οὐ ῥᾴδιον εὐπρεπῶς θέσθαι.", "st": "1.82"}, {"sp": "N", "t": "‘καὶ ἀνανδρία μηδενὶ πολλοὺς μιᾷ πόλει μὴ ταχὺ ἐπελθεῖν δοκείτω εἶναι. εἰσὶ γὰρ καὶ ἐκείνοις οὐκ ἐλάσσους χρήματα φέροντες ξύμμαχοι, καὶ ἔστιν ὁ πόλεμος οὐχ ὅπλων τὸ πλέον ἀλλὰ δαπάνης, δι’ ἣν τὰ ὅπλα ὠφελεῖ, ἄλλως τε καὶ ἠπειρώταις πρὸς θαλασσίους. πορισώμεθα οὖν πρῶτον αὐτήν, καὶ μὴ τοῖς τῶν ξυμμάχων λόγοις πρότερον ἐπαιρώμεθα, οἵπερ δὲ καὶ τῶν ἀποβαινόντων τὸ πλέον ἐπ’ ἀμφότερα τῆς αἰτίας ἕξομεν, οὗτοι καὶ καθ’ ἡσυχίαν τι αὐτῶν προΐδωμεν.", "st": "1.83"}, {"sp": "N", "t": "καὶ τὸ βραδὺ καὶ μέλλον, ὃ μέμφονται μάλιστα ἡμῶν, μὴ αἰσχύνεσθε. σπεύδοντές τε γὰρ σχολαίτερον ἂν παύσαισθε διὰ τὸ ἀπαράσκευοι ἐγχειρεῖν, καὶ ἅμα ἐλευθέραν καὶ εὐδοξοτάτην πόλιν διὰ παντὸς νεμόμεθα. καὶ δύναται μάλιστα σωφροσύνη ἔμφρων τοῦτ’ εἶναι· μόνοι γὰρ δι’ αὐτὸ εὐπραγίαις τε οὐκ ἐξυβρίζομεν καὶ ξυμφοραῖς ἧσσον ἑτέρων εἴκομεν· τῶν τε ξὺν ἐπαίνῳ ἐξοτρυνόντων ἡμᾶς ἐπὶ τὰ δεινὰ παρὰ τὸ δοκοῦν ἡμῖν οὐκ ἐπαιρόμεθα ἡδονῇ, καὶ ἤν τις ἄρα ξὺν κατηγορίᾳ παροξύνῃ, οὐδὲν δὴ μᾶλλον ἀχθεσθέντες ἀνεπείσθημεν. πολεμικοί τε καὶ εὔβουλοι διὰ τὸ εὔκοσμον γιγνόμεθα, τὸ μὲν ὅτι αἰδὼς σωφροσύνης πλεῖστον μετέχει, αἰσχύνης δὲ εὐψυχία, εὔβουλοι δὲ ἀμαθέστερον τῶν νόμων τῆς ὑπεροψίας παιδευόμενοι καὶ ξὺν χαλεπότητι σωφρονέστερον ἢ ὥστε αὐτῶν ἀνηκουστεῖν, καὶ μὴ τὰ ἀχρεῖα ξυνετοὶ ἄγαν ὄντες τὰς τῶν πολεμίων παρασκευὰς λόγῳ καλῶς μεμφόμενοι ἀνομοίως ἔργῳ ἐπεξιέναι, νομίζειν δὲ τάς τε διανοίας τῶν πέλας παραπλησίους εἶναι καὶ τὰς προσπιπτούσας τύχας οὐ λόγῳ διαιρετάς. αἰεὶ δὲ ὡς πρὸς εὖ βουλευομένους τοὺς ἐναντίους ἔργῳ παρασκευαζόμεθα· καὶ οὐκ ἐξ ἐκείνων ὡς ἁμαρτησομένων ἔχειν δεῖ τὰς ἐλπίδας, ἀλλ’ ὡς ἡμῶν αὐτῶν ἀσφαλῶς προνοουμένων. πολύ τε διαφέρειν οὐ δεῖ νομίζειν ἄνθρωπον ἀνθρώπου, κράτιστον δὲ εἶναι ὅστις ἐν τοῖς ἀναγκαιοτάτοις παιδεύεται.", "st": "1.84"}, {"sp": "N", "t": "‘ταύτας οὖν ἃς οἱ πατέρες τε ἡμῖν παρέδοσαν μελέτας καὶ αὐτοὶ διὰ παντὸς ὠφελούμενοι ἔχομεν μὴ παρῶμεν, μηδὲ ἐπειχθέντες ἐν βραχεῖ μορίῳ ἡμέρας περὶ πολλῶν σωμάτων καὶ χρημάτων καὶ πόλεων καὶ δόξης βουλεύσωμεν, ἀλλὰ καθ’ ἡσυχίαν. ἔξεστι δ’ ἡμῖν μᾶλλον ἑτέρων διὰ ἰσχύν. καὶ πρὸς τοὺς Ἀθηναίους πέμπετε μὲν περὶ τῆς Ποτειδαίας, πέμπετε δὲ περὶ ὧν οἱ ξύμμαχοί φασιν ἀδικεῖσθαι, ἄλλως τε καὶ ἑτοίμων ὄντων αὐτῶν δίκας δοῦναι· ἐπὶ δὲ τὸν διδόντα οὐ πρότερον νόμιμον ὡς ἐπ’ ἀδικοῦντα ἰέναι. παρασκευάζεσθε δὲ τὸν πόλεμον ἅμα. ταῦτα γὰρ καὶ κράτιστα βουλεύσεσθε καὶ τοῖς ἐναντίοις φοβερώτατα.’ καὶ ὁ μὲν Ἀρχίδαμος τοιαῦτα εἶπεν· παρελθὼν δὲ Σθενελαΐδας τελευταῖος, εἷς τῶν ἐφόρων τότε ὤν, ἔλεξεν [τοῖς Λακεδαιμονίοις] ὧδε.", "st": "1.85"}, {"sp": "N", "t": "‘τοὺς μὲν λόγους τοὺς πολλοὺς τῶν Ἀθηναίων οὐ γιγνώσκω· ἐπαινέσαντες γὰρ πολλὰ ἑαυτοὺς οὐδαμοῦ ἀντεῖπον ὡς οὐκ ἀδικοῦσι τοὺς ἡμετέρους ξυμμάχους καὶ τὴν Πελοπόννησον· καίτοι εἰ πρὸς τοὺς Μήδους ἐγένοντο ἀγαθοὶ τότε, πρὸς δ’ ἡμᾶς κακοὶ νῦν, διπλασίας ζημίας ἄξιοί εἰσιν, ὅτι ἀντ’ ἀγαθῶν κακοὶ γεγένηνται. ἡμεῖς δὲ ὁμοῖοι καὶ τότε καὶ νῦν ἐσμέν, καὶ τοὺς ξυμμάχους, ἢν σωφρονῶμεν, οὐ περιοψόμεθα ἀδικουμένους οὐδὲ μελλήσομεν τιμωρεῖν· οἱ δ’ οὐκέτι μέλλουσι κακῶς πάσχειν. ἄλλοις μὲν γὰρ χρήματά ἐστι πολλὰ καὶ νῆες καὶ ἵπποι, ἡμῖν δὲ ξύμμαχοι ἀγαθοί, οὓς οὐ παραδοτέα τοῖς Ἀθηναίοις ἐστίν, οὐδὲ δίκαις καὶ λόγοις διακριτέα μὴ λόγῳ καὶ αὐτοὺς βλαπτομένους, ἀλλὰ τιμωρητέα ἐν τάχει καὶ παντὶ σθένει. καὶ ὡς ἡμᾶς πρέπει βουλεύεσθαι ἀδικουμένους μηδεὶς διδασκέτω, ἀλλὰ τοὺς μέλλοντας ἀδικεῖν μᾶλλον πρέπει πολὺν χρόνον βουλεύεσθαι. ψηφίζεσθε οὖν, ὦ Λακεδαιμόνιοι, ἀξίως τῆς Σπάρτης τὸν πόλεμον, καὶ μήτε τοὺς Ἀθηναίους ἐᾶτε μείζους γίγνεσθαι μήτε τοὺς ξυμμάχους καταπροδιδῶμεν, ἀλλὰ ξὺν τοῖς θεοῖς ἐπίωμεν ἐπὶ τοὺς ἀδικοῦντας.’", "st": "1.86"}, {"sp": "N", "t": "τοιαῦτα λέξας ἐπεψήφιζεν αὐτὸς ἔφορος ὢν ἐς τὴν ἐκκλησίαν τῶν Λακεδαιμονίων. ὁ δέ (κρίνουσι γὰρ βοῇ καὶ οὐ ψήφῳ) οὐκ ἔφη διαγιγνώσκειν τὴν βοὴν ὁποτέρα μείζων, ἀλλὰ βουλόμενος αὐτοὺς φανερῶς ἀποδεικνυμένους τὴν γνώμην ἐς τὸ πολεμεῖν μᾶλλον ὁρμῆσαι ἔλεξεν ‘ὅτῳ μὲν ὑμῶν, ὦ Λακεδαιμόνιοι, δοκοῦσι λελύσθαι αἱ σπονδαὶ καὶ οἱ Ἀθηναῖοι ἀδικεῖν, ἀναστήτω ἐς ἐκεῖνο τὸ χωρίον,’ δείξας τι χωρίον αὐτοῖς, ‘ὅτῳ δὲ μὴ δοκοῦσιν, ἐς τὰ ἐπὶ θάτερα.’ ἀναστάντες δὲ διέστησαν, καὶ πολλῷ πλείους ἐγένοντο οἷς ἐδόκουν αἱ σπονδαὶ λελύσθαι. προσκαλέσαντές τε τοὺς ξυμμάχους εἶπον ὅτι σφίσι μὲν δοκοῖεν ἀδικεῖν οἱ Ἀθηναῖοι, βούλεσθαι δὲ καὶ τοὺς πάντας ξυμμάχους παρακαλέσαντες ψῆφον ἐπαγαγεῖν, ὅπως κοινῇ βουλευσάμενοι τὸν πόλεμον ποιῶνται, ἢν δοκῇ. καὶ οἱ μὲν ἀπεχώρησαν ἐπ’ οἴκου διαπραξάμενοι ταῦτα, καὶ οἱ Ἀθηναίων πρέσβεις ὕστερον ἐφ’ ἅπερ ἦλθον χρηματίσαντες· ἡ δὲ διαγνώμη αὕτη τῆς ἐκκλησίας, τοῦ τὰς σπονδὰς λελύσθαι, ἐγένετο ἐν τῷ τετάρτῳ καὶ δεκάτῳ ἔτει τῶν τριακοντουτίδων σπονδῶν προκεχωρηκυιῶν, αἳ ἐγένοντο μετὰ τὰ Εὐβοϊκά.", "st": "1.87"}, {"sp": "N", "t": "ἐψηφίσαντο δὲ οἱ Λακεδαιμόνιοι τὰς σπονδὰς λελύσθαι καὶ πολεμητέα εἶναι οὐ τοσοῦτον τῶν ξυμμάχων πεισθέντες τοῖς λόγοις ὅσον φοβούμενοι τοὺς Ἀθηναίους μὴ ἐπὶ μεῖζον δυνηθῶσιν, ὁρῶντες αὐτοῖς τὰ πολλὰ τῆς Ἑλλάδος ὑποχείρια ἤδη ὄντα.", "st": "1.88"}, {"sp": "N", "t": "οἱ γὰρ Ἀθηναῖοι τρόπῳ τοιῷδε ἦλθον ἐπὶ τὰ πράγματα ἐν οἷς ηὐξήθησαν. ἐπειδὴ Μῆδοι ἀνεχώρησαν ἐκ τῆς Εὐρώπης νικηθέντες καὶ ναυσὶ καὶ πεζῷ ὑπὸ Ἑλλήνων καὶ οἱ καταφυγόντες αὐτῶν ταῖς ναυσὶν ἐς Μυκάλην διεφθάρησαν, Λεωτυχίδης μὲν ὁ βασιλεὺς τῶν Λακεδαιμονίων, ὅσπερ ἡγεῖτο τῶν ἐν Μυκάλῃ Ἑλλήνων, ἀπεχώρησεν ἐπ’ οἴκου ἔχων τοὺς ἀπὸ Πελοποννήσου ξυμμάχους, οἱ δὲ Ἀθηναῖοι καὶ οἱ ἀπὸ Ἰωνίας καὶ Ἑλλησπόντου ξύμμαχοι ἤδη ἀφεστηκότες ἀπὸ βασιλέως ὑπομείναντες Σηστὸν ἐπολιόρκουν Μήδων ἐχόντων, καὶ ἐπιχειμάσαντες εἷλον αὐτὴν ἐκλιπόντων τῶν βαρβάρων, καὶ μετὰ τοῦτο ἀπέπλευσαν ἐξ Ἑλλησπόντου ὡς ἕκαστοι κατὰ πόλεις. Ἀθηναίων δὲ τὸ κοινόν, ἐπειδὴ αὐτοῖς οἱ βάρβαροι ἐκ τῆς χώρας ἀπῆλθον, διεκομίζοντο εὐθὺς ὅθεν ὑπεξέθεντο παῖδας καὶ γυναῖκας καὶ τὴν περιοῦσαν κατασκευήν, καὶ τὴν πόλιν ἀνοικοδομεῖν παρεσκευάζοντο καὶ τὰ τείχη· τοῦ τε γὰρ περιβόλου βραχέα εἱστήκει καὶ οἰκίαι αἱ μὲν πολλαὶ ἐπεπτώκεσαν, ὀλίγαι δὲ περιῆσαν, ἐν αἷς αὐτοὶ ἐσκήνωσαν οἱ δυνατοὶ τῶν Περσῶν.", "st": "1.89"}, {"sp": "N", "t": "Λακεδαιμόνιοι δὲ αἰσθόμενοι τὸ μέλλον ἦλθον πρεσβείᾳ, τὰ μὲν καὶ αὐτοὶ ἥδιον ἂν ὁρῶντες μήτ’ ἐκείνους μήτ’ ἄλλον μηδένα τεῖχος ἔχοντα, τὸ δὲ πλέον τῶν ξυμμάχων ἐξοτρυνόντων καὶ φοβουμένων τοῦ τε ναυτικοῦ αὐτῶν τὸ πλῆθος, ὃ πρὶν οὐχ ὑπῆρχε, καὶ τὴν ἐς τὸν Μηδικὸν πόλεμον τόλμαν γενομένην. ἠξίουν τε αὐτοὺς μὴ τειχίζειν, ἀλλὰ καὶ τῶν ἔξω Πελοποννήσου μᾶλλον ὅσοις εἱστήκει ξυγκαθελεῖν μετὰ σφῶν τοὺς περιβόλους, τὸ μὲν βουλόμενον καὶ ὕποπτον τῆς γνώμης οὐ δηλοῦντες ἐς τοὺς Ἀθηναίους, ὡς δὲ τοῦ βαρβάρου, εἰ αὖθις ἐπέλθοι, οὐκ ἂν ἔχοντος ἀπὸ ἐχυροῦ ποθέν, ὥσπερ νῦν ἐκ τῶν Θηβῶν, ὁρμᾶσθαι· τήν τε Πελοπόννησον πᾶσιν ἔφασαν ἀναχώρησίν τε καὶ ἀφορμὴν ἱκανὴν εἶναι. οἱ δ’ Ἀθηναῖοι Θεμιστοκλέους γνώμῃ τοὺς μὲν Λακεδαιμονίους ταῦτ’ εἰπόντας ἀποκρινάμενοι ὅτι πέμψουσιν ὡς αὐτοὺς πρέσβεις περὶ ὧν λέγουσιν εὐθὺς ἀπήλλαξαν· ἑαυτὸν δ’ ἐκέλευεν ἀποστέλλειν ὡς τάχιστα ὁ Θεμιστοκλῆς ἐς τὴν Λακεδαίμονα, ἄλλους δὲ πρὸς ἑαυτῷ ἑλομένους πρέσβεις μὴ εὐθὺς ἐκπέμπειν, ἀλλ’ ἐπισχεῖν μέχρι τοσούτου ἕως ἂν τὸ τεῖχος ἱκανὸν ἄρωσιν ὥστε ἀπομάχεσθαι ἐκ τοῦ ἀναγκαιοτάτου ὕψους· τειχίζειν δὲ πάντας πανδημεὶ τοὺς ἐν τῇ πόλει [καὶ αὐτοὺς καὶ γυναῖκας καὶ παῖδας], φειδομένους μήτε ἰδίου μήτε δημοσίου οἰκοδομήματος ὅθεν τις ὠφελία ἔσται ἐς τὸ ἔργον, ἀλλὰ καθαιροῦντας πάντα. καὶ ὁ μὲν ταῦτα διδάξας καὶ ὑπειπὼν τἆλλα ὅτι αὐτὸς τἀκεῖ πράξοι ᾤχετο. καὶ ἐς τὴν Λακεδαίμονα ἐλθὼν οὐ προσῄει πρὸς τὰς ἀρχάς, ἀλλὰ διῆγε καὶ προυφασίζετο. καὶ ὁπότε τις αὐτὸν ἔροιτο τῶν ἐν τέλει ὄντων ὅτι οὐκ ἐπέρχεται ἐπὶ τὸ κοινόν, ἔφη τοὺς ξυμπρέσβεις ἀναμένειν, ἀσχολίας δέ τινος οὔσης αὐτοὺς ὑπολειφθῆναι, προσδέχεσθαι μέντοι ἐν τάχει ἥξειν καὶ θαυμάζειν ὡς οὔπω πάρεισιν.", "st": "1.90"}, {"sp": "N", "t": "οἱ δὲ ἀκούοντες τῷ μὲν Θεμιστοκλεῖ ἐπείθοντο διὰ φιλίαν αὐτοῦ, τῶν δὲ ἄλλων ἀφικνουμένων καὶ σαφῶς κατηγορούντων ὅτι τειχίζεταί τε καὶ ἤδη ὕψος λαμβάνει, οὐκ εἶχον ὅπως χρὴ ἀπιστῆσαι. γνοὺς δὲ ἐκεῖνος κελεύει αὐτοὺς μὴ λόγοις μᾶλλον παράγεσθαι ἢ πέμψαι σφῶν αὐτῶν ἄνδρας οἵτινες χρηστοὶ καὶ πιστῶς ἀναγγελοῦσι σκεψάμενοι. ἀποστέλλουσιν οὖν, καὶ περὶ αὐτῶν ὁ Θεμιστοκλῆς τοῖς Ἀθηναίοις κρύφα πέμπει κελεύων ὡς ἥκιστα ἐπιφανῶς κατασχεῖν καὶ μὴ ἀφεῖναι πρὶν ἂν αὐτοὶ πάλιν κομισθῶσιν (ἤδη γὰρ καὶ ἧκον αὐτῷ οἱ ξυμπρέσβεις, Ἁβρώνιχός τε ὁ Λυσικλέους καὶ Ἀριστείδης ὁ Λυσιμάχου, ἀγγέλλοντες ἔχειν ἱκανῶς τὸ τεῖχος) ἐφοβεῖτο γὰρ μὴ οἱ Λακεδαιμόνιοι σφᾶς, ὁπότε σαφῶς ἀκούσειαν, οὐκέτι ἀφῶσιν. οἵ τε οὖν Ἀθηναῖοι τοὺς πρέσβεις, ὥσπερ ἐπεστάλη, κατεῖχον, καὶ ὁ Θεμιστοκλῆς ἐπελθὼν τοῖς Λακεδαιμονίοις ἐνταῦθα δὴ φανερῶς εἶπεν ὅτι ἡ μὲν πόλις σφῶν τετείχισται ἤδη ὥστε ἱκανὴ εἶναι σῴζειν τοὺς ἐνοικοῦντας, εἰ δέ τι βούλονται Λακεδαιμόνιοι ἢ οἱ ξύμμαχοι πρεσβεύεσθαι παρὰ σφᾶς, ὡς πρὸς διαγιγνώσκοντας τὸ λοιπὸν ἰέναι τά τε σφίσιν αὐτοῖς ξύμφορα καὶ τὰ κοινά. τήν τε γὰρ πόλιν ὅτε ἐδόκει ἐκλιπεῖν ἄμεινον εἶναι καὶ ἐς τὰς ναῦς ἐσβῆναι, ἄνευ ἐκείνων ἔφασαν γνόντες τολμῆσαι, καὶ ὅσα αὖ μετ’ ἐκείνων βουλεύεσθαι, οὐδενὸς ὕστεροι γνώμῃ φανῆναι. δοκεῖν οὖν σφίσι καὶ νῦν ἄμεινον εἶναι τὴν ἑαυτῶν πόλιν τεῖχος ἔχειν, καὶ ἰδίᾳ τοῖς πολίταις καὶ ἐς τοὺς πάντας ξυμμάχους ὠφελιμώτερον ἔσεσθαι· οὐ γὰρ οἷόν τ’ εἶναι μὴ ἀπὸ ἀντιπάλου παρασκευῆς ὁμοῖόν τι ἢ ἴσον ἐς τὸ κοινὸν βουλεύεσθαι. ἢ πάντας οὖν ἀτειχίστους ἔφη χρῆναι ξυμμαχεῖν ἢ καὶ τάδε νομίζειν ὀρθῶς ἔχειν.", "st": "1.91"}, {"sp": "N", "t": "οἱ δὲ Λακεδαιμόνιοι ἀκούσαντες ὀργὴν μὲν φανερὰν οὐκ ἐποιοῦντο τοῖς Ἀθηναίοις (οὐδὲ γὰρ ἐπὶ κωλύμῃ, ἀλλὰ γνώμης παραινέσει δῆθεν τῷ κοινῷ ἐπρεσβεύσαντο, ἅμα δὲ καὶ προσφιλεῖς ὄντες ἐν τῷ τότε διὰ τὴν ἐς τὸν Μῆδον προθυμίαν τὰ μάλιστ’ αὐτοῖς ἐτύγχανον), τῆς μέντοι βουλήσεως ἁμαρτάνοντες ἀδήλως ἤχθοντο. οἵ τε πρέσβεις ἑκατέρων ἀπῆλθον ἐπ’ οἴκου ἀνεπικλήτως.", "st": "1.92"}, {"sp": "N", "t": "τούτῳ τῷ τρόπῳ οἱ Ἀθηναῖοι τὴν πόλιν ἐτείχισαν ἐν ὀλίγῳ χρόνῳ. καὶ δήλη ἡ οἰκοδομία ἔτι καὶ νῦν ἐστὶν ὅτι κατὰ σπουδὴν ἐγένετο· οἱ γὰρ θεμέλιοι παντοίων λίθων ὑπόκεινται καὶ οὐ ξυνειργασμένων ἔστιν ᾗ, ἀλλ’ ὡς ἕκαστόν ποτε προσέφερον, πολλαί τε στῆλαι ἀπὸ σημάτων καὶ λίθοι εἰργασμένοι ἐγκατελέγησαν. μείζων γὰρ ὁ περίβολος πανταχῇ ἐξήχθη τῆς πόλεως, καὶ διὰ τοῦτο πάντα ὁμοίως κινοῦντες ἠπείγοντο. ἔπεισε δὲ καὶ τοῦ Πειραιῶς τὰ λοιπὰ ὁ Θεμιστοκλῆς οἰκοδομεῖν (ὑπῆρκτο δ’ αὐτοῦ πρότερον ἐπὶ τῆς ἐκείνου ἀρχῆς ἧς κατ’ ἐνιαυτὸν Ἀθηναίοις ἦρξε) νομίζων τό τε χωρίον καλὸν εἶναι, λιμένας ἔχον τρεῖς αὐτοφυεῖς, καὶ αὐτοὺς ναυτικοὺς γεγενημένους μέγα προφέρειν ἐς τὸ κτήσασθαι δύναμιν (τῆς γὰρ δὴ θαλάσσης πρῶτος ἐτόλμησεν εἰπεῖν ὡς ἀνθεκτέα ἐστί), καὶ τὴν ἀρχὴν εὐθὺς ξυγκατεσκεύαζεν. καὶ ᾠκοδόμησαν τῇ ἐκείνου γνώμῃ τὸ πάχος τοῦ τείχους ὅπερ νῦν ἔτι δῆλόν ἐστι περὶ τὸν Πειραιᾶ· δύο γὰρ ἅμαξαι ἐναντίαι ἀλλήλαις τοὺς λίθους ἐπῆγον. ἐντὸς δὲ οὔτε χάλιξ οὔτε πηλὸς ἦν, ἀλλὰ ξυνῳκοδομημένοι μεγάλοι λίθοι καὶ ἐντομῇ ἐγγώνιοι, σιδήρῳ πρὸς ἀλλήλους τὰ ἔξωθεν καὶ μολύβδῳ δεδεμένοι. τὸ δὲ ὕψος ἥμισυ μάλιστα ἐτελέσθη οὗ διενοεῖτο. ἐβούλετο γὰρ τῷ μεγέθει καὶ τῷ πάχει ἀφιστάναι τὰς τῶν πολεμίων ἐπιβουλάς, ἀνθρώπων τε ἐνόμιζεν ὀλίγων καὶ τῶν ἀχρειοτάτων ἀρκέσειν τὴν φυλακήν, τοὺς δ’ ἄλλους ἐς τὰς ναῦς ἐσβήσεσθαι. ταῖς γὰρ ναυσὶ μάλιστα προσέκειτο, ἰδών, ὡς ἐμοὶ δοκεῖ, τῆς βασιλέως στρατιᾶς τὴν κατὰ θάλασσαν ἔφοδον εὐπορωτέραν τῆς κατὰ γῆν οὖσαν· τόν τε Πειραιᾶ ὠφελιμώτερον ἐνόμιζε τῆς ἄνω πόλεως, καὶ πολλάκις τοῖς Ἀθηναίοις παρῄνει, ἢν ἄρα ποτὲ κατὰ γῆν βιασθῶσι, καταβάντας ἐς αὐτὸν ταῖς ναυσὶ πρὸς ἅπαντας ἀνθίστασθαι. Ἀθηναῖοι μὲν οὖν οὕτως ἐτειχίσθησαν καὶ τἆλλα κατεσκευάζοντο εὐθὺς μετὰ τὴν Μήδων ἀναχώρησιν.", "st": "1.93"}, {"sp": "N", "t": "Παυσανίας δὲ ὁ Κλεομβρότου ἐκ Λακεδαίμονος στρατηγὸς τῶν Ἑλλήνων ἐξεπέμφθη μετὰ εἴκοσι νεῶν ἀπὸ Πελοποννήσου· ξυνέπλεον δὲ καὶ Ἀθηναῖοι τριάκοντα ναυσὶ καὶ τῶν ἄλλων ξυμμάχων πλῆθος. καὶ ἐστράτευσαν ἐς Κύπρον καὶ αὐτῆς τὰ πολλὰ κατεστρέψαντο, καὶ ὕστερον ἐς Βυζάντιον Μήδων ἐχόντων, καὶ ἐξεπολιόρκησαν ἐν τῇδε τῇ ἡγεμονίᾳ.", "st": "1.94"}, {"sp": "N", "t": "ἤδη δὲ βιαίου ὄντος αὐτοῦ οἵ τε ἄλλοι Ἕλληνες ἤχθοντο καὶ οὐχ ἥκιστα οἱ Ἴωνες καὶ ὅσοι ἀπὸ βασιλέως νεωστὶ ἠλευθέρωντο· φοιτῶντές τε πρὸς τοὺς Ἀθηναίους ἠξίουν αὐτοὺς ἡγεμόνας σφῶν γίγνεσθαι κατὰ τὸ ξυγγενὲς καὶ Παυσανίᾳ μὴ ἐπιτρέπειν, ἤν που βιάζηται. οἱ δὲ Ἀθηναῖοι ἐδέξαντό τε τοὺς λόγους καὶ προσεῖχον τὴν γνώμην ὡς οὐ περιοψόμενοι τἆλλά τε καταστησόμενοι ᾗ φαίνοιτο ἄριστα αὐτοῖς. ἐν τούτῳ δὲ οἱ Λακεδαιμόνιοι μετεπέμποντο Παυσανίαν ἀνακρινοῦντες ὧν πέρι ἐπυνθάνοντο· καὶ γὰρ ἀδικία πολλὴ κατηγορεῖτο αὐτοῦ ὑπὸ τῶν Ἑλλήνων τῶν ἀφικνουμένων, καὶ τυραννίδος μᾶλλον ἐφαίνετο μίμησις ἢ στρατηγία. ξυνέβη τε αὐτῷ καλεῖσθαί τε ἅμα καὶ τοὺς ξυμμάχους τῷ ἐκείνου ἔχθει παρ’ Ἀθηναίους μετατάξασθαι πλὴν τῶν ἀπὸ Πελοποννήσου στρατιωτῶν. ἐλθὼν δὲ ἐς Λακεδαίμονα τῶν μὲν ἰδίᾳ πρός τινα ἀδικημάτων ηὐθύνθη, τὰ δὲ μέγιστα ἀπολύεται μὴ ἀδικεῖν· κατηγορεῖτο δὲ αὐτοῦ οὐχ ἥκιστα μηδισμὸς καὶ ἐδόκει σαφέστατον εἶναι. καὶ ἐκεῖνον μὲν οὐκέτι ἐκπέμπουσιν ἄρχοντα, Δόρκιν δὲ καὶ ἄλλους τινὰς μετ’ αὐτοῦ στρατιὰν ἔχοντας οὐ πολλήν· οἷς οὐκέτι ἐφίεσαν οἱ ξύμμαχοι τὴν ἡγεμονίαν. οἱ δὲ αἰσθόμενοι ἀπῆλθον, καὶ ἄλλους οὐκέτι ὕστερον ἐξέπεμψαν οἱ Λακεδαιμόνιοι, φοβούμενοι μὴ σφίσιν οἱ ἐξιόντες χείρους γίγνωνται, ὅπερ καὶ ἐν τῷ Παυσανίᾳ ἐνεῖδον, ἀπαλλαξείοντες δὲ καὶ τοῦ Μηδικοῦ πολέμου καὶ τοὺς Ἀθηναίους νομίζοντες ἱκανοὺς ἐξηγεῖσθαι καὶ σφίσιν ἐν τῷ τότε παρόντι ἐπιτηδείους.", "st": "1.95"}, {"sp": "N", "t": "παραλαβόντες δὲ οἱ Ἀθηναῖοι τὴν ἡγεμονίαν τούτῳ τῷ τρόπῳ ἑκόντων τῶν ξυμμάχων διὰ τὸ Παυσανίου μῖσος, ἔταξαν ἅς τε ἔδει παρέχειν τῶν πόλεων χρήματα πρὸς τὸν βάρβαρον καὶ ἃς ναῦς· πρόσχημα γὰρ ἦν ἀμύνεσθαι ὧν ἔπαθον δῃοῦντας τὴν βασιλέως χώραν. καὶ Ἑλληνοταμίαι τότε πρῶτον Ἀθηναίοις κατέστη ἀρχή, οἳ ἐδέχοντο τὸν φόρον· οὕτω γὰρ ὠνομάσθη τῶν χρημάτων ἡ φορά. ἦν δ’ ὁ πρῶτος φόρος ταχθεὶς τετρακόσια τάλαντα καὶ ἑξήκοντα. ταμιεῖόν τε Δῆλος ἦν αὐτοῖς, καὶ αἱ ξύνοδοι ἐς τὸ ἱερὸν ἐγίγνοντο.", "st": "1.96"}, {"sp": "N", "t": "ἡγούμενοι δὲ αὐτονόμων τὸ πρῶτον τῶν ξυμμάχων καὶ ἀπὸ κοινῶν ξυνόδων βουλευόντων τοσάδε ἐπῆλθον πολέμῳ τε καὶ διαχειρίσει πραγμάτων μεταξὺ τοῦδε τοῦ πολέμου καὶ τοῦ Μηδικοῦ, ἃ ἐγένετο πρός τε τὸν βάρβαρον αὐτοῖς καὶ πρὸς τοὺς σφετέρους ξυμμάχους νεωτερίζοντας καὶ Πελοποννησίων τοὺς αἰεὶ προστυγχάνοντας ἐν ἑκάστῳ. ἔγραψα δὲ αὐτὰ καὶ τὴν ἐκβολὴν τοῦ λόγου ἐποιησάμην διὰ τόδε, ὅτι τοῖς πρὸ ἐμοῦ ἅπασιν ἐκλιπὲς τοῦτο ἦν τὸ χωρίον καὶ ἢ τὰ πρὸ τῶν Μηδικῶν Ἑλληνικὰ ξυνετίθεσαν ἢ αὐτὰ τὰ Μηδικά· τούτων δὲ ὅσπερ καὶ ἥψατο ἐν τῇ Ἀττικῇ ξυγγραφῇ Ἑλλάνικος, βραχέως τε καὶ τοῖς χρόνοις οὐκ ἀκριβῶς ἐπεμνήσθη. ἅμα δὲ καὶ τῆς ἀρχῆς ἀπόδειξιν ἔχει τῆς τῶν Ἀθηναίων ἐν οἵῳ τρόπῳ κατέστη.", "st": "1.97"}, {"sp": "N", "t": "πρῶτον μὲν Ἠιόνα τὴν ἐπὶ Στρυμόνι Μήδων ἐχόντων πολιορκίᾳ εἷλον καὶ ἠνδραπόδισαν, Κίμωνος τοῦ Μιλτιάδου στρατηγοῦντος. ἔπειτα Σκῦρον τὴν ἐν τῷ Αἰγαίῳ νῆσον, ἣν ᾤκουν Δόλοπες, ἠνδραπόδισαν καὶ ᾤκισαν αὐτοί. πρὸς δὲ Καρυστίους αὐτοῖς ἄνευ τῶν ἄλλων Εὐβοέων πόλεμος ἐγένετο, καὶ χρόνῳ ξυνέβησαν καθ’ ὁμολογίαν. Ναξίοις δὲ ἀποστᾶσι μετὰ ταῦτα ἐπολέμησαν καὶ πολιορκίᾳ παρεστήσαντο, πρώτη τε αὕτη πόλις ξυμμαχὶς παρὰ τὸ καθεστηκὸς ἐδουλώθη, ἔπειτα δὲ καὶ τῶν ἄλλων ὡς ἑκάστῃ ξυνέβη.", "st": "1.98"}, {"sp": "N", "t": "αἰτίαι δὲ ἄλλαι τε ἦσαν τῶν ἀποστάσεων καὶ μέγισται αἱ τῶν φόρων καὶ νεῶν ἔκδειαι καὶ λιποστράτιον εἴ τῳ ἐγένετο· οἱ γὰρ Ἀθηναῖοι ἀκριβῶς ἔπρασσον καὶ λυπηροὶ ἦσαν οὐκ εἰωθόσιν οὐδὲ βουλομένοις ταλαιπωρεῖν προσάγοντες τὰς ἀνάγκας. ἦσαν δέ πως καὶ ἄλλως οἱ Ἀθηναῖοι οὐκέτι ὁμοίως ἐν ἡδονῇ ἄρχοντες, καὶ οὔτε ξυνεστράτευον ἀπὸ τοῦ ἴσου ῥᾴδιόν τε προσάγεσθαι ἦν αὐτοῖς τοὺς ἀφισταμένους. ὧν αὐτοὶ αἴτιοι ἐγένοντο οἱ ξύμμαχοι· διὰ γὰρ τὴν ἀπόκνησιν ταύτην τῶν στρατειῶν οἱ πλείους αὐτῶν, ἵνα μὴ ἀπ’ οἴκου ὦσι, χρήματα ἐτάξαντο ἀντὶ τῶν νεῶν τὸ ἱκνούμενον ἀνάλωμα φέρειν, καὶ τοῖς μὲν Ἀθηναίοις ηὔξετο τὸ ναυτικὸν ἀπὸ τῆς δαπάνης ἣν ἐκεῖνοι ξυμφέροιεν, αὐτοὶ δέ, ὁπότε ἀποσταῖεν, ἀπαράσκευοι καὶ ἄπειροι ἐς τὸν πόλεμον καθίσταντο.", "st": "1.99"}, {"sp": "N", "t": "ἐγένετο δὲ μετὰ ταῦτα καὶ ἡ ἐπ’ Εὐρυμέδοντι ποταμῷ ἐν Παμφυλίᾳ πεζομαχία καὶ ναυμαχία Ἀθηναίων καὶ τῶν ξυμμάχων πρὸς Μήδους, καὶ ἐνίκων τῇ αὐτῇ ἡμέρᾳ ἀμφότερα Ἀθηναῖοι Κίμωνος τοῦ Μιλτιάδου στρατηγοῦντος, καὶ εἷλον τριήρεις Φοινίκων καὶ διέφθειραν τὰς πάσας ἐς διακοσίας. χρόνῳ δὲ ὕστερον ξυνέβη Θασίους αὐτῶν ἀποστῆναι, διενεχθέντας περὶ τῶν ἐν τῇ ἀντιπέρας Θρᾴκῃ ἐμπορίων καὶ τοῦ μετάλλου ἃ ἐνέμοντο. καὶ ναυσὶ μὲν ἐπὶ Θάσον πλεύσαντες οἱ Ἀθηναῖοι ναυμαχίᾳ ἐκράτησαν καὶ ἐς τὴν γῆν ἀπέβησαν, ἐπὶ δὲ Στρυμόνα πέμψαντες μυρίους οἰκήτορας αὑτῶν καὶ τῶν ξυμμάχων ὑπὸ τοὺς αὐτοὺς χρόνους ὡς οἰκιοῦντες τὰς τότε καλουμένας Ἐννέα ὁδούς, νῦν δὲ Ἀμφίπολιν, τῶν μὲν Ἐννέα ὁδῶν αὐτοὶ ἐκράτησαν, ἃς εἶχον Ἠδωνοί, προελθόντες δὲ τῆς Θρᾴκης ἐς μεσόγειαν διεφθάρησαν ἐν Δραβησκῷ τῇ Ἠδωνικῇ ὑπὸ τῶν Θρᾳκῶν ξυμπάντων, οἷς πολέμιον ἦν τὸ χωρίον [αἱ Ἐννέα ὁδοὶ] κτιζόμενον.", "st": "1.100"}, {"sp": "N", "t": "Θάσιοι δὲ νικηθέντες μάχῃ καὶ πολιορκούμενοι Λακεδαιμονίους ἐπεκαλοῦντο καὶ ἐπαμύνειν ἐκέλευον ἐσβαλόντας ἐς τὴν Ἀττικήν. οἱ δὲ ὑπέσχοντο μὲν κρύφα τῶν Ἀθηναίων καὶ ἔμελλον, διεκωλύθησαν δὲ ὑπὸ τοῦ γενομένου σεισμοῦ, ἐν ᾧ καὶ οἱ Εἵλωτες αὐτοῖς καὶ τῶν περιοίκων Θουριᾶταί τε καὶ Αἰθαιῆς ἐς Ἰθώμην ἀπέστησαν. πλεῖστοι δὲ τῶν Εἱλώτων ἐγένοντο οἱ τῶν παλαιῶν Μεσσηνίων τότε δουλωθέντων ἀπόγονοι· ᾗ καὶ Μεσσήνιοι ἐκλήθησαν οἱ πάντες. πρὸς μὲν οὖν τοὺς ἐν Ἰθώμῃ πόλεμος καθειστήκει Λακεδαιμονίοις, Θάσιοι δὲ τρίτῳ ἔτει πολιορκούμενοι ὡμολόγησαν Ἀθηναίοις τεῖχός τε καθελόντες καὶ ναῦς παραδόντες, χρήματά τε ὅσα ἔδει ἀποδοῦναι αὐτίκα ταξάμενοι καὶ τὸ λοιπὸν φέρειν, τήν τε ἤπειρον καὶ τὸ μέταλλον ἀφέντες.", "st": "1.101"}, {"sp": "N", "t": "Λακεδαιμόνιοι δέ, ὡς αὐτοῖς πρὸς τοὺς ἐν Ἰθώμῃ ἐμηκύνετο ὁ πόλεμος, ἄλλους τε ἐπεκαλέσαντο ξυμμάχους καὶ Ἀθηναίους· οἱ δ’ ἦλθον Κίμωνος στρατηγοῦντος πλήθει οὐκ ὀλίγῳ. μάλιστα δ’ αὐτοὺς ἐπεκαλέσαντο ὅτι τειχομαχεῖν ἐδόκουν δυνατοὶ εἶναι, τοῖς δὲ πολιορκίας μακρᾶς καθεστηκυίας τούτου ἐνδεᾶ ἐφαίνετο· βίᾳ γὰρ ἂν εἷλον τὸ χωρίον. καὶ διαφορὰ ἐκ ταύτης τῆς στρατείας πρῶτον Λακεδαιμονίοις καὶ Ἀθηναίοις φανερὰ ἐγένετο. οἱ γὰρ Λακεδαιμόνιοι, ἐπειδὴ τὸ χωρίον βίᾳ οὐχ ἡλίσκετο, δείσαντες τῶν Ἀθηναίων τὸ τολμηρὸν καὶ τὴν νεωτεροποιίαν, καὶ ἀλλοφύλους ἅμα ἡγησάμενοι, μή τι, ἢν παραμείνωσιν, ὑπὸ τῶν ἐν Ἰθώμῃ πεισθέντες νεωτερίσωσι, μόνους τῶν ξυμμάχων ἀπέπεμψαν, τὴν μὲν ὑποψίαν οὐ δηλοῦντες, εἰπόντες δὲ ὅτι οὐδὲν προσδέονται αὐτῶν ἔτι. οἱ δ’ Ἀθηναῖοι ἔγνωσαν οὐκ ἐπὶ τῷ βελτίονι λόγῳ ἀποπεμπόμενοι, ἀλλά τινος ὑπόπτου γενομένου, καὶ δεινὸν ποιησάμενοι καὶ οὐκ ἀξιώσαντες ὑπὸ Λακεδαιμονίων τοῦτο παθεῖν, εὐθὺς ἐπειδὴ ἀνεχώρησαν, ἀφέντες τὴν γενομένην ἐπὶ τῷ Μήδῳ ξυμμαχίαν πρὸς αὐτοὺς Ἀργείοις τοῖς ἐκείνων πολεμίοις ξύμμαχοι ἐγένοντο, καὶ πρὸς Θεσσαλοὺς ἅμα ἀμφοτέροις οἱ αὐτοὶ ὅρκοι καὶ ξυμμαχία κατέστη.", "st": "1.102"}, {"sp": "N", "t": "οἱ δ’ ἐν Ἰθώμῃ δεκάτῳ ἔτει, ὡς οὐκέτι ἐδύναντο ἀντέχειν, ξυνέβησαν πρὸς τοὺς Λακεδαιμονίους ἐφ’ ᾧ ἐξίασιν ἐκ Πελοποννήσου ὑπόσπονδοι καὶ μηδέποτε ἐπιβήσονται αὐτῆς· ἢν δέ τις ἁλίσκηται, τοῦ λαβόντος εἶναι δοῦλον. ἦν δέ τι καὶ χρηστήριον τοῖς Λακεδαιμονίοις Πυθικὸν πρὸ τοῦ, τὸν ἱκέτην τοῦ Διὸς τοῦ Ἰθωμήτα ἀφιέναι. ἐξῆλθον δὲ αὐτοὶ καὶ παῖδες καὶ γυναῖκες, καὶ αὐτοὺς οἱ Ἀθηναῖοι δεξάμενοι κατ’ ἔχθος ἤδη τὸ Λακεδαιμονίων ἐς Ναύπακτον κατῴκισαν, ἣν ἔτυχον ᾑρηκότες νεωστὶ Λοκρῶν τῶν Ὀζολῶν ἐχόντων. προσεχώρησαν δὲ καὶ Μεγαρῆς Ἀθηναίοις ἐς ξυμμαχίαν Λακεδαιμονίων ἀποστάντες, ὅτι αὐτοὺς Κορίνθιοι περὶ γῆς ὅρων πολέμῳ κατεῖχον· καὶ ἔσχον Ἀθηναῖοι Μέγαρα καὶ Πηγάς, καὶ τὰ μακρὰ τείχη ᾠκοδόμησαν Μεγαρεῦσι τὰ ἀπὸ τῆς πόλεως ἐς Νίσαιαν καὶ ἐφρούρουν αὐτοί. καὶ Κορινθίοις μὲν οὐχ ἥκιστα ἀπὸ τοῦδε τὸ σφοδρὸν μῖσος ἤρξατο πρῶτον ἐς Ἀθηναίους γενέσθαι.", "st": "1.103"}, {"sp": "N", "t": "Ἰνάρως δὲ ὁ Ψαμμητίχου, Λίβυς, βασιλεὺς Λιβύων τῶν πρὸς Αἰγύπτῳ, ὁρμώμενος ἐκ Μαρείας τῆς ὑπὲρ Φάρου πόλεως ἀπέστησεν Αἰγύπτου τὰ πλείω ἀπὸ βασιλέως Ἀρταξέρξου, καὶ αὐτὸς ἄρχων γενόμενος Ἀθηναίους ἐπηγάγετο. οἱ δέ (ἔτυχον γὰρ ἐς Κύπρον στρατευόμενοι ναυσὶ διακοσίαις αὑτῶν τε καὶ τῶν ξυμμάχων) ἦλθον ἀπολιπόντες τὴν Κύπρον, καὶ ἀναπλεύσαντες ἀπὸ θαλάσσης ἐς τὸν Νεῖλον τοῦ τε ποταμοῦ κρατοῦντες καὶ τῆς Μέμφιδος τῶν δύο μερῶν πρὸς τὸ τρίτον μέρος ὃ καλεῖται Λευκὸν τεῖχος ἐπολέμουν· ἐνῆσαν δὲ αὐτόθι Περσῶν καὶ Μήδων οἱ καταφυγόντες καὶ Αἰγυπτίων οἱ μὴ ξυναποστάντες.", "st": "1.104"}, {"sp": "N", "t": "Ἀθηναίοις δὲ ναυσὶν ἀποβᾶσιν ἐς Ἁλιᾶς πρὸς Κορινθίους καὶ Ἐπιδαυρίους μάχη ἐγένετο, καὶ ἐνίκων Κορίνθιοι. καὶ ὕστερον Ἀθηναῖοι ἐναυμάχησαν ἐπὶ Κεκρυφαλείᾳ Πελοποννησίων ναυσί, καὶ ἐνίκων Ἀθηναῖοι. πολέμου δὲ καταστάντος πρὸς Αἰγινήτας Ἀθηναίοις μετὰ ταῦτα ναυμαχία γίγνεται ἐπ’ Αἰγίνῃ μεγάλη Ἀθηναίων καὶ Αἰγινητῶν, καὶ οἱ ξύμμαχοι ἑκατέροις παρῆσαν, καὶ ἐνίκων Ἀθηναῖοι καὶ ναῦς ἑβδομήκοντα λαβόντες αὐτῶν ἐς τὴν γῆν ἀπέβησαν καὶ ἐπολιόρκουν, Λεωκράτους τοῦ Στροίβου στρατηγοῦντος. ἔπειτα Πελοποννήσιοι ἀμύνειν βουλόμενοι Αἰγινήταις ἐς μὲν τὴν Αἴγιναν τριακοσίους ὁπλίτας πρότερον Κορινθίων καὶ Ἐπιδαυρίων ἐπικούρους διεβίβασαν, τὰ δὲ ἄκρα τῆς Γερανείας κατέλαβον καὶ ἐς τὴν Μεγαρίδα κατέβησαν Κορίνθιοι μετὰ τῶν ξυμμάχων, νομίζοντες ἀδυνάτους ἔσεσθαι Ἀθηναίους βοηθεῖν τοῖς Μεγαρεῦσιν ἔν τε Αἰγίνῃ ἀπούσης στρατιᾶς πολλῆς καὶ ἐν Αἰγύπτῳ· ἢν δὲ καὶ βοηθῶσιν, ἀπ’ Αἰγίνης ἀναστήσεσθαι αὐτούς. οἱ δὲ Ἀθηναῖοι τὸ μὲν πρὸς Αἰγίνῃ στράτευμα οὐκ ἐκίνησαν, τῶν δ’ ἐκ τῆς πόλεως ὑπολοίπων οἵ τε πρεσβύτατοι καὶ οἱ νεώτατοι ἀφικνοῦνται ἐς τὰ Μέγαρα Μυρωνίδου στρατηγοῦντος. καὶ μάχης γενομένης ἰσορρόπου πρὸς Κορινθίους διεκρίθησαν ἀπ’ ἀλλήλων, καὶ ἐνόμισαν αὐτοὶ ἑκάτεροι οὐκ ἔλασσον ἔχειν ἐν τῷ ἔργῳ. καὶ οἱ μὲν Ἀθηναῖοι (ἐκράτησαν γὰρ ὅμως μᾶλλον) ἀπελθόντων τῶν Κορινθίων τροπαῖον ἔστησαν· οἱ δὲ Κορίνθιοι κακιζόμενοι ὑπὸ τῶν ἐν τῇ πόλει πρεσβυτέρων καὶ παρασκευασάμενοι, ἡμέραις ὕστερον δώδεκα μάλιστα ἐλθόντες ἀνθίστασαν τροπαῖον καὶ αὐτοὶ ὡς νικήσαντες. καὶ οἱ Ἀθηναῖοι ἐκβοηθήσαντες ἐκ τῶν Μεγάρων τούς τε τὸ τροπαῖον ἱστάντας διαφθείρουσι καὶ τοῖς ἄλλοις ξυμβαλόντες ἐκράτησαν.", "st": "1.105"}, {"sp": "N", "t": "οἱ δὲ νικώμενοι ὑπεχώρουν, καί τι αὐτῶν μέρος οὐκ ὀλίγον προσβιασθὲν καὶ διαμαρτὸν τῆς ὁδοῦ ἐσέπεσεν ἔς του χωρίον ἰδιώτου, ᾧ ἔτυχεν ὄρυγμα μέγα περιεῖργον καὶ οὐκ ἦν ἔξοδος. οἱ δὲ Ἀθηναῖοι γνόντες κατὰ πρόσωπόν τε εἶργον τοῖς ὁπλίταις καὶ περιστήσαντες κύκλῳ τοὺς ψιλοὺς κατέλευσαν πάντας τοὺς ἐσελθόντας, καὶ πάθος μέγα τοῦτο Κορινθίοις ἐγένετο. τὸ δὲ πλῆθος ἀπεχώρησεν αὐτοῖς τῆς στρατιᾶς ἐπ’ οἴκου.", "st": "1.106"}, {"sp": "N", "t": "ἤρξαντο δὲ κατὰ τοὺς χρόνους τούτους καὶ τὰ μακρὰ τείχη Ἀθηναῖοι ἐς θάλασσαν οἰκοδομεῖν, τό τε Φαληρόνδε καὶ τὸ ἐς Πειραιᾶ. καὶ Φωκέων στρατευσάντων ἐς Δωριᾶς τὴν Λακεδαιμονίων μητρόπολιν, Βοιὸν καὶ Κυτίνιον καὶ Ἐρινεόν, καὶ ἑλόντων ἓν τῶν πολισμάτων τούτων, οἱ Λακεδαιμόνιοι Νικομήδους τοῦ Κλεομβρότου ὑπὲρ Πλειστοάνακτος τοῦ Παυσανίου βασιλέως νέου ὄντος ἔτι ἡγουμένου ἐβοήθησαν τοῖς Δωριεῦσιν ἑαυτῶν τε πεντακοσίοις καὶ χιλίοις ὁπλίταις καὶ τῶν ξυμμάχων μυρίοις, καὶ τοὺς Φωκέας ὁμολογίᾳ ἀναγκάσαντες ἀποδοῦναι τὴν πόλιν ἀπεχώρουν πάλιν. καὶ κατὰ θάλασσαν μὲν αὐτούς, διὰ τοῦ Κρισαίου κόλπου εἰ βούλοιντο περαιοῦσθαι, Ἀθηναῖοι ναυσὶ περιπλεύσαντες ἔμελλον κωλύσειν· διὰ δὲ τῆς Γερανείας οὐκ ἀσφαλὲς αὐτοῖς ἐφαίνετο Ἀθηναίων ἐχόντων Μέγαρα καὶ Πηγὰς πορεύεσθαι. δύσοδός τε γὰρ ἡ Γερανεία καὶ ἐφρουρεῖτο αἰεὶ ὑπὸ Ἀθηναίων, καὶ τότε ᾐσθάνοντο αὐτοὺς μέλλοντας καὶ ταύτῃ κωλύσειν. ἔδοξε δ’ αὐτοῖς ἐν Βοιωτοῖς περιμείνασι σκέψασθαι ὅτῳ τρόπῳ ἀσφαλέστατα διαπορεύσονται. τὸ δέ τι καὶ ἄνδρες τῶν Ἀθηναίων ἐπῆγον αὐτοὺς κρύφα, ἐλπίσαντες δῆμόν τε καταπαύσειν καὶ τὰ μακρὰ τείχη οἰκοδομούμενα. ἐβοήθησαν δὲ ἐπ’ αὐτοὺς οἱ Ἀθηναῖοι πανδημεὶ καὶ Ἀργείων χίλιοι καὶ τῶν ἄλλων ξυμμάχων ὡς ἕκαστοι· ξύμπαντες δὲ ἐγένοντο τετρακισχίλιοι καὶ μύριοι. νομίσαντες δὲ ἀπορεῖν ὅπῃ διέλθωσιν ἐπεστράτευσαν αὐτοῖς, καί τι καὶ τοῦ δήμου καταλύσεως ὑποψίᾳ. ἦλθον δὲ καὶ Θεσσαλῶν ἱππῆς τοῖς Ἀθηναίοις κατὰ τὸ ξυμμαχικόν, οἳ μετέστησαν ἐν τῷ ἔργῳ παρὰ τοὺς Λακεδαιμονίους.", "st": "1.107"}, {"sp": "N", "t": "γενομένης δὲ μάχης ἐν Τανάγρᾳ τῆς Βοιωτίας ἐνίκων Λακεδαιμόνιοι καὶ οἱ ξύμμαχοι, καὶ φόνος ἐγένετο ἀμφοτέρων πολύς. καὶ Λακεδαιμόνιοι μὲν ἐς τὴν Μεγαρίδα ἐλθόντες καὶ δενδροτομήσαντες πάλιν ἀπῆλθον ἐπ’ οἴκου διὰ Γερανείας καὶ Ἰσθμοῦ· Ἀθηναῖοι δὲ δευτέρᾳ καὶ ἑξηκοστῇ ἡμέρᾳ μετὰ τὴν μάχην ἐστράτευσαν ἐς Βοιωτοὺς Μυρωνίδου στρατηγοῦντος, καὶ μάχῃ ἐν Οἰνοφύτοις τοὺς Βοιωτοὺς νικήσαντες τῆς τε χώρας ἐκράτησαν τῆς Βοιωτίας καὶ Φωκίδος καὶ Ταναγραίων τὸ τεῖχος περιεῖλον καὶ Λοκρῶν τῶν Ὀπουντίων ἑκατὸν ἄνδρας ὁμήρους τοὺς πλουσιωτάτους ἔλαβον, τά τε τείχη ἑαυτῶν τὰ μακρὰ ἀπετέλεσαν. ὡμολόγησαν δὲ καὶ οἱ Αἰγινῆται μετὰ ταῦτα τοῖς Ἀθηναίοις, τείχη τε περιελόντες καὶ ναῦς παραδόντες φόρον τε ταξάμενοι ἐς τὸν ἔπειτα χρόνον. καὶ Πελοπόννησον περιέπλευσαν Ἀθηναῖοι Τολμίδου τοῦ Τολμαίου στρατηγοῦντος, καὶ τὸ νεώριον τῶν Λακεδαιμονίων ἐνέπρησαν καὶ Χαλκίδα Κορινθίων πόλιν εἷλον καὶ Σικυωνίους ἐν ἀποβάσει τῆς γῆς μάχῃ ἐκράτησαν.", "st": "1.108"}, {"sp": "N", "t": "οἱ δ’ ἐν τῇ Αἰγύπτῳ Ἀθηναῖοι καὶ οἱ ξύμμαχοι ἐπέμενον, καὶ αὐτοῖς πολλαὶ ἰδέαι πολέμων κατέστησαν. τὸ μὲν γὰρ πρῶτον ἐκράτουν τῆς Αἰγύπτου οἱ Ἀθηναῖοι, καὶ βασιλεὺς πέμπει ἐς Λακεδαίμονα Μεγάβαζον ἄνδρα Πέρσην χρήματα ἔχοντα, ὅπως ἐς τὴν Ἀττικὴν ἐσβαλεῖν πεισθέντων τῶν Πελοποννησίων ἀπ’ Αἰγύπτου ἀπαγάγοι Ἀθηναίους. ὡς δὲ αὐτῷ οὐ προυχώρει καὶ τὰ χρήματα ἄλλως ἀνηλοῦτο, ὁ μὲν Μεγάβαζος καὶ τὰ λοιπὰ τῶν χρημάτων πάλιν ἐς τὴν Ἀσίαν ἀνεκομίσθη, Μεγάβυζον δὲ τὸν Ζωπύρου πέμπει ἄνδρα Πέρσην μετὰ στρατιᾶς πολλῆς· ὃς ἀφικόμενος κατὰ γῆν τούς τε Αἰγυπτίους καὶ τοὺς ξυμμάχους μάχῃ ἐκράτησε καὶ ἐκ τῆς Μέμφιδος ἐξήλασε τοὺς Ἕλληνας καὶ τέλος ἐς Προσωπίτιδα τὴν νῆσον κατέκλῃσε καὶ ἐπολιόρκει ἐν αὐτῇ ἐνιαυτὸν καὶ ἓξ μῆνας, μέχρι οὗ ξηράνας τὴν διώρυχα καὶ παρατρέψας ἄλλῃ τὸ ὕδωρ τάς τε ναῦς ἐπὶ τοῦ ξηροῦ ἐποίησε καὶ τῆς νήσου τὰ πολλὰ ἤπειρον, καὶ διαβὰς εἷλε τὴν νῆσον πεζῇ.", "st": "1.109"}, {"sp": "N", "t": "οὕτω μὲν τὰ τῶν Ἑλλήνων πράγματα ἐφθάρη ἓξ ἔτη πολεμήσαντα· καὶ ὀλίγοι ἀπὸ πολλῶν πορευόμενοι διὰ τῆς Λιβύης ἐς Κυρήνην ἐσώθησαν, οἱ δὲ πλεῖστοι ἀπώλοντο. Αἴγυπτος δὲ πάλιν ὑπὸ βασιλέα ἐγένετο πλὴν Ἀμυρταίου τοῦ ἐν τοῖς ἕλεσι βασιλέως· τοῦτον δὲ διὰ μέγεθός τε τοῦ ἕλους οὐκ ἐδύναντο ἑλεῖν, καὶ ἅμα μαχιμώτατοί εἰσι τῶν Αἰγυπτίων οἱ ἕλειοι. Ἰνάρως δὲ ὁ Λιβύων βασιλεύς, ὃς τὰ πάντα ἔπραξε περὶ τῆς Αἰγύπτου, προδοσίᾳ ληφθεὶς ἀνεσταυρώθη. ἐκ δὲ τῶν Ἀθηνῶν καὶ τῆς ἄλλης ξυμμαχίδος πεντήκοντα τριήρεις διάδοχοι πλέουσαι ἐς Αἴγυπτον ἔσχον κατὰ τὸ Μενδήσιον κέρας, οὐκ εἰδότες τῶν γεγονότων οὐδέν· καὶ αὐτοῖς ἔκ τε γῆς ἐπιπεσόντες πεζοὶ καὶ ἐκ θαλάσσης Φοινίκων ναυτικὸν διέφθειραν τὰς πολλὰς τῶν νεῶν, αἱ δ’ ἐλάσσους διέφυγον πάλιν. τὰ μὲν κατὰ τὴν μεγάλην στρατείαν Ἀθηναίων καὶ τῶν ξυμμάχων ἐς Αἴγυπτον οὕτως ἐτελεύτησεν.", "st": "1.110"}, {"sp": "N", "t": "ἐκ δὲ Θεσσαλίας Ὀρέστης ὁ Ἐχεκρατίδου υἱὸς τοῦ Θεσσαλῶν βασιλέως φεύγων ἔπεισεν Ἀθηναίους ἑαυτὸν κατάγειν· καὶ παραλαβόντες Βοιωτοὺς καὶ Φωκέας ὄντας ξυμμάχους οἱ Ἀθηναῖοι ἐστράτευσαν τῆς Θεσσαλίας ἐπὶ Φάρσαλον. καὶ τῆς μὲν γῆς ἐκράτουν ὅσα μὴ προϊόντες πολὺ ἐκ τῶν ὅπλων (οἱ γὰρ ἱππῆς τῶν Θεσσαλῶν εἶργον), τὴν δὲ πόλιν οὐχ εἷλον, οὐδ’ ἄλλο προυχώρει αὐτοῖς οὐδὲν ὧν ἕνεκα ἐστράτευσαν, ἀλλ’ ἀπεχώρησαν πάλιν Ὀρέστην ἔχοντες ἄπρακτοι. μετὰ δὲ ταῦτα οὐ πολλῷ ὕστερον χίλιοι Ἀθηναίων ἐπὶ τὰς ναῦς τὰς ἐν Πηγαῖς ἐπιβάντες (εἶχον δ’ αὐτοὶ τὰς Πηγάς) παρέπλευσαν ἐς Σικυῶνα Περικλέους τοῦ Ξανθίππου στρατηγοῦντος, καὶ ἀποβάντες Σικυωνίων τοὺς προσμείξαντας μάχῃ ἐκράτησαν. καὶ εὐθὺς παραλαβόντες Ἀχαιοὺς καὶ διαπλεύσαντες πέραν τῆς Ἀκαρνανίας ἐς Οἰνιάδας ἐστράτευσαν καὶ ἐπολιόρκουν, οὐ μέντοι εἷλόν γε, ἀλλ’ ἀπεχώρησαν ἐπ’ οἴκου.", "st": "1.111"}, {"sp": "N", "t": "ὕστερον δὲ διαλιπόντων ἐτῶν τριῶν σπονδαὶ γίγνονται Πελοποννησίοις καὶ Ἀθηναίοις πεντέτεις. καὶ Ἑλληνικοῦ μὲν πολέμου ἔσχον οἱ Ἀθηναῖοι, ἐς δὲ Κύπρον ἐστρατεύοντο ναυσὶ διακοσίαις αὑτῶν τε καὶ τῶν ξυμμάχων Κίμωνος στρατηγοῦντος. καὶ ἑξήκοντα μὲν νῆες ἐς Αἴγυπτον ἀπ’ αὐτῶν ἔπλευσαν, Ἀμυρταίου μεταπέμποντος τοῦ ἐν τοῖς ἕλεσι βασιλέως, αἱ δὲ ἄλλαι Κίτιον ἐπολιόρκουν. Κίμωνος δὲ ἀποθανόντος καὶ λιμοῦ γενομένου ἀπεχώρησαν ἀπὸ Κιτίου, καὶ πλεύσαντες ὑπὲρ Σαλαμῖνος τῆς ἐν Κύπρῳ Φοίνιξι καὶ Κυπρίοις καὶ Κίλιξιν ἐναυμάχησαν καὶ ἐπεζομάχησαν ἅμα, καὶ νικήσαντες ἀμφότερα ἀπεχώρησαν ἐπ’ οἴκου καὶ αἱ ἐξ Αἰγύπτου νῆες πάλιν [αἱ] ἐλθοῦσαι μετ’ αὐτῶν. Λακεδαιμόνιοι δὲ μετὰ ταῦτα τὸν ἱερὸν καλούμενον πόλεμον ἐστράτευσαν, καὶ κρατήσαντες τοῦ ἐν Δελφοῖς ἱεροῦ παρέδοσαν Δελφοῖς· καὶ αὖθις ὕστερον Ἀθηναῖοι ἀποχωρησάντων αὐτῶν στρατεύσαντες καὶ κρατήσαντες παρέδοσαν Φωκεῦσιν.", "st": "1.112"}, {"sp": "N", "t": "καὶ χρόνου ἐγγενομένου μετὰ ταῦτα Ἀθηναῖοι, Βοιωτῶν τῶν φευγόντων ἐχόντων Ὀρχομενὸν καὶ Χαιρώνειαν καὶ ἄλλ’ ἄττα χωρία τῆς Βοιωτίας, ἐστράτευσαν ἑαυτῶν μὲν χιλίοις ὁπλίταις, τῶν δὲ ξυμμάχων ὡς ἑκάστοις ἐπὶ τὰ χωρία ταῦτα πολέμια ὄντα, Τολμίδου τοῦ Τολμαίου στρατηγοῦντος. καὶ Χαιρώνειαν ἑλόντες καὶ ἀνδραποδίσαντες ἀπεχώρουν φυλακὴν καταστήσαντες. πορευομένοις δ’ αὐτοῖς ἐν Κορωνείᾳ ἐπιτίθενται οἵ τε ἐκ τῆς Ὀρχομενοῦ φυγάδες Βοιωτῶν καὶ Λοκροὶ μετ’ αὐτῶν καὶ Εὐβοέων φυγάδες καὶ ὅσοι τῆς αὐτῆς γνώμης ἦσαν, καὶ μάχῃ κρατήσαντες τοὺς μὲν διέφθειραν τῶν Ἀθηναίων, τοὺς δὲ ζῶντας ἔλαβον. καὶ τὴν Βοιωτίαν ἐξέλιπον Ἀθηναῖοι πᾶσαν, σπονδὰς ποιησάμενοι ἐφ’ ᾧ τοὺς ἄνδρας κομιοῦνται. καὶ οἱ φεύγοντες Βοιωτῶν κατελθόντες καὶ οἱ ἄλλοι πάντες αὐτόνομοι πάλιν ἐγένοντο.", "st": "1.113"}, {"sp": "N", "t": "μετὰ δὲ ταῦτα οὐ πολλῷ ὕστερον Εὔβοια ἀπέστη ἀπὸ Ἀθηναίων, καὶ ἐς αὐτὴν διαβεβηκότος ἤδη Περικλέους στρατιᾷ Ἀθηναίων ἠγγέλθη αὐτῷ ὅτι Μέγαρα ἀφέστηκε καὶ Πελοποννήσιοι μέλλουσιν ἐσβαλεῖν ἐς τὴν Ἀττικὴν καὶ οἱ φρουροὶ Ἀθηναίων διεφθαρμένοι εἰσὶν ὑπὸ Μεγαρέων, πλὴν ὅσοι ἐς Νίσαιαν ἀπέφυγον· ἐπαγαγόμενοι δὲ Κορινθίους καὶ Σικυωνίους καὶ Ἐπιδαυρίους ἀπέστησαν οἱ Μεγαρῆς. ὁ δὲ Περικλῆς πάλιν κατὰ τάχος ἐκόμιζε τὴν στρατιὰν ἐκ τῆς Εὐβοίας. καὶ μετὰ τοῦτο οἱ Πελοποννήσιοι τῆς Ἀττικῆς ἐς Ἐλευσῖνα καὶ Θριῶζε ἐσβαλόντες ἐδῄωσαν Πλειστοάνακτος τοῦ Παυσανίου βασιλέως Λακεδαιμονίων ἡγουμένου, καὶ τὸ πλέον οὐκέτι προελθόντες ἀπεχώρησαν ἐπ’ οἴκου. καὶ Ἀθηναῖοι πάλιν ἐς Εὔβοιαν διαβάντες Περικλέους στρατηγοῦντος κατεστρέψαντο πᾶσαν, καὶ τὴν μὲν ἄλλην ὁμολογίᾳ κατεστήσαντο, Ἑστιαιᾶς δὲ ἐξοικίσαντες αὐτοὶ τὴν γῆν ἔσχον.", "st": "1.114"}, {"sp": "N", "t": "ἀναχωρήσαντες δὲ ἀπ’ Εὐβοίας οὐ πολλῷ ὕστερον σπονδὰς ἐποιήσαντο πρὸς Λακεδαιμονίους καὶ τοὺς ξυμμάχους τριακοντούτεις, ἀποδόντες Νίσαιαν καὶ Πηγὰς καὶ Τροιζῆνα καὶ Ἀχαΐαν· ταῦτα γὰρ εἶχον Ἀθηναῖοι Πελοποννησίων.", "st": "1.115"}, {"sp": "N", "t": "ἕκτῳ δὲ ἔτει Σαμίοις καὶ Μιλησίοις πόλεμος ἐγένετο περὶ Πριήνης, καὶ οἱ Μιλήσιοι ἐλασσούμενοι τῷ πολέμῳ παρ’ Ἀθηναίους ἐλθόντες κατεβόων τῶν Σαμίων. ξυνεπελάβοντο δὲ καὶ ἐξ αὐτῆς τῆς Σάμου ἄνδρες ἰδιῶται νεωτερίσαι βουλόμενοι τὴν πολιτείαν. πλεύσαντες οὖν Ἀθηναῖοι ἐς Σάμον ναυσὶ τεσσαράκοντα δημοκρατίαν κατέστησαν, καὶ ὁμήρους ἔλαβον τῶν Σαμίων πεντήκοντα μὲν παῖδας, ἴσους δὲ ἄνδρας, καὶ κατέθεντο ἐς Λῆμνον, καὶ φρουρὰν ἐγκαταλιπόντες ἀνεχώρησαν. τῶν δὲ Σαμίων ἦσαν γάρ τινες οἳ οὐχ ὑπέμειναν, ἀλλ’ ἔφυγον ἐς τὴν ἤπειρον, ξυνθέμενοι τῶν ἐν τῇ πόλει τοῖς δυνατωτάτοις καὶ Πισσούθνῃ τῷ Ὑστάσπου ξυμμαχίαν, ὃς εἶχε Σάρδεις τότε, ἐπικούρους τε ξυλλέξαντες ἐς ἑπτακοσίους διέβησαν ὑπὸ νύκτα ἐς τὴν Σάμον, καὶ πρῶτον μὲν τῷ δήμῳ ἐπανέστησαν καὶ ἐκράτησαν τῶν πλείστων, ἔπειτα τοὺς ὁμήρους ἐκκλέψαντες ἐκ Λήμνου τοὺς αὑτῶν ἀπέστησαν, καὶ τοὺς φρουροὺς τοὺς Ἀθηναίων καὶ τοὺς ἄρχοντας οἳ ἦσαν παρὰ σφίσιν ἐξέδοσαν Πισσούθνῃ, ἐπί τε Μίλητον εὐθὺς παρεσκευάζοντο στρατεύειν. ξυναπέστησαν δ’ αὐτοῖς καὶ Βυζάντιοι.", "st": "1.115"}, {"sp": "N", "t": "Ἀθηναῖοι δὲ ὡς ᾔσθοντο, πλεύσαντες ναυσὶν ἑξήκοντα ἐπὶ Σάμου ταῖς μὲν ἑκκαίδεκα τῶν νεῶν οὐκ ἐχρήσαντο (ἔτυχον γὰρ αἱ μὲν ἐπὶ Καρίας ἐς προσκοπὴν τῶν Φοινισσῶν νεῶν οἰχόμεναι, αἱ δὲ ἐπὶ Χίου καὶ Λέσβου περιαγγέλλουσαι βοηθεῖν), τεσσαράκοντα δὲ ναυσὶ καὶ τέσσαρσι Περικλέους δεκάτου αὐτοῦ στρατηγοῦντος ἐναυμάχησαν πρὸς Τραγίᾳ τῇ νήσῳ Σαμίων ναυσὶν ἑβδομήκοντα, ὧν ἦσαν αἱ εἴκοσι στρατιώτιδες (ἔτυχον δὲ αἱ πᾶσαι ἀπὸ Μιλήτου πλέουσαι), καὶ ἐνίκων Ἀθηναῖοι. ὕστερον δὲ αὐτοῖς ἐβοήθησαν ἐκ τῶν Ἀθηνῶν νῆες τεσσαράκοντα καὶ Χίων καὶ Λεσβίων πέντε καὶ εἴκοσι, καὶ ἀποβάντες καὶ κρατοῦντες τῷ πεζῷ ἐπολιόρκουν τρισὶ τείχεσι τὴν πόλιν καὶ ἐκ θαλάσσης ἅμα. Περικλῆς δὲ λαβὼν ἑξήκοντα ναῦς ἀπὸ τῶν ἐφορμουσῶν ᾤχετο κατὰ τάχος ἐπὶ Καύνου καὶ Καρίας, ἐσαγγελθέντων ὅτι Φοίνισσαι νῆες ἐπ’ αὐτοὺς πλέουσιν· ᾤχετο γὰρ καὶ ἐκ τῆς Σάμου πέντε ναυσὶ Στησαγόρας καὶ ἄλλοι ἐπὶ τὰς Φοινίσσας.", "st": "1.116"}, {"sp": "N", "t": "ἐν τούτῳ δὲ οἱ Σάμιοι ἐξαπιναίως ἔκπλουν ποιησάμενοι ἀφάρκτῳ τῷ στρατοπέδῳ ἐπιπεσόντες τάς τε προφυλακίδας ναῦς διέφθειραν καὶ ναυμαχοῦντες τὰς ἀνταναγομένας ἐνίκησαν, καὶ τῆς θαλάσσης τῆς καθ’ ἑαυτοὺς ἐκράτησαν ἡμέρας περὶ τέσσαρας καὶ δέκα, καὶ ἐσεκομίσαντο καὶ ἐξεκομίσαντο ἃ ἐβούλοντο. ἐλθόντος δὲ Περικλέους πάλιν ταῖς ναυσὶ κατεκλῄσθησαν. καὶ ἐκ τῶν Ἀθηνῶν ὕστερον προσεβοήθησαν τεσσαράκοντα μὲν αἱ μετὰ Θουκυδίδου καὶ Ἅγνωνος καὶ Φορμίωνος νῆες, εἴκοσι δὲ αἱ μετὰ Τληπολέμου καὶ Ἀντικλέους, ἐκ δὲ Χίου καὶ Λέσβου τριάκοντα. καὶ ναυμαχίαν μέν τινα βραχεῖαν ἐποιήσαντο οἱ Σάμιοι, ἀδύνατοι δὲ ὄντες ἀντίσχειν ἐξεπολιορκήθησαν ἐνάτῳ μηνὶ καὶ προσεχώρησαν ὁμολογίᾳ, τεῖχός τε καθελόντες καὶ ὁμήρους δόντες καὶ ναῦς παραδόντες καὶ χρήματα τὰ ἀναλωθέντα ταξάμενοι κατὰ χρόνους ἀποδοῦναι. ξυνέβησαν δὲ καὶ Βυζάντιοι ὥσπερ καὶ πρότερον ὑπήκοοι εἶναι.", "st": "1.117"}, {"sp": "N", "t": "μετὰ ταῦτα δὲ ἤδη γίγνεται οὐ πολλοῖς ἔτεσιν ὕστερον τὰ προειρημένα, τά τε Κερκυραϊκὰ καὶ τὰ Ποτειδεατικὰ καὶ ὅσα πρόφασις τοῦδε τοῦ πολέμου κατέστη. ταῦτα δὲ ξύμπαντα ὅσα ἔπραξαν οἱ Ἕλληνες πρός τε ἀλλήλους καὶ τὸν βάρβαρον ἐγένετο ἐν ἔτεσι πεντήκοντα μάλιστα μεταξὺ τῆς τε Ξέρξου ἀναχωρήσεως καὶ τῆς ἀρχῆς τοῦδε τοῦ πολέμου· ἐν οἷς οἱ Ἀθηναῖοι τήν τε ἀρχὴν ἐγκρατεστέραν κατεστήσαντο καὶ αὐτοὶ ἐπὶ μέγα ἐχώρησαν δυνάμεως, οἱ δὲ Λακεδαιμόνιοι αἰσθόμενοι οὔτε ἐκώλυον εἰ μὴ ἐπὶ βραχύ, ἡσύχαζόν τε τὸ πλέον τοῦ χρόνου, ὄντες μὲν καὶ πρὸ τοῦ μὴ ταχεῖς ἰέναι ἐς τοὺς πολέμους, ἢν μὴ ἀναγκάζωνται, τὸ δέ τι καὶ πολέμοις οἰκείοις ἐξειργόμενοι, πρὶν δὴ ἡ δύναμις τῶν Ἀθηναίων σαφῶς ᾔρετο καὶ τῆς ξυμμαχίας αὐτῶν ἥπτοντο. τότε δὲ οὐκέτι ἀνασχετὸν ἐποιοῦντο, ἀλλ’ ἐπιχειρητέα ἐδόκει εἶναι πάσῃ προθυμίᾳ καὶ καθαιρετέα ἡ ἰσχύς, ἢν δύνωνται, ἀραμένοις τόνδε τὸν πόλεμον. αὐτοῖς μὲν οὖν τοῖς Λακεδαιμονίοις διέγνωστο λελύσθαι τε τὰς σπονδὰς καὶ τοὺς Ἀθηναίους ἀδικεῖν, πέμψαντες δὲ ἐς Δελφοὺς ἐπηρώτων τὸν θεὸν εἰ πολεμοῦσιν ἄμεινον ἔσται· ὁ δὲ ἀνεῖλεν αὐτοῖς, ὡς λέγεται, κατὰ κράτος πολεμοῦσι νίκην ἔσεσθαι, καὶ αὐτὸς ἔφη ξυλλήψεσθαι καὶ παρακαλούμενος καὶ ἄκλητος.", "st": "1.118"}, {"sp": "N", "t": "αὖθις δὲ τοὺς ξυμμάχους παρακαλέσαντες ψῆφον ἐβούλοντο ἐπαγαγεῖν εἰ χρὴ πολεμεῖν. καὶ ἐλθόντων τῶν πρέσβεων ἀπὸ τῆς ξυμμαχίας καὶ ξυνόδου γενομένης οἵ τε ἄλλοι εἶπον ἃ ἐβούλοντο, κατηγοροῦντες οἱ πλείους τῶν Ἀθηναίων καὶ τὸν πόλεμον ἀξιοῦντες γίγνεσθαι, καὶ οἱ Κορίνθιοι δεηθέντες μὲν καὶ κατὰ πόλεις πρότερον ἑκάστων ἰδίᾳ ὥστε ψηφίσασθαι τὸν πόλεμον, δεδιότες περὶ τῇ Ποτειδαίᾳ μὴ προδιαφθαρῇ, παρόντες δὲ καὶ τότε καὶ τελευταῖοι ἐπελθόντες ἔλεγον τοιάδε.", "st": "1.119"}, {"sp": "N", "t": "‘τοὺς μὲν Λακεδαιμονίους, ὦ ἄνδρες ξύμμαχοι, οὐκ ἂν ἔτι αἰτιασαίμεθα ὡς οὐ καὶ αὐτοὶ ἐψηφισμένοι τὸν πόλεμόν εἰσι καὶ ἡμᾶς ἐς τοῦτο νῦν ξυνήγαγον. χρὴ γὰρ τοὺς ἡγεμόνας τὰ ἴδια ἐξ ἴσου νέμοντας τὰ κοινὰ προσκοπεῖν, ὥσπερ καὶ ἐν ἄλλοις ἐκ πάντων προτιμῶνται. ἡμῶν δὲ ὅσοι μὲν Ἀθηναίοις ἤδη ἐνηλλάγησαν οὐχὶ διδαχῆς δέονται ὥστε φυλάξασθαι αὐτούς· τοὺς δὲ τὴν μεσόγειαν μᾶλλον καὶ μὴ ἐν πόρῳ κατῳκημένους εἰδέναι χρὴ ὅτι, τοῖς κάτω ἢν μὴ ἀμύνωσι, χαλεπωτέραν ἕξουσι τὴν κατακομιδὴν τῶν ὡραίων καὶ πάλιν ἀντίληψιν ὧν ἡ θάλασσα τῇ ἠπείρῳ δίδωσι, καὶ τῶν νῦν λεγομένων μὴ κακοὺς κριτὰς ὡς μὴ προσηκόντων εἶναι, προσδέχεσθαι δέ ποτε, εἰ τὰ κάτω πρόοιντο, κἂν μέχρι σφῶν τὸ δεινὸν προελθεῖν, καὶ περὶ αὑτῶν οὐχ ἧσσον νῦν βουλεύεσθαι. δι’ ὅπερ καὶ μὴ ὀκνεῖν δεῖ αὐτοὺς τὸν πόλεμον ἀντ’ εἰρήνης μεταλαμβάνειν. ἀνδρῶν γὰρ σωφρόνων μέν ἐστιν, εἰ μὴ ἀδικοῖντο, ἡσυχάζειν, ἀγαθῶν δὲ ἀδικουμένους ἐκ μὲν εἰρήνης πολεμεῖν, εὖ δὲ παρασχὸν ἐκ πολέμου πάλιν ξυμβῆναι, καὶ μήτε τῇ κατὰ πόλεμον εὐτυχίᾳ ἐπαίρεσθαι μήτε τῷ ἡσύχῳ τῆς εἰρήνης ἡδόμενον ἀδικεῖσθαι. ὅ τε γὰρ διὰ τὴν ἡδονὴν ὀκνῶν τάχιστ’ ἂν ἀφαιρεθείη τῆς ῥᾳστώνης τὸ τερπνὸν δι’ ὅπερ ὀκνεῖ, εἰ ἡσυχάζοι, ὅ τε ἐν πολέμῳ εὐτυχίᾳ πλεονάζων οὐκ ἐντεθύμηται θράσει ἀπίστῳ ἐπαιρόμενος. πολλὰ γὰρ κακῶς γνωσθέντα ἀβουλοτέρων τῶν ἐναντίων τυχόντα κατωρθώθη, καὶ ἔτι πλείω καλῶς δοκοῦντα βουλευθῆναι ἐς τοὐναντίον αἰσχρῶς περιέστη· ἐνθυμεῖται γὰρ οὐδεὶς ὁμοῖα τῇ πίστει καὶ ἔργῳ ἐπεξέρχεται, ἀλλὰ μετ’ ἀσφαλείας μὲν δοξάζομεν, μετὰ δέους δὲ ἐν τῷ ἔργῳ ἐλλείπομεν.", "st": "1.120"}, {"sp": "N", "t": "‘ἡμεῖς δὲ νῦν καὶ ἀδικούμενοι τὸν πόλεμον ἐγείρομεν καὶ ἱκανὰ ἔχοντες ἐγκλήματα, καὶ ὅταν ἀμυνώμεθα Ἀθηναίους, καταθησόμεθα αὐτὸν ἐν καιρῷ. κατὰ πολλὰ δὲ ἡμᾶς εἰκὸς ἐπικρατῆσαι, πρῶτον μὲν πλήθει προύχοντας καὶ ἐμπειρίᾳ πολεμικῇ, ἔπειτα ὁμοίως πάντας ἐς τὰ παραγγελλόμενα ἰόντας, ναυτικόν τε, ᾧ ἰσχύουσιν, ἀπὸ τῆς ὑπαρχούσης τε ἑκάστοις οὐσίας ἐξαρτυσόμεθα καὶ ἀπὸ τῶν ἐν Δελφοῖς καὶ Ὀλυμπίᾳ χρημάτων· δάνεισμα γὰρ ποιησάμενοι ὑπολαβεῖν οἷοί τ’ ἐσμὲν μισθῷ μείζονι τοὺς ξένους αὐτῶν ναυβάτας. ὠνητὴ γὰρ ἡ Ἀθηναίων δύναμις μᾶλλον ἢ οἰκεία· ἡ δὲ ἡμετέρα ἧσσον ἂν τοῦτο πάθοι, τοῖς σώμασι τὸ πλέον ἰσχύουσα ἢ τοῖς χρήμασιν. μιᾷ τε νίκῃ ναυμαχίας κατὰ τὸ εἰκὸς ἁλίσκονται· εἰ δ’ ἀντίσχοιεν, μελετήσομεν καὶ ἡμεῖς ἐν πλέονι χρόνῳ τὰ ναυτικά, καὶ ὅταν τὴν ἐπιστήμην ἐς τὸ ἴσον καταστήσωμεν, τῇ γε εὐψυχίᾳ δήπου περιεσόμεθα. ὃ γὰρ ἡμεῖς ἔχομεν φύσει ἀγαθόν, ἐκείνοις οὐκ ἂν γένοιτο διδαχῇ· ὃ δ’ ἐκεῖνοι ἐπιστήμῃ προύχουσι, καθαιρετὸν ἡμῖν ἐστὶ μελέτῃ. χρήματα δὲ ὥστε ἔχειν ἐς αὐτά, οἴσομεν· ἢ δεινὸν ἂν εἴη εἰ οἱ μὲν ἐκείνων ξύμμαχοι ἐπὶ δουλείᾳ τῇ αὑτῶν φέροντες οὐκ ἀπεροῦσιν, ἡμεῖς δ’ ἐπὶ τῷ τιμωρούμενοι τοὺς ἐχθροὺς καὶ αὐτοὶ ἅμα σῴζεσθαι οὐκ ἄρα δαπανήσομεν καὶ ἐπὶ τῷ μὴ ὑπ’ ἐκείνων αὐτὰ ἀφαιρεθέντες αὐτοῖς τούτοις κακῶς πάσχειν.", "st": "1.121"}, {"sp": "N", "t": "ὑπάρχουσι δὲ καὶ ἄλλαι ὁδοὶ τοῦ πολέμου ἡμῖν, ξυμμάχων τε ἀπόστασις, μάλιστα παραίρεσις οὖσα τῶν προσόδων αἷς ἰσχύουσι, καὶ ἐπιτειχισμὸς τῇ χώρᾳ, ἄλλα τε ὅσα οὐκ ἄν τις νῦν προΐδοι. ἥκιστα γὰρ πόλεμος ἐπὶ ῥητοῖς χωρεῖ, αὐτὸς δὲ ἀφ’ αὑτοῦ τὰ πολλὰ τεχνᾶται πρὸς τὸ παρατυγχάνον· ἐν ᾧ ὁ μὲν εὐοργήτως αὐτῷ προσομιλήσας βεβαιότερος, ὁ δ’ ὀργισθεὶς περὶ αὐτὸν οὐκ ἐλάσσω πταίει.", "st": "1.122"}, {"sp": "N", "t": "‘ἐνθυμώμεθα δὲ καὶ ὅτι εἰ μὲν ἡμῶν ἦσαν ἑκάστοις πρὸς ἀντιπάλους περὶ γῆς ὅρων αἱ διαφοραί, οἰστὸν ἂν ἦν· νῦν δὲ πρὸς ξύμπαντάς τε ἡμᾶς Ἀθηναῖοι ἱκανοὶ καὶ κατὰ πόλιν ἔτι δυνατώτεροι, ὥστε εἰ μὴ καὶ ἁθρόοι καὶ κατὰ ἔθνη καὶ ἕκαστον ἄστυ μιᾷ γνώμῃ ἀμυνούμεθα αὐτούς, δίχα γε ὄντας ἡμᾶς ἀπόνως χειρώσονται. καὶ τὴν ἧσσαν, εἰ καὶ δεινόν τῳ ἀκοῦσαι, ἴστω οὐκ ἄλλο τι φέρουσαν ἢ ἄντικρυς δουλείαν· ὃ καὶ λόγῳ ἐνδοιασθῆναι αἰσχρὸν τῇ Πελοποννήσῳ καὶ πόλεις τοσάσδε ὑπὸ μιᾶς κακοπαθεῖν. ἐν ᾧ ἢ δικαίως δοκοῖμεν ἂν πάσχειν ἢ διὰ δειλίαν ἀνέχεσθαι καὶ τῶν πατέρων χείρους φαίνεσθαι, οἳ τὴν Ἑλλάδα ἠλευθέρωσαν, ἡμεῖς δὲ οὐδ’ ἡμῖν αὐτοῖς βεβαιοῦμεν αὐτό, τύραννον δὲ ἐῶμεν ἐγκαθεστάναι πόλιν, τοὺς δ’ ἐν μιᾷ μονάρχους ἀξιοῦμεν καταλύειν. καὶ οὐκ ἴσμεν ὅπως τάδε τριῶν τῶν μεγίστων ξυμφορῶν ἀπήλλακται, ἀξυνεσίας ἢ μαλακίας ἢ ἀμελείας. οὐ γὰρ δὴ πεφευγότες αὐτὰ ἐπὶ τὴν πλείστους δὴ βλάψασαν καταφρόνησιν κεχωρήκατε, ἣ ἐκ τοῦ πολλοὺς σφάλλειν τὸ ἐναντίον ὄνομα ἀφροσύνη μετωνόμασται.", "st": "1.122"}, {"sp": "N", "t": "τὰ μὲν οὖν προγεγενημένα τί δεῖ μακρότερον ἢ ἐς ὅσον τοῖς νῦν ξυμφέρει αἰτιᾶσθαι; περὶ δὲ τῶν ἔπειτα μελλόντων τοῖς παροῦσι βοηθοῦντας χρὴ ἐπιταλαιπωρεῖν (πάτριον γὰρ ὑμῖν ἐκ τῶν πόνων τὰς ἀρετὰς κτᾶσθαι), καὶ μὴ μεταβάλλειν τὸ ἔθος, εἰ ἄρα πλούτῳ τε νῦν καὶ ἐξουσίᾳ ὀλίγον προφέρετε (οὐ γὰρ δίκαιον ἃ τῇ ἀπορίᾳ ἐκτήθη τῇ περιουσίᾳ ἀπολέσθαι), ἀλλὰ θαρσοῦντας ἰέναι κατὰ πολλὰ ἐς τὸν πόλεμον, τοῦ τε θεοῦ χρήσαντος καὶ αὐτοῦ ὑποσχομένου ξυλλήψεσθαι καὶ τῆς ἄλλης Ἑλλάδος ἁπάσης ξυναγωνιουμένης, τὰ μὲν φόβῳ, τὰ δὲ ὠφελίᾳ. σπονδάς τε οὐ λύσετε πρότεροι, ἅς γε καὶ ὁ θεὸς κελεύων πολεμεῖν νομίζει παραβεβάσθαι, ἠδικημέναις δὲ μᾶλλον βοηθήσετε· λύουσι γὰρ οὐχ οἱ ἀμυνόμενοι, ἀλλ’ οἱ πρότεροι ἐπιόντες.", "st": "1.123"}, {"sp": "N", "t": "‘ὥστε πανταχόθεν καλῶς ὑπάρχον ὑμῖν πολεμεῖν καὶ ἡμῶν κοινῇ τάδε παραινούντων, εἴπερ βεβαιότατον τὸ ταὐτὰ ξυμφέροντα καὶ πόλεσι καὶ ἰδιώταις εἶναι, μὴ μέλλετε Ποτειδεάταις τε ποιεῖσθαι τιμωρίαν οὖσι Δωριεῦσι καὶ ὑπὸ Ἰώνων πολιορκουμένοις, οὗ πρότερον ἦν τοὐναντίον, καὶ τῶν ἄλλων μετελθεῖν τὴν ἐλευθερίαν, ὡς οὐκέτι ἐνδέχεται περιμένοντας τοὺς μὲν ἤδη βλάπτεσθαι, τοὺς δ’, εἰ γνωσθησόμεθα ξυνελθόντες μέν, ἀμύνεσθαι δὲ οὐ τολμῶντες, μὴ πολὺ ὕστερον τὸ αὐτὸ πάσχειν· ἀλλὰ νομίσαντες ἐς ἀνάγκην ἀφῖχθαι, ὦ ἄνδρες ξύμμαχοι, καὶ ἅμα τάδε ἄριστα λέγεσθαι, ψηφίσασθε τὸν πόλεμον μὴ φοβηθέντες τὸ αὐτίκα δεινόν, τῆς δ’ ἀπ’ αὐτοῦ διὰ πλείονος εἰρήνης ἐπιθυμήσαντες· ἐκ πολέμου μὲν γὰρ εἰρήνη μᾶλλον βεβαιοῦται, ἀφ’ ἡσυχίας δὲ μὴ πολεμῆσαι οὐχ ὁμοίως ἀκίνδυνον. καὶ τὴν καθεστηκυῖαν ἐν τῇ Ἑλλάδι πόλιν τύραννον ἡγησάμενοι ἐπὶ πᾶσιν ὁμοίως καθεστάναι, ὥστε τῶν μὲν ἤδη ἄρχειν, τῶν δὲ διανοεῖσθαι, παραστησώμεθα ἐπελθόντες, καὶ αὐτοί τε ἀκινδύνως τὸ λοιπὸν οἰκῶμεν καὶ τοὺς νῦν δεδουλωμένους Ἕλληνας ἐλευθερώσωμεν.’ τοιαῦτα μὲν οἱ Κορίνθιοι εἶπον.", "st": "1.124"}, {"sp": "N", "t": "οἱ δὲ Λακεδαιμόνιοι ἐπειδὴ ἀφ’ ἁπάντων ἤκουσαν γνώμην, ψῆφον ἐπήγαγον τοῖς ξυμμάχοις ἅπασιν ὅσοι παρῆσαν ἑξῆς, καὶ μείζονι καὶ ἐλάσσονι πόλει· καὶ τὸ πλῆθος ἐψηφίσαντο πολεμεῖν. δεδογμένον δὲ αὐτοῖς εὐθὺς μὲν ἀδύνατα ἦν ἐπιχειρεῖν ἀπαρασκεύοις οὖσιν, ἐκπορίζεσθαι δὲ ἐδόκει ἑκάστοις ἃ πρόσφορα ἦν καὶ μὴ εἶναι μέλλησιν. ὅμως δὲ καθισταμένοις ὧν ἔδει ἐνιαυτὸς μὲν οὐ διετρίβη, ἔλασσον δέ, πρὶν ἐσβαλεῖν ἐς τὴν Ἀττικὴν καὶ τὸν πόλεμον ἄρασθαι φανερῶς.", "st": "1.125"}, {"sp": "N", "t": "ἐν τούτῳ δὲ ἐπρεσβεύοντο τῷ χρόνῳ πρὸς τοὺς Ἀθηναίους ἐγκλήματα ποιούμενοι, ὅπως σφίσιν ὅτι μεγίστη πρόφασις εἴη τοῦ πολεμεῖν, ἢν μή τι ἐσακούωσιν.", "st": "1.126"}, {"sp": "N", "t": "καὶ πρῶτον μὲν πρέσβεις πέμψαντες οἱ Λακεδαιμόνιοι ἐκέλευον τοὺς Ἀθηναίους τὸ ἄγος ἐλαύνειν τῆς θεοῦ· τὸ δὲ ἄγος ἦν τοιόνδε. Κύλων ἦν Ἀθηναῖος ἀνὴρ Ὀλυμπιονίκης τῶν πάλαι εὐγενής τε καὶ δυνατός, ἐγεγαμήκει δὲ θυγατέρα Θεαγένους Μεγαρέως ἀνδρός, ὃς κατ’ ἐκεῖνον τὸν χρόνον ἐτυράννει Μεγάρων. χρωμένῳ δὲ τῷ Κύλωνι ἐν Δελφοῖς ἀνεῖλεν ὁ θεὸς ἐν τοῦ Διὸς τῇ μεγίστῃ ἑορτῇ καταλαβεῖν τὴν Ἀθηναίων ἀκρόπολιν. ὁ δὲ παρά τε τοῦ Θεαγένους δύναμιν λαβὼν καὶ τοὺς φίλους ἀναπείσας, ἐπειδὴ ἐπῆλθεν Ὀλύμπια τὰ ἐν Πελοποννήσῳ, κατέλαβε τὴν ἀκρόπολιν ὡς ἐπὶ τυραννίδι, νομίσας ἑορτήν τε τοῦ Διὸς μεγίστην εἶναι καὶ ἑαυτῷ τι προσήκειν Ὀλύμπια νενικηκότι. εἰ δὲ ἐν τῇ Ἀττικῇ ἢ ἄλλοθί που ἡ μεγίστη ἑορτὴ εἴρητο, οὔτε ἐκεῖνος ἔτι κατενόησε τό τε μαντεῖον οὐκ ἐδήλου (ἔστι γὰρ καὶ Ἀθηναίοις Διάσια ἃ καλεῖται Διὸς ἑορτὴ Μειλιχίου μεγίστη ἔξω τῆς πόλεως, ἐν ᾗ πανδημεὶ θύουσι πολλὰ οὐχ ἱερεῖα, ἀλλ’ ⟨ἁγνὰ⟩ θύματα ἐπιχώρια), δοκῶν δὲ ὀρθῶς γιγνώσκειν ἐπεχείρησε τῷ ἔργῳ. οἱ δὲ Ἀθηναῖοι αἰσθόμενοι ἐβοήθησάν τε πανδημεὶ ἐκ τῶν ἀγρῶν ἐπ’ αὐτοὺς καὶ προσκαθεζόμενοι ἐπολιόρκουν. χρόνου δὲ ἐγγιγνομένου οἱ Ἀθηναῖοι τρυχόμενοι τῇ προσεδρίᾳ ἀπῆλθον οἱ πολλοί, ἐπιτρέψαντες τοῖς ἐννέα ἄρχουσι τήν τε φυλακὴν καὶ τὸ πᾶν αὐτοκράτορσι διαθεῖναι ᾗ ἂν ἄριστα διαγιγνώσκωσιν· τότε δὲ τὰ πολλὰ τῶν πολιτικῶν οἱ ἐννέα ἄρχοντες ἔπρασσον. οἱ δὲ μετὰ τοῦ Κύλωνος πολιορκούμενοι φλαύρως εἶχον σίτου τε καὶ ὕδατος ἀπορίᾳ. ὁ μὲν οὖν Κύλων καὶ ὁ ἀδελφὸς αὐτοῦ ἐκδιδράσκουσιν· οἱ δ’ ἄλλοι ὡς ἐπιέζοντο καί τινες καὶ ἀπέθνῃσκον ὑπὸ τοῦ λιμοῦ, καθίζουσιν ἐπὶ τὸν βωμὸν ἱκέται τὸν ἐν τῇ ἀκροπόλει. ἀναστήσαντες δὲ αὐτοὺς οἱ τῶν Ἀθηναίων ἐπιτετραμμένοι τὴν φυλακήν, ὡς ἑώρων ἀποθνῄσκοντας ἐν τῷ ἱερῷ, ἐφ’ ᾧ μηδὲν κακὸν ποιήσουσιν, ἀπαγαγόντες ἀπέκτειναν· καθεζομένους δέ τινας καὶ ἐπὶ τῶν σεμνῶν θεῶν τοῖς βωμοῖς ἐν τῇ παρόδῳ ἀπεχρήσαντο. καὶ ἀπὸ τούτου ἐναγεῖς καὶ ἀλιτήριοι τῆς θεοῦ ἐκεῖνοί τε ἐκαλοῦντο καὶ τὸ γένος τὸ ἀπ’ ἐκείνων. ἤλασαν μὲν οὖν καὶ οἱ Ἀθηναῖοι τοὺς ἐναγεῖς τούτους, ἤλασε δὲ καὶ Κλεομένης ὁ Λακεδαιμόνιος ὕστερον μετὰ Ἀθηναίων στασιαζόντων, τούς τε ζῶντας ἐλαύνοντες καὶ τῶν τεθνεώτων τὰ ὀστᾶ ἀνελόντες ἐξέβαλον· κατῆλθον μέντοι ὕστερον, καὶ τὸ γένος αὐτῶν ἔστιν ἔτι ἐν τῇ πόλει.", "st": "1.126"}, {"sp": "N", "t": "τοῦτο δὴ τὸ ἄγος οἱ Λακεδαιμόνιοι ἐκέλευον ἐλαύνειν δῆθεν τοῖς θεοῖς πρῶτον τιμωροῦντες, εἰδότες δὲ Περικλέα τὸν Ξανθίππου προσεχόμενον αὐτῷ κατὰ τὴν μητέρα καὶ νομίζοντες ἐκπεσόντος αὐτοῦ ῥᾷον ⟨ἂν⟩ σφίσι προχωρεῖν τὰ ἀπὸ τῶν Ἀθηναίων. οὐ μέντοι τοσοῦτον ἤλπιζον παθεῖν ἂν αὐτὸν τοῦτο ὅσον διαβολὴν οἴσειν αὐτῷ πρὸς τὴν πόλιν ὡς καὶ διὰ τὴν ἐκείνου ξυμφορὰν τὸ μέρος ἔσται ὁ πόλεμος. ὢν γὰρ δυνατώτατος τῶν καθ’ ἑαυτὸν καὶ ἄγων τὴν πολιτείαν ἠναντιοῦτο πάντα τοῖς Λακεδαιμονίοις, καὶ οὐκ εἴα ὑπείκειν, ἀλλ’ ἐς τὸν πόλεμον ὥρμα τοὺς Ἀθηναίους.", "st": "1.127"}, {"sp": "N", "t": "ἀντεκέλευον δὲ καὶ οἱ Ἀθηναῖοι τοὺς Λακεδαιμονίους τὸ ἀπὸ Ταινάρου ἄγος ἐλαύνειν· οἱ γὰρ Λακεδαιμόνιοι ἀναστήσαντές ποτε ἐκ τοῦ ἱεροῦ τοῦ Ποσειδῶνος [ἀπὸ Ταινάρου] τῶν Εἱλώτων ἱκέτας ἀπαγαγόντες διέφθειραν, δι’ ὃ δὴ καὶ σφίσιν αὐτοῖς νομίζουσι τὸν μέγαν σεισμὸν γενέσθαι ἐν Σπάρτῃ. ἐκέλευον δὲ καὶ τὸ τῆς Χαλκιοίκου ἄγος ἐλαύνειν αὐτούς· ἐγένετο δὲ τοιόνδε. ἐπειδὴ Παυσανίας ὁ Λακεδαιμόνιος τὸ πρῶτον μεταπεμφθεὶς ὑπὸ Σπαρτιατῶν ἀπὸ τῆς ἀρχῆς τῆς ἐν Ἑλλησπόντῳ καὶ κριθεὶς ὑπ’ αὐτῶν ἀπελύθη μὴ ἀδικεῖν, δημοσίᾳ μὲν οὐκέτι ἐξεπέμφθη, ἰδίᾳ δὲ αὐτὸς τριήρη λαβὼν Ἑρμιονίδα ἄνευ Λακεδαιμονίων ἀφικνεῖται ἐς Ἑλλήσποντον, τῷ μὲν λόγῳ ἐπὶ τὸν Ἑλληνικὸν πόλεμον, τῷ δὲ ἔργῳ τὰ πρὸς βασιλέα πράγματα πράσσειν, ὥσπερ καὶ τὸ πρῶτον ἐπεχείρησεν, ἐφιέμενος τῆς Ἑλληνικῆς ἀρχῆς. εὐεργεσίαν δὲ ἀπὸ τοῦδε πρῶτον ἐς βασιλέα κατέθετο καὶ τοῦ παντὸς πράγματος ἀρχὴν ἐποιήσατο· Βυζάντιον γὰρ ἑλὼν τῇ προτέρᾳ παρουσίᾳ μετὰ τὴν ἐκ Κύπρου ἀναχώρησιν (εἶχον δὲ Μῆδοι αὐτὸ καὶ βασιλέως προσήκοντές τινες καὶ ξυγγενεῖς οἳ ἑάλωσαν ἐν αὐτῷ) τότε τούτους οὓς ἔλαβεν ἀποπέμπει βασιλεῖ κρύφα τῶν ἄλλων ξυμμάχων, τῷ δὲ λόγῳ ἀπέδρασαν αὐτόν. ἔπρασσε δὲ ταῦτα μετὰ Γογγύλου τοῦ Ἐρετριῶς, ᾧπερ ἐπέτρεψε τό τε Βυζάντιον καὶ τοὺς αἰχμαλώτους. ἔπεμψε δὲ καὶ ἐπιστολὴν τὸν Γόγγυλον φέροντα αὐτῷ· ἐνεγέγραπτο δὲ τάδε ἐν αὐτῇ, ὡς ὕστερον ἀνηυρέθη· ‘Παυσανίας ὁ ἡγεμὼν τῆς Σπάρτης τούσδε τέ σοι χαρίζεσθαι βουλόμενος ἀποπέμπει δορὶ ἑλών, καὶ γνώμην ποιοῦμαι, εἰ καὶ σοὶ δοκεῖ, θυγατέρα τε τὴν σὴν γῆμαι καί σοι Σπάρτην τε καὶ τὴν ἄλλην Ἑλλάδα ὑποχείριον ποιῆσαι. δυνατὸς δὲ δοκῶ εἶναι ταῦτα πρᾶξαι μετὰ σοῦ βουλευόμενος. εἰ οὖν τί σε τούτων ἀρέσκει, πέμπε ἄνδρα πιστὸν ἐπὶ θάλασσαν δι’ οὗ τὸ λοιπὸν τοὺς λόγους ποιησόμεθα.’", "st": "1.128"}, {"sp": "N", "t": "τοσαῦτα μὲν ἡ γραφὴ ἐδήλου, Ξέρξης δὲ ἥσθη τε τῇ ἐπιστολῇ καὶ ἀποστέλλει Ἀρτάβαζον τὸν Φαρνάκου ἐπὶ θάλασσαν καὶ κελεύει αὐτὸν τήν τε Δασκυλῖτιν σατραπείαν παραλαβεῖν Μεγαβάτην ἀπαλλάξαντα, ὃς πρότερον ἦρχε, καὶ παρὰ Παυσανίαν ἐς Βυζάντιον ἐπιστολὴν ἀντεπετίθει αὐτῷ ὡς τάχιστα διαπέμψαι καὶ τὴν σφραγῖδα ἀποδεῖξαι, καὶ ἤν τι αὐτῷ Παυσανίας παραγγέλλῃ περὶ τῶν ἑαυτοῦ πραγμάτων, πράσσειν ὡς ἄριστα καὶ πιστότατα. ὁ δὲ ἀφικόμενος τά τε ἄλλα ἐποίησεν ὥσπερ εἴρητο καὶ τὴν ἐπιστολὴν διέπεμψεν· ἀντενεγέγραπτο δὲ τάδε· ‘ὧδε λέγει βασιλεὺς Ξέρξης Παυσανίᾳ. καὶ τῶν ἀνδρῶν οὕς μοι πέραν θαλάσσης ἐκ Βυζαντίου ἔσωσας κείσεταί σοι εὐεργεσία ἐν τῷ ἡμετέρῳ οἴκῳ ἐς αἰεὶ ἀνάγραπτος, καὶ τοῖς λόγοις τοῖς ἀπὸ σοῦ ἀρέσκομαι. καί σε μήτε νὺξ μήθ’ ἡμέρα ἐπισχέτω ὥστε ἀνεῖναι πράσσειν τι ὧν ἐμοὶ ὑπισχνῇ, μηδὲ χρυσοῦ καὶ ἀργύρου δαπάνῃ κεκωλύσθω μηδὲ στρατιᾶς πλήθει, εἴ ποι δεῖ παραγίγνεσθαι, ἀλλὰ μετ’ Ἀρταβάζου ἀνδρὸς ἀγαθοῦ, ὅν σοι ἔπεμψα, πρᾶσσε θαρσῶν καὶ τὰ ἐμὰ καὶ τὰ σὰ ὅπῃ κάλλιστα καὶ ἄριστα ἕξει ἀμφοτέροις.’", "st": "1.129"}, {"sp": "N", "t": "ταῦτα λαβὼν ὁ Παυσανίας τὰ γράμματα, ὢν καὶ πρότερον ἐν μεγάλῳ ἀξιώματι ὑπὸ τῶν Ἑλλήνων διὰ τὴν Πλαταιᾶσιν ἡγεμονίαν, πολλῷ τότε μᾶλλον ἦρτο καὶ οὐκέτι ἐδύνατο ἐν τῷ καθεστῶτι τρόπῳ βιοτεύειν, ἀλλὰ σκευάς τε Μηδικὰς ἐνδυόμενος ἐκ τοῦ Βυζαντίου ἐξῄει καὶ διὰ τῆς Θρᾴκης πορευόμενον αὐτὸν Μῆδοι καὶ Αἰγύπτιοι ἐδορυφόρουν, τράπεζάν τε Περσικὴν παρετίθετο καὶ κατέχειν τὴν διάνοιαν οὐκ ἐδύνατο, ἀλλ’ ἔργοις βραχέσι προυδήλου ἃ τῇ γνώμῃ μειζόνως ἐς ἔπειτα ἔμελλε πράξειν. δυσπρόσοδόν τε αὑτὸν παρεῖχε καὶ τῇ ὀργῇ οὕτω χαλεπῇ ἐχρῆτο ἐς πάντας ὁμοίως ὥστε μηδένα δύνασθαι προσιέναι· δι’ ὅπερ καὶ πρὸς τοὺς Ἀθηναίους οὐχ ἥκιστα ἡ ξυμμαχία μετέστη.", "st": "1.130"}, {"sp": "N", "t": "οἱ δὲ Λακεδαιμόνιοι αἰσθόμενοι τό τε πρῶτον δι’ αὐτὰ ταῦτα ἀνεκάλεσαν αὐτόν, καὶ ἐπειδὴ τῇ Ἑρμιονίδι νηὶ τὸ δεύτερον ἐκπλεύσας οὐ κελευσάντων αὐτῶν τοιαῦτα ἐφαίνετο ποιῶν, καὶ ἐκ τοῦ Βυζαντίου βίᾳ ὑπ’ Ἀθηναίων ἐκπολιορκηθεὶς ἐς μὲν τὴν Σπάρτην οὐκ ἐπανεχώρει, ἐς δὲ Κολωνὰς τὰς Τρῳάδας ἱδρυθεὶς πράσσων τε ἐσηγγέλλετο αὐτοῖς ἐς τοὺς βαρβάρους καὶ οὐκ ἐπ’ ἀγαθῷ τὴν μονὴν ποιούμενος, οὕτω δὴ οὐκέτι ἐπέσχον, ἀλλὰ πέμψαντες κήρυκα οἱ ἔφοροι καὶ σκυτάλην εἶπον τοῦ κήρυκος μὴ λείπεσθαι, εἰ δὲ μή, πόλεμον αὐτῷ Σπαρτιάτας προαγορεύειν. ὁ δὲ βουλόμενος ὡς ἥκιστα ὕποπτος εἶναι καὶ πιστεύων χρήμασι διαλύσειν τὴν διαβολὴν ἀνεχώρει τὸ δεύτερον ἐς Σπάρτην. καὶ ἐς μὲν τὴν εἱρκτὴν ἐσπίπτει τὸ πρῶτον ὑπὸ τῶν ἐφόρων (ἔξεστι δὲ τοῖς ἐφόροις τὸν βασιλέα δρᾶσαι τοῦτο), ἔπειτα διαπραξάμενος ὕστερον ἐξῆλθε καὶ καθίστησιν ἑαυτὸν ἐς κρίσιν τοῖς βουλομένοις περὶ αὐτῶν ἐλέγχειν.", "st": "1.131"}, {"sp": "N", "t": "καὶ φανερὸν μὲν εἶχον οὐδὲν οἱ Σπαρτιᾶται σημεῖον, οὔτε οἱ ἐχθροὶ οὔτε ἡ πᾶσα πόλις, ὅτῳ ἂν πιστεύσαντες βεβαίως ἐτιμωροῦντο ἄνδρα γένους τε τοῦ βασιλείου ὄντα καὶ ἐν τῷ παρόντι τιμὴν ἔχοντα (Πλείσταρχον γὰρ τὸν Λεωνίδου ὄντα βασιλέα καὶ νέον ἔτι ἀνεψιὸς ὢν ἐπετρόπευεν), ὑποψίας δὲ πολλὰς παρεῖχε τῇ τε παρανομίᾳ καὶ ζηλώσει τῶν βαρβάρων μὴ ἴσος βούλεσθαι εἶναι τοῖς παροῦσι, τά τε ἄλλα αὐτοῦ ἀνεσκόπουν, εἴ τί που ἐξεδεδιῄτητο τῶν καθεστώτων νομίμων, καὶ ὅτι ἐπὶ τὸν τρίποδά ποτε τὸν ἐν Δελφοῖς, ὃν ἀνέθεσαν οἱ Ἕλληνες ἀπὸ τῶν Μήδων ἀκροθίνιον, ἠξίωσεν ἐπιγράψασθαι αὐτὸς ἰδίᾳ τὸ ἐλεγεῖον τόδε·<br>Ἑλλήνων ἀρχηγὸς ἐπεὶ στρατὸν ὤλεσε Μήδων,<br>Παυσανίας Φοίβῳ μνῆμ’ ἀνέθηκε τόδε.<br>τὸ μὲν οὖν ἐλεγεῖον οἱ Λακεδαιμόνιοι ἐξεκόλαψαν εὐθὺς τότε ἀπὸ τοῦ τρίποδος τοῦτο καὶ ἐπέγραψαν ὀνομαστὶ τὰς πόλεις ὅσαι ξυγκαθελοῦσαι τὸν βάρβαρον ἔστησαν τὸ ἀνάθημα· τοῦ μέντοι Παυσανίου ἀδίκημα καὶ τότ’ ἐδόκει εἶναι, καὶ ἐπεί γε δὴ ἐν τούτῳ καθειστήκει, πολλῷ μᾶλλον παρόμοιον πραχθῆναι ἐφαίνετο τῇ παρούσῃ διανοίᾳ. ἐπυνθάνοντο δὲ καὶ ἐς τοὺς Εἵλωτας πράσσειν τι αὐτόν, καὶ ἦν δὲ οὕτως· ἐλευθέρωσίν τε γὰρ ὑπισχνεῖτο αὐτοῖς καὶ πολιτείαν, ἢν ξυνεπαναστῶσι καὶ τὸ πᾶν ξυγκατεργάσωνται. ἀλλ’ οὐδ’ ὣς οὐδὲ τῶν Εἱλώτων μηνυταῖς τισὶ πιστεύσαντες ἠξίωσαν νεώτερόν τι ποιεῖν ἐς αὐτόν, χρώμενοι τῷ τρόπῳ ᾧπερ εἰώθασιν ἐς σφᾶς αὐτούς, μὴ ταχεῖς εἶναι περὶ ἀνδρὸς Σπαρτιάτου ἄνευ ἀναμφισβητήτων τεκμηρίων βουλεῦσαί τι ἀνήκεστον, πρίν γε δὴ αὐτοῖς, ὡς λέγεται, ὁ μέλλων τὰς τελευταίας βασιλεῖ ἐπιστολὰς πρὸς Ἀρτάβαζον κομιεῖν, ἀνὴρ Ἀργίλιος, παιδικά ποτε ὢν αὐτοῦ καὶ πιστότατος ἐκείνῳ, μηνυτὴς γίγνεται, δείσας κατὰ ἐνθύμησίν τινα ὅτι οὐδείς πω τῶν πρὸ ἑαυτοῦ ἀγγέλων πάλιν ἀφίκετο, καὶ παρασημηνάμενος σφραγῖδα, ἵνα, ἢν ψευσθῇ τῆς δόξης ἢ καὶ ἐκεῖνός τι μεταγράψαι αἰτήσῃ, μὴ ἐπιγνῷ, λύει τὰς ἐπιστολάς, ἐν αἷς ὑπονοήσας τι τοιοῦτον προσεπεστάλθαι καὶ αὑτὸν ηὗρεν ἐγγεγραμμένον κτείνειν.", "st": "1.132"}, {"sp": "N", "t": "τότε δὴ οἱ ἔφοροι δείξαντος αὐτοῦ τὰ γράμματα μᾶλλον μὲν ἐπίστευσαν, αὐτήκοοι δὲ βουληθέντες ἔτι γενέσθαι αὐτοῦ Παυσανίου τι λέγοντος, ἀπὸ παρασκευῆς τοῦ ἀνθρώπου ἐπὶ Ταίναρον ἱκέτου οἰχομένου καὶ σκηνησαμένου διπλῆν διαφράγματι καλύβην, ἐς ἣν τῶν [τε] ἐφόρων ἐντός τινας ἔκρυψε, καὶ Παυσανίου ὡς αὐτὸν ἐλθόντος καὶ ἐρωτῶντος τὴν πρόφασιν τῆς ἱκετείας ᾔσθοντο πάντα σαφῶς, αἰτιωμένου τοῦ ἀνθρώπου τά τε περὶ αὐτοῦ γραφέντα καὶ τἆλλ’ ἀποφαίνοντος καθ’ ἕκαστον, ὡς οὐδὲν πώποτε αὐτὸν ἐν ταῖς πρὸς βασιλέα διακονίαις παραβάλοιτο, προτιμηθείη δ’ ἐν ἴσῳ τοῖς πολλοῖς τῶν διακόνων ἀποθανεῖν, κἀκείνου αὐτά τε ταῦτα ξυνομολογοῦντος καὶ περὶ τοῦ παρόντος οὐκ ἐῶντος ὀργίζεσθαι, ἀλλὰ πίστιν ἐκ τοῦ ἱεροῦ διδόντος τῆς ἀναστάσεως καὶ ἀξιοῦντος ὡς τάχιστα πορεύεσθαι καὶ μὴ τὰ πρασσόμενα διακωλύειν.", "st": "1.133"}, {"sp": "N", "t": "ἀκούσαντες δὲ ἀκριβῶς τότε μὲν ἀπῆλθον οἱ ἔφοροι, βεβαίως δὲ ἤδη εἰδότες ἐν τῇ πόλει τὴν ξύλληψιν ἐποιοῦντο. λέγεται δ’ αὐτὸν μέλλοντα ξυλληφθήσεσθαι ἐν τῇ ὁδῷ, ἑνὸς μὲν τῶν ἐφόρων τὸ πρόσωπον προσιόντος ὡς εἶδε, γνῶναι ἐφ’ ᾧ ἐχώρει, ἄλλου δὲ νεύματι ἀφανεῖ χρησαμένου καὶ δηλώσαντος εὐνοίᾳ πρὸς τὸ ἱερὸν τῆς Χαλκιοίκου χωρῆσαι δρόμῳ καὶ προκαταφυγεῖν· ἦν δ’ ἐγγὺς τὸ τέμενος. καὶ ἐς οἴκημα οὐ μέγα ὃ ἦν τοῦ ἱεροῦ ἐσελθών, ἵνα μὴ ὑπαίθριος ταλαιπωροίη, ἡσύχαζεν. οἱ δὲ τὸ παραυτίκα μὲν ὑστέρησαν τῇ διώξει, μετὰ δὲ τοῦτο τοῦ τε οἰκήματος τὸν ὄροφον ἀφεῖλον καὶ τὰς θύρας ἔνδον ὄντα τηρήσαντες αὐτὸν καὶ ἀπολαβόντες ἔσω ἀπῳκοδόμησαν, προσκαθεζόμενοί τε ἐξεπολιόρκησαν λιμῷ. καὶ μέλλοντος αὐτοῦ ἀποψύχειν ὥσπερ εἶχεν ἐν τῷ οἰκήματι, αἰσθόμενοι ἐξάγουσιν ἐκ τοῦ ἱεροῦ ἔτι ἔμπνουν ὄντα, καὶ ἐξαχθεὶς ἀπέθανε παραχρῆμα. καὶ αὐτὸν ἐμέλλησαν μὲν ἐς τὸν Καιάδαν [οὗπερ τοὺς κακούργους] ἐσβάλλειν· ἔπειτα ἔδοξε πλησίον που κατορύξαι. ὁ δὲ θεὸς ὁ ἐν Δελφοῖς τόν τε τάφον ὕστερον ἔχρησε τοῖς Λακεδαιμονίοις μετενεγκεῖν οὗπερ ἀπέθανε (καὶ νῦν κεῖται ἐν τῷ προτεμενίσματι, ὃ γραφῇ στῆλαι δηλοῦσι) καὶ ὡς ἄγος αὐτοῖς ὂν τὸ πεπραγμένον δύο σώματα ἀνθ’ ἑνὸς τῇ Χαλκιοίκῳ ἀποδοῦναι. οἱ δὲ ποιησάμενοι χαλκοῦς ἀνδριάντας δύο ὡς ἀντὶ Παυσανίου ἀνέθεσαν.", "st": "1.134"}, {"sp": "N", "t": "οἱ δὲ Ἀθηναῖοι, ὡς καὶ τοῦ θεοῦ ἄγος κρίναντος, ἀντεπέταξαν τοῖς Λακεδαιμονίοις ἐλαύνειν αὐτό.", "st": "1.135"}, {"sp": "N", "t": "τοῦ δὲ μηδισμοῦ τοῦ Παυσανίου οἱ Λακεδαιμόνιοι πρέσβεις πέμψαντες παρὰ τοὺς Ἀθηναίους ξυνεπῃτιῶντο καὶ τὸν Θεμιστοκλέα, ὡς ηὕρισκον ἐκ τῶν περὶ Παυσανίαν ἐλέγχων, ἠξίουν τε τοῖς αὐτοῖς κολάζεσθαι αὐτόν. οἱ δὲ πεισθέντες (ἔτυχε γὰρ ὠστρακισμένος καὶ ἔχων δίαιταν μὲν ἐν Ἄργει, ἐπιφοιτῶν δὲ καὶ ἐς τὴν ἄλλην Πελοπόννησον) πέμπουσι μετὰ τῶν Λακεδαιμονίων ἑτοίμων ὄντων ξυνδιώκειν ἄνδρας οἷς εἴρητο ἄγειν ὅπου ἂν περιτύχωσιν.", "st": "1.135"}, {"sp": "N", "t": "ὁ δὲ Θεμιστοκλῆς προαισθόμενος φεύγει ἐκ Πελοποννήσου ἐς Κέρκυραν, ὢν αὐτῶν εὐεργέτης. δεδιέναι δὲ φασκόντων Κερκυραίων ἔχειν αὐτὸν ὥστε Λακεδαιμονίοις καὶ Ἀθηναίοις ἀπεχθέσθαι, διακομίζεται ὑπ’ αὐτῶν ἐς τὴν ἤπειρον τὴν καταντικρύ. καὶ διωκόμενος ὑπὸ τῶν προστεταγμένων κατὰ πύστιν ᾗ χωροίη, ἀναγκάζεται κατά τι ἄπορον παρὰ Ἄδμητον τὸν Μολοσσῶν βασιλέα ὄντα αὐτῷ οὐ φίλον καταλῦσαι. καὶ ὁ μὲν οὐκ ἔτυχεν ἐπιδημῶν, ὁ δὲ τῆς γυναικὸς ἱκέτης γενόμενος διδάσκεται ὑπ’ αὐτῆς τὸν παῖδα σφῶν λαβὼν καθέζεσθαι ἐπὶ τὴν ἑστίαν. καὶ ἐλθόντος οὐ πολὺ ὕστερον τοῦ Ἀδμήτου δηλοῖ τε ὅς ἐστι καὶ οὐκ ἀξιοῖ, εἴ τι ἄρα αὐτὸς ἀντεῖπεν αὐτῷ Ἀθηναίων δεομένῳ, φεύγοντα τιμωρεῖσθαι· καὶ γὰρ ἂν ὑπ’ ἐκείνου πολλῷ ἀσθενεστέρου ἐν τῷ παρόντι κακῶς πάσχειν, γενναῖον δὲ εἶναι τοὺς ὁμοίους ἀπὸ τοῦ ἴσου τιμωρεῖσθαι. καὶ ἅμα αὐτὸς μὲν ἐκείνῳ χρείας τινὸς καὶ οὐκ ἐς τὸ σῶμα σῴζεσθαι ἐναντιωθῆναι, ἐκεῖνον δ’ ἄν, εἰ ἐκδοίη αὐτόν (εἰπὼν ὑφ’ ὧν καὶ ἐφ’ ᾧ διώκεται), σωτηρίας ἂν τῆς ψυχῆς ἀποστερῆσαι.", "st": "1.136"}, {"sp": "N", "t": "ὁ δὲ ἀκούσας ἀνίστησί τε αὐτὸν μετὰ τοῦ ἑαυτοῦ υἱέος, ὥσπερ καὶ ἔχων αὐτὸν ἐκαθέζετο, καὶ μέγιστον ἦν ἱκέτευμα τοῦτο, καὶ ὕστερον οὐ πολλῷ τοῖς τε Λακεδαιμονίοις καὶ Ἀθηναίοις ἐλθοῦσι καὶ πολλὰ εἰποῦσιν οὐκ ἐκδίδωσιν, ἀλλ’ ἀποστέλλει βουλόμενον ὡς βασιλέα πορευθῆναι ἐπὶ τὴν ἑτέραν θάλασσαν πεζῇ ἐς Πύδναν τὴν Ἀλεξάνδρου. ἐν ᾗ ὁλκάδος τυχὼν ἀναγομένης ἐπ’ Ἰωνίας καὶ ἐπιβὰς καταφέρεται χειμῶνι ἐς τὸ Ἀθηναίων στρατόπεδον, ὃ ἐπολιόρκει Νάξον. καί (ἦν γὰρ ἀγνὼς τοῖς ἐν τῇ νηί) δείσας φράζει τῷ ναυκλήρῳ ὅστις ἐστὶ καὶ δι’ ἃ φεύγει, καὶ εἰ μὴ σώσει αὐτόν, ἔφη ἐρεῖν ὅτι χρήμασι πεισθεὶς αὐτὸν ἄγει· τὴν δὲ ἀσφάλειαν εἶναι μηδένα ἐκβῆναι ἐκ τῆς νεὼς μέχρι πλοῦς γένηται· πειθομένῳ δ’ αὐτῷ χάριν ἀπομνήσεσθαι ἀξίαν. ὁ δὲ ναύκληρος ποιεῖ τε ταῦτα καὶ ἀποσαλεύσας ἡμέραν καὶ νύκτα ὑπὲρ τοῦ στρατοπέδου ὕστερον ἀφικνεῖται ἐς Ἔφεσον. καὶ ὁ Θεμιστοκλῆς ἐκεῖνόν τε ἐθεράπευσε χρημάτων δόσει (ἦλθε γὰρ αὐτῷ ὕστερον ἔκ τε Ἀθηνῶν παρὰ τῶν φίλων καὶ ἐξ Ἄργους ἃ ὑπεξέκειτο) καὶ μετὰ τῶν κάτω Περσῶν τινὸς πορευθεὶς ἄνω ἐσπέμπει γράμματα πρὸς βασιλέα Ἀρταξέρξην τὸν Ξέρξου νεωστὶ βασιλεύοντα. ἐδήλου δὲ ἡ γραφὴ ὅτι ‘Θεμιστοκλῆς ἥκω παρὰ σέ, ὃς κακὰ μὲν πλεῖστα Ἑλλήνων εἴργασμαι τὸν ὑμέτερον οἶκον, ὅσον χρόνον τὸν σὸν πατέρα ἐπιόντα ἐμοὶ ἀνάγκῃ ἠμυνόμην, πολὺ δ’ ἔτι πλείω ἀγαθά, ἐπειδὴ ἐν τῷ ἀσφαλεῖ μὲν ἐμοί, ἐκείνῳ δὲ ἐν ἐπικινδύνῳ πάλιν ἡ ἀποκομιδὴ ἐγίγνετο. καί μοι εὐεργεσία ὀφείλεται (γράψας τήν τε ἐκ Σαλαμῖνος προάγγελσιν τῆς ἀναχωρήσεως καὶ τὴν τῶν γεφυρῶν, ἣν ψευδῶς προσεποιήσατο, τότε δι’ αὑτὸν οὐ διάλυσιν), καὶ νῦν ἔχων σε μεγάλα ἀγαθὰ δρᾶσαι πάρειμι διωκόμενος ὑπὸ τῶν Ἑλλήνων διὰ τὴν σὴν φιλίαν. βούλομαι δ’ ἐνιαυτὸν ἐπισχὼν αὐτός σοι περὶ ὧν ἥκω δηλῶσαι.’", "st": "1.137"}, {"sp": "N", "t": "βασιλεὺς δέ, ὡς λέγεται, ἐθαύμασέ τε αὐτοῦ τὴν διάνοιαν καὶ ἐκέλευε ποιεῖν οὕτως. ὁ δ’ ἐν τῷ χρόνῳ ὃν ἐπέσχε τῆς τε Περσίδος γλώσσης ὅσα ἐδύνατο κατενόησε καὶ τῶν ἐπιτηδευμάτων τῆς χώρας· ἀφικόμενος δὲ μετὰ τὸν ἐνιαυτὸν γίγνεται παρ’ αὐτῷ μέγας καὶ ὅσος οὐδείς πω Ἑλλήνων διά τε τὴν προϋπάρχουσαν ἀξίωσιν καὶ τοῦ Ἑλληνικοῦ ἐλπίδα, ἣν ὑπετίθει αὐτῷ δουλώσειν, μάλιστα δὲ ἀπὸ τοῦ πεῖραν διδοὺς ξυνετὸς φαίνεσθαι.", "st": "1.138"}, {"sp": "N", "t": "ἦν γὰρ ὁ Θεμιστοκλῆς βεβαιότατα δὴ φύσεως ἰσχὺν δηλώσας καὶ διαφερόντως τι ἐς αὐτὸ μᾶλλον ἑτέρου ἄξιος θαυμάσαι· οἰκείᾳ γὰρ ξυνέσει καὶ οὔτε προμαθὼν ἐς αὐτὴν οὐδὲν οὔτ’ ἐπιμαθών, τῶν τε παραχρῆμα δι’ ἐλαχίστης βουλῆς κράτιστος γνώμων καὶ τῶν μελλόντων ἐπὶ πλεῖστον τοῦ γενησομένου ἄριστος εἰκαστής· καὶ ἃ μὲν μετὰ χεῖρας ἔχοι, καὶ ἐξηγήσασθαι οἷός τε, ὧν δ’ ἄπειρος εἴη, κρῖναι ἱκανῶς οὐκ ἀπήλλακτο· τό τε ἄμεινον ἢ χεῖρον ἐν τῷ ἀφανεῖ ἔτι προεώρα μάλιστα. καὶ τὸ ξύμπαν εἰπεῖν φύσεως μὲν δυνάμει, μελέτης δὲ βραχύτητι κράτιστος δὴ οὗτος αὐτοσχεδιάζειν τὰ δέοντα ἐγένετο. νοσήσας δὲ τελευτᾷ τὸν βίον· λέγουσι δέ τινες καὶ ἑκούσιον φαρμάκῳ ἀποθανεῖν αὐτόν, ἀδύνατον νομίσαντα εἶναι ἐπιτελέσαι βασιλεῖ ἃ ὑπέσχετο. μνημεῖον μὲν οὖν αὐτοῦ ἐν Μαγνησίᾳ ἐστὶ τῇ Ἀσιανῇ ἐν τῇ ἀγορᾷ· ταύτης γὰρ ἦρχε τῆς χώρας, δόντος βασιλέως αὐτῷ Μαγνησίαν μὲν ἄρτον, ἣ προσέφερε πεντήκοντα τάλαντα τοῦ ἐνιαυτοῦ, Λάμψακον δὲ οἶνον (ἐδόκει γὰρ πολυοινότατον τῶν τότε εἶναι), Μυοῦντα δὲ ὄψον. τὰ δὲ ὀστᾶ φασὶ κομισθῆναι αὐτοῦ οἱ προσήκοντες οἴκαδε κελεύσαντος ἐκείνου καὶ τεθῆναι κρύφα Ἀθηναίων ἐν τῇ Ἀττικῇ· οὐ γὰρ ἐξῆν θάπτειν ὡς ἐπὶ προδοσίᾳ φεύγοντος. τὰ μὲν κατὰ Παυσανίαν τὸν Λακεδαιμόνιον καὶ Θεμιστοκλέα τὸν Ἀθηναῖον, λαμπροτάτους γενομένους τῶν καθ’ ἑαυτοὺς Ἑλλήνων, οὕτως ἐτελεύτησεν.", "st": "1.138"}, {"sp": "N", "t": "Λακεδαιμόνιοι δὲ ἐπὶ μὲν τῆς πρώτης πρεσβείας τοιαῦτα ἐπέταξάν τε καὶ ἀντεκελεύσθησαν περὶ τῶν ἐναγῶν τῆς ἐλάσεως· ὕστερον δὲ φοιτῶντες παρ’ Ἀθηναίους Ποτειδαίας τε ἀπανίστασθαι ἐκέλευον καὶ Αἴγιναν αὐτόνομον ἀφιέναι, καὶ μάλιστά γε πάντων καὶ ἐνδηλότατα προύλεγον τὸ περὶ Μεγαρέων ψήφισμα καθελοῦσι μὴ ἂν γίγνεσθαι πόλεμον, ἐν ᾧ εἴρητο αὐτοὺς μὴ χρῆσθαι τοῖς λιμέσι τοῖς ἐν τῇ Ἀθηναίων ἀρχῇ μηδὲ τῇ Ἀττικῇ ἀγορᾷ. οἱ δὲ Ἀθηναῖοι οὔτε τἆλλα ὑπήκουον οὔτε τὸ ψήφισμα καθῄρουν, ἐπικαλοῦντες ἐπεργασίαν Μεγαρεῦσι τῆς γῆς τῆς ἱερᾶς καὶ τῆς ἀορίστου καὶ ἀνδραπόδων ὑποδοχὴν τῶν ἀφισταμένων. τέλος δὲ ἀφικομένων τῶν τελευταίων πρέσβεων ἐκ Λακεδαίμονος, Ῥαμφίου τε καὶ Μελησίππου καὶ Ἀγησάνδρου, καὶ λεγόντων ἄλλο μὲν οὐδὲν ὧν πρότερον εἰώθεσαν, αὐτὰ δὲ τάδε ὅτι ‘Λακεδαιμόνιοι βούλονται τὴν εἰρήνην εἶναι, εἴη δ’ ἂν εἰ τοὺς Ἕλληνας αὐτονόμους ἀφεῖτε,’ ποιήσαντες ἐκκλησίαν οἱ Ἀθηναῖοι γνώμας σφίσιν αὐτοῖς προυτίθεσαν, καὶ ἐδόκει ἅπαξ περὶ ἁπάντων βουλευσαμένους ἀποκρίνασθαι. καὶ παριόντες ἄλλοι τε πολλοὶ ἔλεγον ἐπ’ ἀμφότερα γιγνόμενοι ταῖς γνώμαις καὶ ὡς χρὴ πολεμεῖν καὶ ὡς μὴ ἐμπόδιον εἶναι τὸ ψήφισμα εἰρήνης, ἀλλὰ καθελεῖν, καὶ παρελθὼν Περικλῆς ὁ Ξανθίππου, ἀνὴρ κατ’ ἐκεῖνον τὸν χρόνον πρῶτος Ἀθηναίων, λέγειν τε καὶ πράσσειν δυνατώτατος, παρῄνει τοιάδε.", "st": "1.139"}, {"sp": "N", "t": "‘τῆς μὲν γνώμης, ὦ Ἀθηναῖοι, αἰεὶ τῆς αὐτῆς ἔχομαι, μὴ εἴκειν Πελοποννησίοις, καίπερ εἰδὼς τοὺς ἀνθρώπους οὐ τῇ αὐτῇ ὀργῇ ἀναπειθομένους τε πολεμεῖν καὶ ἐν τῷ ἔργῳ πράσσοντας, πρὸς δὲ τὰς ξυμφορὰς καὶ τὰς γνώμας τρεπομένους. ὁρῶ δὲ καὶ νῦν ὁμοῖα καὶ παραπλήσια ξυμβουλευτέα μοι ὄντα, καὶ τοὺς ἀναπειθομένους ὑμῶν δικαιῶ τοῖς κοινῇ δόξασιν, ἢν ἄρα τι καὶ σφαλλώμεθα, βοηθεῖν, ἢ μηδὲ κατορθοῦντας τῆς ξυνέσεως μεταποιεῖσθαι. ἐνδέχεται γὰρ τὰς ξυμφορὰς τῶν πραγμάτων οὐχ ἧσσον ἀμαθῶς χωρῆσαι ἢ καὶ τὰς διανοίας τοῦ ἀνθρώπου· δι’ ὅπερ καὶ τὴν τύχην, ὅσα ἂν παρὰ λόγον ξυμβῇ, εἰώθαμεν αἰτιᾶσθαι.", "st": "1.140"}, {"sp": "N", "t": "‘Λακεδαιμόνιοι δὲ πρότερόν τε δῆλοι ἦσαν ἐπιβουλεύοντες ἡμῖν καὶ νῦν οὐχ ἥκιστα. εἰρημένον γὰρ δίκας μὲν τῶν διαφορῶν ἀλλήλοις διδόναι καὶ δέχεσθαι, ἔχειν δὲ ἑκατέρους ἃ ἔχομεν, οὔτε αὐτοὶ δίκας πω ᾔτησαν οὔτε ἡμῶν διδόντων δέχονται, βούλονται δὲ πολέμῳ μᾶλλον ἢ λόγοις τὰ ἐγκλήματα διαλύεσθαι, καὶ ἐπιτάσσοντες ἤδη καὶ οὐκέτι αἰτιώμενοι πάρεισιν. Ποτειδαίας τε γὰρ ἀπανίστασθαι κελεύουσι καὶ Αἴγιναν αὐτόνομον ἀφιέναι καὶ τὸ Μεγαρέων ψήφισμα καθαιρεῖν· οἱ δὲ τελευταῖοι οἵδε ἥκοντες καὶ τοὺς Ἕλληνας προαγορεύουσιν αὐτονόμους ἀφιέναι. ὑμῶν δὲ μηδεὶς νομίσῃ περὶ βραχέος ἂν πολεμεῖν, εἰ τὸ Μεγαρέων ψήφισμα μὴ καθέλοιμεν, ὅπερ μάλιστα προύχονται, εἰ καθαιρεθείη, μὴ ἂν γίγνεσθαι τὸν πόλεμον, μηδὲ ἐν ὑμῖν αὐτοῖς αἰτίαν ὑπολίπησθε ὡς διὰ μικρὸν ἐπολεμήσατε. τὸ γὰρ βραχύ τι τοῦτο πᾶσαν ὑμῶν ἔχει τὴν βεβαίωσιν καὶ πεῖραν τῆς γνώμης. οἷς εἰ ξυγχωρήσετε, καὶ ἄλλο τι μεῖζον εὐθὺς ἐπιταχθήσεσθε ὡς φόβῳ καὶ τοῦτο ὑπακούσαντες· ἀπισχυρισάμενοι δὲ σαφὲς ἂν καταστήσαιτε αὐτοῖς ἀπὸ τοῦ ἴσου ὑμῖν μᾶλλον προσφέρεσθαι.", "st": "1.140"}, {"sp": "N", "t": "αὐτόθεν δὴ διανοήθητε ἢ ὑπακούειν πρίν τι βλαβῆναι, ἢ εἰ πολεμήσομεν, ὥσπερ ἔμοιγε ἄμεινον δοκεῖ εἶναι, καὶ ἐπὶ μεγάλῃ καὶ ἐπὶ βραχείᾳ ὁμοίως προφάσει μὴ εἴξοντες μηδὲ ξὺν φόβῳ ἕξοντες ἃ κεκτήμεθα· τὴν γὰρ αὐτὴν δύναται δούλωσιν ἥ τε μεγίστη καὶ ἐλαχίστη δικαίωσις ἀπὸ τῶν ὁμοίων πρὸ δίκης τοῖς πέλας ἐπιτασσομένη.", "st": "1.141"}, {"sp": "N", "t": "‘τὰ δὲ τοῦ πολέμου καὶ τῶν ἑκατέροις ὑπαρχόντων ὡς οὐκ ἀσθενέστερα ἕξομεν γνῶτε καθ’ ἕκαστον ἀκούοντες. αὐτουργοί τε γάρ εἰσι Πελοποννήσιοι καὶ οὔτε ἰδίᾳ οὔτ’ ἐν κοινῷ χρήματά ἐστιν αὐτοῖς, ἔπειτα χρονίων πολέμων καὶ διαποντίων ἄπειροι διὰ τὸ βραχέως αὐτοὶ ἐπ’ ἀλλήλους ὑπὸ πενίας ἐπιφέρειν. καὶ οἱ τοιοῦτοι οὔτε ναῦς πληροῦντες οὔτε πεζὰς στρατιὰς πολλάκις ἐκπέμπειν δύνανται, ἀπὸ τῶν ἰδίων τε ἅμα ἀπόντες καὶ ἀπὸ τῶν αὑτῶν δαπανῶντες καὶ προσέτι καὶ θαλάσσης εἰργόμενοι· αἱ δὲ περιουσίαι τοὺς πολέμους μᾶλλον ἢ αἱ βίαιοι ἐσφοραὶ ἀνέχουσιν. σώμασί τε ἑτοιμότεροι οἱ αὐτουργοὶ τῶν ἀνθρώπων ἢ χρήμασι πολεμεῖν, τὸ μὲν πιστὸν ἔχοντες ἐκ τῶν κινδύνων κἂν περιγενέσθαι, τὸ δὲ οὐ βέβαιον μὴ οὐ προαναλώσειν, ἄλλως τε κἂν παρὰ δόξαν, ὅπερ εἰκός, ὁ πόλεμος αὐτοῖς μηκύνηται. μάχῃ μὲν γὰρ μιᾷ πρὸς ἅπαντας Ἕλληνας δυνατοὶ Πελοποννήσιοι καὶ οἱ ξύμμαχοι ἀντισχεῖν, πολεμεῖν δὲ μὴ πρὸς ὁμοίαν ἀντιπαρασκευὴν ἀδύνατοι, ὅταν μήτε βουλευτηρίῳ ἑνὶ χρώμενοι παραχρῆμά τι ὀξέως ἐπιτελῶσι πάντες τε ἰσόψηφοι ὄντες καὶ οὐχ ὁμόφυλοι τὸ ἐφ’ ἑαυτὸν ἕκαστος σπεύδῃ· ἐξ ὧν φιλεῖ μηδὲν ἐπιτελὲς γίγνεσθαι. καὶ γὰρ οἱ μὲν ὡς μάλιστα τιμωρήσασθαί τινα βούλονται, οἱ δὲ ὡς ἥκιστα τὰ οἰκεῖα φθεῖραι. χρόνιοί τε ξυνιόντες ἐν βραχεῖ μὲν μορίῳ σκοποῦσί τι τῶν κοινῶν, τῷ δὲ πλέονι τὰ οἰκεῖα πράσσουσι, καὶ ἕκαστος οὐ παρὰ τὴν ἑαυτοῦ ἀμέλειαν οἴεται βλάψειν, μέλειν δέ τινι καὶ ἄλλῳ ὑπὲρ ἑαυτοῦ τι προϊδεῖν, ὥστε τῷ αὐτῷ ὑπὸ ἁπάντων ἰδίᾳ δοξάσματι λανθάνειν τὸ κοινὸν ἁθρόον φθειρόμενον.", "st": "1.141"}, {"sp": "N", "t": "‘μέγιστον δέ, τῇ τῶν χρημάτων σπάνει κωλύσονται, ὅταν σχολῇ αὐτὰ ποριζόμενοι διαμέλλωσιν· τοῦ δὲ πολέμου οἱ καιροὶ οὐ μενετοί. καὶ μὴν οὐδ’ ἡ ἐπιτείχισις οὐδὲ τὸ ναυτικὸν αὐτῶν ἄξιον φοβηθῆναι. τὴν μὲν γὰρ χαλεπὸν καὶ ἐν εἰρήνῃ πόλιν ἀντίπαλον κατασκευάσασθαι, ἦ που δὴ ἐν πολεμίᾳ τε καὶ οὐχ ἧσσον ἐκείνοις ἡμῶν ἀντεπιτετειχισμένων· φρούριον δ’ εἰ ποιήσονται, τῆς μὲν γῆς βλάπτοιεν ἄν τι μέρος καταδρομαῖς καὶ αὐτομολίαις, οὐ μέντοι ἱκανόν γε ἔσται ἐπιτειχίζειν τε κωλύειν ἡμᾶς πλεύσαντας ἐς τὴν ἐκείνων καί, ᾗπερ ἰσχύομεν, ταῖς ναυσὶν ἀμύνεσθαι· πλέον γὰρ ἡμεῖς ἔχομεν τοῦ κατὰ γῆν ἐκ τοῦ ναυτικοῦ ἐμπειρίας ἢ ἐκεῖνοι ἐκ τοῦ κατ’ ἤπειρον ἐς τὰ ναυτικά. τὸ δὲ τῆς θαλάσσης ἐπιστήμονας γενέσθαι οὐ ῥᾳδίως αὐτοῖς προσγενήσεται. οὐδὲ γὰρ ὑμεῖς μελετῶντες αὐτὸ εὐθὺς ἀπὸ τῶν Μηδικῶν ἐξείργασθέ πω· πῶς δὴ ἄνδρες γεωργοὶ καὶ οὐ θαλάσσιοι, καὶ προσέτι οὐδὲ μελετῆσαι ἐασόμενοι διὰ τὸ ὑφ’ ἡμῶν πολλαῖς ναυσὶν αἰεὶ ἐφορμεῖσθαι, ἄξιον ἄν τι δρῷεν; πρὸς μὲν γὰρ ὀλίγας ἐφορμούσας κἂν διακινδυνεύσειαν πλήθει τὴν ἀμαθίαν θρασύνοντες, πολλαῖς δὲ εἰργόμενοι ἡσυχάσουσι καὶ ἐν τῷ μὴ μελετῶντι ἀξυνετώτεροι ἔσονται καὶ δι’ αὐτὸ καὶ ὀκνηρότεροι. τὸ δὲ ναυτικὸν τέχνης ἐστίν, ὥσπερ καὶ ἄλλο τι, καὶ οὐκ ἐνδέχεται, ὅταν τύχῃ, ἐκ παρέργου μελετᾶσθαι, ἀλλὰ μᾶλλον μηδὲν ἐκείνῳ πάρεργον ἄλλο γίγνεσθαι.", "st": "1.142"}, {"sp": "N", "t": "‘εἴ τε καὶ κινήσαντες τῶν Ὀλυμπίασιν ἢ Δελφοῖς χρημάτων μισθῷ μείζονι πειρῷντο ἡμῶν ὑπολαβεῖν τοὺς ξένους τῶν ναυτῶν, μὴ ὄντων μὲν ἡμῶν ἀντιπάλων ἐσβάντων αὐτῶν τε καὶ τῶν μετοίκων δεινὸν ἂν ἦν· νῦν δὲ τόδε τε ὑπάρχει, καί, ὅπερ κράτιστον, κυβερνήτας ἔχομεν πολίτας καὶ τὴν ἄλλην ὑπηρεσίαν πλείους καὶ ἀμείνους ἢ ἅπασα ἡ ἄλλη Ἑλλάς. καὶ ἐπὶ τῷ κινδύνῳ οὐδεὶς ἂν δέξαιτο τῶν ξένων τήν τε αὑτοῦ φεύγειν καὶ μετὰ τῆς ἥσσονος ἅμα ἐλπίδος ὀλίγων ἡμερῶν ἕνεκα μεγάλου μισθοῦ δόσεως ἐκείνοις ξυναγωνίζεσθαι.", "st": "1.143"}, {"sp": "N", "t": "‘καὶ τὰ μὲν Πελοποννησίων ἔμοιγε τοιαῦτα καὶ παραπλήσια δοκεῖ εἶναι, τὰ δὲ ἡμέτερα τούτων τε ὧνπερ ἐκείνοις ἐμεμψάμην ἀπηλλάχθαι καὶ ἄλλα οὐκ ἀπὸ τοῦ ἴσου μεγάλα ἔχειν. ἤν τε ἐπὶ τὴν χώραν ἡμῶν πεζῇ ἴωσιν, ἡμεῖς ἐπὶ τὴν ἐκείνων πλευσούμεθα, καὶ οὐκέτι ἐκ τοῦ ὁμοίου ἔσται Πελοποννήσου τε μέρος τι τμηθῆναι καὶ τὴν Ἀττικὴν ἅπασαν· οἱ μὲν γὰρ οὐχ ἕξουσιν ἄλλην ἀντιλαβεῖν ἀμαχεί, ἡμῖν δ’ ἐστὶ γῆ πολλὴ καὶ ἐν νήσοις καὶ κατ’ ἤπειρον· μέγα γὰρ τὸ τῆς θαλάσσης κράτος. σκέψασθε δέ· εἰ γὰρ ἦμεν νησιῶται, τίνες ἂν ἀληπτότεροι ἦσαν; καὶ νῦν χρὴ ὅτι ἐγγύτατα τούτου διανοηθέντας τὴν μὲν γῆν καὶ οἰκίας ἀφεῖναι, τῆς δὲ θαλάσσης καὶ πόλεως φυλακὴν ἔχειν, καὶ Πελοποννησίοις ὑπὲρ αὐτῶν ὀργισθέντας πολλῷ πλέοσι μὴ διαμάχεσθαι (κρατήσαντές τε γὰρ αὖθις οὐκ ἐλάσσοσι μαχούμεθα καὶ ἢν σφαλῶμεν, τὰ τῶν ξυμμάχων, ὅθεν ἰσχύομεν, προσαπόλλυται· οὐ γὰρ ἡσυχάσουσι μὴ ἱκανῶν ἡμῶν ὄντων ἐπ’ αὐτοὺς στρατεύειν), τήν τε ὀλόφυρσιν μὴ οἰκιῶν καὶ γῆς ποιεῖσθαι, ἀλλὰ τῶν σωμάτων· οὐ γὰρ τάδε τοὺς ἄνδρας, ἀλλ’ οἱ ἄνδρες ταῦτα κτῶνται. καὶ εἰ ᾤμην πείσειν ὑμᾶς, αὐτοὺς ἂν ἐξελθόντας ἐκέλευον αὐτὰ δῃῶσαι καὶ δεῖξαι Πελοποννησίοις ὅτι τούτων γε ἕνεκα οὐχ ὑπακούσεσθε.", "st": "1.143"}, {"sp": "N", "t": "‘πολλὰ δὲ καὶ ἄλλα ἔχω ἐς ἐλπίδα τοῦ περιέσεσθαι, ἢν ἐθέλητε ἀρχήν τε μὴ ἐπικτᾶσθαι ἅμα πολεμοῦντες καὶ κινδύνους αὐθαιρέτους μὴ προστίθεσθαι· μᾶλλον γὰρ πεφόβημαι τὰς οἰκείας ἡμῶν ἁμαρτίας ἢ τὰς τῶν ἐναντίων διανοίας. ἀλλ’ ἐκεῖνα μὲν καὶ ἐν ἄλλῳ λόγῳ ἅμα τοῖς ἔργοις δηλωθήσεται· νῦν δὲ τούτοις ἀποκρινάμενοι ἀποπέμψωμεν, Μεγαρέας μὲν ὅτι ἐάσομεν ἀγορᾷ καὶ λιμέσι χρῆσθαι, ἢν καὶ Λακεδαιμόνιοι ξενηλασίας μὴ ποιῶσι μήτε ἡμῶν μήτε τῶν ἡμετέρων ξυμμάχων (οὔτε γὰρ ἐκεῖνο κωλύει ἐν ταῖς σπονδαῖς οὔτε τόδε), τὰς δὲ πόλεις ὅτι αὐτονόμους ἀφήσομεν, εἰ καὶ αὐτονόμους ἔχοντες ἐσπεισάμεθα, καὶ ὅταν κἀκεῖνοι ταῖς ἑαυτῶν ἀποδῶσι πόλεσι μὴ σφίσι [τοῖς Λακεδαιμονίοις] ἐπιτηδείως αὐτονομεῖσθαι, ἀλλ’ αὐτοῖς ἑκάστοις ὡς βούλονται· δίκας τε ὅτι ἐθέλομεν δοῦναι κατὰ τὰς ξυνθήκας, πολέμου δὲ οὐκ ἄρξομεν, ἀρχομένους δὲ ἀμυνούμεθα. ταῦτα γὰρ δίκαια καὶ πρέποντα ἅμα τῇδε τῇ πόλει ἀποκρίνασθαι. εἰδέναι δὲ χρὴ ὅτι ἀνάγκη πολεμεῖν, ἢν δὲ ἑκούσιοι μᾶλλον δεχώμεθα, ἧσσον ἐγκεισομένους τοὺς ἐναντίους ἕξομεν, ἔκ τε τῶν μεγίστων κινδύνων ὅτι καὶ πόλει καὶ ἰδιώτῃ μέγισται τιμαὶ περιγίγνονται. οἱ γοῦν πατέρες ἡμῶν ὑποστάντες Μήδους καὶ οὐκ ἀπὸ τοσῶνδε ὁρμώμενοι, ἀλλὰ καὶ τὰ ὑπάρχοντα ἐκλιπόντες, γνώμῃ τε πλέονι ἢ τύχῃ καὶ τόλμῃ μείζονι ἢ δυνάμει τόν τε βάρβαρον ἀπεώσαντο καὶ ἐς τάδε προήγαγον αὐτά. ὧν οὐ χρὴ λείπεσθαι, ἀλλὰ τούς τε ἐχθροὺς παντὶ τρόπῳ ἀμύνεσθαι καὶ τοῖς ἐπιγιγνομένοις πειρᾶσθαι αὐτὰ μὴ ἐλάσσω παραδοῦναι.’", "st": "1.144"}, {"sp": "N", "t": "ὁ μὲν Περικλῆς τοιαῦτα εἶπεν, οἱ δὲ Ἀθηναῖοι νομίσαντες ἄριστα σφίσι παραινεῖν αὐτὸν ἐψηφίσαντο ἃ ἐκέλευε, καὶ τοῖς Λακεδαιμονίοις ἀπεκρίναντο τῇ ἐκείνου γνώμῃ, καθ’ ἕκαστά τε ὡς ἔφρασε καὶ τὸ ξύμπαν, οὐδὲν κελευόμενοι ποιήσειν, δίκῃ δὲ κατὰ τὰς ξυνθήκας ἑτοῖμοι εἶναι διαλύεσθαι περὶ τῶν ἐγκλημάτων ἐπὶ ἴσῃ καὶ ὁμοίᾳ. καὶ οἱ μὲν ἀπεχώρησαν ἐπ’ οἴκου καὶ οὐκέτι ὕστερον ἐπρεσβεύοντο·", "st": "1.145"}, {"sp": "N", "t": "αἰτίαι δὲ αὗται καὶ διαφοραὶ ἐγένοντο ἀμφοτέροις πρὸ τοῦ πολέμου, ἀρξάμεναι εὐθὺς ἀπὸ τῶν ἐν Ἐπιδάμνῳ καὶ Κερκύρᾳ· ἐπεμείγνυντο δὲ ὅμως ἐν αὐταῖς καὶ παρ’ ἀλλήλους ἐφοίτων ἀκηρύκτως μέν, ἀνυπόπτως δὲ οὔ· σπονδῶν γὰρ ξύγχυσις τὰ γιγνόμενα ἦν καὶ πρόφασις τοῦ πολεμεῖν.", "st": "1.146"}, {"sp": "HDR", "t": "Βιβλίον Βʹ", "st": "2"}, {"sp": "N", "t": "ἄρχεται δὲ ὁ πόλεμος ἐνθένδε ἤδη Ἀθηναίων καὶ Πελοποννησίων καὶ τῶν ἑκατέροις ξυμμάχων, ἐν ᾧ οὔτε ἐπεμείγνυντο ἔτι ἀκηρυκτεὶ παρ’ ἀλλήλους καταστάντες τε ξυνεχῶς ἐπολέμουν· γέγραπται δὲ ἑξῆς ὡς ἕκαστα ἐγίγνετο κατὰ θέρος καὶ χειμῶνα.", "st": "2.1"}, {"sp": "N", "t": "τέσσαρα μὲν γὰρ καὶ δέκα ἔτη ἐνέμειναν αἱ τριακοντούτεις σπονδαὶ αἳ ἐγένοντο μετ’ Εὐβοίας ἅλωσιν· τῷ δὲ πέμπτῳ καὶ δεκάτῳ ἔτει, ἐπὶ Χρυσίδος ἐν Ἄργει τότε πεντήκοντα δυοῖν δέοντα ἔτη ἱερωμένης καὶ Αἰνησίου ἐφόρου ἐν Σπάρτῃ καὶ Πυθοδώρου ἔτι δύο μῆνας ἄρχοντος Ἀθηναίοις, μετὰ τὴν ἐν Ποτειδαίᾳ μάχην μηνὶ ἕκτῳ καὶ ἅμα ἦρι ἀρχομένῳ Θηβαίων ἄνδρες ὀλίγῳ πλείους τριακοσίων (ἡγοῦντο δὲ αὐτῶν βοιωταρχοῦντες Πυθάγγελός τε ὁ Φυλείδου καὶ Διέμπορος ὁ Ὀνητορίδου) ἐσῆλθον περὶ πρῶτον ὕπνον ξὺν ὅπλοις ἐς Πλάταιαν τῆς Βοιωτίας οὖσαν Ἀθηναίων ξυμμαχίδα. ἐπηγάγοντο δὲ καὶ ἀνέῳξαν τὰς πύλας Πλαταιῶν ἄνδρες, Ναυκλείδης τε καὶ οἱ μετ’ αὐτοῦ, βουλόμενοι ἰδίας ἕνεκα δυνάμεως ἄνδρας τε τῶν πολιτῶν τοὺς σφίσιν ὑπεναντίους διαφθεῖραι καὶ τὴν πόλιν Θηβαίοις προσποιῆσαι. ἔπραξαν δὲ ταῦτα δι’ Εὐρυμάχου τοῦ Λεοντιάδου, ἀνδρὸς Θηβαίων δυνατωτάτου. προϊδόντες γὰρ οἱ Θηβαῖοι ὅτι ἔσοιτο ὁ πόλεμος ἐβούλοντο τὴν Πλάταιαν αἰεὶ σφίσι διάφορον οὖσαν ἔτι ἐν εἰρήνῃ τε καὶ τοῦ πολέμου μήπω φανεροῦ καθεστῶτος προκαταλαβεῖν. ᾗ καὶ ῥᾷον ἔλαθον ἐσελθόντες, φυλακῆς οὐ προκαθεστηκυίας. θέμενοι δὲ ἐς τὴν ἀγορὰν τὰ ὅπλα τοῖς μὲν ἐπαγαγομένοις οὐκ ἐπείθοντο ὥστε εὐθὺς ἔργου ἔχεσθαι καὶ ἰέναι ἐπὶ τὰς οἰκίας τῶν ἐχθρῶν, γνώμην δ’ ἐποιοῦντο κηρύγμασί τε χρήσασθαι ἐπιτηδείοις καὶ ἐς ξύμβασιν μᾶλλον καὶ φιλίαν τὴν πόλιν ἀγαγεῖν (καὶ ἀνεῖπεν ὁ κῆρυξ, εἴ τις βούλεται κατὰ τὰ πάτρια τῶν πάντων Βοιωτῶν ξυμμαχεῖν, τίθεσθαι παρ’ αὑτοὺς τὰ ὅπλα), νομίζοντες σφίσι ῥᾳδίως τούτῳ τῷ τρόπῳ προσχωρήσειν τὴν πόλιν.", "st": "2.2"}, {"sp": "N", "t": "οἱ δὲ Πλαταιῆς ὡς ᾔσθοντο ἔνδον τε ὄντας τοὺς Θηβαίους καὶ ἐξαπιναίως κατειλημμένην τὴν πόλιν, καταδείσαντες καὶ νομίσαντες πολλῷ πλείους ἐσεληλυθέναι (οὐ γὰρ ἑώρων ἐν τῇ νυκτί) πρὸς ξύμβασιν ἐχώρησαν καὶ τοὺς λόγους δεξάμενοι ἡσύχαζον, ἄλλως τε καὶ ἐπειδὴ ἐς οὐδένα οὐδὲν ἐνεωτέριζον. πράσσοντες δέ πως ταῦτα κατενόησαν οὐ πολλοὺς τοὺς Θηβαίους ὄντας καὶ ἐνόμισαν ἐπιθέμενοι ῥᾳδίως κρατήσειν· τῷ γὰρ πλήθει τῶν Πλαταιῶν οὐ βουλομένῳ ἦν τῶν Ἀθηναίων ἀφίστασθαι. ἐδόκει οὖν ἐπιχειρητέα εἶναι, καὶ ξυνελέγοντο διορύσσοντες τοὺς κοινοὺς τοίχους παρ’ ἀλλήλους, ὅπως μὴ διὰ τῶν ὁδῶν φανεροὶ ὦσιν ἰόντες, ἁμάξας τε ἄνευ τῶν ὑποζυγίων ἐς τὰς ὁδοὺς καθίστασαν, ἵνα ἀντὶ τείχους ᾖ, καὶ τἆλλα ἐξήρτυον ᾗ ἕκαστον ἐφαίνετο πρὸς τὰ παρόντα ξύμφορον ἔσεσθαι. ἐπεὶ δὲ ὡς ἐκ τῶν δυνατῶν ἑτοῖμα ἦν, φυλάξαντες ἔτι νύκτα καὶ αὐτὸ τὸ περίορθρον ἐχώρουν ἐκ τῶν οἰκιῶν ἐπ’ αὐτούς, ὅπως μὴ κατὰ φῶς θαρσαλεωτέροις οὖσι προσφέροιντο καὶ σφίσιν ἐκ τοῦ ἴσου γίγνωνται, ἀλλ’ ἐν νυκτὶ φοβερώτεροι ὄντες ἥσσους ὦσι τῆς σφετέρας ἐμπειρίας τῆς κατὰ τὴν πόλιν. προσέβαλόν τε εὐθὺς καὶ ἐς χεῖρας ᾖσαν κατὰ τάχος.", "st": "2.3"}, {"sp": "N", "t": "οἱ δ’ ὡς ἔγνωσαν ἐξηπατημένοι, ξυνεστρέφοντό τε ἐν σφίσιν αὐτοῖς καὶ τὰς προσβολὰς ᾗ προσπίπτοιεν ἀπεωθοῦντο. καὶ δὶς μὲν ἢ τρὶς ἀπεκρούσαντο, ἔπειτα πολλῷ θορύβῳ αὐτῶν τε προσβαλόντων καὶ τῶν γυναικῶν καὶ τῶν οἰκετῶν ἅμα ἀπὸ τῶν οἰκιῶν κραυγῇ τε καὶ ὀλολυγῇ χρωμένων λίθοις τε καὶ κεράμῳ βαλλόντων, καὶ ὑετοῦ ἅμα διὰ νυκτὸς πολλοῦ ἐπιγενομένου, ἐφοβήθησαν καὶ τραπόμενοι ἔφευγον διὰ τῆς πόλεως, ἄπειροι μὲν ὄντες οἱ πλείους ἐν σκότῳ καὶ πηλῷ τῶν διόδων ᾗ χρὴ σωθῆναι (καὶ γὰρ τελευτῶντος τοῦ μηνὸς τὰ γιγνόμενα ἦν), ἐμπείρους δὲ ἔχοντες τοὺς διώκοντας τοῦ μὴ ἐκφεύγειν, ὥστε διεφθείροντο οἱ πολλοί. τῶν δὲ Πλαταιῶν τις τὰς πύλας ᾗ ἐσῆλθον καὶ αἵπερ ἦσαν μόναι ἀνεῳγμέναι ἔκλῃσε στυρακίῳ ἀκοντίου ἀντὶ βαλάνου χρησάμενος ἐς τὸν μοχλόν, ὥστε μηδὲ ταύτῃ ἔξοδον ἔτι εἶναι. διωκόμενοι δὲ κατὰ τὴν πόλιν οἱ μέν τινες αὐτῶν ἐπὶ τὸ τεῖχος ἀναβάντες ἔρριψαν ἐς τὸ ἔξω σφᾶς αὐτοὺς καὶ διεφθάρησαν οἱ πλείους, οἱ δὲ κατὰ πύλας ἐρήμους γυναικὸς δούσης πέλεκυν λαθόντες καὶ διακόψαντες τὸν μοχλὸν ἐξῆλθον οὐ πολλοί (αἴσθησις γὰρ ταχεῖα ἐπεγένετο), ἄλλοι δὲ ἄλλῃ τῆς πόλεως σποράδες ἀπώλλυντο. τὸ δὲ πλεῖστον καὶ ὅσον μάλιστα ἦν ξυνεστραμμένον ἐσπίπτουσιν ἐς οἴκημα μέγα, ὃ ἦν τοῦ τείχους καὶ αἱ θύραι ἀνεῳγμέναι ἔτυχον αὐτοῦ, οἰόμενοι πύλας τὰς θύρας τοῦ οἰκήματος εἶναι καὶ ἄντικρυς δίοδον ἐς τὸ ἔξω. ὁρῶντες δὲ αὐτοὺς οἱ Πλαταιῆς ἀπειλημμένους ἐβουλεύοντο εἴτε κατακαύσωσιν ὥσπερ ἔχουσιν, ἐμπρήσαντες τὸ οἴκημα, εἴτε τι ἄλλο χρήσωνται. τέλος δὲ οὗτοί τε καὶ ὅσοι ἄλλοι τῶν Θηβαίων περιῆσαν κατὰ τὴν πόλιν πλανώμενοι, ξυνέβησαν τοῖς Πλαταιεῦσι παραδοῦναι σφᾶς τε αὐτοὺς καὶ τὰ ὅπλα χρήσασθαι ὅτι ἂν βούλωνται. οἱ μὲν δὴ ἐν τῇ Πλαταίᾳ οὕτως ἐπεπράγεσαν·", "st": "2.4"}, {"sp": "N", "t": "οἱ δ’ ἄλλοι Θηβαῖοι, οὓς ἔδει ἔτι τῆς νυκτὸς παραγενέσθαι πανστρατιᾷ, εἴ τι ἄρα μὴ προχωροίη τοῖς ἐσεληλυθόσι, τῆς ἀγγελίας ἅμα καθ’ ὁδὸν αὐτοῖς ῥηθείσης περὶ τῶν γεγενημένων ἐπεβοήθουν. ἀπέχει δὲ ἡ Πλάταια τῶν Θηβῶν σταδίους ἑβδομήκοντα, καὶ τὸ ὕδωρ τὸ γενόμενον τῆς νυκτὸς ἐποίησε βραδύτερον αὐτοὺς ἐλθεῖν· ὁ γὰρ Ἀσωπὸς ποταμὸς ἐρρύη μέγας καὶ οὐ ῥᾳδίως διαβατὸς ἦν. πορευόμενοί τε ἐν ὑετῷ καὶ τὸν ποταμὸν μόλις διαβάντες ὕστερον παρεγένοντο, ἤδη τῶν ἀνδρῶν τῶν μὲν διεφθαρμένων, τῶν δὲ ζώντων ἐχομένων. ὡς δ’ ᾔσθοντο οἱ Θηβαῖοι τὸ γεγενημένον, ἐπεβούλευον τοῖς ἔξω τῆς πόλεως τῶν Πλαταιῶν· ἦσαν γὰρ καὶ ἄνθρωποι κατὰ τοὺς ἀγροὺς καὶ κατασκευή, οἷα ἀπροσδοκήτου κακοῦ ἐν εἰρήνῃ γενομένου· ἐβούλοντο γὰρ σφίσιν, εἴ τινα λάβοιεν, ὑπάρχειν ἀντὶ τῶν ἔνδον, ἢν ἄρα τύχωσί τινες ἐζωγρημένοι. καὶ οἱ μὲν ταῦτα διενοοῦντο, οἱ δὲ Πλαταιῆς ἔτι διαβουλευομένων αὐτῶν ὑποτοπήσαντες τοιοῦτόν τι ἔσεσθαι καὶ δείσαντες περὶ τοῖς ἔξω κήρυκα ἐξέπεμψαν παρὰ τοὺς Θηβαίους, λέγοντες ὅτι οὔτε τὰ πεποιημένα ὅσια δράσειαν ἐν σπονδαῖς σφῶν πειράσαντες καταλαβεῖν τὴν πόλιν, τά τε ἔξω ἔλεγον αὐτοῖς μὴ ἀδικεῖν· εἰ δὲ μή, καὶ αὐτοὶ ἔφασαν αὐτῶν τοὺς ἄνδρας ἀποκτενεῖν οὓς ἔχουσι ζῶντας· ἀναχωρησάντων δὲ πάλιν ἐκ τῆς γῆς ἀποδώσειν αὐτοῖς τοὺς ἄνδρας. Θηβαῖοι μὲν ταῦτα λέγουσι καὶ ἐπομόσαι φασὶν αὐτούς· Πλαταιῆς δ’ οὐχ ὁμολογοῦσι τοὺς ἄνδρας εὐθὺς ὑποσχέσθαι ἀποδώσειν, ἀλλὰ λόγων πρῶτον γενομένων ἤν τι ξυμβαίνωσι, καὶ ἐπομόσαι οὔ φασιν. ἐκ δ’ οὖν τῆς γῆς ἀνεχώρησαν οἱ Θηβαῖοι οὐδὲν ἀδικήσαντες· οἱ δὲ Πλαταιῆς ἐπειδὴ τὰ ἐκ τῆς χώρας κατὰ τάχος ἐσεκομίσαντο, ἀπέκτειναν τοὺς ἄνδρας εὐθύς. ἦσαν δὲ ὀγδοήκοντα καὶ ἑκατὸν οἱ ληφθέντες, καὶ Εὐρύμαχος εἷς αὐτῶν ἦν, πρὸς ὃν ἔπραξαν οἱ προδιδόντες.", "st": "2.5"}, {"sp": "N", "t": "τοῦτο δὲ ποιήσαντες ἔς τε τὰς Ἀθήνας ἄγγελον ἔπεμπον καὶ τοὺς νεκροὺς ὑποσπόνδους ἀπέδοσαν τοῖς Θηβαίοις, τά τε ἐν τῇ πόλει καθίσταντο πρὸς τὰ παρόντα ᾗ ἐδόκει αὐτοῖς. τοῖς δ’ Ἀθηναίοις ἠγγέλθη εὐθὺς τὰ περὶ τῶν Πλαταιῶν γεγενημένα, καὶ Βοιωτῶν τε παραχρῆμα ξυνέλαβον ὅσοι ἦσαν ἐν τῇ Ἀττικῇ καὶ ἐς τὴν Πλάταιαν ἔπεμψαν κήρυκα, κελεύοντες εἰπεῖν μηδὲν νεώτερον ποιεῖν περὶ τῶν ἀνδρῶν οὓς ἔχουσι Θηβαίων, πρὶν ἄν τι καὶ αὐτοὶ βουλεύσωσι περὶ αὐτῶν· οὐ γὰρ ἠγγέλθη αὐτοῖς ὅτι τεθνηκότες εἶεν. ἅμα γὰρ τῇ ἐσόδῳ γιγνομένῃ τῶν Θηβαίων ὁ πρῶτος ἄγγελος ἐξῄει, ὁ δὲ δεύτερος ἄρτι νενικημένων τε καὶ ξυνειλημμένων· καὶ τῶν ὕστερον οὐδὲν ᾔδεσαν. οὕτω δὴ οὐκ εἰδότες οἱ Ἀθηναῖοι ἐπέστελλον· ὁ δὲ κῆρυξ ἀφικόμενος ηὗρε τοὺς ἄνδρας διεφθαρμένους. καὶ μετὰ ταῦτα οἱ Ἀθηναῖοι στρατεύσαντες ἐς Πλάταιαν σῖτόν τε ἐσήγαγον καὶ φρουροὺς ἐγκατέλιπον, τῶν τε ἀνθρώπων τοὺς ἀχρειοτάτους ξὺν γυναιξὶ καὶ παισὶν ἐξεκόμισαν.", "st": "2.6"}, {"sp": "N", "t": "γεγενημένου δὲ τοῦ ἐν Πλαταιαῖς ἔργου καὶ λελυμένων λαμπρῶς τῶν σπονδῶν οἱ Ἀθηναῖοι παρεσκευάζοντο ὡς πολεμήσοντες, παρεσκευάζοντο δὲ καὶ Λακεδαιμόνιοι καὶ οἱ ξύμμαχοι, πρεσβείας τε μέλλοντες πέμπειν παρὰ βασιλέα καὶ ἄλλοσε πρὸς τοὺς βαρβάρους, εἴ ποθέν τινα ὠφελίαν ἤλπιζον ἑκάτεροι προσλήψεσθαι, πόλεις τε ξυμμαχίδας ποιούμενοι ὅσαι ἦσαν ἐκτὸς τῆς ἑαυτῶν δυνάμεως. καὶ Λακεδαιμονίοις μὲν πρὸς ταῖς αὐτοῦ ὑπαρχούσαις ἐξ Ἰταλίας καὶ Σικελίας τοῖς τἀκείνων ἑλομένοις ναῦς ἐπετάχθη ποιεῖσθαι κατὰ μέγεθος τῶν πόλεων, ὡς ἐς τὸν πάντα ἀριθμὸν πεντακοσίων νεῶν ἐσομένων, καὶ ἀργύριον ῥητὸν ἑτοιμάζειν, τά τε ἄλλα ἡσυχάζοντας καὶ Ἀθηναίους δεχομένους μιᾷ νηὶ ἕως ἂν ταῦτα παρασκευασθῇ. Ἀθηναῖοι δὲ τήν τε ὑπάρχουσαν ξυμμαχίαν ἐξήταζον καὶ ἐς τὰ περὶ Πελοπόννησον μᾶλλον χωρία ἐπρεσβεύοντο, Κέρκυραν καὶ Κεφαλληνίαν καὶ Ἀκαρνᾶνας καὶ Ζάκυνθον, ὁρῶντες, εἰ σφίσι φίλια ταῦτ’ εἴη βεβαίως, πέριξ τὴν Πελοπόννησον καταπολεμήσοντες.", "st": "2.7"}, {"sp": "N", "t": "ὀλίγον τε ἐπενόουν οὐδὲν ἀμφότεροι, ἀλλ’ ἔρρωντο ἐς τὸν πόλεμον οὐκ ἀπεικότως· ἀρχόμενοι γὰρ πάντες ὀξύτερον ἀντιλαμβάνονται, τότε δὲ καὶ νεότης πολλὴ μὲν οὖσα ἐν τῇ Πελοποννήσῳ, πολλὴ δ’ ἐν ταῖς Ἀθήναις οὐκ ἀκουσίως ὑπὸ ἀπειρίας ἥπτετο τοῦ πολέμου, ἥ τε ἄλλη Ἑλλὰς ἅπασα μετέωρος ἦν ξυνιουσῶν τῶν πρώτων πόλεων. καὶ πολλὰ μὲν λόγια ἐλέγετο, πολλὰ δὲ χρησμολόγοι ᾖδον ἔν τε τοῖς μέλλουσι πολεμήσειν καὶ ἐν ταῖς ἄλλαις πόλεσιν. ἔτι δὲ Δῆλος ἐκινήθη ὀλίγον πρὸ τούτων, πρότερον οὔπω σεισθεῖσα ἀφ’ οὗ Ἕλληνες μέμνηνται· ἐλέγετο δὲ καὶ ἐδόκει ἐπὶ τοῖς μέλλουσι γενήσεσθαι σημῆναι. εἴ τέ τι ἄλλο τοιουτότροπον ξυνέβη γενέσθαι, πάντα ἀνεζητεῖτο. ἡ δὲ εὔνοια παρὰ πολὺ ἐποίει τῶν ἀνθρώπων μᾶλλον ἐς τοὺς Λακεδαιμονίους, ἄλλως τε καὶ προειπόντων ὅτι τὴν Ἑλλάδα ἐλευθεροῦσιν. ἔρρωτό τε πᾶς καὶ ἰδιώτης καὶ πόλις εἴ τι δύναιτο καὶ λόγῳ καὶ ἔργῳ ξυνεπιλαμβάνειν αὐτοῖς· ἐν τούτῳ τε κεκωλῦσθαι ἐδόκει ἑκάστῳ τὰ πράγματα ᾧ μή τις αὐτὸς παρέσται. οὕτως ⟨ἐν⟩ ὀργῇ εἶχον οἱ πλείους τοὺς Ἀθηναίους, οἱ μὲν τῆς ἀρχῆς ἀπολυθῆναι βουλόμενοι, οἱ δὲ μὴ ἀρχθῶσι φοβούμενοι.", "st": "2.8"}, {"sp": "N", "t": "παρασκευῇ μὲν οὖν καὶ γνώμῃ τοιαύτῃ ὥρμηντο, πόλεις δὲ ἑκάτεροι τάσδε ἔχοντες ξυμμάχους ἐς τὸν πόλεμον καθίσταντο. Λακεδαιμονίων μὲν οἵδε ξύμμαχοι· Πελοποννήσιοι μὲν οἱ ἐντὸς Ἰσθμοῦ πάντες πλὴν Ἀργείων καὶ Ἀχαιῶν (τούτοις δὲ ἐς ἀμφοτέρους φιλία ἦν· Πελληνῆς δὲ Ἀχαιῶν μόνοι ξυνεπολέμουν τὸ πρῶτον, ἔπειτα δὲ ὕστερον καὶ ἅπαντες), ἔξω δὲ Πελοποννήσου Μεγαρῆς, Βοιωτοί, Λοκροί, Φωκῆς, Ἀμπρακιῶται, Λευκάδιοι, Ἀνακτόριοι. τούτων ναυτικὸν παρείχοντο Κορίνθιοι, Μεγαρῆς, Σικυώνιοι, Πελληνῆς, Ἠλεῖοι, Ἀμπρακιῶται, Λευκάδιοι, ἱππέας δὲ Βοιωτοί, Φωκῆς, Λοκροί· αἱ δ’ ἄλλαι πόλεις πεζὸν παρεῖχον. αὕτη μὲν Λακεδαιμονίων ξυμμαχία· Ἀθηναίων δὲ Χῖοι, Λέσβιοι, Πλαταιῆς, Μεσσήνιοι οἱ ἐν Ναυπάκτῳ, Ἀκαρνάνων οἱ πλείους, Κερκυραῖοι, Ζακύνθιοι, καὶ ἄλλαι πόλεις αἱ ὑποτελεῖς οὖσαι ἐν ἔθνεσι τοσοῖσδε, Καρία ἡ ἐπὶ θαλάσσῃ, Δωριῆς Καρσὶ πρόσοικοι, Ἰωνία, Ἑλλήσποντος, τὰ ἐπὶ Θρᾴκης, νῆσοι ὅσαι ἐντὸς Πελοποννήσου καὶ Κρήτης πρὸς ἥλιον ἀνίσχοντα, πᾶσαι αἱ Κυκλάδες πλὴν Μήλου καὶ Θήρας. τούτων ναυτικὸν παρείχοντο Χῖοι, Λέσβιοι, Κερκυραῖοι, οἱ δ’ ἄλλοι πεζὸν καὶ χρήματα. ξυμμαχία μὲν αὕτη ἑκατέρων καὶ παρασκευὴ ἐς τὸν πόλεμον ἦν.", "st": "2.9"}, {"sp": "N", "t": "οἱ δὲ Λακεδαιμόνιοι μετὰ τὰ ἐν Πλαταιαῖς εὐθὺς περιήγγελλον κατὰ τὴν Πελοπόννησον καὶ τὴν ἔξω ξυμμαχίδα στρατιὰν παρασκευάζεσθαι ταῖς πόλεσι τά τε ἐπιτήδεια οἷα εἰκὸς ἐπὶ ἔξοδον ἔκδημον ἔχειν, ὡς ἐσβαλοῦντες ἐς τὴν Ἀττικήν. ἐπειδὴ δὲ ἑκάστοις ἑτοῖμα γίγνοιτο, κατὰ τὸν χρόνον τὸν εἰρημένον ξυνῇσαν τὰ δύο μέρη ἀπὸ πόλεως ἑκάστης ἐς τὸν Ἰσθμόν. καὶ ἐπειδὴ πᾶν τὸ στράτευμα ξυνειλεγμένον ἦν, Ἀρχίδαμος ὁ βασιλεὺς τῶν Λακεδαιμονίων, ὅσπερ ἡγεῖτο τῆς ἐξόδου ταύτης, ξυγκαλέσας τοὺς στρατηγοὺς τῶν πόλεων πασῶν καὶ τοὺς μάλιστα ἐν τέλει καὶ ἀξιολογωτάτους παρῄνει τοιάδε.", "st": "2.10"}, {"sp": "N", "t": "‘ἄνδρες Πελοποννήσιοι καὶ ξύμμαχοι, καὶ οἱ πατέρες ἡμῶν πολλὰς στρατείας καὶ ἐν αὐτῇ Πελοποννήσῳ καὶ ἔξω ἐποιήσαντο, καὶ ἡμῶν αὐτῶν οἱ πρεσβύτεροι οὐκ ἄπειροι πολέμων εἰσίν· ὅμως δὲ τῆσδε οὔπω μείζονα παρασκευὴν ἔχοντες ἐξήλθομεν, ἀλλὰ καὶ ἐπὶ πόλιν δυνατωτάτην νῦν ἐρχόμεθα καὶ αὐτοὶ πλεῖστοι καὶ ἄριστοι στρατεύοντες. δίκαιον οὖν ἡμᾶς μήτε τῶν πατέρων χείρους φαίνεσθαι μήτε ἡμῶν αὐτῶν τῆς δόξης ἐνδεεστέρους. ἡ γὰρ Ἑλλὰς πᾶσα τῇδε τῇ ὁρμῇ ἐπῆρται καὶ προσέχει τὴν γνώμην, εὔνοιαν ἔχουσα διὰ τὸ Ἀθηναίων ἔχθος πρᾶξαι ἡμᾶς ἃ ἐπινοοῦμεν. οὔκουν χρή, εἴ τῳ καὶ δοκοῦμεν πλήθει ἐπιέναι καὶ ἀσφάλεια πολλὴ εἶναι μὴ ἂν ἐλθεῖν τοὺς ἐναντίους ἡμῖν διὰ μάχης, τούτων ἕνεκα ἀμελέστερόν τι παρεσκευασμένους χωρεῖν, ἀλλὰ καὶ πόλεως ἑκάστης ἡγεμόνα καὶ στρατιώτην τὸ καθ’ αὑτὸν αἰεὶ προσδέχεσθαι ἐς κίνδυνόν τινα ἥξειν. ἄδηλα γὰρ τὰ τῶν πολέμων, καὶ ἐξ ὀλίγου τὰ πολλὰ καὶ δι’ ὀργῆς αἱ ἐπιχειρήσεις γίγνονται· πολλάκις τε τὸ ἔλασσον πλῆθος δεδιὸς ἄμεινον ἠμύνατο τοὺς πλέονας διὰ τὸ καταφρονοῦντας ἀπαρασκεύους γενέσθαι. χρὴ δὲ αἰεὶ ἐν τῇ πολεμίᾳ τῇ μὲν γνώμῃ θαρσαλέους στρατεύειν, τῷ δ’ ἔργῳ δεδιότας παρεσκευάσθαι· οὕτω γὰρ πρός τε τὸ ἐπιέναι τοῖς ἐναντίοις εὐψυχότατοι ἂν εἶεν πρός τε τὸ ἐπιχειρεῖσθαι ἀσφαλέστατοι. ἡμεῖς δὲ οὐδ’ ἐπὶ ἀδύνατον ἀμύνεσθαι οὕτω πόλιν ἐρχόμεθα, ἀλλὰ τοῖς πᾶσιν ἄριστα παρεσκευασμένην, ὥστε χρὴ καὶ πάνυ ἐλπίζειν διὰ μάχης ἰέναι αὐτούς, εἰ μὴ καὶ νῦν ὥρμηνται ἐν ᾧ οὔπω πάρεσμεν, ἀλλ’ ὅταν ἐν τῇ γῇ ὁρῶσιν ἡμᾶς δῃοῦντάς τε καὶ τἀκείνων φθείροντας. πᾶσι γὰρ ἐν τοῖς ὄμμασι καὶ ἐν τῷ παραυτίκα ὁρᾶν πάσχοντάς τι ἄηθες ὀργὴ προσπίπτει· καὶ οἱ λογισμῷ ἐλάχιστα χρώμενοι θυμῷ πλεῖστα ἐς ἔργον καθίστανται. Ἀθηναίους δὲ καὶ πλέον τι τῶν ἄλλων εἰκὸς τοῦτο δρᾶσαι, οἳ ἄρχειν τε τῶν ἄλλων ἀξιοῦσι καὶ ἐπιόντες τὴν τῶν πέλας δῃοῦν μᾶλλον ἢ τὴν αὑτῶν ὁρᾶν. ὡς οὖν ἐπὶ τοσαύτην πόλιν στρατεύοντες καὶ μεγίστην δόξαν οἰσόμενοι τοῖς τε προγόνοις καὶ ἡμῖν αὐτοῖς ἐπ’ ἀμφότερα ἐκ τῶν ἀποβαινόντων, ἕπεσθ’ ὅπῃ ἄν τις ἡγῆται, κόσμον καὶ φυλακὴν περὶ παντὸς ποιούμενοι καὶ τὰ παραγγελλόμενα ὀξέως δεχόμενοι· κάλλιστον γὰρ τόδε καὶ ἀσφαλέστατον, πολλοὺς ὄντας ἑνὶ κόσμῳ χρωμένους φαίνεσθαι.’", "st": "2.11"}, {"sp": "N", "t": "τοσαῦτα εἰπὼν καὶ διαλύσας τὸν ξύλλογον ὁ Ἀρχίδαμος Μελήσιππον πρῶτον ἀποστέλλει ἐς τὰς Ἀθήνας τὸν Διακρίτου ἄνδρα Σπαρτιάτην, εἴ τι ἄρα μᾶλλον ἐνδοῖεν οἱ Ἀθηναῖοι ὁρῶντες σφᾶς ἤδη ἐν ὁδῷ ὄντας. οἱ δὲ οὐ προσεδέξαντο αὐτὸν ἐς τὴν πόλιν οὐδ’ ἐπὶ τὸ κοινόν· ἦν γὰρ Περικλέους γνώμη πρότερον νενικηκυῖα κήρυκα καὶ πρεσβείαν μὴ προσδέχεσθαι Λακεδαιμονίων ἐξεστρατευμένων· ἀποπέμπουσιν οὖν αὐτὸν πρὶν ἀκοῦσαι καὶ ἐκέλευον ἐκτὸς ὅρων εἶναι αὐθημερόν, τό τε λοιπὸν ἀναχωρήσαντας ἐπὶ τὰ σφέτερα αὐτῶν, ἤν τι βούλωνται, πρεσβεύεσθαι. ξυμπέμπουσί τε τῷ Μελησίππῳ ἀγωγούς, ὅπως μηδενὶ ξυγγένηται. ὁ δ’ ἐπειδὴ ἐπὶ τοῖς ὁρίοις ἐγένετο καὶ ἔμελλε διαλύσεσθαι, τοσόνδε εἰπὼν ἐπορεύετο ὅτι ‘ἥδε ἡ ἡμέρα τοῖς Ἕλλησι μεγάλων κακῶν ἄρξει.’ ὡς δὲ ἀφίκετο ἐς τὸ στρατόπεδον καὶ ἔγνω ὁ Ἀρχίδαμος ὅτι οἱ Ἀθηναῖοι οὐδέν πω ἐνδώσουσιν, οὕτω δὴ ἄρας τῷ στρατῷ προυχώρει ἐς τὴν γῆν αὐτῶν. Βοιωτοὶ δὲ μέρος μὲν τὸ σφέτερον καὶ τοὺς ἱππέας παρείχοντο Πελοποννησίοις ξυστρατεύειν, τοῖς δὲ λειπομένοις ἐς Πλάταιαν ἐλθόντες τὴν γῆν ἐδῄουν.", "st": "2.12"}, {"sp": "N", "t": "ἔτι δὲ τῶν Πελοποννησίων ξυλλεγομένων τε ἐς τὸν Ἰσθμὸν καὶ ἐν ὁδῷ ὄντων, πρὶν ἐσβαλεῖν ἐς τὴν Ἀττικήν, Περικλῆς ὁ Ξανθίππου στρατηγὸς ὢν Ἀθηναίων δέκατος αὐτός, ὡς ἔγνω τὴν ἐσβολὴν ἐσομένην, ὑποτοπήσας, ὅτι Ἀρχίδαμος αὐτῷ ξένος ὢν ἐτύγχανε, μὴ πολλάκις ἢ αὐτὸς ἰδίᾳ βουλόμενος χαρίζεσθαι τοὺς ἀγροὺς αὐτοῦ παραλίπῃ καὶ μὴ δῃώσῃ, ἢ καὶ Λακεδαιμονίων κελευσάντων ἐπὶ διαβολῇ τῇ ἑαυτοῦ γένηται τοῦτο, ὥσπερ καὶ τὰ ἄγη ἐλαύνειν προεῖπον ἕνεκα ἐκείνου, προηγόρευε τοῖς Ἀθηναίοις ἐν τῇ ἐκκλησίᾳ ὅτι Ἀρχίδαμος μέν οἱ ξένος εἴη, οὐ μέντοι ἐπὶ κακῷ γε τῆς πόλεως γένοιτο, τοὺς δὲ ἀγροὺς τοὺς ἑαυτοῦ καὶ οἰκίας ἢν ἄρα μὴ δῃώσωσιν οἱ πολέμιοι ὥσπερ καὶ τὰ τῶν ἄλλων, ἀφίησιν αὐτὰ δημόσια εἶναι καὶ μηδεμίαν οἱ ὑποψίαν κατὰ ταῦτα γίγνεσθαι. παρῄνει δὲ καὶ περὶ τῶν παρόντων ἅπερ καὶ πρότερον, παρασκευάζεσθαί τε ἐς τὸν πόλεμον καὶ τὰ ἐκ τῶν ἀγρῶν ἐσκομίζεσθαι, ἔς τε μάχην μὴ ἐπεξιέναι, ἀλλὰ τὴν πόλιν ἐσελθόντας φυλάσσειν, καὶ τὸ ναυτικόν, ᾗπερ ἰσχύουσιν, ἐξαρτύεσθαι, τά τε τῶν ξυμμάχων διὰ χειρὸς ἔχειν, λέγων τὴν ἰσχὺν αὐτοῖς ἀπὸ τούτων εἶναι τῶν χρημάτων τῆς προσόδου, τὰ δὲ πολλὰ τοῦ πολέμου γνώμῃ καὶ χρημάτων περιουσίᾳ κρατεῖσθαι. θαρσεῖν τε ἐκέλευε προσιόντων μὲν ἑξακοσίων ταλάντων ὡς ἐπὶ τὸ πολὺ φόρου κατ’ ἐνιαυτὸν ἀπὸ τῶν ξυμμάχων τῇ πόλει ἄνευ τῆς ἄλλης προσόδου, ὑπαρχόντων δὲ ἐν τῇ ἀκροπόλει ἔτι τότε ἀργυρίου ἐπισήμου ἑξακισχιλίων ταλάντων (τὰ γὰρ πλεῖστα τριακοσίων ἀποδέοντα μύρια ἐγένετο, ἀφ’ ὧν ἔς τε τὰ προπύλαια τῆς ἀκροπόλεως καὶ τἆλλα οἰκοδομήματα καὶ ἐς Ποτείδαιαν ἀπανηλώθη), χωρὶς δὲ χρυσίου ἀσήμου καὶ ἀργυρίου ἔν τε ἀναθήμασιν ἰδίοις καὶ δημοσίοις καὶ ὅσα ἱερὰ σκεύη περί τε τὰς πομπὰς καὶ τοὺς ἀγῶνας καὶ σκῦλα Μηδικὰ καὶ εἴ τι τοιουτότροπον, οὐκ ἐλάσσονος [ἦν] ἢ πεντακοσίων ταλάντων. ἔτι δὲ καὶ τὰ ἐκ τῶν ἄλλων ἱερῶν προσετίθει χρήματα οὐκ ὀλίγα, οἷς χρήσεσθαι αὐτούς, καὶ ἢν πάνυ ἐξείργωνται πάντων, καὶ αὐτῆς τῆς θεοῦ τοῖς περικειμένοις χρυσίοις· ἀπέφαινε δ’ ἔχον τὸ ἄγαλμα τεσσαράκοντα τάλαντα σταθμὸν χρυσίου ἀπέφθου, καὶ περιαιρετὸν εἶναι ἅπαν. χρησαμένους τε ἐπὶ σωτηρίᾳ ἔφη χρῆναι μὴ ἐλάσσω ἀντικαταστῆσαι πάλιν. χρήμασι μὲν οὖν οὕτως ἐθάρσυνεν αὐτούς, ὁπλίτας δὲ τρισχιλίους καὶ μυρίους εἶναι ἄνευ τῶν ἐν τοῖς φρουρίοις καὶ τῶν παρ’ ἔπαλξιν ἑξακισχιλίων καὶ μυρίων. τοσοῦτοι γὰρ ἐφύλασσον τὸ πρῶτον ὁπότε οἱ πολέμιοι ἐσβάλοιεν, ἀπό τε τῶν πρεσβυτάτων καὶ τῶν νεωτάτων, καὶ μετοίκων ὅσοι ὁπλῖται ἦσαν. τοῦ τε γὰρ Φαληρικοῦ τείχους στάδιοι ἦσαν πέντε καὶ τριάκοντα πρὸς τὸν κύκλον τοῦ ἄστεως, καὶ αὐτοῦ τοῦ κύκλου τὸ φυλασσόμενον τρεῖς καὶ τεσσαράκοντα (ἔστι δὲ αὐτοῦ ὃ καὶ ἀφύλακτον ἦν, τὸ μεταξὺ τοῦ τε μακροῦ καὶ τοῦ Φαληρικοῦ), τὰ δὲ μακρὰ τείχη πρὸς τὸν Πειραιᾶ τεσσαράκοντα σταδίων, ὧν τὸ ἔξωθεν ἐτηρεῖτο· καὶ τοῦ Πειραιῶς ξὺν Μουνιχίᾳ ἑξήκοντα μὲν σταδίων ὁ ἅπας περίβολος, τὸ δ’ ἐν φυλακῇ ὂν ἥμισυ τούτου. ἱππέας δὲ ἀπέφαινε διακοσίους καὶ χιλίους ξὺν ἱπποτοξόταις, ἑξακοσίους δὲ καὶ χιλίους τοξότας, καὶ τριήρεις τὰς πλωίμους τριακοσίας. ταῦτα γὰρ ὑπῆρχεν Ἀθηναίοις καὶ οὐκ ἐλάσσω ἕκαστα τούτων, ὅτε ἡ ἐσβολὴ τὸ πρῶτον ἔμελλε Πελοποννησίων ἔσεσθαι καὶ ἐς τὸν πόλεμον καθίσταντο. ἔλεγε δὲ καὶ ἄλλα οἷάπερ εἰώθει Περικλῆς ἐς ἀπόδειξιν τοῦ περιέσεσθαι τῷ πολέμῳ.", "st": "2.13"}, {"sp": "N", "t": "οἱ δὲ Ἀθηναῖοι ἀκούσαντες ἀνεπείθοντό τε καὶ ἐσεκομίζοντο ἐκ τῶν ἀγρῶν παῖδας καὶ γυναῖκας καὶ τὴν ἄλλην κατασκευὴν ᾗ κατ’ οἶκον ἐχρῶντο, καὶ αὐτῶν τῶν οἰκιῶν καθαιροῦντες τὴν ξύλωσιν· πρόβατα δὲ καὶ ὑποζύγια ἐς τὴν Εὔβοιαν διεπέμψαντο καὶ ἐς τὰς νήσους τὰς ἐπικειμένας. χαλεπῶς δὲ αὐτοῖς διὰ τὸ αἰεὶ εἰωθέναι τοὺς πολλοὺς ἐν τοῖς ἀγροῖς διαιτᾶσθαι ἡ ἀνάστασις ἐγίγνετο.", "st": "2.14"}, {"sp": "N", "t": "ξυνεβεβήκει δὲ ἀπὸ τοῦ πάνυ ἀρχαίου ἑτέρων μᾶλλον Ἀθηναίοις τοῦτο. ἐπὶ γὰρ Κέκροπος καὶ τῶν πρώτων βασιλέων ἡ Ἀττικὴ ἐς Θησέα αἰεὶ κατὰ πόλεις ᾠκεῖτο πρυτανεῖά τε ἐχούσας καὶ ἄρχοντας, καὶ ὁπότε μή τι δείσειαν, οὐ ξυνῇσαν βουλευσόμενοι ὡς τὸν βασιλέα, ἀλλ’ αὐτοὶ ἕκαστοι ἐπολίτευον καὶ ἐβουλεύοντο· καί τινες καὶ ἐπολέμησάν ποτε αὐτῶν, ὥσπερ καὶ Ἐλευσίνιοι μετ’ Εὐμόλπου πρὸς Ἐρεχθέα. ἐπειδὴ δὲ Θησεὺς ἐβασίλευσε, γενόμενος μετὰ τοῦ ξυνετοῦ καὶ δυνατὸς τά τε ἄλλα διεκόσμησε τὴν χώραν καὶ καταλύσας τῶν ἄλλων πόλεων τά τε βουλευτήρια καὶ τὰς ἀρχὰς ἐς τὴν νῦν πόλιν οὖσαν, ἓν βουλευτήριον ἀποδείξας καὶ πρυτανεῖον, ξυνῴκισε πάντας, καὶ νεμομένους τὰ αὑτῶν ἑκάστους ἅπερ καὶ πρὸ τοῦ ἠνάγκασε μιᾷ πόλει ταύτῃ χρῆσθαι, ἣ ἁπάντων ἤδη ξυντελούντων ἐς αὐτὴν μεγάλη γενομένη παρεδόθη ὑπὸ Θησέως τοῖς ἔπειτα· καὶ ξυνοίκια ἐξ ἐκείνου Ἀθηναῖοι ἔτι καὶ νῦν τῇ θεῷ ἑορτὴν δημοτελῆ ποιοῦσιν. τὸ δὲ πρὸ τοῦ ἡ ἀκρόπολις ἡ νῦν οὖσα πόλις ἦν, καὶ τὸ ὑπ’ αὐτὴν πρὸς νότον μάλιστα τετραμμένον. τεκμήριον δέ· τὰ γὰρ ἱερὰ ἐν αὐτῇ τῇ ἀκροπόλει † καὶ ἄλλων θεῶν ἐστὶ καὶ τὰ ἔξω πρὸς τοῦτο τὸ μέρος τῆς πόλεως μᾶλλον ἵδρυται, τό τε τοῦ Διὸς τοῦ Ὀλυμπίου καὶ τὸ Πύθιον καὶ τὸ τῆς Γῆς καὶ τὸ ⟨τοῦ⟩ ἐν Λίμναις Διονύσου, ᾧ τὰ ἀρχαιότερα Διονύσια [τῇ δωδεκάτῃ] ποιεῖται ἐν μηνὶ Ἀνθεστηριῶνι, ὥσπερ καὶ οἱ ἀπ’ Ἀθηναίων Ἴωνες ἔτι καὶ νῦν νομίζουσιν. ἵδρυται δὲ καὶ ἄλλα ἱερὰ ταύτῃ ἀρχαῖα. καὶ τῇ κρήνῃ τῇ νῦν μὲν τῶν τυράννων οὕτω σκευασάντων Ἐννεακρούνῳ καλουμένῃ, τὸ δὲ πάλαι φανερῶν τῶν πηγῶν οὐσῶν Καλλιρρόῃ ὠνομασμένῃ, ἐκεῖνοί τε ἐγγὺς οὔσῃ τὰ πλείστου ἄξια ἐχρῶντο, καὶ νῦν ἔτι ἀπὸ τοῦ ἀρχαίου πρό τε γαμικῶν καὶ ἐς ἄλλα τῶν ἱερῶν νομίζεται τῷ ὕδατι χρῆσθαι· καλεῖται δὲ διὰ τὴν παλαιὰν ταύτῃ κατοίκησιν καὶ ἡ ἀκρόπολις μέχρι τοῦδε ἔτι ὑπ’ Ἀθηναίων πόλις.", "st": "2.15"}, {"sp": "N", "t": "τῇ τε οὖν ἐπὶ πολὺ κατὰ τὴν χώραν αὐτονόμῳ οἰκήσει μετεῖχον οἱ Ἀθηναῖοι, καὶ ἐπειδὴ ξυνῳκίσθησαν, διὰ τὸ ἔθος ἐν τοῖς ἀγροῖς ὅμως οἱ πλείους τῶν τε ἀρχαίων καὶ τῶν ὕστερον μέχρι τοῦδε τοῦ πολέμου γενόμενοί τε καὶ οἰκήσαντες οὐ ῥᾳδίως πανοικεσίᾳ τὰς μεταναστάσεις ἐποιοῦντο, ἄλλως τε καὶ ἄρτι ἀνειληφότες τὰς κατασκευὰς μετὰ τὰ Μηδικά· ἐβαρύνοντο δὲ καὶ χαλεπῶς ἔφερον οἰκίας τε καταλείποντες καὶ ἱερὰ ἃ διὰ παντὸς ἦν αὐτοῖς ἐκ τῆς κατὰ τὸ ἀρχαῖον πολιτείας πάτρια δίαιτάν τε μέλλοντες μεταβάλλειν καὶ οὐδὲν ἄλλο ἢ πόλιν τὴν αὑτοῦ ἀπολείπων ἕκαστος.", "st": "2.16"}, {"sp": "N", "t": "ἐπειδή τε ἀφίκοντο ἐς τὸ ἄστυ, ὀλίγοις μέν τισιν ὑπῆρχον οἰκήσεις καὶ παρὰ φίλων τινὰς ἢ οἰκείων καταφυγή, οἱ δὲ πολλοὶ τά τε ἐρῆμα τῆς πόλεως ᾤκησαν καὶ τὰ ἱερὰ καὶ τὰ ἡρῷα πάντα πλὴν τῆς ἀκροπόλεως καὶ τοῦ Ἐλευσινίου καὶ εἴ τι ἄλλο βεβαίως κλῃστὸν ἦν· τό τε Πελαργικὸν καλούμενον τὸ ὑπὸ τὴν ἀκρόπολιν, ὃ καὶ ἐπάρατόν τε ἦν μὴ οἰκεῖν καί τι καὶ Πυθικοῦ μαντείου ἀκροτελεύτιον τοιόνδε διεκώλυε, λέγον ὡς ‘τὸ Πελαργικὸν ἀργὸν ἄμεινον,’ ὅμως ὑπὸ τῆς παραχρῆμα ἀνάγκης ἐξῳκήθη. καί μοι δοκεῖ τὸ μαντεῖον τοὐναντίον ξυμβῆναι ἢ προσεδέχοντο· οὐ γὰρ διὰ τὴν παράνομον ἐνοίκησιν αἱ ξυμφοραὶ γενέσθαι τῇ πόλει, ἀλλὰ διὰ τὸν πόλεμον ἡ ἀνάγκη τῆς οἰκήσεως, ὃν οὐκ ὀνομάζον τὸ μαντεῖον προῄδει μὴ ἐπ’ ἀγαθῷ ποτὲ αὐτὸ κατοικισθησόμενον. κατεσκευάσαντο δὲ καὶ ἐν τοῖς πύργοις τῶν τειχῶν πολλοὶ καὶ ὡς ἕκαστός που ἐδύνατο· οὐ γὰρ ἐχώρησε ξυνελθόντας αὐτοὺς ἡ πόλις, ἀλλ’ ὕστερον δὴ τά τε μακρὰ τείχη ᾤκησαν κατανειμάμενοι καὶ τοῦ Πειραιῶς τὰ πολλά. ἅμα δὲ καὶ τῶν πρὸς τὸν πόλεμον ἥπτοντο, ξυμμάχους τε ἀγείροντες καὶ τῇ Πελοποννήσῳ ἑκατὸν νεῶν ἐπίπλουν ἐξαρτύοντες. καὶ οἱ μὲν ἐν τούτῳ παρασκευῆς ἦσαν.", "st": "2.17"}, {"sp": "N", "t": "ὁ δὲ στρατὸς τῶν Πελοποννησίων προϊὼν ἀφίκετο τῆς Ἀττικῆς ἐς Οἰνόην πρῶτον, ᾗπερ ἔμελλον ἐσβαλεῖν. καὶ ὡς ἐκαθέζοντο, προσβολὰς παρεσκευάζοντο τῷ τείχει ποιησόμενοι μηχαναῖς τε καὶ ἄλλῳ τρόπῳ· ἡ γὰρ Οἰνόη οὖσα ἐν μεθορίοις τῆς Ἀττικῆς καὶ Βοιωτίας ἐτετείχιστο, καὶ αὐτῷ φρουρίῳ οἱ Ἀθηναῖοι ἐχρῶντο ὁπότε πόλεμος καταλάβοι. τάς τε οὖν προσβολὰς ηὐτρεπίζοντο καὶ ἄλλως ἐνδιέτριψαν χρόνον περὶ αὐτήν. αἰτίαν τε οὐκ ἐλαχίστην Ἀρχίδαμος ἔλαβεν ἀπ’ αὐτοῦ, δοκῶν καὶ ἐν τῇ ξυναγωγῇ τοῦ πολέμου μαλακὸς εἶναι καὶ τοῖς Ἀθηναίοις ἐπιτήδειος, οὐ παραινῶν προθύμως πολεμεῖν· ἐπειδή τε ξυνελέγετο ὁ στρατός, ἥ τε ἐν τῷ Ἰσθμῷ ἐπιμονὴ γενομένη καὶ κατὰ τὴν ἄλλην πορείαν ἡ σχολαιότης διέβαλεν αὐτόν, μάλιστα δὲ ἡ ἐν τῇ Οἰνόῃ ἐπίσχεσις. οἱ γὰρ Ἀθηναῖοι ἐσεκομίζοντο ἐν τῷ χρόνῳ τούτῳ, καὶ ἐδόκουν οἱ Πελοποννήσιοι ἐπελθόντες ἂν διὰ τάχους πάντα ἔτι ἔξω καταλαβεῖν, εἰ μὴ διὰ τὴν ἐκείνου μέλλησιν. ἐν τοιαύτῃ μὲν ὀργῇ ὁ στρατὸς τὸν Ἀρχίδαμον ἐν τῇ καθέδρᾳ εἶχεν. ὁ δὲ προσδεχόμενος, ὡς λέγεται, τοὺς Ἀθηναίους τῆς γῆς ἔτι ἀκεραίου οὔσης ἐνδώσειν τι καὶ κατοκνήσειν περιιδεῖν αὐτὴν τμηθεῖσαν, ἀνεῖχεν.", "st": "2.18"}, {"sp": "N", "t": "ἐπειδὴ μέντοι προσβαλόντες τῇ Οἰνόῃ καὶ πᾶσαν ἰδέαν πειράσαντες οὐκ ἐδύναντο ἑλεῖν, οἵ τε Ἀθηναῖοι οὐδὲν ἐπεκηρυκεύοντο, οὕτω δὴ ὁρμήσαντες ἀπ’ αὐτῆς μετὰ τὰ ἐν Πλαταίᾳ [τῶν ἐσελθόντων Θηβαίων] γενόμενα ἡμέρᾳ ὀγδοηκοστῇ μάλιστα, θέρους καὶ τοῦ σίτου ἀκμάζοντος, ἐσέβαλον ἐς τὴν Ἀττικήν· ἡγεῖτο δὲ Ἀρχίδαμος ὁ Ζευξιδάμου, Λακεδαιμονίων βασιλεύς. καὶ καθεζόμενοι ἔτεμνον πρῶτον μὲν Ἐλευσῖνα καὶ τὸ Θριάσιον πεδίον καὶ τροπήν τινα τῶν Ἀθηναίων ἱππέων περὶ τοὺς Ῥείτους καλουμένους ἐποιήσαντο· ἔπειτα προυχώρουν ἐν δεξιᾷ ἔχοντες τὸ Αἰγάλεων ὄρος διὰ Κρωπιᾶς, ἕως ἀφίκοντο ἐς Ἀχαρνάς, χωρίον μέγιστον τῆς Ἀττικῆς τῶν δήμων καλουμένων, καὶ καθεζόμενοι ἐς αὐτὸ στρατόπεδόν τε ἐποιήσαντο χρόνον τε πολὺν ἐμμείναντες ἔτεμνον.", "st": "2.19"}, {"sp": "N", "t": "γνώμῃ δὲ τοιᾷδε λέγεται τὸν Ἀρχίδαμον περί τε τὰς Ἀχαρνὰς ὡς ἐς μάχην ταξάμενον μεῖναι καὶ ἐς τὸ πεδίον ἐκείνῃ τῇ ἐσβολῇ οὐ καταβῆναι· τοὺς γὰρ Ἀθηναίους ἤλπιζεν, ἀκμάζοντάς τε νεότητι πολλῇ καὶ παρεσκευασμένους ἐς πόλεμον ὡς οὔπω πρότερον, ἴσως ἂν ἐπεξελθεῖν καὶ τὴν γῆν οὐκ ἂν περιιδεῖν τμηθῆναι. ἐπειδὴ οὖν αὐτῷ ἐς Ἐλευσῖνα καὶ τὸ Θριάσιον πεδίον οὐκ ἀπήντησαν, πεῖραν ἐποιεῖτο περὶ τὰς Ἀχαρνὰς καθήμενος εἰ ἐπεξίασιν· ἅμα μὲν γὰρ αὐτῷ ὁ χῶρος ἐπιτήδειος ἐφαίνετο ἐνστρατοπεδεῦσαι, ἅμα δὲ καὶ οἱ Ἀχαρνῆς μέγα μέρος ὄντες τῆς πόλεως (τρισχίλιοι γὰρ ὁπλῖται ἐγένοντο) οὐ περιόψεσθαι ἐδόκουν τὰ σφέτερα διαφθαρέντα, ἀλλ’ ὁρμήσειν καὶ τοὺς πάντας ἐς μάχην. εἴ τε καὶ μὴ ἐπεξέλθοιεν ἐκείνῃ τῇ ἐσβολῇ οἱ Ἀθηναῖοι, ἀδεέστερον ἤδη ἐς τὸ ὕστερον τό τε πεδίον τεμεῖν καὶ πρὸς αὐτὴν τὴν πόλιν χωρήσεσθαι· τοὺς γὰρ Ἀχαρνέας ἐστερημένους τῶν σφετέρων οὐχ ὁμοίως προθύμους ἔσεσθαι ὑπὲρ τῆς τῶν ἄλλων κινδυνεύειν, στάσιν δ’ ἐνέσεσθαι τῇ γνώμῃ. τοιαύτῃ μὲν διανοίᾳ ὁ Ἀρχίδαμος περὶ τὰς Ἀχαρνὰς ἦν.", "st": "2.20"}, {"sp": "N", "t": "Ἀθηναῖοι δὲ μέχρι μὲν οὗ περὶ Ἐλευσῖνα καὶ τὸ Θριάσιον πεδίον ὁ στρατὸς ἦν, καί τινα ἐλπίδα εἶχον ἐς τὸ ἐγγυτέρω αὐτοὺς μὴ προϊέναι, μεμνημένοι καὶ Πλειστοάνακτα τὸν Παυσανίου Λακεδαιμονίων βασιλέα, ὅτε ἐσβαλὼν τῆς Ἀττικῆς ἐς Ἐλευσῖνα καὶ Θριῶζε στρατῷ Πελοποννησίων πρὸ τοῦδε τοῦ πολέμου τέσσαρσι καὶ δέκα ἔτεσιν ἀνεχώρησε πάλιν ἐς τὸ πλέον οὐκέτι προελθών (δι’ ὃ δὴ καὶ ἡ φυγὴ αὐτῷ ἐγένετο ἐκ Σπάρτης δόξαντι χρήμασι πεισθῆναι [τὴν ἀναχώρησιν])· ἐπειδὴ δὲ περὶ Ἀχαρνὰς εἶδον τὸν στρατὸν ἑξήκοντα σταδίους τῆς πόλεως ἀπέχοντα, οὐκέτι ἀνασχετὸν ἐποιοῦντο, ἀλλ’ αὐτοῖς, ὡς εἰκός, γῆς τεμνομένης ἐν τῷ ἐμφανεῖ, ὃ οὔπω ἑοράκεσαν οἵ γε νεώτεροι, οὐδ’ οἱ πρεσβύτεροι πλὴν τὰ Μηδικά, δεινὸν ἐφαίνετο καὶ ἐδόκει τοῖς τε ἄλλοις καὶ μάλιστα τῇ νεότητι ἐπεξιέναι καὶ μὴ περιορᾶν. κατὰ ξυστάσεις τε γιγνόμενοι ἐν πολλῇ ἔριδι ἦσαν, οἱ μὲν κελεύοντες ἐπεξιέναι, οἱ δέ τινες οὐκ ἐῶντες. χρησμολόγοι τε ᾖδον χρησμοὺς παντοίους, ὧν ἀκροᾶσθαι ὡς ἕκαστος ὥρμητο. οἵ τε Ἀχαρνῆς οἰόμενοι παρὰ σφίσιν αὐτοῖς οὐκ ἐλαχίστην μοῖραν εἶναι Ἀθηναίων, ὡς αὐτῶν ἡ γῆ ἐτέμνετο, ἐνῆγον τὴν ἔξοδον μάλιστα. παντί τε τρόπῳ ἀνηρέθιστο ἡ πόλις, καὶ τὸν Περικλέα ἐν ὀργῇ εἶχον, καὶ ὧν παρῄνεσε πρότερον ἐμέμνηντο οὐδέν, ἀλλ’ ἐκάκιζον ὅτι στρατηγὸς ὢν οὐκ ἐπεξάγοι, αἴτιόν τε σφίσιν ἐνόμιζον πάντων ὧν ἔπασχον.", "st": "2.21"}, {"sp": "N", "t": "Περικλῆς δὲ ὁρῶν μὲν αὐτοὺς πρὸς τὸ παρὸν χαλεπαίνοντας καὶ οὐ τὰ ἄριστα φρονοῦντας, πιστεύων δὲ ὀρθῶς γιγνώσκειν περὶ τοῦ μὴ ἐπεξιέναι, ἐκκλησίαν τε οὐκ ἐποίει αὐτῶν οὐδὲ ξύλλογον οὐδένα, τοῦ μὴ ὀργῇ τι μᾶλλον ἢ γνώμῃ ξυνελθόντας ἐξαμαρτεῖν, τήν τε πόλιν ἐφύλασσε καὶ δι’ ἡσυχίας μάλιστα ὅσον ἐδύνατο εἶχεν. ἱππέας μέντοι ἐξέπεμπεν αἰεὶ τοῦ μὴ προδρόμους ἀπὸ τῆς στρατιᾶς ἐσπίπτοντας ἐς τοὺς ἀγροὺς τοὺς ἐγγὺς τῆς πόλεως κακουργεῖν· καὶ ἱππομαχία τις ἐγένετο βραχεῖα ἐν Φρυγίοις τῶν τε Ἀθηναίων τέλει ἑνὶ τῶν ἱππέων καὶ Θεσσαλοῖς μετ’ αὐτῶν πρὸς τοὺς Βοιωτῶν ἱππέας, ἐν ᾗ οὐκ ἔλασσον ἔσχον οἱ Ἀθηναῖοι καὶ Θεσσαλοί, μέχρι οὗ προσβοηθησάντων τοῖς Βοιωτοῖς τῶν ὁπλιτῶν τροπὴ ἐγένετο αὐτῶν καὶ ἀπέθανον τῶν Θεσσαλῶν καὶ Ἀθηναίων οὐ πολλοί· ἀνείλοντο μέντοι αὐτοὺς αὐθημερὸν ἀσπόνδους. καὶ οἱ Πελοποννήσιοι τροπαῖον τῇ ὑστεραίᾳ ἔστησαν. ἡ δὲ βοήθεια αὕτη τῶν Θεσσαλῶν κατὰ τὸ παλαιὸν ξυμμαχικὸν ἐγένετο τοῖς Ἀθηναίοις, καὶ ἀφίκοντο παρ’ αὐτοὺς Λαρισαῖοι, Φαρσάλιοι, [Παράσιοι], Κραννώνιοι, Πυράσιοι, Γυρτώνιοι, Φεραῖοι. ἡγοῦντο δὲ αὐτῶν ἐκ μὲν Λαρίσης Πολυμήδης καὶ Ἀριστόνους, ἀπὸ τῆς στάσεως ἑκάτερος, ἐκ δὲ Φαρσάλου Μένων· ἦσαν δὲ καὶ τῶν ἄλλων κατὰ πόλεις ἄρχοντες.", "st": "2.22"}, {"sp": "N", "t": "οἱ δὲ Πελοποννήσιοι, ἐπειδὴ οὐκ ἐπεξῇσαν αὐτοῖς οἱ Ἀθηναῖοι ἐς μάχην, ἄραντες ἐκ τῶν Ἀχαρνῶν ἐδῄουν τῶν δήμων τινὰς ἄλλους τῶν μεταξὺ Πάρνηθος καὶ Βριλησσοῦ ὄρους. ὄντων δὲ αὐτῶν ἐν τῇ γῇ οἱ Ἀθηναῖοι ἀπέστειλαν τὰς ἑκατὸν ναῦς περὶ Πελοπόννησον ἅσπερ παρεσκευάζοντο καὶ χιλίους ὁπλίτας ἐπ’ αὐτῶν καὶ τοξότας τετρακοσίους· ἐστρατήγει δὲ Καρκίνος τε ὁ Ξενοτίμου καὶ Πρωτέας ὁ Ἐπικλέους καὶ Σωκράτης ὁ Ἀντιγένους. καὶ οἱ μὲν ἄραντες τῇ παρασκευῇ ταύτῃ περιέπλεον, οἱ δὲ Πελοποννήσιοι χρόνον ἐμμείναντες ἐν τῇ Ἀττικῇ ὅσου εἶχον τὰ ἐπιτήδεια ἀνεχώρησαν διὰ Βοιωτῶν, οὐχ ᾗπερ ἐσέβαλον· παριόντες δὲ Ὠρωπὸν τὴν γῆν τὴν Γραϊκὴν καλουμένην, ἣν νέμονται Ὠρώπιοι Ἀθηναίων ὑπήκοοι, ἐδῄωσαν. ἀφικόμενοι δὲ ἐς Πελοπόννησον διελύθησαν κατὰ πόλεις ἕκαστοι.", "st": "2.23"}, {"sp": "N", "t": "ἀναχωρησάντων δὲ αὐτῶν οἱ Ἀθηναῖοι φυλακὰς κατεστήσαντο κατὰ γῆν καὶ κατὰ θάλασσαν, ὥσπερ δὴ ἔμελλον διὰ παντὸς τοῦ πολέμου φυλάξειν· καὶ χίλια τάλαντα ἀπὸ τῶν ἐν τῇ ἀκροπόλει χρημάτων ἔδοξεν αὐτοῖς ἐξαίρετα ποιησαμένοις χωρὶς θέσθαι καὶ μὴ ἀναλοῦν, ἀλλ’ ἀπὸ τῶν ἄλλων πολεμεῖν· ἢν δέ τις εἴπῃ ἢ ἐπιψηφίσῃ κινεῖν τὰ χρήματα ταῦτα ἐς ἄλλο τι, ἢν μὴ οἱ πολέμιοι νηίτῃ στρατῷ ἐπιπλέωσι τῇ πόλει καὶ δέῃ ἀμύνασθαι, θάνατον ζημίαν ἐπέθεντο. τριήρεις τε μετ’ αὐτῶν ἐξαιρέτους ἑκατὸν ἐποιήσαντο κατὰ τὸν ἐνιαυτὸν ἕκαστον τὰς βελτίστας, καὶ τριηράρχους αὐταῖς, ὧν μὴ χρῆσθαι μηδεμιᾷ ἐς ἄλλο τι ἢ μετὰ τῶν χρημάτων περὶ τοῦ αὐτοῦ κινδύνου, ἢν δέῃ.", "st": "2.24"}, {"sp": "N", "t": "οἱ δ’ ἐν ταῖς ἑκατὸν ναυσὶ περὶ Πελοπόννησον Ἀθηναῖοι καὶ Κερκυραῖοι μετ’ αὐτῶν πεντήκοντα ναυσὶ προσβεβοηθηκότες καὶ ἄλλοι τινὲς τῶν ἐκεῖ ξυμμάχων ἄλλα τε ἐκάκουν περιπλέοντες καὶ ἐς Μεθώνην τῆς Λακωνικῆς ἀποβάντες τῷ τείχει προσέβαλον ὄντι ἀσθενεῖ καὶ ἀνθρώπων οὐκ ἐνόντων. ἔτυχε δὲ περὶ τοὺς χώρους τούτους Βρασίδας ὁ Τέλλιδος ἀνὴρ Σπαρτιάτης φρουρὰν ἔχων, καὶ αἰσθόμενος ἐβοήθει τοῖς ἐν τῷ χωρίῳ μετὰ ὁπλιτῶν ἑκατόν. διαδραμὼν δὲ τὸ τῶν Ἀθηναίων στρατόπεδον ἐσκεδασμένον κατὰ τὴν χώραν καὶ πρὸς τὸ τεῖχος τετραμμένον ἐσπίπτει ἐς τὴν Μεθώνην καὶ ὀλίγους τινὰς ἐν τῇ ἐσδρομῇ ἀπολέσας τῶν μεθ’ αὑτοῦ τήν τε πόλιν περιεποίησε καὶ ἀπὸ τούτου τοῦ τολμήματος πρῶτος τῶν κατὰ τὸν πόλεμον ἐπῃνέθη ἐν Σπάρτῃ. οἱ δὲ Ἀθηναῖοι ἄραντες παρέπλεον, καὶ σχόντες τῆς Ἠλείας ἐς Φειὰν ἐδῄουν τὴν γῆν ἐπὶ δύο ἡμέρας καὶ προσβοηθήσαντας τῶν ἐκ τῆς κοίλης Ἤλιδος τριακοσίους λογάδας καὶ τῶν αὐτόθεν ἐκ τῆς περιοικίδος Ἠλείων μάχῃ ἐκράτησαν. ἀνέμου δὲ κατιόντος μεγάλου χειμαζόμενοι ἐν ἀλιμένῳ χωρίῳ, οἱ μὲν πολλοὶ ἐπέβησαν ἐπὶ τὰς ναῦς καὶ περιέπλεον τὸν Ἰχθῦν καλούμενον τὴν ἄκραν ἐς τὸν ἐν τῇ Φειᾷ λιμένα, οἱ δὲ Μεσσήνιοι ἐν τούτῳ καὶ ἄλλοι τινὲς οἱ οὐ δυνάμενοι ἐπιβῆναι κατὰ γῆν χωρήσαντες τὴν Φειὰν αἱροῦσιν. καὶ ὕστερον αἵ τε νῆες περιπλεύσασαι ἀναλαμβάνουσιν αὐτοὺς καὶ ἐξανάγονται ἐκλιπόντες Φειάν, καὶ τῶν Ἠλείων ἡ πολλὴ ἤδη στρατιὰ προσεβεβοηθήκει. παραπλεύσαντες δὲ οἱ Ἀθηναῖοι ἐπὶ ἄλλα χωρία ἐδῄουν.", "st": "2.25"}, {"sp": "N", "t": "ὑπὸ δὲ τὸν αὐτὸν χρόνον τοῦτον Ἀθηναῖοι τριάκοντα ναῦς ἐξέπεμψαν περὶ τὴν Λοκρίδα καὶ Εὐβοίας ἅμα φυλακήν· ἐστρατήγει δὲ αὐτῶν Κλεόπομπος ὁ Κλεινίου. καὶ ἀποβάσεις ποιησάμενος τῆς τε παραθαλασσίου ἔστιν ἃ ἐδῄωσε καὶ Θρόνιον εἷλεν, ὁμήρους τε ἔλαβεν αὐτῶν, καὶ ἐν Ἀλόπῃ τοὺς βοηθήσαντας Λοκρῶν μάχῃ ἐκράτησεν.", "st": "2.26"}, {"sp": "N", "t": "ἀνέστησαν δὲ καὶ Αἰγινήτας τῷ αὐτῷ θέρει τούτῳ ἐξ Αἰγίνης Ἀθηναῖοι, αὐτούς τε καὶ παῖδας καὶ γυναῖκας, ἐπικαλέσαντες οὐχ ἥκιστα τοῦ πολέμου σφίσιν αἰτίους εἶναι· καὶ τὴν Αἴγιναν ἀσφαλέστερον ἐφαίνετο τῇ Πελοποννήσῳ ἐπικειμένην αὑτῶν πέμψαντας ἐποίκους ἔχειν. καὶ ἐξέπεμψαν ὕστερον οὐ πολλῷ ἐς αὐτὴν τοὺς οἰκήτορας. ἐκπεσοῦσι δὲ τοῖς Αἰγινήταις οἱ Λακεδαιμόνιοι ἔδοσαν Θυρέαν οἰκεῖν καὶ τὴν γῆν νέμεσθαι, κατά τε τὸ Ἀθηναίων διάφορον καὶ ὅτι σφῶν εὐεργέται ἦσαν ὑπὸ τὸν σεισμὸν καὶ τῶν Εἱλώτων τὴν ἐπανάστασιν. ἡ δὲ Θυρεᾶτις γῆ μεθορία τῆς Ἀργείας καὶ Λακωνικῆς ἐστίν, ἐπὶ θάλασσαν καθήκουσα. καὶ οἱ μὲν αὐτῶν ἐνταῦθα ᾤκησαν, οἱ δ’ ἐσπάρησαν κατὰ τὴν ἄλλην Ἑλλάδα.", "st": "2.27"}, {"sp": "N", "t": "τοῦ δ’ αὐτοῦ θέρους νουμηνίᾳ κατὰ σελήνην, ὥσπερ καὶ μόνον δοκεῖ εἶναι γίγνεσθαι δυνατόν, ὁ ἥλιος ἐξέλιπε μετὰ μεσημβρίαν καὶ πάλιν ἀνεπληρώθη, γενόμενος μηνοειδὴς καὶ ἀστέρων τινῶν ἐκφανέντων.", "st": "2.28"}, {"sp": "N", "t": "καὶ ἐν τῷ αὐτῷ θέρει Νυμφόδωρον τὸν Πύθεω ἄνδρα Ἀβδηρίτην, οὗ εἶχε τὴν ἀδελφὴν Σιτάλκης, δυνάμενον παρ’ αὐτῷ μέγα οἱ Ἀθηναῖοι πρότερον πολέμιον νομίζοντες πρόξενον ἐποιήσαντο καὶ μετεπέμψαντο, βουλόμενοι Σιτάλκην σφίσι τὸν Τήρεω, Θρᾳκῶν βασιλέα, ξύμμαχον γενέσθαι. ὁ δὲ Τήρης οὗτος ὁ τοῦ Σιτάλκου πατὴρ πρῶτος Ὀδρύσαις τὴν μεγάλην βασιλείαν ἐπὶ πλέον τῆς ἄλλης Θρᾴκης ἐποίησεν· πολὺ γὰρ μέρος καὶ αὐτόνομόν ἐστι Θρᾳκῶν. Τηρεῖ δὲ τῷ Πρόκνην τὴν Πανδίονος ἀπ’ Ἀθηνῶν σχόντι γυναῖκα προσήκει ὁ Τήρης οὗτος οὐδέν, οὐδὲ τῆς αὐτῆς Θρᾴκης ἐγένοντο, ἀλλ’ ὁ μὲν ἐν Δαυλίᾳ τῆς Φωκίδος νῦν καλουμένης γῆς [ὁ Τηρεὺς] ᾤκει, τότε ὑπὸ Θρᾳκῶν οἰκουμένης, καὶ τὸ ἔργον τὸ περὶ τὸν Ἴτυν αἱ γυναῖκες ἐν τῇ γῇ ταύτῃ ἔπραξαν (πολλοῖς δὲ καὶ τῶν ποιητῶν ἐν ἀηδόνος μνήμῃ Δαυλιὰς ἡ ὄρνις ἐπωνόμασται), εἰκός τε καὶ τὸ κῆδος Πανδίονα ξυνάψασθαι τῆς θυγατρὸς διὰ τοσούτου ἐπ’ ὠφελίᾳ τῇ πρὸς ἀλλήλους μᾶλλον ἢ διὰ πολλῶν ἡμερῶν ἐς Ὀδρύσας ὁδοῦ. Τήρης δὲ οὐδὲ τὸ αὐτὸ ὄνομα ἔχων βασιλεύς [τε] πρῶτος ἐν κράτει Ὀδρυσῶν ἐγένετο. οὗ δὴ ὄντα τὸν Σιτάλκην οἱ Ἀθηναῖοι ξύμμαχον ἐποιοῦντο, βουλόμενοι σφίσι τὰ ἐπὶ Θρᾴκης χωρία καὶ Περδίκκαν ξυνεξελεῖν αὐτόν. ἐλθών τε ἐς τὰς Ἀθήνας ὁ Νυμφόδωρος τήν τε τοῦ Σιτάλκου ξυμμαχίαν ἐποίησε καὶ Σάδοκον τὸν υἱὸν αὐτοῦ Ἀθηναῖον τόν τε ἐπὶ Θρᾴκης πόλεμον ὑπεδέχετο καταλύσειν· πείσειν γὰρ Σιτάλκην πέμπειν στρατιὰν Θρᾳκίαν Ἀθηναίοις ἱππέων τε καὶ πελταστῶν. ξυνεβίβασε δὲ καὶ τὸν Περδίκκαν τοῖς Ἀθηναίοις καὶ Θέρμην αὐτῷ ἔπεισεν ἀποδοῦναι· ξυνεστράτευσέ τε εὐθὺς Περδίκκας ἐπὶ Χαλκιδέας μετὰ Ἀθηναίων καὶ Φορμίωνος. οὕτω μὲν Σιτάλκης τε ὁ Τήρεω Θρᾳκῶν βασιλεὺς ξύμμαχος ἐγένετο Ἀθηναίοις καὶ Περδίκκας ὁ Ἀλεξάνδρου Μακεδόνων βασιλεύς.", "st": "2.29"}, {"sp": "N", "t": "οἱ δ’ ἐν ταῖς ἑκατὸν ναυσὶν Ἀθηναῖοι ἔτι ὄντες περὶ Πελοπόννησον Σόλλιόν τε Κορινθίων πόλισμα αἱροῦσι καὶ παραδιδόασι Παλαιρεῦσιν Ἀκαρνάνων μόνοις τὴν γῆν καὶ πόλιν νέμεσθαι· καὶ Ἀστακόν, ἧς Εὔαρχος ἐτυράννει, λαβόντες κατὰ κράτος καὶ ἐξελάσαντες αὐτὸν τὸ χωρίον ἐς τὴν ξυμμαχίαν προσεποιήσαντο. ἐπί τε Κεφαλληνίαν τὴν νῆσον προσπλεύσαντες προσηγάγοντο ἄνευ μάχης· κεῖται δὲ ἡ Κεφαλληνία κατὰ Ἀκαρνανίαν καὶ Λευκάδα τετράπολις οὖσα, Παλῆς, Κράνιοι, Σαμαῖοι, Προνναῖοι. ὕστερον δ’ οὐ πολλῷ ἀνεχώρησαν αἱ νῆες ἐς τὰς Ἀθήνας.", "st": "2.30"}, {"sp": "N", "t": "περὶ δὲ τὸ φθινόπωρον τοῦ θέρους τούτου Ἀθηναῖοι πανδημεί, αὐτοὶ καὶ οἱ μέτοικοι, ἐσέβαλον ἐς τὴν Μεγαρίδα Περικλέους τοῦ Ξανθίππου στρατηγοῦντος. καὶ οἱ περὶ Πελοπόννησον Ἀθηναῖοι ἐν ταῖς ἑκατὸν ναυσίν (ἔτυχον γὰρ ἤδη ἐν Αἰγίνῃ ὄντες ἐπ’ οἴκου ἀνακομιζόμενοι) ὡς ᾔσθοντο τοὺς ἐκ τῆς πόλεως πανστρατιᾷ ἐν Μεγάροις ὄντας, ἔπλευσαν παρ’ αὐτοὺς καὶ ξυνεμείχθησαν. στρατόπεδόν τε μέγιστον δὴ τοῦτο ἁθρόον Ἀθηναίων ἐγένετο, ἀκμαζούσης ἔτι τῆς πόλεως καὶ οὔπω νενοσηκυίας· μυρίων γὰρ ὁπλιτῶν οὐκ ἐλάσσους ἦσαν αὐτοὶ Ἀθηναῖοι (χωρὶς δὲ αὐτοῖς οἱ ἐν Ποτειδαίᾳ τρισχίλιοι ἦσαν), μέτοικοι δὲ ξυνεσέβαλον οὐκ ἐλάσσους τρισχιλίων ὁπλιτῶν, χωρὶς δὲ ὁ ἄλλος ὅμιλος ψιλῶν οὐκ ὀλίγος. δῃώσαντες δὲ τὰ πολλὰ τῆς γῆς ἀνεχώρησαν. ἐγένοντο δὲ καὶ ἄλλαι ὕστερον ἐν τῷ πολέμῳ κατὰ ἔτος ἕκαστον ἐσβολαὶ Ἀθηναίων ἐς τὴν Μεγαρίδα καὶ ἱππέων καὶ πανστρατιᾷ, μέχρι οὗ Νίσαια ἑάλω ὑπ’ Ἀθηναίων.", "st": "2.31"}, {"sp": "N", "t": "ἐτειχίσθη δὲ καὶ Ἀταλάντη ὑπὸ Ἀθηναίων φρούριον τοῦ θέρους τούτου τελευτῶντος, ἡ ἐπὶ Λοκροῖς τοῖς Ὀπουντίοις νῆσος ἐρήμη πρότερον οὖσα, τοῦ μὴ λῃστὰς ἐκπλέοντας ἐξ Ὀποῦντος καὶ τῆς ἄλλης Λοκρίδος κακουργεῖν τὴν Εὔβοιαν.", "st": "2.32"}, {"sp": "N", "t": "ταῦτα μὲν ἐν τῷ θέρει τούτῳ μετὰ τὴν Πελοποννησίων ἐκ τῆς Ἀττικῆς ἀναχώρησιν ἐγένετο.", "st": "2.32"}, {"sp": "N", "t": "τοῦ δ’ ἐπιγιγνομένου χειμῶνος Εὔαρχος ὁ Ἀκαρνὰν βουλόμενος ἐς τὴν Ἀστακὸν κατελθεῖν πείθει Κορινθίους τεσσαράκοντα ναυσὶ καὶ πεντακοσίοις καὶ χιλίοις ὁπλίταις ἑαυτὸν κατάγειν πλεύσαντας, καὶ αὐτὸς ἐπικούρους τινὰς προσεμισθώσατο· ἦρχον δὲ τῆς στρατιᾶς Εὐφαμίδας τε ὁ Ἀριστωνύμου καὶ Τιμόξενος ὁ Τιμοκράτους καὶ Εὔμαχος ὁ Χρύσιδος. καὶ πλεύσαντες κατήγαγον· καὶ τῆς ἄλλης Ἀκαρνανίας τῆς περὶ θάλασσαν ἔστιν ἃ χωρία βουλόμενοι προσποιήσασθαι καὶ πειραθέντες, ὡς οὐκ ἐδύναντο, ἀπέπλεον ἐπ’ οἴκου. σχόντες δ’ ἐν τῷ παράπλῳ ἐς Κεφαλληνίαν καὶ ἀπόβασιν ποιησάμενοι ἐς τὴν Κρανίων γῆν, ἀπατηθέντες ὑπ’ αὐτῶν ἐξ ὁμολογίας τινὸς ἄνδρας τε ἀποβάλλουσι σφῶν αὐτῶν, ἐπιθεμένων ἀπροσδοκήτοις τῶν Κρανίων, καὶ βιαιότερον ἀναγαγόμενοι ἐκομίσθησαν ἐπ’ οἴκου.", "st": "2.33"}, {"sp": "N", "t": "ἐν δὲ τῷ αὐτῷ χειμῶνι Ἀθηναῖοι τῷ πατρίῳ νόμῳ χρώμενοι δημοσίᾳ ταφὰς ἐποιήσαντο τῶν ἐν τῷδε τῷ πολέμῳ πρώτων ἀποθανόντων τρόπῳ τοιῷδε. τὰ μὲν ὀστᾶ προτίθενται τῶν ἀπογενομένων πρότριτα σκηνὴν ποιήσαντες, καὶ ἐπιφέρει τῷ αὑτοῦ ἕκαστος ἤν τι βούληται· ἐπειδὰν δὲ ἡ ἐκφορὰ ᾖ, λάρνακας κυπαρισσίνας ἄγουσιν ἅμαξαι, φυλῆς ἑκάστης μίαν· ἔνεστι δὲ τὰ ὀστᾶ ἧς ἕκαστος ἦν φυλῆς. μία δὲ κλίνη κενὴ φέρεται ἐστρωμένη τῶν ἀφανῶν, οἳ ἂν μὴ εὑρεθῶσιν ἐς ἀναίρεσιν. ξυνεκφέρει δὲ ὁ βουλόμενος καὶ ἀστῶν καὶ ξένων, καὶ γυναῖκες πάρεισιν αἱ προσήκουσαι ἐπὶ τὸν τάφον ὀλοφυρόμεναι. τιθέασιν οὖν ἐς τὸ δημόσιον σῆμα, ὅ ἐστιν ἐπὶ τοῦ καλλίστου προαστείου τῆς πόλεως, καὶ αἰεὶ ἐν αὐτῷ θάπτουσι τοὺς ἐκ τῶν πολέμων, πλήν γε τοὺς ἐν Μαραθῶνι· ἐκείνων δὲ διαπρεπῆ τὴν ἀρετὴν κρίναντες αὐτοῦ καὶ τὸν τάφον ἐποίησαν. ἐπειδὰν δὲ κρύψωσι γῇ, ἀνὴρ ᾑρημένος ὑπὸ τῆς πόλεως, ὃς ἂν γνώμῃ τε δοκῇ μὴ ἀξύνετος εἶναι καὶ ἀξιώσει προήκῃ, λέγει ἐπ’ αὐτοῖς ἔπαινον τὸν πρέποντα· μετὰ δὲ τοῦτο ἀπέρχονται. ὧδε μὲν θάπτουσιν· καὶ διὰ παντὸς τοῦ πολέμου, ὁπότε ξυμβαίη αὐτοῖς, ἐχρῶντο τῷ νόμῳ. ἐπὶ δ’ οὖν τοῖς πρώτοις τοῖσδε Περικλῆς ὁ Ξανθίππου ᾑρέθη λέγειν. καὶ ἐπειδὴ καιρὸς ἐλάμβανε, προελθὼν ἀπὸ τοῦ σήματος ἐπὶ βῆμα ὑψηλὸν πεποιημένον, ὅπως ἀκούοιτο ὡς ἐπὶ πλεῖστον τοῦ ὁμίλου, ἔλεγε τοιάδε.", "st": "2.34"}, {"sp": "N", "t": "‘οἱ μὲν πολλοὶ τῶν ἐνθάδε ἤδη εἰρηκότων ἐπαινοῦσι τὸν προσθέντα τῷ νόμῳ τὸν λόγον τόνδε, ὡς καλὸν ἐπὶ τοῖς ἐκ τῶν πολέμων θαπτομένοις ἀγορεύεσθαι αὐτόν. ἐμοὶ δὲ ἀρκοῦν ἂν ἐδόκει εἶναι ἀνδρῶν ἀγαθῶν ἔργῳ γενομένων ἔργῳ καὶ δηλοῦσθαι τὰς τιμάς, οἷα καὶ νῦν περὶ τὸν τάφον τόνδε δημοσίᾳ παρασκευασθέντα ὁρᾶτε, καὶ μὴ ἐν ἑνὶ ἀνδρὶ πολλῶν ἀρετὰς κινδυνεύεσθαι εὖ τε καὶ χεῖρον εἰπόντι πιστευθῆναι. χαλεπὸν γὰρ τὸ μετρίως εἰπεῖν ἐν ᾧ μόλις καὶ ἡ δόκησις τῆς ἀληθείας βεβαιοῦται. ὅ τε γὰρ ξυνειδὼς καὶ εὔνους ἀκροατὴς τάχ’ ἄν τι ἐνδεεστέρως πρὸς ἃ βούλεταί τε καὶ ἐπίσταται νομίσειε δηλοῦσθαι, ὅ τε ἄπειρος ἔστιν ἃ καὶ πλεονάζεσθαι, διὰ φθόνον, εἴ τι ὑπὲρ τὴν αὑτοῦ φύσιν ἀκούοι. μέχρι γὰρ τοῦδε ἀνεκτοὶ οἱ ἔπαινοί εἰσι περὶ ἑτέρων λεγόμενοι, ἐς ὅσον ἂν καὶ αὐτὸς ἕκαστος οἴηται ἱκανὸς εἶναι δρᾶσαί τι ὧν ἤκουσεν· τῷ δὲ ὑπερβάλλοντι αὐτῶν φθονοῦντες ἤδη καὶ ἀπιστοῦσιν. ἐπειδὴ δὲ τοῖς πάλαι οὕτως ἐδοκιμάσθη ταῦτα καλῶς ἔχειν, χρὴ καὶ ἐμὲ ἑπόμενον τῷ νόμῳ πειρᾶσθαι ὑμῶν τῆς ἑκάστου βουλήσεώς τε καὶ δόξης τυχεῖν ὡς ἐπὶ πλεῖστον.", "st": "2.35"}, {"sp": "N", "t": "‘ἄρξομαι δὲ ἀπὸ τῶν προγόνων πρῶτον· δίκαιον γὰρ αὐτοῖς καὶ πρέπον δὲ ἅμα ἐν τῷ τοιῷδε τὴν τιμὴν ταύτην τῆς μνήμης δίδοσθαι. τὴν γὰρ χώραν οἱ αὐτοὶ αἰεὶ οἰκοῦντες διαδοχῇ τῶν ἐπιγιγνομένων μέχρι τοῦδε ἐλευθέραν δι’ ἀρετὴν παρέδοσαν. καὶ ἐκεῖνοί τε ἄξιοι ἐπαίνου καὶ ἔτι μᾶλλον οἱ πατέρες ἡμῶν· κτησάμενοι γὰρ πρὸς οἷς ἐδέξαντο ὅσην ἔχομεν ἀρχὴν οὐκ ἀπόνως ἡμῖν τοῖς νῦν προσκατέλιπον. τὰ δὲ πλείω αὐτῆς αὐτοὶ ἡμεῖς οἵδε οἱ νῦν ἔτι ὄντες μάλιστα ἐν τῇ καθεστηκυίᾳ ἡλικίᾳ ἐπηυξήσαμεν καὶ τὴν πόλιν τοῖς πᾶσι παρεσκευάσαμεν καὶ ἐς πόλεμον καὶ ἐς εἰρήνην αὐταρκεστάτην. ὧν ἐγὼ τὰ μὲν κατὰ πολέμους ἔργα, οἷς ἕκαστα ἐκτήθη, ἢ εἴ τι αὐτοὶ ἢ οἱ πατέρες ἡμῶν βάρβαρον ἢ Ἕλληνα πολέμιον ἐπιόντα προθύμως ἠμυνάμεθα, μακρηγορεῖν ἐν εἰδόσιν οὐ βουλόμενος ἐάσω· ἀπὸ δὲ οἵας τε ἐπιτηδεύσεως ἤλθομεν ἐπ’ αὐτὰ καὶ μεθ’ οἵας πολιτείας καὶ τρόπων ἐξ οἵων μεγάλα ἐγένετο, ταῦτα δηλώσας πρῶτον εἶμι καὶ ἐπὶ τὸν τῶνδε ἔπαινον, νομίζων ἐπί τε τῷ παρόντι οὐκ ἂν ἀπρεπῆ λεχθῆναι αὐτὰ καὶ τὸν πάντα ὅμιλον καὶ ἀστῶν καὶ ξένων ξύμφορον εἶναι ἐπακοῦσαι αὐτῶν.", "st": "2.36"}, {"sp": "N", "t": "‘χρώμεθα γὰρ πολιτείᾳ οὐ ζηλούσῃ τοὺς τῶν πέλας νόμους, παράδειγμα δὲ μᾶλλον αὐτοὶ ὄντες τισὶν ἢ μιμούμενοι ἑτέρους. καὶ ὄνομα μὲν διὰ τὸ μὴ ἐς ὀλίγους ἀλλ’ ἐς πλείονας οἰκεῖν δημοκρατία κέκληται· μέτεστι δὲ κατὰ μὲν τοὺς νόμους πρὸς τὰ ἴδια διάφορα πᾶσι τὸ ἴσον, κατὰ δὲ τὴν ἀξίωσιν, ὡς ἕκαστος ἔν τῳ εὐδοκιμεῖ, οὐκ ἀπὸ μέρους τὸ πλέον ἐς τὰ κοινὰ ἢ ἀπ’ ἀρετῆς προτιμᾶται, οὐδ’ αὖ κατὰ πενίαν, ἔχων γέ τι ἀγαθὸν δρᾶσαι τὴν πόλιν, ἀξιώματος ἀφανείᾳ κεκώλυται. ἐλευθέρως δὲ τά τε πρὸς τὸ κοινὸν πολιτεύομεν καὶ ἐς τὴν πρὸς ἀλλήλους τῶν καθ’ ἡμέραν ἐπιτηδευμάτων ὑποψίαν, οὐ δι’ ὀργῆς τὸν πέλας, εἰ καθ’ ἡδονήν τι δρᾷ, ἔχοντες, οὐδὲ ἀζημίους μέν, λυπηρὰς δὲ τῇ ὄψει ἀχθηδόνας προστιθέμενοι. ἀνεπαχθῶς δὲ τὰ ἴδια προσομιλοῦντες τὰ δημόσια διὰ δέος μάλιστα οὐ παρανομοῦμεν, τῶν τε αἰεὶ ἐν ἀρχῇ ὄντων ἀκροάσει καὶ τῶν νόμων, καὶ μάλιστα αὐτῶν ὅσοι τε ἐπ’ ὠφελίᾳ τῶν ἀδικουμένων κεῖνται καὶ ὅσοι ἄγραφοι ὄντες αἰσχύνην ὁμολογουμένην φέρουσιν.", "st": "2.37"}, {"sp": "N", "t": "‘καὶ μὴν καὶ τῶν πόνων πλείστας ἀναπαύλας τῇ γνώμῃ ἐπορισάμεθα, ἀγῶσι μέν γε καὶ θυσίαις διετησίοις νομίζοντες, ἰδίαις δὲ κατασκευαῖς εὐπρεπέσιν, ὧν καθ’ ἡμέραν ἡ τέρψις τὸ λυπηρὸν ἐκπλήσσει. ἐπεσέρχεται δὲ διὰ μέγεθος τῆς πόλεως ἐκ πάσης γῆς τὰ πάντα, καὶ ξυμβαίνει ἡμῖν μηδὲν οἰκειοτέρᾳ τῇ ἀπολαύσει τὰ αὐτοῦ ἀγαθὰ γιγνόμενα καρποῦσθαι ἢ καὶ τὰ τῶν ἄλλων ἀνθρώπων.", "st": "2.38"}, {"sp": "N", "t": "‘διαφέρομεν δὲ καὶ ταῖς τῶν πολεμικῶν μελέταις τῶν ἐναντίων τοῖσδε. τήν τε γὰρ πόλιν κοινὴν παρέχομεν, καὶ οὐκ ἔστιν ὅτε ξενηλασίαις ἀπείργομέν τινα ἢ μαθήματος ἢ θεάματος, ὃ μὴ κρυφθὲν ἄν τις τῶν πολεμίων ἰδὼν ὠφεληθείη, πιστεύοντες οὐ ταῖς παρασκευαῖς τὸ πλέον καὶ ἀπάταις ἢ τῷ ἀφ’ ἡμῶν αὐτῶν ἐς τὰ ἔργα εὐψύχῳ· καὶ ἐν ταῖς παιδείαις οἱ μὲν ἐπιπόνῳ ἀσκήσει εὐθὺς νέοι ὄντες τὸ ἀνδρεῖον μετέρχονται, ἡμεῖς δὲ ἀνειμένως διαιτώμενοι οὐδὲν ἧσσον ἐπὶ τοὺς ἰσοπαλεῖς κινδύνους χωροῦμεν. τεκμήριον δέ· οὔτε γὰρ Λακεδαιμόνιοι καθ’ ἑαυτούς, μεθ’ ἁπάντων δὲ ἐς τὴν γῆν ἡμῶν στρατεύουσι, τήν τε τῶν πέλας αὐτοὶ ἐπελθόντες οὐ χαλεπῶς ἐν τῇ ἀλλοτρίᾳ τοὺς περὶ τῶν οἰκείων ἀμυνομένους μαχόμενοι τὰ πλείω κρατοῦμεν. ἁθρόᾳ τε τῇ δυνάμει ἡμῶν οὐδείς πω πολέμιος ἐνέτυχε διὰ τὴν τοῦ ναυτικοῦ τε ἅμα ἐπιμέλειαν καὶ τὴν ἐν τῇ γῇ ἐπὶ πολλὰ ἡμῶν αὐτῶν ἐπίπεμψιν· ἢν δέ που μορίῳ τινὶ προσμείξωσι, κρατήσαντές τέ τινας ἡμῶν πάντας αὐχοῦσιν ἀπεῶσθαι καὶ νικηθέντες ὑφ’ ἁπάντων ἡσσῆσθαι. καίτοι εἰ ῥᾳθυμίᾳ μᾶλλον ἢ πόνων μελέτῃ καὶ μὴ μετὰ νόμων τὸ πλέον ἢ τρόπων ἀνδρείας ἐθέλομεν κινδυνεύειν, περιγίγνεται ἡμῖν τοῖς τε μέλλουσιν ἀλγεινοῖς μὴ προκάμνειν, καὶ ἐς αὐτὰ ἐλθοῦσι μὴ ἀτολμοτέρους τῶν αἰεὶ μοχθούντων φαίνεσθαι, καὶ ἔν τε τούτοις τὴν πόλιν ἀξίαν εἶναι θαυμάζεσθαι καὶ ἔτι ἐν ἄλλοις.", "st": "2.39"}, {"sp": "N", "t": "‘φιλοκαλοῦμέν τε γὰρ μετ’ εὐτελείας καὶ φιλοσοφοῦμεν ἄνευ μαλακίας· πλούτῳ τε ἔργου μᾶλλον καιρῷ ἢ λόγου κόμπῳ χρώμεθα, καὶ τὸ πένεσθαι οὐχ ὁμολογεῖν τινὶ αἰσχρόν, ἀλλὰ μὴ διαφεύγειν ἔργῳ αἴσχιον. ἔνι τε τοῖς αὐτοῖς οἰκείων ἅμα καὶ πολιτικῶν ἐπιμέλεια, καὶ ἑτέροις πρὸς ἔργα τετραμμένοις τὰ πολιτικὰ μὴ ἐνδεῶς γνῶναι· μόνοι γὰρ τόν τε μηδὲν τῶνδε μετέχοντα οὐκ ἀπράγμονα, ἀλλ’ ἀχρεῖον νομίζομεν, καὶ οἱ αὐτοὶ ἤτοι κρίνομέν γε ἢ ἐνθυμούμεθα ὀρθῶς τὰ πράγματα, οὐ τοὺς λόγους τοῖς ἔργοις βλάβην ἡγούμενοι, ἀλλὰ μὴ προδιδαχθῆναι μᾶλλον λόγῳ πρότερον ἢ ἐπὶ ἃ δεῖ ἔργῳ ἐλθεῖν. διαφερόντως γὰρ δὴ καὶ τόδε ἔχομεν ὥστε τολμᾶν τε οἱ αὐτοὶ μάλιστα καὶ περὶ ὧν ἐπιχειρήσομεν ἐκλογίζεσθαι· ὃ τοῖς ἄλλοις ἀμαθία μὲν θράσος, λογισμὸς δὲ ὄκνον φέρει. κράτιστοι δ’ ἂν τὴν ψυχὴν δικαίως κριθεῖεν οἱ τά τε δεινὰ καὶ ἡδέα σαφέστατα γιγνώσκοντες καὶ διὰ ταῦτα μὴ ἀποτρεπόμενοι ἐκ τῶν κινδύνων. καὶ τὰ ἐς ἀρετὴν ἐνηντιώμεθα τοῖς πολλοῖς· οὐ γὰρ πάσχοντες εὖ, ἀλλὰ δρῶντες κτώμεθα τοὺς φίλους. βεβαιότερος δὲ ὁ δράσας τὴν χάριν ὥστε ὀφειλομένην δι’ εὐνοίας ᾧ δέδωκε σῴζειν· ὁ δὲ ἀντοφείλων ἀμβλύτερος, εἰδὼς οὐκ ἐς χάριν, ἀλλ’ ἐς ὀφείλημα τὴν ἀρετὴν ἀποδώσων. καὶ μόνοι οὐ τοῦ ξυμφέροντος μᾶλλον λογισμῷ ἢ τῆς ἐλευθερίας τῷ πιστῷ ἀδεῶς τινὰ ὠφελοῦμεν.", "st": "2.40"}, {"sp": "N", "t": "‘ξυνελών τε λέγω τήν τε πᾶσαν πόλιν τῆς Ἑλλάδος παίδευσιν εἶναι καὶ καθ’ ἕκαστον δοκεῖν ἄν μοι τὸν αὐτὸν ἄνδρα παρ’ ἡμῶν ἐπὶ πλεῖστ’ ἂν εἴδη καὶ μετὰ χαρίτων μάλιστ’ ἂν εὐτραπέλως τὸ σῶμα αὔταρκες παρέχεσθαι. καὶ ὡς οὐ λόγων ἐν τῷ παρόντι κόμπος τάδε μᾶλλον ἢ ἔργων ἐστὶν ἀλήθεια, αὐτὴ ἡ δύναμις τῆς πόλεως, ἣν ἀπὸ τῶνδε τῶν τρόπων ἐκτησάμεθα, σημαίνει. μόνη γὰρ τῶν νῦν ἀκοῆς κρείσσων ἐς πεῖραν ἔρχεται, καὶ μόνη οὔτε τῷ πολεμίῳ ἐπελθόντι ἀγανάκτησιν ἔχει ὑφ’ οἵων κακοπαθεῖ οὔτε τῷ ὑπηκόῳ κατάμεμψιν ὡς οὐχ ὑπ’ ἀξίων ἄρχεται. μετὰ μεγάλων δὲ σημείων καὶ οὐ δή τοι ἀμάρτυρόν γε τὴν δύναμιν παρασχόμενοι τοῖς τε νῦν καὶ τοῖς ἔπειτα θαυμασθησόμεθα, καὶ οὐδὲν προσδεόμενοι οὔτε Ὁμήρου ἐπαινέτου οὔτε ὅστις ἔπεσι μὲν τὸ αὐτίκα τέρψει, τῶν δ’ ἔργων τὴν ὑπόνοιαν ἡ ἀλήθεια βλάψει, ἀλλὰ πᾶσαν μὲν θάλασσαν καὶ γῆν ἐσβατὸν τῇ ἡμετέρᾳ τόλμῃ καταναγκάσαντες γενέσθαι, πανταχοῦ δὲ μνημεῖα κακῶν τε κἀγαθῶν ἀίδια ξυγκατοικίσαντες. περὶ τοιαύτης οὖν πόλεως οἵδε τε γενναίως δικαιοῦντες μὴ ἀφαιρεθῆναι αὐτὴν μαχόμενοι ἐτελεύτησαν, καὶ τῶν λειπομένων πάντα τινὰ εἰκὸς ἐθέλειν ὑπὲρ αὐτῆς κάμνειν.", "st": "2.41"}, {"sp": "N", "t": "‘δι’ ὃ δὴ καὶ ἐμήκυνα τὰ περὶ τῆς πόλεως, διδασκαλίαν τε ποιούμενος μὴ περὶ ἴσου ἡμῖν εἶναι τὸν ἀγῶνα καὶ οἷς τῶνδε μηδὲν ὑπάρχει ὁμοίως, καὶ τὴν εὐλογίαν ἅμα ἐφ’ οἷς νῦν λέγω φανερὰν σημείοις καθιστάς. καὶ εἴρηται αὐτῆς τὰ μέγιστα· ἃ γὰρ τὴν πόλιν ὕμνησα, αἱ τῶνδε καὶ τῶν τοιῶνδε ἀρεταὶ ἐκόσμησαν, καὶ οὐκ ἂν πολλοῖς τῶν Ἑλλήνων ἰσόρροπος ὥσπερ τῶνδε ὁ λόγος τῶν ἔργων φανείη. δοκεῖ δέ μοι δηλοῦν ἀνδρὸς ἀρετὴν πρώτη τε μηνύουσα καὶ τελευταία βεβαιοῦσα ἡ νῦν τῶνδε καταστροφή. καὶ γὰρ τοῖς τἆλλα χείροσι δίκαιον τὴν ἐς τοὺς πολέμους ὑπὲρ τῆς πατρίδος ἀνδραγαθίαν προτίθεσθαι· ἀγαθῷ γὰρ κακὸν ἀφανίσαντες κοινῶς μᾶλλον ὠφέλησαν ἢ ἐκ τῶν ἰδίων ἔβλαψαν. τῶνδε δὲ οὔτε πλούτου τις τὴν ἔτι ἀπόλαυσιν προτιμήσας ἐμαλακίσθη οὔτε πενίας ἐλπίδι, ὡς κἂν ἔτι διαφυγὼν αὐτὴν πλουτήσειεν, ἀναβολὴν τοῦ δεινοῦ ἐποιήσατο· τὴν δὲ τῶν ἐναντίων τιμωρίαν ποθεινοτέραν αὐτῶν λαβόντες καὶ κινδύνων ἅμα τόνδε κάλλιστον νομίσαντες ἐβουλήθησαν μετ’ αὐτοῦ τοὺς μὲν τιμωρεῖσθαι, τῶν δὲ ἐφίεσθαι, ἐλπίδι μὲν τὸ ἀφανὲς τοῦ κατορθώσειν ἐπιτρέψαντες, ἔργῳ δὲ περὶ τοῦ ἤδη ὁρωμένου σφίσιν αὐτοῖς ἀξιοῦντες πεποιθέναι, καὶ ἐν αὐτῷ τῷ ἀμύνεσθαι καὶ παθεῖν μᾶλλον ἡγησάμενοι ἢ [τὸ] ἐνδόντες σῴζεσθαι, τὸ μὲν αἰσχρὸν τοῦ λόγου ἔφυγον, τὸ δ’ ἔργον τῷ σώματι ὑπέμειναν καὶ δι’ ἐλαχίστου καιροῦ τύχης ἅμα ἀκμῇ τῆς δόξης μᾶλλον ἢ τοῦ δέους ἀπηλλάγησαν.", "st": "2.42"}, {"sp": "N", "t": "‘καὶ οἵδε μὲν προσηκόντως τῇ πόλει τοιοίδε ἐγένοντο· τοὺς δὲ λοιποὺς χρὴ ἀσφαλεστέραν μὲν εὔχεσθαι, ἀτολμοτέραν δὲ μηδὲν ἀξιοῦν τὴν ἐς τοὺς πολεμίους διάνοιαν ἔχειν, σκοποῦντας μὴ λόγῳ μόνῳ τὴν ὠφελίαν, ἣν ἄν τις πρὸς οὐδὲν χεῖρον αὐτοὺς ὑμᾶς εἰδότας μηκύνοι, λέγων ὅσα ἐν τῷ τοὺς πολεμίους ἀμύνεσθαι ἀγαθὰ ἔνεστιν, ἀλλὰ μᾶλλον τὴν τῆς πόλεως δύναμιν καθ’ ἡμέραν ἔργῳ θεωμένους καὶ ἐραστὰς γιγνομένους αὐτῆς, καὶ ὅταν ὑμῖν μεγάλη δόξῃ εἶναι, ἐνθυμουμένους ὅτι τολμῶντες καὶ γιγνώσκοντες τὰ δέοντα καὶ ἐν τοῖς ἔργοις αἰσχυνόμενοι ἄνδρες αὐτὰ ἐκτήσαντο, καὶ ὁπότε καὶ πείρᾳ του σφαλεῖεν, οὐκ οὖν καὶ τὴν πόλιν γε τῆς σφετέρας ἀρετῆς ἀξιοῦντες στερίσκειν, κάλλιστον δὲ ἔρανον αὐτῇ προϊέμενοι. κοινῇ γὰρ τὰ σώματα διδόντες ἰδίᾳ τὸν ἀγήρων ἔπαινον ἐλάμβανον καὶ τὸν τάφον ἐπισημότατον, οὐκ ἐν ᾧ κεῖνται μᾶλλον, ἀλλ’ ἐν ᾧ ἡ δόξα αὐτῶν παρὰ τῷ ἐντυχόντι αἰεὶ καὶ λόγου καὶ ἔργου καιρῷ αἰείμνηστος καταλείπεται. ἀνδρῶν γὰρ ἐπιφανῶν πᾶσα γῆ τάφος, καὶ οὐ στηλῶν μόνον ἐν τῇ οἰκείᾳ σημαίνει ἐπιγραφή, ἀλλὰ καὶ ἐν τῇ μὴ προσηκούσῃ ἄγραφος μνήμη παρ’ ἑκάστῳ τῆς γνώμης μᾶλλον ἢ τοῦ ἔργου ἐνδιαιτᾶται. οὓς νῦν ὑμεῖς ζηλώσαντες καὶ τὸ εὔδαιμον τὸ ἐλεύθερον, τὸ δ’ ἐλεύθερον τὸ εὔψυχον κρίναντες μὴ περιορᾶσθε τοὺς πολεμικοὺς κινδύνους. οὐ γὰρ οἱ κακοπραγοῦντες δικαιότερον ἀφειδοῖεν ἂν τοῦ βίου, οἷς ἐλπὶς οὐκ ἔστιν ἀγαθοῦ, ἀλλ’ οἷς ἡ ἐναντία μεταβολὴ ἐν τῷ ζῆν ἔτι κινδυνεύεται καὶ ἐν οἷς μάλιστα μεγάλα τὰ διαφέροντα, ἤν τι πταίσωσιν. ἀλγεινοτέρα γὰρ ἀνδρί γε φρόνημα ἔχοντι ἡ μετὰ τοῦ [ἐν τῷ] μαλακισθῆναι κάκωσις ἢ ὁ μετὰ ῥώμης καὶ κοινῆς ἐλπίδος ἅμα γιγνόμενος ἀναίσθητος θάνατος.", "st": "2.43"}, {"sp": "N", "t": "‘δι’ ὅπερ καὶ τοὺς τῶνδε νῦν τοκέας, ὅσοι πάρεστε, οὐκ ὀλοφύρομαι μᾶλλον ἢ παραμυθήσομαι. ἐν πολυτρόποις γὰρ ξυμφοραῖς ἐπίστανται τραφέντες· τὸ δ’ εὐτυχές, οἳ ἂν τῆς εὐπρεπεστάτης λάχωσιν, ὥσπερ οἵδε μὲν νῦν, τελευτῆς, ὑμεῖς δὲ λύπης, καὶ οἷς ἐνευδαιμονῆσαί τε ὁ βίος ὁμοίως καὶ ἐντελευτῆσαι ξυνεμετρήθη. χαλεπὸν μὲν οὖν οἶδα πείθειν ὄν, ὧν καὶ πολλάκις ἕξετε ὑπομνήματα ἐν ἄλλων εὐτυχίαις, αἷς ποτὲ καὶ αὐτοὶ ἠγάλλεσθε· καὶ λύπη οὐχ ὧν ἄν τις μὴ πειρασάμενος ἀγαθῶν στερίσκηται, ἀλλ’ οὗ ἂν ἐθὰς γενόμενος ἀφαιρεθῇ. καρτερεῖν δὲ χρὴ καὶ ἄλλων παίδων ἐλπίδι, οἷς ἔτι ἡλικία τέκνωσιν ποιεῖσθαι· ἰδίᾳ τε γὰρ τῶν οὐκ ὄντων λήθη οἱ ἐπιγιγνόμενοί τισιν ἔσονται, καὶ τῇ πόλει διχόθεν, ἔκ τε τοῦ μὴ ἐρημοῦσθαι καὶ ἀσφαλείᾳ, ξυνοίσει· οὐ γὰρ οἷόν τε ἴσον τι ἢ δίκαιον βουλεύεσθαι οἳ ἂν μὴ καὶ παῖδας ἐκ τοῦ ὁμοίου παραβαλλόμενοι κινδυνεύωσιν. ὅσοι δ’ αὖ παρηβήκατε, τόν τε πλέονα κέρδος ὃν ηὐτυχεῖτε βίον ἡγεῖσθε καὶ τόνδε βραχὺν ἔσεσθαι, καὶ τῇ τῶνδε εὐκλείᾳ κουφίζεσθε. τὸ γὰρ φιλότιμον ἀγήρων μόνον, καὶ οὐκ ἐν τῷ ἀχρείῳ τῆς ἡλικίας τὸ κερδαίνειν, ὥσπερ τινές φασι, μᾶλλον τέρπει, ἀλλὰ τὸ τιμᾶσθαι.", "st": "2.44"}, {"sp": "N", "t": "παισὶ δ’ αὖ ὅσοι τῶνδε πάρεστε ἢ ἀδελφοῖς ὁρῶ μέγαν τὸν ἀγῶνα (τὸν γὰρ οὐκ ὄντα ἅπας εἴωθεν ἐπαινεῖν), καὶ μόλις ἂν καθ’ ὑπερβολὴν ἀρετῆς οὐχ ὁμοῖοι, ἀλλ’ ὀλίγῳ χείρους κριθεῖτε. φθόνος γὰρ τοῖς ζῶσι πρὸς τὸ ἀντίπαλον, τὸ δὲ μὴ ἐμποδὼν ἀνανταγωνίστῳ εὐνοίᾳ τετίμηται. εἰ δέ με δεῖ καὶ γυναικείας τι ἀρετῆς, ὅσαι νῦν ἐν χηρείᾳ ἔσονται, μνησθῆναι, βραχείᾳ παραινέσει ἅπαν σημανῶ. τῆς τε γὰρ ὑπαρχούσης φύσεως μὴ χείροσι γενέσθαι ὑμῖν μεγάλη ἡ δόξα καὶ ἧς ἂν ἐπ’ ἐλάχιστον ἀρετῆς πέρι ἢ ψόγου ἐν τοῖς ἄρσεσι κλέος ᾖ.", "st": "2.45"}, {"sp": "N", "t": "‘εἴρηται καὶ ἐμοὶ λόγῳ κατὰ τὸν νόμον ὅσα εἶχον πρόσφορα, καὶ ἔργῳ οἱ θαπτόμενοι τὰ μὲν ἤδη κεκόσμηνται, τὰ δὲ αὐτῶν τοὺς παῖδας τὸ ἀπὸ τοῦδε δημοσίᾳ ἡ πόλις μέχρι ἥβης θρέψει, ὠφέλιμον στέφανον τοῖσδέ τε καὶ τοῖς λειπομένοις τῶν τοιῶνδε ἀγώνων προτιθεῖσα· ἆθλα γὰρ οἷς κεῖται ἀρετῆς μέγιστα, τοῖς δὲ καὶ ἄνδρες ἄριστοι πολιτεύουσιν. νῦν δὲ ἀπολοφυράμενοι ὃν προσήκει ἑκάστῳ ἄπιτε.’", "st": "2.46"}, {"sp": "N", "t": "τοιόσδε μὲν ὁ τάφος ἐγένετο ἐν τῷ χειμῶνι τούτῳ· καὶ διελθόντος αὐτοῦ πρῶτον ἔτος τοῦ πολέμου τοῦδε ἐτελεύτα. τοῦ δὲ θέρους εὐθὺς ἀρχομένου Πελοποννήσιοι καὶ οἱ ξύμμαχοι τὰ δύο μέρη ὥσπερ καὶ τὸ πρῶτον ἐσέβαλον ἐς τὴν Ἀττικήν (ἡγεῖτο δὲ Ἀρχίδαμος ὁ Ζευξιδάμου Λακεδαιμονίων βασιλεύς), καὶ καθεζόμενοι ἐδῄουν τὴν γῆν. καὶ ὄντων αὐτῶν οὐ πολλάς πω ἡμέρας ἐν τῇ Ἀττικῇ ἡ νόσος πρῶτον ἤρξατο γενέσθαι τοῖς Ἀθηναίοις, λεγόμενον μὲν καὶ πρότερον πολλαχόσε ἐγκατασκῆψαι καὶ περὶ Λῆμνον καὶ ἐν ἄλλοις χωρίοις, οὐ μέντοι τοσοῦτός γε λοιμὸς οὐδὲ φθορὰ οὕτως ἀνθρώπων οὐδαμοῦ ἐμνημονεύετο γενέσθαι. οὔτε γὰρ ἰατροὶ ἤρκουν τὸ πρῶτον θεραπεύοντες ἀγνοίᾳ, ἀλλ’ αὐτοὶ μάλιστα ἔθνῃσκον ὅσῳ καὶ μάλιστα προσῇσαν, οὔτε ἄλλη ἀνθρωπεία τέχνη οὐδεμία· ὅσα τε πρὸς ἱεροῖς ἱκέτευσαν ἢ μαντείοις καὶ τοῖς τοιούτοις ἐχρήσαντο, πάντα ἀνωφελῆ ἦν, τελευτῶντές τε αὐτῶν ἀπέστησαν ὑπὸ τοῦ κακοῦ νικώμενοι.", "st": "2.47"}, {"sp": "N", "t": "ἤρξατο δὲ τὸ μὲν πρῶτον, ὡς λέγεται, ἐξ Αἰθιοπίας τῆς ὑπὲρ Αἰγύπτου, ἔπειτα δὲ καὶ ἐς Αἴγυπτον καὶ Λιβύην κατέβη καὶ ἐς τὴν βασιλέως γῆν τὴν πολλήν. ἐς δὲ τὴν Ἀθηναίων πόλιν ἐξαπιναίως ἐσέπεσε, καὶ τὸ πρῶτον ἐν τῷ Πειραιεῖ ἥψατο τῶν ἀνθρώπων, ὥστε καὶ ἐλέχθη ὑπ’ αὐτῶν ὡς οἱ Πελοποννήσιοι φάρμακα ἐσβεβλήκοιεν ἐς τὰ φρέατα· κρῆναι γὰρ οὔπω ἦσαν αὐτόθι. ὕστερον δὲ καὶ ἐς τὴν ἄνω πόλιν ἀφίκετο, καὶ ἔθνῃσκον πολλῷ μᾶλλον ἤδη. λεγέτω μὲν οὖν περὶ αὐτοῦ ὡς ἕκαστος γιγνώσκει καὶ ἰατρὸς καὶ ἰδιώτης, ἀφ’ ὅτου εἰκὸς ἦν γενέσθαι αὐτό, καὶ τὰς αἰτίας ἅστινας νομίζει τοσαύτης μεταβολῆς ἱκανὰς εἶναι δύναμιν ἐς τὸ μεταστῆσαι σχεῖν· ἐγὼ δὲ οἷόν τε ἐγίγνετο λέξω, καὶ ἀφ’ ὧν ἄν τις σκοπῶν, εἴ ποτε καὶ αὖθις ἐπιπέσοι, μάλιστ’ ἂν ἔχοι τι προειδὼς μὴ ἀγνοεῖν, ταῦτα δηλώσω αὐτός τε νοσήσας καὶ αὐτὸς ἰδὼν ἄλλους πάσχοντας.", "st": "2.48"}, {"sp": "N", "t": "τὸ μὲν γὰρ ἔτος, ὡς ὡμολογεῖτο, ἐκ πάντων μάλιστα δὴ ἐκεῖνο ἄνοσον ἐς τὰς ἄλλας ἀσθενείας ἐτύγχανεν ὄν· εἰ δέ τις καὶ προύκαμνέ τι, ἐς τοῦτο πάντα ἀπεκρίθη. τοὺς δὲ ἄλλους ἀπ’ οὐδεμιᾶς προφάσεως, ἀλλ’ ἐξαίφνης ὑγιεῖς ὄντας πρῶτον μὲν τῆς κεφαλῆς θέρμαι ἰσχυραὶ καὶ τῶν ὀφθαλμῶν ἐρυθήματα καὶ φλόγωσις ἐλάμβανε, καὶ τὰ ἐντός, ἥ τε φάρυγξ καὶ ἡ γλῶσσα, εὐθὺς αἱματώδη ἦν καὶ πνεῦμα ἄτοπον καὶ δυσῶδες ἠφίει· ἔπειτα ἐξ αὐτῶν πταρμὸς καὶ βράγχος ἐπεγίγνετο, καὶ ἐν οὐ πολλῷ χρόνῳ κατέβαινεν ἐς τὰ στήθη ὁ πόνος μετὰ βηχὸς ἰσχυροῦ· καὶ ὁπότε ἐς τὴν καρδίαν στηρίξειεν, ἀνέστρεφέ τε αὐτὴν καὶ ἀποκαθάρσεις χολῆς πᾶσαι ὅσαι ὑπὸ ἰατρῶν ὠνομασμέναι εἰσὶν ἐπῇσαν, καὶ αὗται μετὰ ταλαιπωρίας μεγάλης. λύγξ τε τοῖς πλέοσιν ἐνέπιπτε κενή, σπασμὸν ἐνδιδοῦσα ἰσχυρόν, τοῖς μὲν μετὰ ταῦτα λωφήσαντα, τοῖς δὲ καὶ πολλῷ ὕστερον. καὶ τὸ μὲν ἔξωθεν ἁπτομένῳ σῶμα οὔτ’ ἄγαν θερμὸν ἦν οὔτε χλωρόν, ἀλλ’ ὑπέρυθρον, πελιτνόν, φλυκταίναις μικραῖς καὶ ἕλκεσιν ἐξηνθηκός· τὰ δὲ ἐντὸς οὕτως ἐκάετο ὥστε μήτε τῶν πάνυ λεπτῶν ἱματίων καὶ σινδόνων τὰς ἐπιβολὰς μηδ’ ἄλλο τι ἢ γυμνοὶ ἀνέχεσθαι, ἥδιστά τε ἂν ἐς ὕδωρ ψυχρὸν σφᾶς αὐτοὺς ῥίπτειν. καὶ πολλοὶ τοῦτο τῶν ἠμελημένων ἀνθρώπων καὶ ἔδρασαν ἐς φρέατα, τῇ δίψῃ ἀπαύστῳ ξυνεχόμενοι· καὶ ἐν τῷ ὁμοίῳ καθειστήκει τό τε πλέον καὶ ἔλασσον ποτόν. καὶ ἡ ἀπορία τοῦ μὴ ἡσυχάζειν καὶ ἡ ἀγρυπνία ἐπέκειτο διὰ παντός. καὶ τὸ σῶμα, ὅσονπερ χρόνον καὶ ἡ νόσος ἀκμάζοι, οὐκ ἐμαραίνετο, ἀλλ’ ἀντεῖχε παρὰ δόξαν τῇ ταλαιπωρίᾳ, ὥστε ἢ διεφθείροντο οἱ πλεῖστοι ἐναταῖοι καὶ ἑβδομαῖοι ὑπὸ τοῦ ἐντὸς καύματος, ἔτι ἔχοντές τι δυνάμεως, ἢ εἰ διαφύγοιεν, ἐπικατιόντος τοῦ νοσήματος ἐς τὴν κοιλίαν καὶ ἑλκώσεώς τε αὐτῇ ἰσχυρᾶς ἐγγιγνομένης καὶ διαρροίας ἅμα ἀκράτου ἐπιπιπτούσης οἱ πολλοὶ ὕστερον δι’ αὐτὴν ἀσθενείᾳ διεφθείροντο. διεξῄει γὰρ διὰ παντὸς τοῦ σώματος ἄνωθεν ἀρξάμενον τὸ ἐν τῇ κεφαλῇ πρῶτον ἱδρυθὲν κακόν, καὶ εἴ τις ἐκ τῶν μεγίστων περιγένοιτο, τῶν γε ἀκρωτηρίων ἀντίληψις αὐτοῦ ἐπεσήμαινεν. κατέσκηπτε γὰρ ἐς αἰδοῖα καὶ ἐς ἄκρας χεῖρας καὶ πόδας, καὶ πολλοὶ στερισκόμενοι τούτων διέφευγον, εἰσὶ δ’ οἳ καὶ τῶν ὀφθαλμῶν. τοὺς δὲ καὶ λήθη ἐλάμβανε παραυτίκα ἀναστάντας τῶν πάντων ὁμοίως, καὶ ἠγνόησαν σφᾶς τε αὐτοὺς καὶ τοὺς ἐπιτηδείους.", "st": "2.49"}, {"sp": "N", "t": "γενόμενον γὰρ κρεῖσσον λόγου τὸ εἶδος τῆς νόσου τά τε ἄλλα χαλεπωτέρως ἢ κατὰ τὴν ἀνθρωπείαν φύσιν προσέπιπτεν ἑκάστῳ καὶ ἐν τῷδε ἐδήλωσε μάλιστα ἄλλο τι ὂν ἢ τῶν ξυντρόφων τι· τὰ γὰρ ὄρνεα καὶ τετράποδα ὅσα ἀνθρώπων ἅπτεται, πολλῶν ἀτάφων γιγνομένων ἢ οὐ προσῄει ἢ γευσάμενα διεφθείρετο. τεκμήριον δέ· τῶν μὲν τοιούτων ὀρνίθων ἐπίλειψις σαφὴς ἐγένετο, καὶ οὐχ ἑωρῶντο οὔτε ἄλλως οὔτε περὶ τοιοῦτον οὐδέν· οἱ δὲ κύνες μᾶλλον αἴσθησιν παρεῖχον τοῦ ἀποβαίνοντος διὰ τὸ ξυνδιαιτᾶσθαι.", "st": "2.50"}, {"sp": "N", "t": "τὸ μὲν οὖν νόσημα, πολλὰ καὶ ἄλλα παραλιπόντι ἀτοπίας, ὡς ἑκάστῳ ἐτύγχανέ τι διαφερόντως ἑτέρῳ πρὸς ἕτερον γιγνόμενον, τοιοῦτον ἦν ἐπὶ πᾶν τὴν ἰδέαν. καὶ ἄλλο παρελύπει κατ’ ἐκεῖνον τὸν χρόνον οὐδὲν τῶν εἰωθότων· ὃ δὲ καὶ γένοιτο, ἐς τοῦτο ἐτελεύτα. ἔθνῃσκον δὲ οἱ μὲν ἀμελείᾳ, οἱ δὲ καὶ πάνυ θεραπευόμενοι. ἕν τε οὐδὲ ἓν κατέστη ἴαμα ὡς εἰπεῖν ὅτι χρῆν προσφέροντας ὠφελεῖν· τὸ γάρ τῳ ξυνενεγκὸν ἄλλον τοῦτο ἔβλαπτεν. σῶμά τε αὔταρκες ὂν οὐδὲν διεφάνη πρὸς αὐτὸ ἰσχύος πέρι ἢ ἀσθενείας, ἀλλὰ πάντα ξυνῄρει καὶ τὰ πάσῃ διαίτῃ θεραπευόμενα. δεινότατον δὲ παντὸς ἦν τοῦ κακοῦ ἥ τε ἀθυμία ὁπότε τις αἴσθοιτο κάμνων (πρὸς γὰρ τὸ ἀνέλπιστον εὐθὺς τραπόμενοι τῇ γνώμῃ πολλῷ μᾶλλον προΐεντο σφᾶς αὐτοὺς καὶ οὐκ ἀντεῖχον), καὶ ὅτι ἕτερος ἀφ’ ἑτέρου θεραπείας ἀναπιμπλάμενοι ὥσπερ τὰ πρόβατα ἔθνῃσκον· καὶ τὸν πλεῖστον φθόρον τοῦτο ἐνεποίει. εἴτε γὰρ μὴ ’θέλοιεν δεδιότες ἀλλήλοις προσιέναι, ἀπώλλυντο ἐρῆμοι, καὶ οἰκίαι πολλαὶ ἐκενώθησαν ἀπορίᾳ τοῦ θεραπεύσοντος· εἴτε προσίοιεν, διεφθείροντο, καὶ μάλιστα οἱ ἀρετῆς τι μεταποιούμενοι· αἰσχύνῃ γὰρ ἠφείδουν σφῶν αὐτῶν ἐσιόντες παρὰ τοὺς φίλους, ἐπεὶ καὶ τὰς ὀλοφύρσεις τῶν ἀπογιγνομένων τελευτῶντες καὶ οἱ οἰκεῖοι ἐξέκαμνον ὑπὸ τοῦ πολλοῦ κακοῦ νικώμενοι. ἐπὶ πλέον δ’ ὅμως οἱ διαπεφευγότες τόν τε θνῄσκοντα καὶ τὸν πονούμενον ᾠκτίζοντο διὰ τὸ προειδέναι τε καὶ αὐτοὶ ἤδη ἐν τῷ θαρσαλέῳ εἶναι· δὶς γὰρ τὸν αὐτόν, ὥστε καὶ κτείνειν, οὐκ ἐπελάμβανεν. καὶ ἐμακαρίζοντό τε ὑπὸ τῶν ἄλλων, καὶ αὐτοὶ τῷ παραχρῆμα περιχαρεῖ καὶ ἐς τὸν ἔπειτα χρόνον ἐλπίδος τι εἶχον κούφης μηδ’ ἂν ὑπ’ ἄλλου νοσήματός ποτε ἔτι διαφθαρῆναι.", "st": "2.51"}, {"sp": "N", "t": "ἐπίεσε δ’ αὐτοὺς μᾶλλον πρὸς τῷ ὑπάρχοντι πόνῳ καὶ ἡ ξυγκομιδὴ ἐκ τῶν ἀγρῶν ἐς τὸ ἄστυ, καὶ οὐχ ἧσσον τοὺς ἐπελθόντας. οἰκιῶν γὰρ οὐχ ὑπαρχουσῶν, ἀλλ’ ἐν καλύβαις πνιγηραῖς ὥρᾳ ἔτους διαιτωμένων ὁ φθόρος ἐγίγνετο οὐδενὶ κόσμῳ, ἀλλὰ καὶ νεκροὶ ἐπ’ ἀλλήλοις ἀποθνῄσκοντες ἔκειντο καὶ ἐν ταῖς ὁδοῖς ἐκαλινδοῦντο καὶ περὶ τὰς κρήνας ἁπάσας ἡμιθνῆτες τοῦ ὕδατος ἐπιθυμίᾳ. τά τε ἱερὰ ἐν οἷς ἐσκήνηντο νεκρῶν πλέα ἦν, αὐτοῦ ἐναποθνῃσκόντων· ὑπερβιαζομένου γὰρ τοῦ κακοῦ οἱ ἄνθρωποι, οὐκ ἔχοντες ὅτι γένωνται, ἐς ὀλιγωρίαν ἐτράποντο καὶ ἱερῶν καὶ ὁσίων ὁμοίως. νόμοι τε πάντες ξυνεταράχθησαν οἷς ἐχρῶντο πρότερον περὶ τὰς ταφάς, ἔθαπτον δὲ ὡς ἕκαστος ἐδύνατο. καὶ πολλοὶ ἐς ἀναισχύντους θήκας ἐτράποντο σπάνει τῶν ἐπιτηδείων διὰ τὸ συχνοὺς ἤδη προτεθνάναι σφίσιν· ἐπὶ πυρὰς γὰρ ἀλλοτρίας φθάσαντες τοὺς νήσαντας οἱ μὲν ἐπιθέντες τὸν ἑαυτῶν νεκρὸν ὑφῆπτον, οἱ δὲ καιομένου ἄλλου ἐπιβαλόντες ἄνωθεν ὃν φέροιεν ἀπῇσαν.", "st": "2.52"}, {"sp": "N", "t": "πρῶτόν τε ἦρξε καὶ ἐς τἆλλα τῇ πόλει ἐπὶ πλέον ἀνομίας τὸ νόσημα. ῥᾷον γὰρ ἐτόλμα τις ἃ πρότερον ἀπεκρύπτετο μὴ καθ’ ἡδονὴν ποιεῖν, ἀγχίστροφον τὴν μεταβολὴν ὁρῶντες τῶν τε εὐδαιμόνων καὶ αἰφνιδίως θνῃσκόντων καὶ τῶν οὐδὲν πρότερον κεκτημένων, εὐθὺς δὲ τἀκείνων ἐχόντων. ὥστε ταχείας τὰς ἐπαυρέσεις καὶ πρὸς τὸ τερπνὸν ἠξίουν ποιεῖσθαι, ἐφήμερα τά τε σώματα καὶ τὰ χρήματα ὁμοίως ἡγούμενοι. καὶ τὸ μὲν προσταλαιπωρεῖν τῷ δόξαντι καλῷ οὐδεὶς πρόθυμος ἦν, ἄδηλον νομίζων εἰ πρὶν ἐπ’ αὐτὸ ἐλθεῖν διαφθαρήσεται· ὅτι δὲ ἤδη τε ἡδὺ πανταχόθεν τε ἐς αὐτὸ κερδαλέον, τοῦτο καὶ καλὸν καὶ χρήσιμον κατέστη. θεῶν δὲ φόβος ἢ ἀνθρώπων νόμος οὐδεὶς ἀπεῖργε, τὸ μὲν κρίνοντες ἐν ὁμοίῳ καὶ σέβειν καὶ μὴ ἐκ τοῦ πάντας ὁρᾶν ἐν ἴσῳ ἀπολλυμένους, τῶν δὲ ἁμαρτημάτων οὐδεὶς ἐλπίζων μέχρι τοῦ δίκην γενέσθαι βιοὺς ἂν τὴν τιμωρίαν ἀντιδοῦναι, πολὺ δὲ μείζω τὴν ἤδη κατεψηφισμένην σφῶν ἐπικρεμασθῆναι, ἣν πρὶν ἐμπεσεῖν εἰκὸς εἶναι τοῦ βίου τι ἀπολαῦσαι.", "st": "2.53"}, {"sp": "N", "t": "τοιούτῳ μὲν πάθει οἱ Ἀθηναῖοι περιπεσόντες ἐπιέζοντο, ἀνθρώπων τ’ ἔνδον θνῃσκόντων καὶ γῆς ἔξω δῃουμένης. ἐν δὲ τῷ κακῷ οἷα εἰκὸς ἀνεμνήσθησαν καὶ τοῦδε τοῦ ἔπους, φάσκοντες οἱ πρεσβύτεροι πάλαι ᾄδεσθαι<br>‘ἥξει Δωριακὸς πόλεμος καὶ λοιμὸς ἅμ’ αὐτῷ.’<br>ἐγένετο μὲν οὖν ἔρις τοῖς ἀνθρώποις μὴ λοιμὸν ὠνομάσθαι ἐν τῷ ἔπει ὑπὸ τῶν παλαιῶν, ἀλλὰ λιμόν, ἐνίκησε δὲ ἐπὶ τοῦ παρόντος εἰκότως λοιμὸν εἰρῆσθαι· οἱ γὰρ ἄνθρωποι πρὸς ἃ ἔπασχον τὴν μνήμην ἐποιοῦντο. ἢν δέ γε οἶμαί ποτε ἄλλος πόλεμος καταλάβῃ Δωρικὸς τοῦδε ὕστερος καὶ ξυμβῇ γενέσθαι λιμόν, κατὰ τὸ εἰκὸς οὕτως ᾄσονται. μνήμη δὲ ἐγένετο καὶ τοῦ Λακεδαιμονίων χρηστηρίου τοῖς εἰδόσιν, ὅτε ἐπερωτῶσιν αὐτοῖς τὸν θεὸν εἰ χρὴ πολεμεῖν ἀνεῖλε κατὰ κράτος πολεμοῦσι νίκην ἔσεσθαι, καὶ αὐτὸς ἔφη ξυλλήψεσθαι. περὶ μὲν οὖν τοῦ χρηστηρίου τὰ γιγνόμενα ᾔκαζον ὁμοῖα εἶναι· ἐσβεβληκότων δὲ τῶν Πελοποννησίων ἡ νόσος ἤρξατο εὐθύς, καὶ ἐς μὲν Πελοπόννησον οὐκ ἐσῆλθεν, ὅτι καὶ ἄξιον εἰπεῖν, ἐπενείματο δὲ Ἀθήνας μὲν μάλιστα, ἔπειτα δὲ καὶ τῶν ἄλλων χωρίων τὰ πολυανθρωπότατα. ταῦτα μὲν τὰ κατὰ τὴν νόσον γενόμενα.", "st": "2.54"}, {"sp": "N", "t": "οἱ δὲ Πελοποννήσιοι ἐπειδὴ ἔτεμον τὸ πεδίον, παρῆλθον ἐς τὴν Πάραλον γῆν καλουμένην μέχρι Λαυρείου, οὗ τὰ ἀργύρεια μέταλλά ἐστιν Ἀθηναίοις. καὶ πρῶτον μὲν ἔτεμον ταύτην ᾗ πρὸς Πελοπόννησον ὁρᾷ, ἔπειτα δὲ τὴν πρὸς Εὔβοιάν τε καὶ Ἄνδρον τετραμμένην. Περικλῆς δὲ στρατηγὸς ὢν καὶ τότε περὶ μὲν τοῦ μὴ ἐπεξιέναι τοὺς Ἀθηναίους τὴν αὐτὴν γνώμην εἶχεν ὥσπερ καὶ ἐν τῇ προτέρᾳ ἐσβολῇ.", "st": "2.55"}, {"sp": "N", "t": "ἔτι δ’ αὐτῶν ἐν τῷ πεδίῳ ὄντων, πρὶν ἐς τὴν παραλίαν ἐλθεῖν, ἑκατὸν νεῶν ἐπίπλουν τῇ Πελοποννήσῳ παρεσκευάζετο, καὶ ἐπειδὴ ἑτοῖμα ἦν, ἀνήγετο. ἦγε δ’ ἐπὶ τῶν νεῶν ὁπλίτας Ἀθηναίων τετρακισχιλίους καὶ ἱππέας τριακοσίους ἐν ναυσὶν ἱππαγωγοῖς πρῶτον τότε ἐκ τῶν παλαιῶν νεῶν ποιηθείσαις· ξυνεστρατεύοντο δὲ καὶ Χῖοι καὶ Λέσβιοι πεντήκοντα ναυσίν. ὅτε δὲ ἀνήγετο ἡ στρατιὰ αὕτη Ἀθηναίων, Πελοποννησίους κατέλιπον τῆς Ἀττικῆς ὄντας ἐν τῇ παραλίᾳ. ἀφικόμενοι δὲ ἐς Ἐπίδαυρον τῆς Πελοποννήσου ἔτεμον τῆς γῆς τὴν πολλήν, καὶ πρὸς τὴν πόλιν προσβαλόντες ἐς ἐλπίδα μὲν ἦλθον τοῦ ἑλεῖν, οὐ μέντοι προυχώρησέ γε. ἀναγαγόμενοι δὲ ἐκ τῆς Ἐπιδαύρου ἔτεμον τήν τε Τροιζηνίδα γῆν καὶ Ἁλιάδα καὶ Ἑρμιονίδα· ἔστι δὲ ταῦτα πάντα ἐπιθαλάσσια τῆς Πελοποννήσου. ἄραντες δὲ ἀπ’ αὐτῶν ἀφίκοντο ἐς Πρασιὰς τῆς Λακωνικῆς πόλισμα ἐπιθαλάσσιον, καὶ τῆς τε γῆς ἔτεμον καὶ αὐτὸ τὸ πόλισμα εἷλον καὶ ἐπόρθησαν. ταῦτα δὲ ποιήσαντες ἐπ’ οἴκου ἀνεχώρησαν. τοὺς δὲ Πελοποννησίους οὐκέτι κατέλαβον ἐν τῇ Ἀττικῇ ὄντας, ἀλλ’ ἀνακεχωρηκότας.", "st": "2.56"}, {"sp": "N", "t": "ὅσον δὲ χρόνον οἵ τε Πελοποννήσιοι ἦσαν ἐν τῇ γῇ τῇ Ἀθηναίων καὶ οἱ Ἀθηναῖοι ἐστράτευον ἐπὶ τῶν νεῶν, ἡ νόσος ἔν τε τῇ στρατιᾷ τοὺς Ἀθηναίους ἔφθειρε καὶ ἐν τῇ πόλει, ὥστε καὶ ἐλέχθη τοὺς Πελοποννησίους δείσαντας τὸ νόσημα, ὡς ἐπυνθάνοντο τῶν αὐτομόλων ὅτι ἐν τῇ πόλει εἴη καὶ θάπτοντας ἅμα ᾐσθάνοντο, θᾶσσον ἐκ τῆς γῆς ἐξελθεῖν. τῇ δὲ ἐσβολῇ ταύτῃ πλεῖστόν τε χρόνον ἐνέμειναν καὶ τὴν γῆν πᾶσαν ἔτεμον· ἡμέρας γὰρ τεσσαράκοντα μάλιστα ἐν τῇ γῇ τῇ Ἀττικῇ ἐγένοντο.", "st": "2.57"}, {"sp": "N", "t": "τοῦ δ’ αὐτοῦ θέρους Ἅγνων ὁ Νικίου καὶ Κλεόπομπος ὁ Κλεινίου, ξυστράτηγοι ὄντες Περικλέους, λαβόντες τὴν στρατιὰν ᾗπερ ἐκεῖνος ἐχρήσατο ἐστράτευσαν εὐθὺς ἐπὶ Χαλκιδέας τοὺς ἐπὶ Θρᾴκης καὶ Ποτείδαιαν ἔτι πολιορκουμένην, ἀφικόμενοι δὲ μηχανάς τε τῇ Ποτειδαίᾳ προσέφερον καὶ παντὶ τρόπῳ ἐπειρῶντο ἑλεῖν. προυχώρει δὲ αὐτοῖς οὔτε ἡ αἵρεσις τῆς πόλεως οὔτε τἆλλα τῆς παρασκευῆς ἀξίως· ἐπιγενομένη γὰρ ἡ νόσος ἐνταῦθα δὴ πάνυ ἐπίεσε τοὺς Ἀθηναίους, φθείρουσα τὴν στρατιάν, ὥστε καὶ τοὺς προτέρους στρατιώτας νοσῆσαι τῶν Ἀθηναίων ἀπὸ τῆς ξὺν Ἅγνωνι στρατιᾶς, ἐν τῷ πρὸ τοῦ χρόνῳ ὑγιαίνοντας. Φορμίων δὲ καὶ οἱ ἑξακόσιοι καὶ χίλιοι οὐκέτι ἦσαν περὶ Χαλκιδέας. ὁ μὲν οὖν Ἅγνων ἀνεχώρησε ταῖς ναυσὶν ἐς τὰς Ἀθήνας, ἀπὸ τετρακισχιλίων ὁπλιτῶν χιλίους καὶ πεντήκοντα τῇ νόσῳ ἀπολέσας ἐν τεσσαράκοντα μάλιστα ἡμέραις· οἱ δὲ πρότεροι στρατιῶται κατὰ χώραν μένοντες ἐπολιόρκουν τὴν Ποτείδαιαν.", "st": "2.58"}, {"sp": "N", "t": "μετὰ δὲ τὴν δευτέραν ἐσβολὴν τῶν Πελοποννησίων οἱ Ἀθηναῖοι, ὡς ἥ τε γῆ αὐτῶν ἐτέτμητο τὸ δεύτερον καὶ ἡ νόσος ἐπέκειτο ἅμα καὶ ὁ πόλεμος, ἠλλοίωντο τὰς γνώμας, καὶ τὸν μὲν Περικλέα ἐν αἰτίᾳ εἶχον ὡς πείσαντα σφᾶς πολεμεῖν καὶ δι’ ἐκεῖνον ταῖς ξυμφοραῖς περιπεπτωκότες, πρὸς δὲ τοὺς Λακεδαιμονίους ὥρμηντο ξυγχωρεῖν· καὶ πρέσβεις τινὰς πέμψαντες ὡς αὐτοὺς ἄπρακτοι ἐγένοντο. πανταχόθεν τε τῇ γνώμῃ ἄποροι καθεστηκότες ἐνέκειντο τῷ Περικλεῖ. ὁ δὲ ὁρῶν αὐτοὺς πρὸς τὰ παρόντα χαλεπαίνοντας καὶ πάντα ποιοῦντας ἅπερ αὐτὸς ἤλπιζε, ξύλλογον ποιήσας (ἔτι δ’ ἐστρατήγει) ἐβούλετο θαρσῦναί τε καὶ ἀπαγαγὼν τὸ ὀργιζόμενον τῆς γνώμης πρὸς τὸ ἠπιώτερον καὶ ἀδεέστερον καταστῆσαι· παρελθὼν δὲ ἔλεξε τοιάδε.", "st": "2.59"}, {"sp": "N", "t": "‘καὶ προσδεχομένῳ μοι τὰ τῆς ὀργῆς ὑμῶν ἔς με γεγένηται (αἰσθάνομαι γὰρ τὰς αἰτίας) καὶ ἐκκλησίαν τούτου ἕνεκα ξυνήγαγον, ὅπως ὑπομνήσω καὶ μέμψωμαι εἴ τι μὴ ὀρθῶς ἢ ἐμοὶ χαλεπαίνετε ἢ ταῖς ξυμφοραῖς εἴκετε. ἐγὼ γὰρ ἡγοῦμαι πόλιν πλείω ξύμπασαν ὀρθουμένην ὠφελεῖν τοὺς ἰδιώτας ἢ καθ’ ἕκαστον τῶν πολιτῶν εὐπραγοῦσαν, ἁθρόαν δὲ σφαλλομένην. καλῶς μὲν γὰρ φερόμενος ἀνὴρ τὸ καθ’ ἑαυτὸν διαφθειρομένης τῆς πατρίδος οὐδὲν ἧσσον ξυναπόλλυται, κακοτυχῶν δὲ ἐν εὐτυχούσῃ πολλῷ μᾶλλον διασῴζεται. ὁπότε οὖν πόλις μὲν τὰς ἰδίας ξυμφορὰς οἵα τε φέρειν, εἷς δ’ ἕκαστος τὰς ἐκείνης ἀδύνατος, πῶς οὐ χρὴ πάντας ἀμύνειν αὐτῇ, καὶ μὴ ὃ νῦν ὑμεῖς δρᾶτε· ταῖς κατ’ οἶκον κακοπραγίαις ἐκπεπληγμένοι τοῦ κοινοῦ τῆς σωτηρίας ἀφίεσθε, καὶ ἐμέ τε τὸν παραινέσαντα πολεμεῖν καὶ ὑμᾶς αὐτοὺς οἳ ξυνέγνωτε δι’ αἰτίας ἔχετε. καίτοι ἐμοὶ τοιούτῳ ἀνδρὶ ὀργίζεσθε ὃς οὐδενὸς ἥσσων οἴομαι εἶναι γνῶναί τε τὰ δέοντα καὶ ἑρμηνεῦσαι ταῦτα, φιλόπολίς τε καὶ χρημάτων κρείσσων. ὅ τε γὰρ γνοὺς καὶ μὴ σαφῶς διδάξας ἐν ἴσῳ καὶ εἰ μὴ ἐνεθυμήθη· ὅ τε ἔχων ἀμφότερα, τῇ δὲ πόλει δύσνους, οὐκ ἂν ὁμοίως τι οἰκείως φράζοι· προσόντος δὲ καὶ τοῦδε, χρήμασι δὲ νικωμένου, τὰ ξύμπαντα τούτου ἑνὸς ἂν πωλοῖτο. ὥστ’ εἴ μοι καὶ μέσως ἡγούμενοι μᾶλλον ἑτέρων προσεῖναι αὐτὰ πολεμεῖν ἐπείσθητε, οὐκ ἂν εἰκότως νῦν τοῦ γε ἀδικεῖν αἰτίαν φεροίμην.", "st": "2.60"}, {"sp": "N", "t": "‘καὶ γὰρ οἷς μὲν αἵρεσις γεγένηται τἆλλα εὐτυχοῦσι, πολλὴ ἄνοια πολεμῆσαι· εἰ δ’ ἀναγκαῖον ἦν ἢ εἴξαντας εὐθὺς τοῖς πέλας ὑπακοῦσαι ἢ κινδυνεύσαντας περιγενέσθαι, ὁ φυγὼν τὸν κίνδυνον τοῦ ὑποστάντος μεμπτότερος. καὶ ἐγὼ μὲν ὁ αὐτός εἰμι καὶ οὐκ ἐξίσταμαι· ὑμεῖς δὲ μεταβάλλετε, ἐπειδὴ ξυνέβη ὑμῖν πεισθῆναι μὲν ἀκεραίοις, μεταμέλειν δὲ κακουμένοις, καὶ τὸν ἐμὸν λόγον ἐν τῷ ὑμετέρῳ ἀσθενεῖ τῆς γνώμης μὴ ὀρθὸν φαίνεσθαι, διότι τὸ μὲν λυποῦν ἔχει ἤδη τὴν αἴσθησιν ἑκάστῳ, τῆς δὲ ὠφελίας ἄπεστιν ἔτι ἡ δήλωσις ἅπασι, καὶ μεταβολῆς μεγάλης, καὶ ταύτης ἐξ ὀλίγου, ἐμπεσούσης ταπεινὴ ὑμῶν ἡ διάνοια ἐγκαρτερεῖν ἃ ἔγνωτε. δουλοῖ γὰρ φρόνημα τὸ αἰφνίδιον καὶ ἀπροσδόκητον καὶ τὸ πλείστῳ παραλόγῳ ξυμβαῖνον· ὃ ὑμῖν πρὸς τοῖς ἄλλοις οὐχ ἥκιστα καὶ κατὰ τὴν νόσον γεγένηται. ὅμως δὲ πόλιν μεγάλην οἰκοῦντας καὶ ἐν ἤθεσιν ἀντιπάλοις αὐτῇ τεθραμμένους χρεὼν καὶ ξυμφοραῖς ταῖς μεγίσταις ἐθέλειν ὑφίστασθαι καὶ τὴν ἀξίωσιν μὴ ἀφανίζειν (ἐν ἴσῳ γὰρ οἱ ἄνθρωποι δικαιοῦσι τῆς τε ὑπαρχούσης δόξης αἰτιᾶσθαι ὅστις μαλακίᾳ ἐλλείπει καὶ τῆς μὴ προσηκούσης μισεῖν τὸν θρασύτητι ὀρεγόμενον), ἀπαλγήσαντας δὲ τὰ ἴδια τοῦ κοινοῦ τῆς σωτηρίας ἀντιλαμβάνεσθαι.", "st": "2.61"}, {"sp": "N", "t": "‘τὸν δὲ πόνον τὸν κατὰ τὸν πόλεμον, μὴ γένηταί τε πολὺς καὶ οὐδὲν μᾶλλον περιγενώμεθα, ἀρκείτω μὲν ὑμῖν καὶ ἐκεῖνα ἐν οἷς ἄλλοτε πολλάκις γε δὴ ἀπέδειξα οὐκ ὀρθῶς αὐτὸν ὑποπτευόμενον, δηλώσω δὲ καὶ τόδε, ὅ μοι δοκεῖτε οὔτ’ αὐτοὶ πώποτε ἐνθυμηθῆναι ὑπάρχον ὑμῖν μεγέθους πέρι ἐς τὴν ἀρχὴν οὔτ’ ἐγὼ ἐν τοῖς πρὶν λόγοις· οὐδ’ ἂν νῦν ἐχρησάμην κομπωδεστέραν ἔχοντι τὴν προσποίησιν, εἰ μὴ καταπεπληγμένους ὑμᾶς παρὰ τὸ εἰκὸς ἑώρων. οἴεσθε μὲν γὰρ τῶν ξυμμάχων μόνων ἄρχειν, ἐγὼ δὲ ἀποφαίνω δύο μερῶν τῶν ἐς χρῆσιν φανερῶν, γῆς καὶ θαλάσσης, τοῦ ἑτέρου ὑμᾶς παντὸς κυριωτάτους ὄντας, ἐφ’ ὅσον τε νῦν νέμεσθε καὶ ἢν ἐπὶ πλέον βουληθῆτε· καὶ οὐκ ἔστιν ὅστις τῇ ὑπαρχούσῃ παρασκευῇ τοῦ ναυτικοῦ πλέοντας ὑμᾶς οὔτε βασιλεὺς οὔτε ἄλλο οὐδὲν ἔθνος τῶν ἐν τῷ παρόντι κωλύσει. ὥστε οὐ κατὰ τὴν τῶν οἰκιῶν καὶ τῆς γῆς χρείαν, ὧν μεγάλων νομίζετε ἐστερῆσθαι, αὕτη ἡ δύναμις φαίνεται· οὐδ’ εἰκὸς χαλεπῶς φέρειν αὐτῶν μᾶλλον ἢ οὐ κηπίον καὶ ἐγκαλλώπισμα πλούτου πρὸς ταύτην νομίσαντας ὀλιγωρῆσαι, καὶ γνῶναι ἐλευθερίαν μέν, ἢν ἀντιλαμβανόμενοι αὐτῆς διασώσωμεν, ῥᾳδίως ταῦτα ἀναληψομένην, ἄλλων δὲ ὑπακούσασι καὶ τὰ προκεκτημένα φιλεῖν ἐλασσοῦσθαι, τῶν τε πατέρων μὴ χείρους κατ’ ἀμφότερα φανῆναι, οἳ μετὰ πόνων καὶ οὐ παρ’ ἄλλων δεξάμενοι κατέσχον τε καὶ προσέτι διασώσαντες παρέδοσαν ὑμῖν αὐτά (αἴσχιον δὲ ἔχοντας ἀφαιρεθῆναι ἢ κτωμένους ἀτυχῆσαι), ἰέναι δὲ τοῖς ἐχθροῖς ὁμόσε μὴ φρονήματι μόνον, ἀλλὰ καὶ καταφρονήματι. αὔχημα μὲν γὰρ καὶ ἀπὸ ἀμαθίας εὐτυχοῦς καὶ δειλῷ τινὶ ἐγγίγνεται, καταφρόνησις δὲ ὃς ἂν καὶ γνώμῃ πιστεύῃ τῶν ἐναντίων προύχειν, ὃ ἡμῖν ὑπάρχει. καὶ τὴν τόλμαν ἀπὸ τῆς ὁμοίας τύχης ἡ ξύνεσις ἐκ τοῦ ὑπέρφρονος ἐχυρωτέραν παρέχεται, ἐλπίδι τε ἧσσον πιστεύει, ἧς ἐν τῷ ἀπόρῳ ἡ ἰσχύς, γνώμῃ δὲ ἀπὸ τῶν ὑπαρχόντων, ἧς βεβαιοτέρα ἡ πρόνοια.", "st": "2.62"}, {"sp": "N", "t": "τῆς τε πόλεως ὑμᾶς εἰκὸς τῷ τιμωμένῳ ἀπὸ τοῦ ἄρχειν, ᾧπερ ἅπαντες ἀγάλλεσθε, βοηθεῖν, καὶ μὴ φεύγειν τοὺς πόνους ἢ μηδὲ τὰς τιμὰς διώκειν· μηδὲ νομίσαι περὶ ἑνὸς μόνου, δουλείας ἀντ’ ἐλευθερίας, ἀγωνίζεσθαι, ἀλλὰ καὶ ἀρχῆς στερήσεως καὶ κινδύνου ὧν ἐν τῇ ἀρχῇ ἀπήχθεσθε. ἧς οὐδ’ ἐκστῆναι ἔτι ὑμῖν ἔστιν, εἴ τις καὶ τόδε ἐν τῷ παρόντι δεδιὼς ἀπραγμοσύνῃ ἀνδραγαθίζεται· ὡς τυραννίδα γὰρ ἤδη ἔχετε αὐτήν, ἣν λαβεῖν μὲν ἄδικον δοκεῖ εἶναι, ἀφεῖναι δὲ ἐπικίνδυνον. τάχιστ’ ἄν τε πόλιν οἱ τοιοῦτοι ἑτέρους τε πείσαντες ἀπολέσειαν καὶ εἴ που ἐπὶ σφῶν αὐτῶν αὐτόνομοι οἰκήσειαν· τὸ γὰρ ἄπραγμον οὐ σῴζεται μὴ μετὰ τοῦ δραστηρίου τεταγμένον, οὐδὲ ἐν ἀρχούσῃ πόλει ξυμφέρει, ἀλλ’ ἐν ὑπηκόῳ, ἀσφαλῶς δουλεύειν.", "st": "2.63"}, {"sp": "N", "t": "‘ὑμεῖς δὲ μήτε ὑπὸ τῶν τοιῶνδε πολιτῶν παράγεσθε μήτε ἐμὲ δι’ ὀργῆς ἔχετε, ᾧ καὶ αὐτοὶ ξυνδιέγνωτε πολεμεῖν, εἰ καὶ ἐπελθόντες οἱ ἐναντίοι ἔδρασαν ἅπερ εἰκὸς ἦν μὴ ἐθελησάντων ὑμῶν ὑπακούειν, ἐπιγεγένηταί τε πέρα ὧν προσεδεχόμεθα ἡ νόσος ἥδε, πρᾶγμα μόνον δὴ τῶν πάντων ἐλπίδος κρεῖσσον γεγενημένον. καὶ δι’ αὐτὴν οἶδ’ ὅτι μέρος τι μᾶλλον ἔτι μισοῦμαι, οὐ δικαίως, εἰ μὴ καὶ ὅταν παρὰ λόγον τι εὖ πράξητε ἐμοὶ ἀναθήσετε. φέρειν δὲ χρὴ τά τε δαιμόνια ἀναγκαίως τά τε ἀπὸ τῶν πολεμίων ἀνδρείως· ταῦτα γὰρ ἐν ἔθει τῇδε τῇ πόλει πρότερόν τε ἦν νῦν τε μὴ ἐν ὑμῖν κωλυθῇ. γνῶτε δὲ ὄνομα μέγιστον αὐτὴν ἔχουσαν ἐν ἅπασιν ἀνθρώποις διὰ τὸ ταῖς ξυμφοραῖς μὴ εἴκειν, πλεῖστα δὲ σώματα καὶ πόνους ἀνηλωκέναι πολέμῳ, καὶ δύναμιν μεγίστην δὴ μέχρι τοῦδε κεκτημένην, ἧς ἐς ἀΐδιον τοῖς ἐπιγιγνομένοις, ἢν καὶ νῦν ὑπενδῶμέν ποτε (πάντα γὰρ πέφυκε καὶ ἐλασσοῦσθαι), μνήμη καταλελείψεται, Ἑλλήνων τε ὅτι Ἕλληνες πλείστων δὴ ἤρξαμεν, καὶ πολέμοις μεγίστοις ἀντέσχομεν πρός τε ξύμπαντας καὶ καθ’ ἑκάστους, πόλιν τε τοῖς πᾶσιν εὐπορωτάτην καὶ μεγίστην ᾠκήσαμεν. καίτοι ταῦτα ὁ μὲν ἀπράγμων μέμψαιτ’ ἄν, ὁ δὲ δρᾶν τι καὶ αὐτὸς βουλόμενος ζηλώσει· εἰ δέ τις μὴ κέκτηται, φθονήσει. τὸ δὲ μισεῖσθαι καὶ λυπηροὺς εἶναι ἐν τῷ παρόντι πᾶσι μὲν ὑπῆρξε δὴ ὅσοι ἕτεροι ἑτέρων ἠξίωσαν ἄρχειν· ὅστις δὲ ἐπὶ μεγίστοις τὸ ἐπίφθονον λαμβάνει, ὀρθῶς βουλεύεται. μῖσος μὲν γὰρ οὐκ ἐπὶ πολὺ ἀντέχει, ἡ δὲ παραυτίκα τε λαμπρότης καὶ ἐς τὸ ἔπειτα δόξα αἰείμνηστος καταλείπεται. ὑμεῖς δὲ ἔς τε τὸ μέλλον καλὸν προγνόντες ἔς τε τὸ αὐτίκα μὴ αἰσχρὸν τῷ ἤδη προθύμῳ ἀμφότερα κτήσασθε, καὶ Λακεδαιμονίοις μήτε ἐπικηρυκεύεσθε μήτε ἔνδηλοι ἔστε τοῖς παροῦσι πόνοις βαρυνόμενοι, ὡς οἵτινες πρὸς τὰς ξυμφορὰς γνώμῃ μὲν ἥκιστα λυποῦνται, ἔργῳ δὲ μάλιστα ἀντέχουσιν, οὗτοι καὶ πόλεων καὶ ἰδιωτῶν κράτιστοί εἰσιν.’", "st": "2.64"}, {"sp": "N", "t": "τοιαῦτα ὁ Περικλῆς λέγων ἐπειρᾶτο τοὺς Ἀθηναίους τῆς τε ἐς αὑτὸν ὀργῆς παραλύειν καὶ ἀπὸ τῶν παρόντων δεινῶν ἀπάγειν τὴν γνώμην. οἱ δὲ δημοσίᾳ μὲν τοῖς λόγοις ἀνεπείθοντο καὶ οὔτε πρὸς τοὺς Λακεδαιμονίους ἔτι ἔπεμπον ἔς τε τὸν πόλεμον μᾶλλον ὥρμηντο, ἰδίᾳ δὲ τοῖς παθήμασιν ἐλυποῦντο, ὁ μὲν δῆμος ὅτι ἀπ’ ἐλασσόνων ὁρμώμενος ἐστέρητο καὶ τούτων, οἱ δὲ δυνατοὶ καλὰ κτήματα κατὰ τὴν χώραν οἰκοδομίαις τε καὶ πολυτελέσι κατασκευαῖς ἀπολωλεκότες, τὸ δὲ μέγιστον, πόλεμον ἀντ’ εἰρήνης ἔχοντες. οὐ μέντοι πρότερόν γε οἱ ξύμπαντες ἐπαύσαντο ἐν ὀργῇ ἔχοντες αὐτὸν πρὶν ἐζημίωσαν χρήμασιν. ὕστερον δ’ αὖθις οὐ πολλῷ, ὅπερ φιλεῖ ὅμιλος ποιεῖν, στρατηγὸν εἵλοντο καὶ πάντα τὰ πράγματα ἐπέτρεψαν, ὧν μὲν περὶ τὰ οἰκεῖα ἕκαστος ἤλγει ἀμβλύτεροι ἤδη ὄντες, ὧν δὲ ἡ ξύμπασα πόλις προσεδεῖτο πλείστου ἄξιον νομίζοντες εἶναι. ὅσον τε γὰρ χρόνον προύστη τῆς πόλεως ἐν τῇ εἰρήνῃ, μετρίως ἐξηγεῖτο καὶ ἀσφαλῶς διεφύλαξεν αὐτήν, καὶ ἐγένετο ἐπ’ ἐκείνου μεγίστη, ἐπειδή τε ὁ πόλεμος κατέστη, ὁ δὲ φαίνεται καὶ ἐν τούτῳ προγνοὺς τὴν δύναμιν. ἐπεβίω δὲ δύο ἔτη καὶ ἓξ μῆνας· καὶ ἐπειδὴ ἀπέθανεν, ἐπὶ πλέον ἔτι ἐγνώσθη ἡ πρόνοια αὐτοῦ ἡ ἐς τὸν πόλεμον. ὁ μὲν γὰρ ἡσυχάζοντάς τε καὶ τὸ ναυτικὸν θεραπεύοντας καὶ ἀρχὴν μὴ ἐπικτωμένους ἐν τῷ πολέμῳ μηδὲ τῇ πόλει κινδυνεύοντας ἔφη περιέσεσθαι· οἱ δὲ ταῦτά τε πάντα ἐς τοὐναντίον ἔπραξαν καὶ ἄλλα ἔξω τοῦ πολέμου δοκοῦντα εἶναι κατὰ τὰς ἰδίας φιλοτιμίας καὶ ἴδια κέρδη κακῶς ἔς τε σφᾶς αὐτοὺς καὶ τοὺς ξυμμάχους ἐπολίτευσαν, ἃ κατορθούμενα μὲν τοῖς ἰδιώταις τιμὴ καὶ ὠφελία μᾶλλον ἦν, σφαλέντα δὲ τῇ πόλει ἐς τὸν πόλεμον βλάβη καθίστατο. αἴτιον δ’ ἦν ὅτι ἐκεῖνος μὲν δυνατὸς ὢν τῷ τε ἀξιώματι καὶ τῇ γνώμῃ χρημάτων τε διαφανῶς ἀδωρότατος γενόμενος κατεῖχε τὸ πλῆθος ἐλευθέρως, καὶ οὐκ ἤγετο μᾶλλον ὑπ’ αὐτοῦ ἢ αὐτὸς ἦγε, διὰ τὸ μὴ κτώμενος ἐξ οὐ προσηκόντων τὴν δύναμιν πρὸς ἡδονήν τι λέγειν, ἀλλ’ ἔχων ἐπ’ ἀξιώσει καὶ πρὸς ὀργήν τι ἀντειπεῖν. ὁπότε γοῦν αἴσθοιτό τι αὐτοὺς παρὰ καιρὸν ὕβρει θαρσοῦντας, λέγων κατέπλησσεν ἐπὶ τὸ φοβεῖσθαι, καὶ δεδιότας αὖ ἀλόγως ἀντικαθίστη πάλιν ἐπὶ τὸ θαρσεῖν. ἐγίγνετό τε λόγῳ μὲν δημοκρατία, ἔργῳ δὲ ὑπὸ τοῦ πρώτου ἀνδρὸς ἀρχή. οἱ δὲ ὕστερον ἴσοι μᾶλλον αὐτοὶ πρὸς ἀλλήλους ὄντες καὶ ὀρεγόμενοι τοῦ πρῶτος ἕκαστος γίγνεσθαι ἐτράποντο καθ’ ἡδονὰς τῷ δήμῳ καὶ τὰ πράγματα ἐνδιδόναι. ἐξ ὧν ἄλλα τε πολλά, ὡς ἐν μεγάλῃ πόλει καὶ ἀρχὴν ἐχούσῃ, ἡμαρτήθη καὶ ὁ ἐς Σικελίαν πλοῦς, ὃς οὐ τοσοῦτον γνώμης ἁμάρτημα ἦν πρὸς οὓς ἐπῇσαν, ὅσον οἱ ἐκπέμψαντες οὐ τὰ πρόσφορα τοῖς οἰχομένοις ἐπιγιγνώσκοντες, ἀλλὰ κατὰ τὰς ἰδίας διαβολὰς περὶ τῆς τοῦ δήμου προστασίας τά τε ἐν τῷ στρατοπέδῳ ἀμβλύτερα ἐποίουν καὶ τὰ περὶ τὴν πόλιν πρῶτον ἐν ἀλλήλοις ἐταράχθησαν. σφαλέντες δὲ ἐν Σικελίᾳ ἄλλῃ τε παρασκευῇ καὶ τοῦ ναυτικοῦ τῷ πλέονι μορίῳ καὶ κατὰ τὴν πόλιν ἤδη ἐν στάσει ὄντες ὅμως † τρία † μὲν ἔτη ἀντεῖχον τοῖς τε πρότερον ὑπάρχουσι πολεμίοις καὶ τοῖς ἀπὸ Σικελίας μετ’ αὐτῶν, καὶ τῶν ξυμμάχων ἔτι τοῖς πλέοσιν ἀφεστηκόσι, Κύρῳ τε ὕστερον βασιλέως παιδὶ προσγενομένῳ, ὃς παρεῖχε χρήματα Πελοποννησίοις ἐς τὸ ναυτικόν, καὶ οὐ πρότερον ἐνέδοσαν ἢ αὐτοὶ ἐν σφίσι κατὰ τὰς ἰδίας διαφορὰς περιπεσόντες ἐσφάλησαν. τοσοῦτον τῷ Περικλεῖ ἐπερίσσευσε τότε ἀφ’ ὧν αὐτὸς προέγνω καὶ πάνυ ἂν ῥᾳδίως περιγενέσθαι τὴν πόλιν Πελοποννησίων αὐτῶν τῷ πολέμῳ.", "st": "2.65"}, {"sp": "N", "t": "οἱ δὲ Λακεδαιμόνιοι καὶ οἱ ξύμμαχοι τοῦ αὐτοῦ θέρους ἐστράτευσαν ναυσὶν ἑκατὸν ἐς Ζάκυνθον τὴν νῆσον, ἣ κεῖται ἀντιπέρας Ἤλιδος· εἰσὶ δὲ Ἀχαιῶν τῶν ἐκ Πελοποννήσου ἄποικοι καὶ Ἀθηναίοις ξυνεμάχουν. ἐπέπλεον δὲ Λακεδαιμονίων χίλιοι ὁπλῖται καὶ Κνῆμος Σπαρτιάτης ναύαρχος. ἀποβάντες δὲ ἐς τὴν γῆν ἐδῄωσαν τὰ πολλά. καὶ ἐπειδὴ οὐ ξυνεχώρουν, ἀπέπλευσαν ἐπ’ οἴκου.", "st": "2.66"}, {"sp": "N", "t": "καὶ τοῦ αὐτοῦ θέρους τελευτῶντος Ἀριστεὺς Κορίνθιος καὶ Λακεδαιμονίων πρέσβεις Ἀνήριστος καὶ Νικόλαος καὶ Πρατόδαμος καὶ Τεγεάτης Τιμαγόρας καὶ Ἀργεῖος ἰδίᾳ Πόλλις, πορευόμενοι ἐς τὴν Ἀσίαν ὡς βασιλέα, εἴ πως πείσειαν αὐτὸν χρήματά τε παρασχεῖν καὶ ξυμπολεμεῖν, ἀφικνοῦνται ὡς Σιτάλκην πρῶτον τὸν Τήρεω ἐς Θρᾴκην, βουλόμενοι πεῖσαί τε αὐτόν, εἰ δύναιντο, μεταστάντα τῆς Ἀθηναίων ξυμμαχίας στρατεῦσαι ἐπὶ τὴν Ποτείδαιαν, οὗ ἦν στράτευμα τῶν Ἀθηναίων πολιορκοῦν, καὶ ᾗπερ ὥρμηντο, δι’ ἐκείνου πορευθῆναι πέραν τοῦ Ἑλλησπόντου ὡς Φαρνάκην τὸν Φαρναβάζου, ὃς αὐτοὺς ἔμελλεν ὡς βασιλέα ἀναπέμψειν. παρατυχόντες δὲ Ἀθηναίων πρέσβεις Λέαρχος Καλλιμάχου καὶ Ἀμεινιάδης Φιλήμονος παρὰ τῷ Σιτάλκῃ πείθουσι τὸν Σάδοκον τὸν γεγενημένον Ἀθηναῖον, Σιτάλκου υἱόν, τοὺς ἄνδρας ἐγχειρίσαι σφίσιν, ὅπως μὴ διαβάντες ὡς βασιλέα τὴν ἐκείνου πόλιν τὸ μέρος βλάψωσιν. ὁ δὲ πεισθεὶς πορευομένους αὐτοὺς διὰ τῆς Θρᾴκης ἐπὶ τὸ πλοῖον ᾧ ἔμελλον τὸν Ἑλλήσποντον περαιώσειν, πρὶν ἐσβαίνειν ξυλλαμβάνει, ἄλλους ξυμπέμψας μετὰ τοῦ Λεάρχου καὶ Ἀμεινιάδου, καὶ ἐκέλευσεν ἐκείνοις παραδοῦναι· οἱ δὲ λαβόντες ἐκόμισαν ἐς τὰς Ἀθήνας. ἀφικομένων δὲ αὐτῶν δείσαντες οἱ Ἀθηναῖοι τὸν Ἀριστέα μὴ αὖθις σφᾶς ἔτι πλείω κακουργῇ διαφυγών, ὅτι καὶ πρὸ τούτων τὰ τῆς Ποτειδαίας καὶ τῶν ἐπὶ Θρᾴκης πάντα ἐφαίνετο πράξας, ἀκρίτους καὶ βουλομένους ἔστιν ἃ εἰπεῖν αὐθημερὸν ἀπέκτειναν πάντας καὶ ἐς φάραγγα ἐσέβαλον, δικαιοῦντες τοῖς αὐτοῖς ἀμύνεσθαι οἷσπερ καὶ οἱ Λακεδαιμόνιοι ὑπῆρξαν, τοὺς ἐμπόρους οὓς ἔλαβον Ἀθηναίων καὶ τῶν ξυμμάχων ἐν ὁλκάσι περὶ Πελοπόννησον πλέοντας ἀποκτείναντες καὶ ἐς φάραγγας ἐσβαλόντες. πάντας γὰρ δὴ κατ’ ἀρχὰς τοῦ πολέμου Λακεδαιμόνιοι ὅσους λάβοιεν ἐν τῇ θαλάσσῃ ὡς πολεμίους διέφθειρον, καὶ τοὺς μετὰ Ἀθηναίων ξυμπολεμοῦντας καὶ τοὺς μηδὲ μεθ’ ἑτέρων.", "st": "2.67"}, {"sp": "N", "t": "κατὰ δὲ τοὺς αὐτοὺς χρόνους, τοῦ θέρους τελευτῶντος, καὶ Ἀμπρακιῶται αὐτοί τε καὶ τῶν βαρβάρων πολλοὺς ἀναστήσαντες ἐστράτευσαν ἐπ’ Ἄργος τὸ Ἀμφιλοχικὸν καὶ τὴν ἄλλην Ἀμφιλοχίαν. ἔχθρα δὲ πρὸς τοὺς Ἀργείους ἀπὸ τοῦδε αὐτοῖς ἤρξατο πρῶτον γενέσθαι. Ἄργος τὸ Ἀμφιλοχικὸν καὶ Ἀμφιλοχίαν τὴν ἄλλην ἔκτισε μὲν μετὰ τὰ Τρωικὰ οἴκαδε ἀναχωρήσας καὶ οὐκ ἀρεσκόμενος τῇ ἐν Ἄργει καταστάσει Ἀμφίλοχος ὁ Ἀμφιάρεω ἐν τῷ Ἀμπρακικῷ κόλπῳ, ὁμώνυμον τῇ ἑαυτοῦ πατρίδι Ἄργος ὀνομάσας (καὶ ἦν ἡ πόλις αὕτη μεγίστη τῆς Ἀμφιλοχίας καὶ τοὺς δυνατωτάτους εἶχεν οἰκήτορας), ὑπὸ ξυμφορῶν δὲ πολλαῖς γενεαῖς ὕστερον πιεζόμενοι Ἀμπρακιώτας ὁμόρους ὄντας τῇ Ἀμφιλοχικῇ ξυνοίκους ἐπηγάγοντο, καὶ ἡλληνίσθησαν τὴν νῦν γλῶσσαν τότε πρῶτον ἀπὸ τῶν Ἀμπρακιωτῶν ξυνοικησάντων· οἱ δὲ ἄλλοι Ἀμφίλοχοι βάρβαροί εἰσιν. ἐκβάλλουσιν οὖν τοὺς Ἀργείους οἱ Ἀμπρακιῶται χρόνῳ καὶ αὐτοὶ ἴσχουσι τὴν πόλιν. οἱ δ’ Ἀμφίλοχοι γενομένου τούτου διδόασιν ἑαυτοὺς Ἀκαρνᾶσι, καὶ προσπαρακαλέσαντες ἀμφότεροι Ἀθηναίους, οἳ αὐτοῖς Φορμίωνά τε στρατηγὸν ἔπεμψαν καὶ ναῦς τριάκοντα, ἀφικομένου [δὲ] τοῦ Φορμίωνος αἱροῦσι κατὰ κράτος Ἄργος καὶ τοὺς Ἀμπρακιώτας ἠνδραπόδισαν, κοινῇ τε ᾤκισαν αὐτὸ Ἀμφίλοχοι καὶ Ἀκαρνᾶνες. μετὰ δὲ τοῦτο ἡ ξυμμαχία πρῶτον ἐγένετο Ἀθηναίοις καὶ Ἀκαρνᾶσιν. οἱ δὲ Ἀμπρακιῶται τὴν μὲν ἔχθραν ἐς τοὺς Ἀργείους ἀπὸ τοῦ ἀνδραποδισμοῦ σφῶν αὐτῶν πρῶτον ἐποιήσαντο, ὕστερον δὲ ἐν τῷ πολέμῳ τήνδε τὴν στρατείαν ποιοῦνται αὑτῶν τε καὶ Χαόνων καὶ ἄλλων τινῶν τῶν πλησιοχώρων βαρβάρων· ἐλθόντες τε πρὸς τὸ Ἄργος τῆς μὲν χώρας ἐκράτουν, τὴν δὲ πόλιν ὡς οὐκ ἐδύναντο ἑλεῖν προσβαλόντες, ἀπεχώρησαν ἐπ’ οἴκου καὶ διελύθησαν κατὰ ἔθνη. τοσαῦτα μὲν ἐν τῷ θέρει ἐγένετο.", "st": "2.68"}, {"sp": "N", "t": "τοῦ δ’ ἐπιγιγνομένου χειμῶνος Ἀθηναῖοι ναῦς ἔστειλαν εἴκοσι μὲν περὶ Πελοπόννησον καὶ Φορμίωνα στρατηγόν, ὃς ὁρμώμενος ἐκ Ναυπάκτου φυλακὴν εἶχε μήτ’ ἐκπλεῖν ἐκ Κορίνθου καὶ τοῦ Κρισαίου κόλπου μηδένα μήτ’ ἐσπλεῖν, ἑτέρας δὲ ἓξ ἐπὶ Καρίας καὶ Λυκίας καὶ Μελήσανδρον στρατηγόν, ὅπως ταῦτά τε ἀργυρολογῶσι καὶ τὸ λῃστικὸν τῶν Πελοποννησίων μὴ ἐῶσιν αὐτόθεν ὁρμώμενον βλάπτειν τὸν πλοῦν τῶν ὁλκάδων τῶν ἀπὸ Φασήλιδος καὶ Φοινίκης καὶ τῆς ἐκεῖθεν ἠπείρου. ἀναβὰς δὲ στρατιᾷ Ἀθηναίων τε τῶν ἀπὸ τῶν νεῶν καὶ τῶν ξυμμάχων ἐς τὴν Λυκίαν ὁ Μελήσανδρος ἀποθνῄσκει καὶ τῆς στρατιᾶς μέρος τι διέφθειρε νικηθεὶς μάχῃ.", "st": "2.69"}, {"sp": "N", "t": "τοῦ δ’ αὐτοῦ χειμῶνος οἱ Ποτειδεᾶται ἐπειδὴ οὐκέτι ἐδύναντο πολιορκούμενοι ἀντέχειν, ἀλλ’ αἵ τε ἐς τὴν Ἀττικὴν ἐσβολαὶ Πελοποννησίων οὐδὲν μᾶλλον ἀπανίστασαν τοὺς Ἀθηναίους ὅ τε σῖτος ἐπελελοίπει, καὶ ἄλλα τε πολλὰ ἐπεγεγένητο αὐτόθι ἤδη βρώσεως πέρι ἀναγκαίας καί τινες καὶ ἀλλήλων ἐγέγευντο, οὕτω δὴ λόγους προσφέρουσι περὶ ξυμβάσεως τοῖς στρατηγοῖς τῶν Ἀθηναίων τοῖς ἐπὶ σφίσι τεταγμένοις, Ξενοφῶντί τε τῷ Εὐριπίδου καὶ Ἑστιοδώρῳ τῷ Ἀριστοκλείδου καὶ Φανομάχῳ τῷ Καλλιμάχου. οἱ δὲ προσεδέξαντο, ὁρῶντες μὲν τῆς στρατιᾶς τὴν ταλαιπωρίαν ἐν χωρίῳ χειμερινῷ, ἀνηλωκυίας δὲ ἤδη τῆς πόλεως δισχίλια τάλαντα ἐς τὴν πολιορκίαν. ἐπὶ τοῖσδε οὖν ξυνέβησαν, ἐξελθεῖν αὐτοὺς καὶ παῖδας καὶ γυναῖκας καὶ τοὺς ἐπικούρους ξὺν ἑνὶ ἱματίῳ, γυναῖκας δὲ ξὺν δυοῖν, καὶ ἀργύριόν τι ῥητὸν ἔχοντας ἐφόδιον. καὶ οἱ μὲν ὑπόσπονδοι ἐξῆλθον ἔς τε τὴν Χαλκιδικὴν καὶ ᾗ ἕκαστος ἐδύνατο· Ἀθηναῖοι δὲ τούς τε στρατηγοὺς ἐπῃτιάσαντο ὅτι ἄνευ αὐτῶν ξυνέβησαν (ἐνόμιζον γὰρ ἂν κρατῆσαι τῆς πόλεως ᾗ ἐβούλοντο), καὶ ὕστερον ἐποίκους ἔπεμψαν ἑαυτῶν ἐς τὴν Ποτείδαιαν καὶ κατῴκισαν. ταῦτα μὲν ἐν τῷ χειμῶνι ἐγένετο, καὶ [τὸ] δεύτερον ἔτος ἐτελεύτα τῷ πολέμῳ τῷδε ὃν Θουκυδίδης ξυνέγραψεν.", "st": "2.70"}, {"sp": "N", "t": "τοῦ δ’ ἐπιγιγνομένου θέρους οἱ Πελοποννήσιοι καὶ οἱ ξύμμαχοι ἐς μὲν τὴν Ἀττικὴν οὐκ ἐσέβαλον, ἐστράτευσαν δὲ ἐπὶ Πλάταιαν· ἡγεῖτο δὲ Ἀρχίδαμος ὁ Ζευξιδάμου Λακεδαιμονίων βασιλεύς. καὶ καθίσας τὸν στρατὸν ἔμελλε δῃώσειν τὴν γῆν· οἱ δὲ Πλαταιῆς εὐθὺς πρέσβεις πέμψαντες πρὸς αὐτὸν ἔλεγον τοιάδε· ‘Ἀρχίδαμε καὶ Λακεδαιμόνιοι, οὐ δίκαια ποιεῖτε οὐδ’ ἄξια οὔτε ὑμῶν οὔτε πατέρων ὧν ἐστέ, ἐς γῆν τὴν Πλαταιῶν στρατεύοντες. Παυσανίας γὰρ ὁ Κλεομβρότου Λακεδαιμόνιος ἐλευθερώσας τὴν Ἑλλάδα ἀπὸ τῶν Μήδων μετὰ Ἑλλήνων τῶν ἐθελησάντων ξυνάρασθαι τὸν κίνδυνον τῆς μάχης ἣ παρ’ ἡμῖν ἐγένετο, θύσας ἐν τῇ Πλαταιῶν ἀγορᾷ ἱερὰ Διὶ ἐλευθερίῳ καὶ ξυγκαλέσας πάντας τοὺς ξυμμάχους ἀπεδίδου Πλαταιεῦσι γῆν καὶ πόλιν τὴν σφετέραν ἔχοντας αὐτονόμους οἰκεῖν, στρατεῦσαί τε μηδένα ποτὲ ἀδίκως ἐπ’ αὐτοὺς μηδ’ ἐπὶ δουλείᾳ· εἰ δὲ μή, ἀμύνειν τοὺς παρόντας ξυμμάχους κατὰ δύναμιν. τάδε μὲν ἡμῖν πατέρες οἱ ὑμέτεροι ἔδοσαν ἀρετῆς ἕνεκα καὶ προθυμίας τῆς ἐν ἐκείνοις τοῖς κινδύνοις γενομένης, ὑμεῖς δὲ τἀναντία δρᾶτε· μετὰ γὰρ Θηβαίων τῶν ἡμῖν ἐχθίστων ἐπὶ δουλείᾳ τῇ ἡμετέρᾳ ἥκετε. μάρτυρας δὲ θεοὺς τούς τε ὁρκίους τότε γενομένους ποιούμενοι καὶ τοὺς ὑμετέρους πατρῴους καὶ ἡμετέρους ἐγχωρίους, λέγομεν ὑμῖν γῆν τὴν Πλαταιίδα μὴ ἀδικεῖν μηδὲ παραβαίνειν τοὺς ὅρκους, ἐᾶν δὲ οἰκεῖν αὐτονόμους καθάπερ Παυσανίας ἐδικαίωσεν.’", "st": "2.71"}, {"sp": "N", "t": "τοσαῦτα εἰπόντων τῶν Πλαταιῶν Ἀρχίδαμος ὑπολαβὼν εἶπεν· ‘δίκαια λέγετε, ὦ ἄνδρες Πλαταιῆς, ἢν ποιῆτε ὁμοῖα τοῖς λόγοις. καθάπερ γὰρ Παυσανίας ὑμῖν παρέδωκεν, αὐτοί τε αὐτονομεῖσθε καὶ τοὺς ἄλλους ξυνελευθεροῦτε, ὅσοι μετασχόντες τῶν τότε κινδύνων ὑμῖν τε ξυνώμοσαν καὶ εἰσὶ νῦν ὑπ’ Ἀθηναίοις, παρασκευή τε τοσήδε καὶ πόλεμος γεγένηται αὐτῶν ἕνεκα καὶ τῶν ἄλλων ἐλευθερώσεως. ἧς μάλιστα μὲν μετασχόντες καὶ αὐτοὶ ἐμμείνατε τοῖς ὅρκοις· εἰ δὲ μή, ἅπερ καὶ πρότερον ἤδη προυκαλεσάμεθα, ἡσυχίαν ἄγετε νεμόμενοι τὰ ὑμέτερα αὐτῶν, καὶ ἔστε μηδὲ μεθ’ ἑτέρων, δέχεσθε δὲ ἀμφοτέρους φίλους, ἐπὶ πολέμῳ δὲ μηδετέρους. καὶ τάδε ἡμῖν ἀρκέσει.’ ὁ μὲν Ἀρχίδαμος τοσαῦτα εἶπεν· οἱ δὲ Πλαταιῶν πρέσβεις ἀκούσαντες ταῦτα ἐσῆλθον ἐς τὴν πόλιν, καὶ τῷ πλήθει τὰ ῥηθέντα κοινώσαντες ἀπεκρίναντο αὐτῷ ὅτι ἀδύνατα σφίσιν εἴη ποιεῖν ἃ προκαλεῖται ἄνευ Ἀθηναίων (παῖδες γὰρ σφῶν καὶ γυναῖκες παρ’ ἐκείνοις εἶεν), δεδιέναι δὲ καὶ περὶ τῇ πάσῃ πόλει μὴ ἐκείνων ἀποχωρησάντων Ἀθηναῖοι ἐλθόντες σφίσιν οὐκ ἐπιτρέπωσιν, ἢ Θηβαῖοι, ὡς ἔνορκοι ὄντες κατὰ τὸ ἀμφοτέρους δέχεσθαι, αὖθις σφῶν τὴν πόλιν πειράσωσι καταλαβεῖν. ὁ δὲ θαρσύνων αὐτοὺς πρὸς ταῦτα ἔφη· ‘ὑμεῖς δὲ πόλιν μὲν καὶ οἰκίας ἡμῖν παράδοτε τοῖς Λακεδαιμονίοις, καὶ γῆς ὅρους ἀποδείξατε καὶ δένδρα ἀριθμῷ τὰ ὑμέτερα καὶ ἄλλο εἴ τι δυνατὸν ἐς ἀριθμὸν ἐλθεῖν· αὐτοὶ δὲ μεταχωρήσατε ὅποι βούλεσθε, ἕως ἂν ὁ πόλεμος ᾖ· ἐπειδὰν δὲ παρέλθῃ, ἀποδώσομεν ὑμῖν ἃ ἂν παραλάβωμεν. μέχρι δὲ τοῦδε ἕξομεν παρακαταθήκην, ἐργαζόμενοι καὶ φορὰν φέροντες ἣ ἂν ὑμῖν μέλλῃ ἱκανὴ ἔσεσθαι.’", "st": "2.72"}, {"sp": "N", "t": "οἱ δ’ ἀκούσαντες ἐσῆλθον αὖθις ἐς τὴν πόλιν, καὶ βουλευσάμενοι μετὰ τοῦ πλήθους ἔλεξαν ὅτι βούλονται ἃ προκαλεῖται Ἀθηναίοις κοινῶσαι πρῶτον, καὶ ἢν πείθωσιν αὐτούς, ποιεῖν ταῦτα· μέχρι δὲ τούτου σπείσασθαι σφίσιν ἐκέλευον καὶ τὴν γῆν μὴ δῃοῦν. ὁ δὲ ἡμέρας τε ἐσπείσατο ἐν αἷς εἰκὸς ἦν κομισθῆναι, καὶ τὴν γῆν οὐκ ἔτεμνεν. ἐλθόντες δὲ οἱ [Πλαταιῆς] πρέσβεις ὡς τοὺς Ἀθηναίους καὶ βουλευσάμενοι μετ’ αὐτῶν πάλιν ἦλθον ἀπαγγέλλοντες τοῖς ἐν τῇ πόλει τοιάδε· ‘οὔτ’ ἐν τῷ πρὸ τοῦ χρόνῳ, ὦ ἄνδρες Πλαταιῆς, ἀφ’ οὗ ξύμμαχοι ἐγενόμεθα, Ἀθηναῖοί φασιν ἐν οὐδενὶ ὑμᾶς προέσθαι ἀδικουμένους οὔτε νῦν περιόψεσθαι, βοηθήσειν δὲ κατὰ δύναμιν. ἐπισκήπτουσί τε ὑμῖν πρὸς τῶν ὅρκων οὓς οἱ πατέρες ὤμοσαν μηδὲν νεωτερίζειν περὶ τὴν ξυμμαχίαν.’", "st": "2.73"}, {"sp": "N", "t": "τοιαῦτα τῶν πρέσβεων ἀπαγγειλάντων οἱ Πλαταιῆς ἐβουλεύσαντο Ἀθηναίους μὴ προδιδόναι, ἀλλ’ ἀνέχεσθαι καὶ γῆν τεμνομένην, εἰ δεῖ, ὁρῶντας καὶ ἄλλο πάσχοντας ὅτι ἂν ξυμβαίνῃ· ἐξελθεῖν τε μηδένα ἔτι, ἀλλ’ ἀπὸ τοῦ τείχους ἀποκρίνασθαι ὅτι ἀδύνατα σφίσι ποιεῖν ἐστὶν ἃ Λακεδαιμόνιοι προκαλοῦνται. ὡς δὲ ἀπεκρίναντο, ἐντεῦθεν δὴ πρῶτον μὲν ἐς ἐπιμαρτυρίαν καὶ θεῶν καὶ ἡρώων τῶν ἐγχωρίων Ἀρχίδαμος ὁ βασιλεὺς κατέστη, λέγων ὧδε· ‘θεοὶ ὅσοι γῆν τὴν Πλαταιίδα ἔχετε καὶ ἥρωες, ξυνίστορές ἐστε ὅτι οὔτε τὴν ἀρχὴν ἀδίκως, ἐκλιπόντων δὲ τῶνδε προτέρων τὸ ξυνώμοτον, ἐπὶ γῆν τήνδε ἤλθομεν, ἐν ᾗ οἱ πατέρες ἡμῶν εὐξάμενοι ὑμῖν Μήδων ἐκράτησαν καὶ παρέσχετε αὐτὴν εὐμενῆ ἐναγωνίσασθαι τοῖς Ἕλλησιν, οὔτε νῦν, ἤν τι ποιῶμεν, ἀδικήσομεν· προκαλεσάμενοι γὰρ πολλὰ καὶ εἰκότα οὐ τυγχάνομεν. ξυγγνώμονες δὲ ἔστε τῆς μὲν ἀδικίας κολάζεσθαι τοῖς ὑπάρχουσι προτέροις, τῆς δὲ τιμωρίας τυγχάνειν τοῖς ἐπιφέρουσι νομίμως.’", "st": "2.74"}, {"sp": "N", "t": "τοσαῦτα ἐπιθειάσας καθίστη ἐς πόλεμον τὸν στρατόν, καὶ πρῶτον μὲν περιεσταύρωσαν αὐτοὺς τοῖς δένδρεσιν ἃ ἔκοψαν, τοῦ μηδένα ἐπεξιέναι, ἔπειτα χῶμα ἔχουν πρὸς τὴν πόλιν, ἐλπίζοντες ταχίστην αἵρεσιν ἔσεσθαι αὐτῶν στρατεύματος τοσούτου ἐργαζομένου. ξύλα μὲν οὖν τέμνοντες ἐκ τοῦ Κιθαιρῶνος παρῳκοδόμουν ἑκατέρωθεν, φορμηδὸν ἀντὶ τοίχων τιθέντες, ὅπως μὴ διαχέοιτο ἐπὶ πολὺ τὸ χῶμα· ἐφόρουν δὲ ὕλην ἐς αὐτὸ καὶ λίθους καὶ γῆν καὶ εἴ τι ἄλλο ἁνύτειν μέλλοι ἐπιβαλλόμενον. ἡμέρας δὲ ἔχουν † ἑβδομήκοντα † καὶ νύκτας ξυνεχῶς, διῃρημένοι κατ’ ἀναπαύλας, ὥστε τοὺς μὲν φέρειν, τοὺς δὲ ὕπνον τε καὶ σῖτον αἱρεῖσθαι· Λακεδαιμονίων τε οἱ ξεναγοὶ ἑκάστης πόλεως ξυνεφεστῶτες ἠνάγκαζον ἐς τὸ ἔργον. οἱ δὲ Πλαταιῆς ὁρῶντες τὸ χῶμα αἰρόμενον, ξύλινον τεῖχος ξυνθέντες καὶ ἐπιστήσαντες τῷ ἑαυτῶν τείχει ᾗ προσεχοῦτο, ἐσῳκοδόμουν ἐς αὐτὸ πλίνθους ἐκ τῶν ἐγγὺς οἰκιῶν καθαιροῦντες. ξύνδεσμος δ’ ἦν αὐτοῖς τὰ ξύλα, τοῦ μὴ ὑψηλὸν γιγνόμενον ἀσθενὲς εἶναι τὸ οἰκοδόμημα, καὶ προκαλύμματα εἶχε δέρσεις καὶ διφθέρας, ὥστε τοὺς ἐργαζομένους καὶ τὰ ξύλα μήτε πυρφόροις οἰστοῖς βάλλεσθαι ἐν ἀσφαλείᾳ τε εἶναι. ᾔρετο δὲ τὸ ὕψος τοῦ τείχους μέγα, καὶ τὸ χῶμα οὐ σχολαίτερον ἀντανῄει αὐτῷ. καὶ οἱ Πλαταιῆς τοιόνδε τι ἐπινοοῦσιν· διελόντες τοῦ τείχους ᾗ προσέπιπτε τὸ χῶμα ἐσεφόρουν τὴν γῆν.", "st": "2.75"}, {"sp": "N", "t": "οἱ δὲ Πελοποννήσιοι αἰσθόμενοι ἐν ταρσοῖς καλάμου πηλὸν ἐνίλλοντες ἐσέβαλλον ἐς τὸ διῃρημένον, ὅπως μὴ διαχεόμενον ὥσπερ ἡ γῆ φοροῖτο. οἱ δὲ ταύτῃ ἀποκλῃόμενοι τοῦτο μὲν ἐπέσχον, ὑπόνομον δὲ ἐκ τῆς πόλεως ὀρύξαντες καὶ ξυντεκμηράμενοι ὑπὸ τὸ χῶμα ὑφεῖλκον αὖθις παρὰ σφᾶς τὸν χοῦν· καὶ ἐλάνθανον ἐπὶ πολὺ τοὺς ἔξω, ὥστε ἐπιβάλλοντας ἧσσον ἁνύτειν ὑπαγομένου αὐτοῖς κάτωθεν τοῦ χώματος καὶ ἱζάνοντος αἰεὶ ἐπὶ τὸ κενούμενον. δεδιότες δὲ μὴ οὐδ’ οὕτω δύνωνται ὀλίγοι πρὸς πολλοὺς ἀντέχειν, προσεπεξηῦρον τόδε· τὸ μὲν μέγα οἰκοδόμημα ἐπαύσαντο ἐργαζόμενοι τὸ κατὰ τὸ χῶμα, ἔνθεν δὲ καὶ ἔνθεν αὐτοῦ ἀρξάμενοι ἀπὸ τοῦ βραχέος τείχους ἐκ τοῦ ἐντὸς μηνοειδὲς ἐς τὴν πόλιν ἐσῳκοδόμουν, ὅπως, εἰ τὸ μέγα τεῖχος ἁλίσκοιτο, τοῦτ’ ἀντέχοι, καὶ δέοι τοὺς ἐναντίους αὖθις πρὸς αὐτὸ χοῦν καὶ προχωροῦντας ἔσω διπλάσιόν τε πόνον ἔχειν καὶ ἐν ἀμφιβόλῳ μᾶλλον γίγνεσθαι. ἅμα δὲ τῇ χώσει καὶ μηχανὰς προσῆγον οἱ Πελοποννήσιοι τῇ πόλει, μίαν μὲν ἣ τοῦ μεγάλου οἰκοδομήματος κατὰ τὸ χῶμα προσαχθεῖσα ἐπὶ μέγα τε κατέσεισε καὶ τοὺς Πλαταιᾶς ἐφόβησεν, ἄλλας δὲ ἄλλῃ τοῦ τείχους, ἃς βρόχους τε περιβάλλοντες ἀνέκλων οἱ Πλαταιῆς, καὶ δοκοὺς μεγάλας ἀρτήσαντες ἁλύσεσι μακραῖς σιδηραῖς ἀπὸ τῆς τομῆς ἑκατέρωθεν ἀπὸ κεραιῶν δύο ἐπικεκλιμένων καὶ ὑπερτεινουσῶν ὑπὲρ τοῦ τείχους ἀνελκύσαντες ἐγκαρσίας, ὁπότε προσπεσεῖσθαί πῃ μέλλοι ἡ μηχανή, ἀφίεσαν τὴν δοκὸν χαλαραῖς ταῖς ἁλύσεσι καὶ οὐ διὰ χειρὸς ἔχοντες, ἡ δὲ ῥύμῃ ἐμπίπτουσα ἀπεκαύλιζε τὸ προῦχον τῆς ἐμβολῆς.", "st": "2.76"}, {"sp": "N", "t": "μετὰ δὲ τοῦτο οἱ Πελοποννήσιοι, ὡς αἵ τε μηχαναὶ οὐδὲν ὠφέλουν καὶ τῷ χώματι τὸ ἀντιτείχισμα ἐγίγνετο, νομίσαντες ἄπορον εἶναι ἀπὸ τῶν παρόντων δεινῶν ἑλεῖν τὴν πόλιν πρὸς τὴν περιτείχισιν παρεσκευάζοντο. πρότερον δὲ πυρὶ ἔδοξεν αὐτοῖς πειρᾶσαι εἰ δύναιντο πνεύματος γενομένου ἐπιφλέξαι τὴν πόλιν οὖσαν οὐ μεγάλην· πᾶσαν γὰρ δὴ ἰδέαν ἐπενόουν, εἴ πως σφίσιν ἄνευ δαπάνης καὶ πολιορκίας προσαχθείη. φοροῦντες δὲ ὕλης φακέλους παρέβαλον ἀπὸ τοῦ χώματος ἐς τὸ μεταξὺ πρῶτον τοῦ τείχους καὶ τῆς προσχώσεως, ταχὺ δὲ πλήρους γενομένου διὰ πολυχειρίαν ἐπιπαρένησαν καὶ τῆς ἄλλης πόλεως ὅσον ἐδύναντο ἀπὸ τοῦ μετεώρου πλεῖστον ἐπισχεῖν, ἐμβαλόντες δὲ πῦρ ξὺν θείῳ καὶ πίσσῃ ἧψαν τὴν ὕλην. καὶ ἐγένετο φλὸξ τοσαύτη ὅσην οὐδείς πω ἔς γε ἐκεῖνον τὸν χρόνον χειροποίητον εἶδεν· ἤδη γὰρ ἐν ὄρεσιν ὕλη τριφθεῖσα ὑπ’ ἀνέμων πρὸς αὑτὴν ἀπὸ ταὐτομάτου πῦρ καὶ φλόγα ἀπ’ αὐτοῦ ἀνῆκεν. τοῦτο δὲ μέγα τε ἦν καὶ τοὺς Πλαταιᾶς τἆλλα διαφυγόντας ἐλαχίστου ἐδέησε διαφθεῖραι· ἐντὸς γὰρ πολλοῦ χωρίου τῆς πόλεως οὐκ ἦν πελάσαι, πνεῦμά τε εἰ ἐπεγένετο αὐτῇ ἐπίφορον, ὅπερ καὶ ἤλπιζον οἱ ἐναντίοι, οὐκ ἂν διέφυγον. νῦν δὲ καὶ τόδε λέγεται ξυμβῆναι, ὕδωρ [ἐξ οὐρανοῦ] πολὺ καὶ βροντὰς γενομένας σβέσαι τὴν φλόγα καὶ οὕτω παυσθῆναι τὸν κίνδυνον.", "st": "2.77"}, {"sp": "N", "t": "οἱ δὲ Πελοποννήσιοι ἐπειδὴ καὶ τούτου διήμαρτον, μέρος μέν τι καταλιπόντες τοῦ στρατοῦ, τὸ δὲ πλέον ἀφέντες περιετείχιζον τὴν πόλιν κύκλῳ, διελόμενοι κατὰ πόλεις τὸ χωρίον· τάφρος δὲ ἐντός τε ἦν καὶ ἔξωθεν ἐξ ἧς ἐπλινθεύσαντο. καὶ ἐπειδὴ πᾶν ἐξείργαστο περὶ ἀρκτούρου ἐπιτολάς, καταλιπόντες φυλακὰς τοῦ ἡμίσεος τείχους (τὸ δὲ ἥμισυ Βοιωτοὶ ἐφύλασσον) ἀνεχώρησαν τῷ στρατῷ καὶ διελύθησαν κατὰ πόλεις. Πλαταιῆς δὲ παῖδας μὲν καὶ γυναῖκας καὶ τοὺς πρεσβυτάτους τε καὶ πλῆθος τὸ ἀχρεῖον τῶν ἀνθρώπων πρότερον ἐκκεκομισμένοι ἦσαν ἐς τὰς Ἀθήνας, αὐτοὶ δὲ ἐπολιορκοῦντο ἐγκαταλελειμμένοι τετρακόσιοι, Ἀθηναίων δὲ ὀγδοήκοντα, γυναῖκες δὲ δέκα καὶ ἑκατὸν σιτοποιοί. τοσοῦτοι ἦσαν οἱ ξύμπαντες ὅτε ἐς τὴν πολιορκίαν καθίσταντο, καὶ ἄλλος οὐδεὶς ἦν ἐν τῷ τείχει οὔτε δοῦλος οὔτ’ ἐλεύθερος. τοιαύτη μὲν ἡ Πλαταιῶν πολιορκία κατεσκευάσθη.", "st": "2.78"}, {"sp": "N", "t": "τοῦ δ’ αὐτοῦ θέρους καὶ ἅμα τῇ τῶν Πλαταιῶν ἐπιστρατείᾳ Ἀθηναῖοι δισχιλίοις ὁπλίταις ἑαυτῶν καὶ ἱππεῦσι διακοσίοις ἐπεστράτευσαν ἐπὶ Χαλκιδέας τοὺς ἐπὶ Θρᾴκης καὶ Βοττιαίους ἀκμάζοντος τοῦ σίτου· ἐστρατήγει δὲ Ξενοφῶν ὁ Εὐριπίδου τρίτος αὐτός. ἐλθόντες δὲ ὑπὸ Σπάρτωλον τὴν Βοττικὴν τὸν σῖτον διέφθειραν. ἐδόκει δὲ καὶ προσχωρήσειν ἡ πόλις ὑπό τινων ἔνδοθεν πρασσόντων. προσπεμψάντων δὲ ἐς Ὄλυνθον τῶν οὐ ταὐτὰ βουλομένων ὁπλῖταί τε ἦλθον καὶ στρατιὰ ἐς φυλακήν· ἧς ἐπεξελθούσης ἐκ τῆς Σπαρτώλου ἐς μάχην καθίστανται οἱ Ἀθηναῖοι ὑπ’ αὐτῇ τῇ πόλει. καὶ οἱ μὲν ὁπλῖται τῶν Χαλκιδέων καὶ ἐπίκουροί τινες μετ’ αὐτῶν νικῶνται ὑπὸ τῶν Ἀθηναίων καὶ ἀναχωροῦσιν ἐς τὴν Σπάρτωλον, οἱ δὲ ἱππῆς τῶν Χαλκιδέων καὶ ψιλοὶ νικῶσι τοὺς τῶν Ἀθηναίων ἱππέας καὶ ψιλούς· εἶχον δέ τινας οὐ πολλοὺς πελταστὰς ἐκ τῆς Κρουσίδος γῆς καλουμένης. ἄρτι δὲ τῆς μάχης γεγενημένης ἐπιβοηθοῦσιν ἄλλοι πελτασταὶ ἐκ τῆς Ὀλύνθου. καὶ οἱ ἐκ τῆς Σπαρτώλου ψιλοὶ ὡς εἶδον, θαρσήσαντες τοῖς τε προσγιγνομένοις καὶ ὅτι πρότερον οὐχ ἥσσηντο, ἐπιτίθενται αὖθις μετὰ τῶν Χαλκιδέων ἱππέων καὶ τῶν προσβοηθησάντων τοῖς Ἀθηναίοις· καὶ ἀναχωροῦσι πρὸς τὰς δύο τάξεις ἃς κατέλιπον παρὰ τοῖς σκευοφόροις. καὶ ὁπότε μὲν ἐπίοιεν οἱ Ἀθηναῖοι, ἐνεδίδοσαν, ἀναχωροῦσι δ’ ἐνέκειντο καὶ ἐσηκόντιζον. οἵ τε ἱππῆς τῶν Χαλκιδέων προσιππεύοντες ᾗ δοκοίη προσέβαλλον, καὶ οὐχ ἥκιστα φοβήσαντες ἔτρεψαν τοὺς Ἀθηναίους καὶ ἐπεδίωξαν ἐπὶ πολύ. καὶ οἱ μὲν Ἀθηναῖοι ἐς τὴν Ποτείδαιαν καταφεύγουσι, καὶ ὕστερον τοὺς νεκροὺς ὑποσπόνδους κομισάμενοι ἐς τὰς Ἀθήνας ἀναχωροῦσι τῷ περιόντι τοῦ στρατοῦ· ἀπέθανον δὲ αὐτῶν τριάκοντα καὶ τετρακόσιοι καὶ οἱ στρατηγοὶ πάντες. οἱ δὲ Χαλκιδῆς καὶ Βοττιαῖοι τροπαῖόν τε ἔστησαν καὶ τοὺς νεκροὺς τοὺς αὑτῶν ἀνελόμενοι διελύθησαν κατὰ πόλεις.", "st": "2.79"}, {"sp": "N", "t": "τοῦ δ’ αὐτοῦ θέρους, οὐ πολλῷ ὕστερον τούτων, Ἀμπρακιῶται καὶ Χάονες βουλόμενοι Ἀκαρνανίαν τὴν πᾶσαν καταστρέψασθαι καὶ Ἀθηναίων ἀποστῆσαι πείθουσι Λακεδαιμονίους ναυτικόν τε παρασκευάσασθαι ἐκ τῆς ξυμμαχίδος καὶ ὁπλίτας χιλίους πέμψαι ἐπ’ Ἀκαρνανίαν, λέγοντες ὅτι, ἢν ναυσὶ καὶ πεζῷ ἅμα μετὰ σφῶν ἔλθωσιν, ἀδυνάτων ὄντων ξυμβοηθεῖν τῶν ἀπὸ θαλάσσης Ἀκαρνάνων ῥᾳδίως Ἀκαρνανίαν σχόντες καὶ τῆς Ζακύνθου καὶ Κεφαλληνίας κρατήσουσι, καὶ ὁ περίπλους οὐκέτι ἔσοιτο Ἀθηναίοις ὁμοίως περὶ Πελοπόννησον· ἐλπίδα δ’ εἶναι καὶ Ναύπακτον λαβεῖν. οἱ δὲ Λακεδαιμόνιοι πεισθέντες Κνῆμον μὲν ναύαρχον ἔτι ὄντα καὶ τοὺς ὁπλίτας ἐπὶ ναυσὶν ὀλίγαις εὐθὺς πέμπουσι, τῷ δὲ ναυτικῷ περιήγγειλαν παρασκευασαμένῳ ὡς τάχιστα πλεῖν ἐς Λευκάδα. ἦσαν δὲ Κορίνθιοι ξυμπροθυμούμενοι μάλιστα τοῖς Ἀμπρακιώταις ἀποίκοις οὖσιν. καὶ τὸ μὲν ναυτικὸν ἔκ τε Κορίνθου καὶ Σικυῶνος καὶ τῶν ταύτῃ χωρίων ἐν παρασκευῇ ἦν, τὸ δ’ ἐκ Λευκάδος καὶ Ἀνακτορίου καὶ Ἀμπρακίας πρότερον ἀφικόμενον ἐν Λευκάδι περιέμενεν. Κνῆμος δὲ καὶ οἱ μετ’ αὐτοῦ χίλιοι ὁπλῖται ἐπειδὴ ἐπεραιώθησαν λαθόντες Φορμίωνα, ὃς ἦρχε τῶν εἴκοσι νεῶν τῶν Ἀττικῶν αἳ περὶ Ναύπακτον ἐφρούρουν, εὐθὺς παρεσκευάζοντο τὴν κατὰ γῆν στρατείαν. καὶ αὐτῷ παρῆσαν Ἑλλήνων μὲν Ἀμπρακιῶται καὶ Λευκάδιοι καὶ Ἀνακτόριοι καὶ οὓς αὐτὸς ἔχων ἦλθε χίλιοι Πελοποννησίων, βάρβαροι δὲ Χάονες χίλιοι ἀβασίλευτοι, ὧν ἡγοῦντο ἐπετησίῳ προστατείᾳ ἐκ τοῦ ἀρχικοῦ γένους Φώτιος καὶ Νικάνωρ. ξυνεστρατεύοντο δὲ μετὰ Χαόνων καὶ Θεσπρωτοὶ ἀβασίλευτοι. Μολοσσοὺς δὲ ἦγε καὶ Ἀτιντᾶνας Σαβύλινθος ἐπίτροπος ὢν Θάρυπος τοῦ βασιλέως ἔτι παιδὸς ὄντος, καὶ Παραυαίους Ὄροιδος βασιλεύων. Ὀρέσται δὲ χίλιοι, ὧν ἐβασίλευεν Ἀντίοχος, μετὰ Παραυαίων ξυνεστρατεύοντο Ὀροίδῳ Ἀντιόχου ἐπιτρέψαντος. ἔπεμψε δὲ καὶ Περδίκκας κρύφα τῶν Ἀθηναίων χιλίους Μακεδόνων, οἳ ὕστερον ἦλθον. τούτῳ τῷ στρατῷ ἐπορεύετο Κνῆμος οὐ περιμείνας τὸ ἀπὸ Κορίνθου ναυτικόν, καὶ διὰ τῆς Ἀργείας ἰόντες Λιμναίαν, κώμην ἀτείχιστον, ἐπόρθησαν. ἀφικνοῦνταί τε ἐπὶ Στράτον, πόλιν μεγίστην τῆς Ἀκαρνανίας, νομίζοντες, εἰ ταύτην πρώτην λάβοιεν, ῥᾳδίως σφίσι τἆλλα προσχωρήσειν.", "st": "2.80"}, {"sp": "N", "t": "Ἀκαρνᾶνες δὲ αἰσθόμενοι κατά τε γῆν πολλὴν στρατιὰν ἐσβεβληκυῖαν ἔκ τε θαλάσσης ναυσὶν ἅμα τοὺς πολεμίους παρεσομένους, οὔτε ξυνεβοήθουν ἐφύλασσόν τε τὰ αὑτῶν ἕκαστοι, παρά τε Φορμίωνα ἔπεμπον κελεύοντες ἀμύνειν· ὁ δὲ ἀδύνατος ἔφη εἶναι ναυτικοῦ ἐκ Κορίνθου μέλλοντος ἐκπλεῖν Ναύπακτον ἐρήμην ἀπολιπεῖν. οἱ δὲ Πελοποννήσιοι καὶ οἱ ξύμμαχοι τρία τέλη ποιήσαντες σφῶν αὐτῶν ἐχώρουν πρὸς τὴν τῶν Στρατίων πόλιν, ὅπως ἐγγὺς στρατοπεδευσάμενοι, εἰ μὴ λόγοις πείθοιεν, ἔργῳ πειρῷντο τοῦ τείχους. καὶ μέσον μὲν ἔχοντες προσῇσαν Χάονες καὶ οἱ ἄλλοι βάρβαροι, ἐκ δεξιᾶς δ’ αὐτῶν Λευκάδιοι καὶ Ἀνακτόριοι καὶ οἱ μετὰ τούτων, ἐν ἀριστερᾷ δὲ Κνῆμος καὶ οἱ Πελοποννήσιοι καὶ Ἀμπρακιῶται· διεῖχον δὲ πολὺ ἀπ’ ἀλλήλων καὶ ἔστιν ὅτε οὐδὲ ἑωρῶντο. καὶ οἱ μὲν Ἕλληνες τεταγμένοι τε προσῇσαν καὶ διὰ φυλακῆς ἔχοντες, ἕως ἐστρατοπεδεύσαντο ἐν ἐπιτηδείῳ· οἱ δὲ Χάονες σφίσι τε αὐτοῖς πιστεύοντες καὶ ἀξιούμενοι ὑπὸ τῶν ἐκείνῃ ἠπειρωτῶν μαχιμώτατοι εἶναι οὔτε ἐπέσχον τὸ στρατόπεδον καταλαβεῖν, χωρήσαντές τε ῥύμῃ μετὰ τῶν ἄλλων βαρβάρων ἐνόμισαν αὐτοβοεὶ ἂν τὴν πόλιν ἑλεῖν καὶ αὑτῶν τὸ ἔργον γενέσθαι. γνόντες δ’ αὐτοὺς οἱ Στράτιοι ἔτι προσιόντας καὶ ἡγησάμενοι, μεμονωμένων εἰ κρατήσειαν, οὐκ ἂν ἔτι σφίσι τοὺς Ἕλληνας ὁμοίως προσελθεῖν, προλοχίζουσι δὴ τὰ περὶ τὴν πόλιν ἐνέδραις, καὶ ἐπειδὴ ἐγγὺς ἦσαν, ἔκ τε τῆς πόλεως ὁμόσε χωρήσαντες καὶ ἐκ τῶν ἐνεδρῶν προσπίπτουσιν. καὶ ἐς φόβον καταστάντων διαφθείρονταί τε πολλοὶ τῶν Χαόνων, καὶ οἱ ἄλλοι βάρβαροι ὡς εἶδον αὐτοὺς ἐνδόντας, οὐκέτι ὑπέμειναν, ἀλλ’ ἐς φυγὴν κατέστησαν. τῶν δὲ Ἑλληνικῶν στρατοπέδων οὐδέτερον ᾔσθετο τῆς μάχης διὰ τὸ πολὺ προελθεῖν αὐτοὺς καὶ στρατόπεδον οἰηθῆναι καταληψομένους ἐπείγεσθαι. ἐπεὶ δ’ ἐνέκειντο φεύγοντες οἱ βάρβαροι, ἀνελάμβανόν τε αὐτοὺς καὶ ξυναγαγόντες τὰ στρατόπεδα ἡσύχαζον αὐτοῦ τὴν ἡμέραν, ἐς χεῖρας μὲν οὐκ ἰόντων σφίσι τῶν Στρατίων διὰ τὸ μήπω τοὺς ἄλλους Ἀκαρνᾶνας ξυμβεβοηθηκέναι, ἄπωθεν δὲ σφενδονώντων καὶ ἐς ἀπορίαν καθιστάντων· οὐ γὰρ ἦν ἄνευ ὅπλων κινηθῆναι. δοκοῦσι δὲ οἱ Ἀκαρνᾶνες κράτιστοι εἶναι τοῦτο ποιεῖν.", "st": "2.81"}, {"sp": "N", "t": "ἐπειδὴ δὲ νὺξ ἐγένετο, ἀναχωρήσας ὁ Κνῆμος τῇ στρατιᾷ κατὰ τάχος ἐπὶ τὸν Ἄναπον ποταμόν, ὃς ἀπέχει σταδίους ὀγδοήκοντα Στράτου, τούς τε νεκροὺς κομίζεται τῇ ὑστεραίᾳ ὑποσπόνδους, καὶ Οἰνιαδῶν ξυμπαραγενομένων κατὰ φιλίαν ἀναχωρεῖ παρ’ αὐτοὺς πρὶν τὴν ξυμβοήθειαν ἐλθεῖν. κἀκεῖθεν ἐπ’ οἴκου ἀπῆλθον ἕκαστοι. οἱ δὲ Στράτιοι τροπαῖον ἔστησαν τῆς μάχης τῆς πρὸς τοὺς βαρβάρους.", "st": "2.82"}, {"sp": "N", "t": "τὸ δ’ ἐκ τῆς Κορίνθου καὶ τῶν ἄλλων ξυμμάχων τῶν ἐκ τοῦ Κρισαίου κόλπου ναυτικόν, ὃ ἔδει παραγενέσθαι τῷ Κνήμῳ, ὅπως μὴ ξυμβοηθῶσιν οἱ ἀπὸ θαλάσσης ἄνω Ἀκαρνᾶνες, οὐ παραγίγνεται, ἀλλ’ ἠναγκάσθησαν περὶ τὰς αὐτὰς ἡμέρας τῆς ἐν Στράτῳ μάχης ναυμαχῆσαι πρὸς Φορμίωνα καὶ τὰς εἴκοσι ναῦς τῶν Ἀθηναίων αἳ ἐφρούρουν ἐν Ναυπάκτῳ. ὁ γὰρ Φορμίων παραπλέοντας αὐτοὺς ἔξω τοῦ κόλπου ἐτήρει, βουλόμενος ἐν τῇ εὐρυχωρίᾳ ἐπιθέσθαι. οἱ δὲ Κορίνθιοι καὶ οἱ ξύμμαχοι ἔπλεον μὲν οὐχ ὡς ἐπὶ ναυμαχίᾳ, ἀλλὰ στρατιωτικώτερον παρεσκευασμένοι ἐς τὴν Ἀκαρνανίαν καὶ οὐκ ἂν οἰόμενοι πρὸς ἑπτὰ καὶ τεσσαράκοντα ναῦς τὰς σφετέρας τολμῆσαι τοὺς Ἀθηναίους εἴκοσι ταῖς ἑαυτῶν ναυμαχίαν ποιήσασθαι· ἐπειδὴ μέντοι ἀντιπαραπλέοντάς τε ἑώρων αὐτούς, παρὰ γῆν σφῶν κομιζομένων, καὶ ἐκ Πατρῶν τῆς Ἀχαΐας πρὸς τὴν ἀντιπέρας ἤπειρον διαβάλλοντες ἐπ’ Ἀκαρνανίας κατεῖδον τοὺς Ἀθηναίους ἀπὸ τῆς Χαλκίδος καὶ τοῦ Εὐήνου ποταμοῦ προσπλέοντας σφίσι καὶ οὐκ ἔλαθον νυκτὸς ἀφορμισάμενοι, οὕτω δὴ ἀναγκάζονται ναυμαχεῖν κατὰ μέσον τὸν πορθμόν. στρατηγοὶ δὲ ἦσαν μὲν καὶ κατὰ πόλεις ἑκάστων οἳ παρεσκευάζοντο, Κορινθίων δὲ Μαχάων καὶ Ἰσοκράτης καὶ Ἀγαθαρχίδας. καὶ οἱ μὲν Πελοποννήσιοι ἐτάξαντο κύκλον τῶν νεῶν ὡς μέγιστον οἷοί τ’ ἦσαν μὴ διδόντες διέκπλουν, τὰς πρῴρας μὲν ἔξω, ἔσω δὲ τὰς πρύμνας, καὶ τά τε λεπτὰ πλοῖα ἃ ξυνέπλει ἐντὸς ποιοῦνται καὶ πέντε ναῦς τὰς ἄριστα πλεούσας, ὅπως ἐκπλέοιεν διὰ βραχέος παραγιγνόμενοι, εἴ πῃ προσπίπτοιεν οἱ ἐναντίοι.", "st": "2.83"}, {"sp": "N", "t": "οἱ δ’ Ἀθηναῖοι κατὰ μίαν ναῦν τεταγμένοι περιέπλεον αὐτοὺς κύκλῳ καὶ ξυνῆγον ἐς ὀλίγον, ἐν χρῷ αἰεὶ παραπλέοντες καὶ δόκησιν παρέχοντες αὐτίκα ἐμβαλεῖν· προείρητο δ’ αὐτοῖς ὑπὸ Φορμίωνος μὴ ἐπιχειρεῖν πρὶν ἂν αὐτὸς σημήνῃ. ἤλπιζε γὰρ αὐτῶν οὐ μενεῖν τὴν τάξιν, ὥσπερ ἐν γῇ πεζήν, ἀλλὰ ξυμπεσεῖσθαι πρὸς ἀλλήλας τὰς ναῦς καὶ τὰ πλοῖα ταραχὴν παρέξειν, εἴ τ’ ἐκπνεύσειεν ἐκ τοῦ κόλπου τὸ πνεῦμα, ὅπερ ἀναμένων τε περιέπλει καὶ εἰώθει γίγνεσθαι ἐπὶ τὴν ἕω, οὐδένα χρόνον ἡσυχάσειν αὐτούς· καὶ τὴν ἐπιχείρησιν ἐφ’ ἑαυτῷ τε ἐνόμιζεν εἶναι, ὁπόταν βούληται, τῶν νεῶν ἄμεινον πλεουσῶν, καὶ τότε καλλίστην γίγνεσθαι. ὡς δὲ τό τε πνεῦμα κατῄει καὶ αἱ νῆες ἐν ὀλίγῳ ἤδη οὖσαι ὑπ’ ἀμφοτέρων, τοῦ τε ἀνέμου τῶν τε πλοίων, ἅμα προσκειμένων ἐταράσσοντο, καὶ ναῦς τε νηὶ προσέπιπτε καὶ τοῖς κοντοῖς διεωθοῦντο, βοῇ τε χρώμενοι καὶ πρὸς ἀλλήλους ἀντιφυλακῇ τε καὶ λοιδορίᾳ οὐδὲν κατήκουον οὔτε τῶν παραγγελλομένων οὔτε τῶν κελευστῶν, καὶ τὰς κώπας ἀδύνατοι ὄντες ἐν κλύδωνι ἀναφέρειν ἄνθρωποι ἄπειροι τοῖς κυβερνήταις ἀπειθεστέρας τὰς ναῦς παρεῖχον, τότε δὴ κατὰ τὸν καιρὸν τοῦτον σημαίνει, καὶ οἱ Ἀθηναῖοι προσπεσόντες πρῶτον μὲν καταδύουσι τῶν στρατηγίδων νεῶν μίαν, ἔπειτα δὲ καὶ τὰς ἄλλας ᾗ χωρήσειαν διέφθειρον, καὶ κατέστησαν ἐς ἀλκὴν μὲν μηδένα τρέπεσθαι αὐτῶν ὑπὸ τῆς ταραχῆς, φεύγειν δὲ ἐς Πάτρας καὶ Δύμην τῆς Ἀχαΐας. οἱ δὲ Ἀθηναῖοι καταδιώξαντες καὶ ναῦς δώδεκα λαβόντες τούς τε ἄνδρας ἐξ αὐτῶν τοὺς πλείστους ἀνελόμενοι ἐς Μολύκρειον ἀπέπλεον, καὶ τροπαῖον στήσαντες ἐπὶ τῷ Ῥίῳ καὶ ναῦν ἀναθέντες τῷ Ποσειδῶνι ἀνεχώρησαν ἐς Ναύπακτον. παρέπλευσαν δὲ καὶ οἱ Πελοποννήσιοι εὐθὺς ταῖς περιλοίποις τῶν νεῶν ἐκ τῆς Δύμης καὶ Πατρῶν ἐς Κυλλήνην τὸ Ἠλείων ἐπίνειον· καὶ ἀπὸ Λευκάδος Κνῆμος καὶ αἱ ἐκείνων νῆες, ἃς ἔδει ταύταις ξυμμεῖξαι, ἀφικνοῦνται μετὰ τὴν ἐν Στράτῳ μάχην ἐς τὴν Κυλλήνην.", "st": "2.84"}, {"sp": "N", "t": "πέμπουσι δὲ καὶ οἱ Λακεδαιμόνιοι τῷ Κνήμῳ ξυμβούλους ἐπὶ τὰς ναῦς Τιμοκράτη καὶ Βρασίδαν καὶ Λυκόφρονα, κελεύοντες ἄλλην ναυμαχίαν βελτίω παρασκευάζεσθαι καὶ μὴ ὑπ’ ὀλίγων νεῶν εἴργεσθαι τῆς θαλάσσης. ἐδόκει γὰρ αὐτοῖς ἄλλως τε καὶ πρῶτον ναυμαχίας πειρασαμένοις πολὺς ὁ παράλογος εἶναι, καὶ οὐ τοσούτῳ ᾤοντο σφῶν τὸ ναυτικὸν λείπεσθαι, γεγενῆσθαι δέ τινα μαλακίαν, οὐκ ἀντιτιθέντες τὴν Ἀθηναίων ἐκ πολλοῦ ἐμπειρίαν τῆς σφετέρας δι’ ὀλίγου μελέτης. ὀργῇ οὖν ἀπέστελλον. οἱ δὲ ἀφικόμενοι μετὰ τοῦ Κνήμου ναῦς τε προσπεριήγγειλαν κατὰ πόλεις καὶ τὰς προϋπαρχούσας ἐξηρτύοντο ὡς ἐπὶ ναυμαχίαν. πέμπει δὲ καὶ ὁ Φορμίων ἐς τὰς Ἀθήνας τήν τε παρασκευὴν αὐτῶν ἀγγελοῦντας καὶ περὶ τῆς ναυμαχίας ἣν ἐνίκησαν φράσοντας, καὶ κελεύων αὑτῷ ναῦς ὅτι πλείστας διὰ τάχους ἀποστεῖλαι, ὡς καθ’ ἡμέραν ἑκάστην ἐλπίδος οὔσης αἰεὶ ναυμαχήσειν. οἱ δὲ ἀποπέμπουσιν εἴκοσι ναῦς αὐτῷ, τῷ δὲ κομίζοντι αὐτὰς προσεπέστειλαν ἐς Κρήτην πρῶτον ἀφικέσθαι. Νικίας γὰρ Κρὴς Γορτύνιος πρόξενος ὢν πείθει αὐτοὺς ἐπὶ Κυδωνίαν πλεῦσαι, φάσκων προσποιήσειν αὐτὴν οὖσαν πολεμίαν· ἐπῆγε δὲ Πολιχνίταις χαριζόμενος ὁμόροις τῶν Κυδωνιατῶν. καὶ ὁ μὲν λαβὼν τὰς ναῦς ᾤχετο ἐς Κρήτην, καὶ μετὰ τῶν Πολιχνιτῶν ἐδῄου τὴν γῆν τῶν Κυδωνιατῶν, καὶ ὑπ’ ἀνέμων καὶ ἀπλοίας ἐνδιέτριψεν οὐκ ὀλίγον χρόνον·", "st": "2.85"}, {"sp": "N", "t": "οἱ δ’ ἐν τῇ Κυλλήνῃ Πελοποννήσιοι, ἐν τούτῳ ἐν ᾧ οἱ Ἀθηναῖοι περὶ Κρήτην κατείχοντο, παρεσκευασμένοι ὡς ἐπὶ ναυμαχίαν παρέπλευσαν ἐς Πάνορμον τὸν Ἀχαϊκόν, οὗπερ αὐτοῖς ὁ κατὰ γῆν στρατὸς τῶν Πελοποννησίων προσεβεβοηθήκει. παρέπλευσε δὲ καὶ ὁ Φορμίων ἐπὶ τὸ Ῥίον τὸ Μολυκρικὸν καὶ ὡρμίσατο ἔξω αὐτοῦ ναυσὶν εἴκοσιν, αἷσπερ καὶ ἐναυμάχησεν. ἦν δὲ τοῦτο μὲν τὸ Ῥίον φίλιον τοῖς Ἀθηναίοις, τὸ δ’ ἕτερον Ῥίον ἐστὶν ἀντιπέρας, τὸ ἐν τῇ Πελοποννήσῳ· διέχετον δὲ ἀπ’ ἀλλήλων σταδίους μάλιστα ἑπτὰ τῆς θαλάσσης, τοῦ δὲ Κρισαίου κόλπου στόμα τοῦτό ἐστιν. ἐπὶ οὖν τῷ Ῥίῳ τῷ Ἀχαϊκῷ οἱ Πελοποννήσιοι, ἀπέχοντι οὐ πολὺ τοῦ Πανόρμου, ἐν ᾧ αὐτοῖς ὁ πεζὸς ἦν, ὡρμίσαντο καὶ αὐτοὶ ναυσὶν ἑπτὰ καὶ ἑβδομήκοντα, ἐπειδὴ καὶ τοὺς Ἀθηναίους εἶδον. καὶ ἐπὶ μὲν ἓξ ἢ ἑπτὰ ἡμέρας ἀνθώρμουν ἀλλήλοις μελετῶντές τε καὶ παρασκευαζόμενοι τὴν ναυμαχίαν, γνώμην ἔχοντες οἱ μὲν μὴ ἐκπλεῖν ἔξω τῶν Ῥίων ἐς τὴν εὐρυχωρίαν, φοβούμενοι τὸ πρότερον πάθος, οἱ δὲ μὴ ἐσπλεῖν ἐς τὰ στενά, νομίζοντες πρὸς ἐκείνων εἶναι τὴν ἐν ὀλίγῳ ναυμαχίαν. ἔπειτα ὁ Κνῆμος καὶ ὁ Βρασίδας καὶ οἱ ἄλλοι τῶν Πελοποννησίων στρατηγοί, βουλόμενοι ἐν τάχει τὴν ναυμαχίαν ποιῆσαι πρίν τι καὶ ἀπὸ τῶν Ἀθηναίων ἐπιβοηθῆσαι, ξυνεκάλεσαν τοὺς στρατιώτας πρῶτον, καὶ ὁρῶντες αὐτῶν τοὺς πολλοὺς διὰ τὴν προτέραν ἧσσαν φοβουμένους καὶ οὐ προθύμους ὄντας παρεκελεύσαντο καὶ ἔλεξαν τοιάδε.", "st": "2.86"}, {"sp": "N", "t": "‘ἡ μὲν γενομένη ναυμαχία, ὦ ἄνδρες Πελοποννήσιοι, εἴ τις ἄρα δι’ αὐτὴν ὑμῶν φοβεῖται τὴν μέλλουσαν, οὐχὶ δικαίαν ἔχει τέκμαρσιν τὸ ἐκφοβῆσαι. τῇ τε γὰρ παρασκευῇ ἐνδεὴς ἐγένετο, ὥσπερ ἴστε, καὶ οὐχὶ ἐς ναυμαχίαν μᾶλλον ἢ ἐπὶ στρατείαν ἐπλέομεν· ξυνέβη δὲ καὶ τὰ ἀπὸ τῆς τύχης οὐκ ὀλίγα ἐναντιωθῆναι, καί πού τι καὶ ἡ ἀπειρία πρῶτον ναυμαχοῦντας ἔσφηλεν. ὥστε οὐ κατὰ τὴν ἡμετέραν κακίαν τὸ ἡσσᾶσθαι προσεγένετο, οὐδὲ δίκαιον τῆς γνώμης τὸ μὴ κατὰ κράτος νικηθέν, ἔχον δέ τινα ἐν αὑτῷ ἀντιλογίαν, τῆς γε ξυμφορᾶς τῷ ἀποβάντι ἀμβλύνεσθαι, νομίσαι δὲ ταῖς μὲν τύχαις ἐνδέχεσθαι σφάλλεσθαι τοὺς ἀνθρώπους, ταῖς δὲ γνώμαις τοὺς αὐτοὺς αἰεὶ ὀρθῶς ἀνδρείους εἶναι, καὶ μὴ ἀπειρίαν τοῦ ἀνδρείου παρόντος προβαλλομένους εἰκότως ἂν ἔν τινι κακοὺς γενέσθαι. ὑμῶν δὲ οὐδ’ ἡ ἀπειρία τοσοῦτον λείπεται ὅσον τόλμῃ προύχετε· τῶνδε δὲ ἡ ἐπιστήμη, ἣν μάλιστα φοβεῖσθε, ἀνδρείαν μὲν ἔχουσα καὶ μνήμην ἕξει ἐν τῷ δεινῷ ἐπιτελεῖν ἃ ἔμαθεν, ἄνευ δὲ εὐψυχίας οὐδεμία τέχνη πρὸς τοὺς κινδύνους ἰσχύει. φόβος γὰρ μνήμην ἐκπλήσσει, τέχνη δὲ ἄνευ ἀλκῆς οὐδὲν ὠφελεῖ. πρὸς μὲν οὖν τὸ ἐμπειρότερον αὐτῶν τὸ τολμηρότερον ἀντιτάξασθε, πρὸς δὲ τὸ διὰ τὴν ἧσσαν δεδιέναι τὸ ἀπαράσκευοι τότε τυχεῖν. περιγίγνεται δὲ ὑμῖν πλῆθός τε νεῶν καὶ πρὸς τῇ γῇ οἰκείᾳ οὔσῃ ὁπλιτῶν παρόντων ναυμαχεῖν· τὰ δὲ πολλὰ τῶν πλεόνων καὶ ἄμεινον παρεσκευασμένων τὸ κράτος ἐστίν. ὥστε οὐδὲ καθ’ ἓν εὑρίσκομεν εἰκότως ἂν ἡμᾶς σφαλλομένους· καὶ ὅσα ἡμάρτομεν πρότερον, νῦν αὐτὰ ταῦτα προσγενόμενα διδασκαλίαν παρέξει. θαρσοῦντες οὖν καὶ κυβερνῆται καὶ ναῦται τὸ καθ’ ἑαυτὸν ἕκαστος ἕπεσθε, χώραν μὴ προλείποντες ᾗ ἄν τις προσταχθῇ. τῶν δὲ πρότερον ἡγεμόνων οὐ χεῖρον τὴν ἐπιχείρησιν ἡμεῖς παρασκευάσομεν, καὶ οὐκ ἐνδώσομεν πρόφασιν οὐδενὶ κακῷ γενέσθαι· ἢν δέ τις ἄρα καὶ βουληθῇ, κολασθήσεται τῇ πρεπούσῃ ζημίᾳ, οἱ δὲ ἀγαθοὶ τιμήσονται τοῖς προσήκουσιν ἄθλοις τῆς ἀρετῆς.’", "st": "2.87"}, {"sp": "N", "t": "τοιαῦτα μὲν τοῖς Πελοποννησίοις οἱ ἄρχοντες παρεκελεύσαντο. ὁ δὲ Φορμίων δεδιὼς καὶ αὐτὸς τὴν τῶν στρατιωτῶν ὀρρωδίαν καὶ αἰσθόμενος ὅτι τὸ πλῆθος τῶν νεῶν κατὰ σφᾶς αὐτοὺς ξυνιστάμενοι ἐφοβοῦντο, ἐβούλετο ξυγκαλέσας θαρσῦναί τε καὶ παραίνεσιν ἐν τῷ παρόντι ποιήσασθαι. πρότερον μὲν γὰρ αἰεὶ αὐτοῖς ἔλεγε καὶ προπαρεσκεύαζε τὰς γνώμας ὡς οὐδὲν αὐτοῖς πλῆθος νεῶν τοσοῦτον, ἢν ἐπιπλέῃ, ὅτι οὐχ ὑπομενετέον ἐστί, καὶ οἱ στρατιῶται ἐκ πολλοῦ ἐν σφίσιν αὐτοῖς τὴν ἀξίωσιν ταύτην εἰλήφεσαν, μηδένα ὄχλον Ἀθηναῖοι ὄντες Πελοποννησίων νεῶν ὑποχωρεῖν· τότε δὲ πρὸς τὴν παροῦσαν ὄψιν ὁρῶν αὐτοὺς ἀθυμοῦντας ἐβούλετο ὑπόμνησιν ποιήσασθαι τοῦ θαρσεῖν, καὶ ξυγκαλέσας τοὺς Ἀθηναίους ἔλεγε τοιάδε.", "st": "2.88"}, {"sp": "N", "t": "‘ὁρῶν ὑμᾶς, ὦ ἄνδρες στρατιῶται, πεφοβημένους τὸ πλῆθος τῶν ἐναντίων ξυνεκάλεσα, οὐκ ἀξιῶν τὰ μὴ δεινὰ ἐν ὀρρωδίᾳ ἔχειν. οὗτοι γὰρ πρῶτον μὲν διὰ τὸ προνενικῆσθαι καὶ μηδ’ αὐτοὶ οἴεσθαι ὁμοῖοι ἡμῖν εἶναι τὸ πλῆθος τῶν νεῶν καὶ οὐκ ἀπὸ τοῦ ἴσου παρεσκευάσαντο· ἔπειτα ᾧ μάλιστα πιστεύοντες προσέρχονται, ὡς προσῆκον σφίσιν ἀνδρείοις εἶναι, οὐ δι’ ἄλλο τι θαρσοῦσιν ἢ διὰ τὴν ἐν τῷ πεζῷ ἐμπειρίαν τὰ πλείω κατορθοῦντες, καὶ οἴονται σφίσι καὶ ἐν τῷ ναυτικῷ ποιήσειν τὸ αὐτό. τὸ δ’ ἐκ τοῦ δικαίου ἡμῖν μᾶλλον νῦν περιέσται, εἴπερ καὶ τούτοις ἐν ἐκείνῳ, ἐπεὶ εὐψυχίᾳ γε οὐδὲν προφέρουσι, τῷ δὲ ἑκάτεροί τι εἶναι ἐμπειρότεροι θρασύτεροί ἐσμεν. Λακεδαιμόνιοί τε ἡγούμενοι αὐτῶν διὰ τὴν σφετέραν δόξαν ἄκοντας προσάγουσι τοὺς πολλοὺς ἐς τὸν κίνδυνον, ἐπεὶ οὐκ ἄν ποτε ἐνεχείρησαν ἡσσηθέντες παρὰ πολὺ αὖθις ναυμαχεῖν. μὴ δὴ αὐτῶν τὴν τόλμαν δείσητε. πολὺ δὲ ὑμεῖς ἐκείνοις πλείω φόβον παρέχετε καὶ πιστότερον κατά τε τὸ προνενικηκέναι καὶ ὅτι οὐκ ἂν ἡγοῦνται μὴ μέλλοντάς τι ἄξιον τοῦ παρὰ πολὺ πράξειν ἀνθίστασθαι ὑμᾶς. ἀντίπαλοι μὲν γὰρ οἱ πλείους, ὥσπερ οὗτοι, τῇ δυνάμει τὸ πλέον πίσυνοι ἢ τῇ γνώμῃ ἐπέρχονται· οἱ δὲ ἐκ πολλῷ ὑποδεεστέρων, καὶ ἅμα οὐκ ἀναγκαζόμενοι, μέγα τι τῆς διανοίας τὸ βέβαιον ἔχοντες ἀντιτολμῶσιν. ἃ λογιζόμενοι οὗτοι τῷ οὐκ εἰκότι πλέον πεφόβηνται ἡμᾶς ἢ τῇ κατὰ λόγον παρασκευῇ. πολλὰ δὲ καὶ στρατόπεδα ἤδη ἔπεσεν ὑπ’ ἐλασσόνων τῇ ἀπειρίᾳ, ἔστι δὲ ἃ καὶ τῇ ἀτολμίᾳ· ὧν οὐδετέρου ἡμεῖς νῦν μετέχομεν. τὸν δὲ ἀγῶνα οὐκ ἐν τῷ κόλπῳ ἑκὼν εἶναι ποιήσομαι οὐδ’ ἐσπλεύσομαι ἐς αὐτόν. ὁρῶ γὰρ ὅτι πρὸς πολλὰς ναῦς ἀνεπιστήμονας ὀλίγαις ναυσὶν ἐμπείροις καὶ ἄμεινον πλεούσαις ἡ στενοχωρία οὐ ξυμφέρει. οὔτε γὰρ ἂν ἐπιπλεύσειέ τις ὡς χρὴ ἐς ἐμβολήν, μὴ ἔχων τὴν πρόσοψιν τῶν πολεμίων ἐκ πολλοῦ, οὔτ’ ἂν ἀποχωρήσειεν ἐν δέοντι πιεζόμενος· διέκπλοι τε οὐκ εἰσὶν οὐδ’ ἀναστροφαί, ἅπερ νεῶν ἄμεινον πλεουσῶν ἔργα ἐστίν, ἀλλὰ ἀνάγκη ἂν εἴη τὴν ναυμαχίαν πεζομαχίαν καθίστασθαι, καὶ ἐν τούτῳ αἱ πλείους νῆες κρείσσους γίγνονται. τούτων μὲν οὖν ἐγὼ ἕξω τὴν πρόνοιαν κατὰ τὸ δυνατόν· ὑμεῖς δὲ εὔτακτοι παρὰ ταῖς ναυσὶ μένοντες τά τε παραγγελλόμενα ὀξέως δέχεσθε, ἄλλως τε καὶ δι’ ὀλίγου τῆς ἐφορμήσεως οὔσης, καὶ ἐν τῷ ἔργῳ κόσμον καὶ σιγὴν περὶ πλείστου ἡγεῖσθε, ὃ ἔς τε τὰ πολλὰ τῶν πολεμίων ξυμφέρει καὶ ναυμαχίᾳ οὐχ ἥκιστα, ἀμύνεσθέ τε τούσδε ἀξίως τῶν προειργασμένων. ὁ δὲ ἀγὼν μέγας ὑμῖν, ἢ καταλῦσαι Πελοποννησίων τὴν ἐλπίδα τοῦ ναυτικοῦ ἢ ἐγγυτέρω καταστῆσαι Ἀθηναίοις τὸν φόβον περὶ τῆς θαλάσσης. ἀναμιμνῄσκω δ’ αὖ ὑμᾶς ὅτι νενικήκατε αὐτῶν τοὺς πολλούς· ἡσσημένων δὲ ἀνδρῶν οὐκ ἐθέλουσιν αἱ γνῶμαι πρὸς τοὺς αὐτοὺς κινδύνους ὁμοῖαι εἶναι.’", "st": "2.89"}, {"sp": "N", "t": "τοιαῦτα δὲ καὶ ὁ Φορμίων παρεκελεύσατο. οἱ δὲ Πελοποννήσιοι, ἐπειδὴ αὐτοῖς οἱ Ἀθηναῖοι οὐκ ἐπέπλεον ἐς τὸν κόλπον καὶ τὰ στενά, βουλόμενοι ἄκοντας ἔσω προαγαγεῖν αὐτούς, ἀναγαγόμενοι ἅμα ἕῳ ἔπλεον, ἐπὶ τεσσάρων ταξάμενοι τὰς ναῦς ἐπὶ τὴν ἑαυτῶν γῆν, ἔσω ἐπὶ τοῦ κόλπου, δεξιῷ κέρᾳ ἡγουμένῳ, ὥσπερ καὶ ὥρμουν· ἐπὶ δ’ αὐτῷ εἴκοσιν ἔταξαν τὰς ἄριστα πλεούσας, ὅπως, εἰ ἄρα νομίσας ἐπὶ τὴν Ναύπακτον αὐτοὺς πλεῖν ὁ Φορμίων καὶ αὐτὸς ἐπιβοηθῶν ταύτῃ παραπλέοι, μὴ διαφύγοιεν πλέοντα τὸν ἐπίπλουν σφῶν οἱ Ἀθηναῖοι ἔξω τοῦ ἑαυτῶν κέρως, ἀλλ’ αὗται αἱ νῆες περικλῄσειαν. ὁ δέ, ὅπερ ἐκεῖνοι προσεδέχοντο, φοβηθεὶς περὶ τῷ χωρίῳ ἐρήμῳ ὄντι, ὡς ἑώρα ἀναγομένους αὐτούς, ἄκων καὶ κατὰ σπουδὴν ἐμβιβάσας ἔπλει παρὰ τὴν γῆν· καὶ ὁ πεζὸς ἅμα τῶν Μεσσηνίων παρεβοήθει. ἰδόντες δὲ οἱ Πελοποννήσιοι κατὰ μίαν ἐπὶ κέρως παραπλέοντας καὶ ἤδη ὄντας ἐντὸς τοῦ κόλπου τε καὶ πρὸς τῇ γῇ, ὅπερ ἐβούλοντο μάλιστα, ἀπὸ σημείου ἑνὸς ἄφνω ἐπιστρέψαντες τὰς ναῦς μετωπηδὸν ἔπλεον, ὡς εἶχε τάχους ἕκαστος, ἐπὶ τοὺς Ἀθηναίους, καὶ ἤλπιζον πάσας τὰς ναῦς ἀπολήψεσθαι. τῶν δὲ ἕνδεκα μέν τινες αἵπερ ἡγοῦντο ὑπεκφεύγουσι τὸ κέρας τῶν Πελοποννησίων καὶ τὴν ἐπιστροφὴν ἐς τὴν εὐρυχωρίαν· τὰς δ’ ἄλλας ἐπικαταλαβόντες ἐξέωσάν τε πρὸς τὴν γῆν ὑποφευγούσας καὶ διέφθειραν, ἄνδρας τε τῶν Ἀθηναίων ἀπέκτειναν ὅσοι μὴ ἐξένευσαν αὐτῶν. καὶ τῶν νεῶν τινὰς ἀναδούμενοι εἷλκον κενάς (μίαν δὲ αὐτοῖς ἀνδράσιν εἷλον ἤδη), τὰς δέ τινας οἱ Μεσσήνιοι παραβοηθήσαντες καὶ ἐπεσβαίνοντες ξὺν τοῖς ὅπλοις ἐς τὴν θάλασσαν καὶ ἐπιβάντες ἀπὸ τῶν καταστρωμάτων μαχόμενοι ἀφείλοντο ἑλκομένας ἤδη.", "st": "2.90"}, {"sp": "N", "t": "ταύτῃ μὲν οὖν οἱ Πελοποννήσιοι ἐκράτουν τε καὶ διέφθειραν τὰς Ἀττικὰς ναῦς· αἱ δὲ εἴκοσι νῆες αὐτῶν αἱ ἀπὸ τοῦ δεξιοῦ κέρως ἐδίωκον τὰς ἕνδεκα ναῦς τῶν Ἀθηναίων αἵπερ ὑπεξέφυγον τὴν ἐπιστροφὴν ἐς τὴν εὐρυχωρίαν. καὶ φθάνουσιν αὐτοὺς πλὴν μιᾶς νεὼς προκαταφυγοῦσαι ἐς τὴν Ναύπακτον, καὶ σχοῦσαι ἀντίπρῳροι κατὰ τὸ Ἀπολλώνιον παρεσκευάζοντο ἀμυνούμενοι, ἢν ἐς τὴν γῆν ἐπὶ σφᾶς πλέωσιν. οἱ δὲ παραγενόμενοι ὕστερον ἐπαιάνιζόν τε ἅμα πλέοντες ὡς νενικηκότες, καὶ τὴν μίαν ναῦν τῶν Ἀθηναίων τὴν ὑπόλοιπον ἐδίωκε Λευκαδία ναῦς μία πολὺ πρὸ τῶν ἄλλων. ἔτυχε δὲ ὁλκὰς ὁρμοῦσα μετέωρος, περὶ ἣν ἡ Ἀττικὴ ναῦς φθάσασα καὶ περιπλεύσασα τῇ Λευκαδίᾳ διωκούσῃ ἐμβάλλει μέσῃ καὶ καταδύει. τοῖς μὲν οὖν Πελοποννησίοις γενομένου τούτου ἀπροσδοκήτου τε καὶ παρὰ λόγον φόβος ἐμπίπτει, καὶ ἅμα ἀτάκτως διώκοντες διὰ τὸ κρατεῖν αἱ μέν τινες τῶν νεῶν καθεῖσαι τὰς κώπας ἐπέστησαν τοῦ πλοῦ, ἀξύμφορον δρῶντες πρὸς τὴν ἐξ ὀλίγου ἀντεφόρμησιν, βουλόμενοι τὰς πλείους περιμεῖναι, αἱ δὲ καὶ ἐς βράχεα ἀπειρίᾳ χωρίων ὤκειλαν.", "st": "2.91"}, {"sp": "N", "t": "τοὺς δ’ Ἀθηναίους ἰδόντας ταῦτα γιγνόμενα θάρσος τε ἔλαβε, καὶ ἀπὸ ἑνὸς κελεύσματος ἐμβοήσαντες ἐπ’ αὐτοὺς ὥρμησαν. οἱ δὲ διὰ τὰ ὑπάρχοντα ἁμαρτήματα καὶ τὴν παροῦσαν ἀταξίαν ὀλίγον μὲν χρόνον ὑπέμειναν, ἔπειτα δὲ ἐτράποντο ἐς τὸν Πάνορμον, ὅθενπερ ἀνηγάγοντο. ἐπιδιώκοντες δὲ οἱ Ἀθηναῖοι τάς τε ἐγγὺς οὔσας μάλιστα ναῦς ἔλαβον ἓξ καὶ τὰς ἑαυτῶν ἀφείλοντο, ἃς ἐκεῖνοι πρὸς τῇ γῇ διαφθείραντες τὸ πρῶτον ἀνεδήσαντο· ἄνδρας τε τοὺς μὲν ἀπέκτειναν, τινὰς δὲ καὶ ἐζώγρησαν. ἐπὶ δὲ τῆς Λευκαδίας νεώς, ἣ περὶ τὴν ὁλκάδα κατέδυ, Τιμοκράτης ὁ Λακεδαιμόνιος πλέων, ὡς ἡ ναῦς διεφθείρετο, ἔσφαξεν ἑαυτόν, καὶ ἐξέπεσεν ἐς τὸν Ναυπακτίων λιμένα. ἀναχωρήσαντες δὲ οἱ Ἀθηναῖοι τροπαῖον ἔστησαν, ὅθεν ἀναγαγόμενοι ἐκράτησαν, καὶ τοὺς νεκροὺς καὶ τὰ ναυάγια ὅσα πρὸς τῇ ἑαυτῶν ἦν ἀνείλοντο, καὶ τοῖς ἐναντίοις τὰ ἐκείνων ὑπόσπονδα ἀπέδοσαν. ἔστησαν δὲ καὶ οἱ Πελοποννήσιοι τροπαῖον ὡς νενικηκότες τῆς τροπῆς, ἃς πρὸς τῇ γῇ διέφθειραν ναῦς· καὶ ἥνπερ ἔλαβον ναῦν, ἀνέθεσαν ἐπὶ τὸ Ῥίον τὸ Ἀχαϊκὸν παρὰ τὸ τροπαῖον. μετὰ δὲ ταῦτα φοβούμενοι τὴν ἀπὸ τῶν Ἀθηναίων βοήθειαν ὑπὸ νύκτα ἐσέπλευσαν ἐς τὸν κόλπον τὸν Κρισαῖον καὶ Κόρινθον ἅπαντες πλὴν Λευκαδίων. καὶ οἱ ἐκ τῆς Κρήτης Ἀθηναῖοι ταῖς εἴκοσι ναυσίν, αἷς ἔδει πρὸ τῆς ναυμαχίας τῷ Φορμίωνι παραγενέσθαι, οὐ πολλῷ ὕστερον τῆς ἀναχωρήσεως τῶν νεῶν ἀφικνοῦνται ἐς τὴν Ναύπακτον. καὶ τὸ θέρος ἐτελεύτα.", "st": "2.92"}, {"sp": "N", "t": "πρὶν δὲ διαλῦσαι τὸ ἐς Κόρινθόν τε καὶ τὸν Κρισαῖον κόλπον ἀναχωρῆσαν ναυτικόν, ὁ Κνῆμος καὶ ὁ Βρασίδας καὶ οἱ ἄλλοι ἄρχοντες τῶν Πελοποννησίων ἀρχομένου τοῦ χειμῶνος ἐβούλοντο διδαξάντων Μεγαρέων ἀποπειρᾶσαι τοῦ Πειραιῶς τοῦ λιμένος τῶν Ἀθηναίων· ἦν δὲ ἀφύλακτος καὶ ἄκλῃστος εἰκότως διὰ τὸ ἐπικρατεῖν πολὺ τῷ ναυτικῷ. ἐδόκει δὲ λαβόντα τῶν ναυτῶν ἕκαστον τὴν κώπην καὶ τὸ ὑπηρέσιον καὶ τὸν τροπωτῆρα πεζῇ ἰέναι ἐκ Κορίνθου ἐπὶ τὴν πρὸς Ἀθήνας θάλασσαν καὶ ἀφικομένους κατὰ τάχος ἐς Μέγαρα καθελκύσαντας ἐκ Νισαίας τοῦ νεωρίου αὐτῶν τεσσαράκοντα ναῦς, αἳ ἔτυχον αὐτόθι οὖσαι, πλεῦσαι εὐθὺς ἐπὶ τὸν Πειραιᾶ· οὔτε γὰρ ναυτικὸν ἦν προφυλάσσον ἐν αὐτῷ οὐδὲν οὔτε προσδοκία οὐδεμία μὴ ἄν ποτε οἱ πολέμιοι ἐξαπιναίως οὕτως ἐπιπλεύσειαν, ἐπεὶ οὐδ’ ἀπὸ τοῦ προφανοῦς τολμῆσαι ἂν καθ’ ἡσυχίαν, οὐδ’ εἰ διενοοῦντο, μὴ οὐκ ἂν προαισθέσθαι. ὡς δὲ ἔδοξεν αὐτοῖς, καὶ ἐχώρουν εὐθύς· καὶ ἀφικόμενοι νυκτὸς καὶ καθελκύσαντες ἐκ τῆς Νισαίας τὰς ναῦς ἔπλεον ἐπὶ μὲν τὸν Πειραιᾶ οὐκέτι, ὥσπερ διενοοῦντο, καταδείσαντες τὸν κίνδυνον (καί τις καὶ ἄνεμος αὐτοὺς λέγεται κωλῦσαι), ἐπὶ δὲ τῆς Σαλαμῖνος τὸ ἀκρωτήριον τὸ πρὸς Μέγαρα ὁρῶν· καὶ φρούριον ἐπ’ αὐτοῦ ἦν καὶ νεῶν τριῶν φυλακὴ τοῦ μὴ ἐσπλεῖν Μεγαρεῦσι μηδὲ ἐκπλεῖν μηδέν. τῷ τε φρουρίῳ προσέβαλον καὶ τὰς τριήρεις ἀφείλκυσαν κενάς, τήν τε ἄλλην Σαλαμῖνα ἀπροσδοκήτοις ἐπιπεσόντες ἐπόρθουν.", "st": "2.93"}, {"sp": "N", "t": "ἐς δὲ τὰς Ἀθήνας φρυκτοί τε ᾔροντο πολέμιοι καὶ ἔκπληξις ἐγένετο οὐδεμιᾶς τῶν κατὰ τὸν πόλεμον ἐλάσσων. οἱ μὲν γὰρ ἐν τῷ ἄστει ἐς τὸν Πειραιᾶ ᾤοντο τοὺς πολεμίους ἐσπεπλευκέναι ἤδη, οἱ δ’ ἐν τῷ Πειραιεῖ τήν τε Σαλαμῖνα ᾑρῆσθαι καὶ παρὰ σφᾶς ὅσον οὐκ ἐσπλεῖν αὐτούς· ὅπερ ἄν, εἰ ἐβουλήθησαν μὴ κατοκνῆσαι, ῥᾳδίως ἐγένετο, καὶ οὐκ ἂν ἄνεμος ἐκώλυσεν. βοηθήσαντες δὲ ἅμ’ ἡμέρᾳ πανδημεὶ οἱ Ἀθηναῖοι ἐς τὸν Πειραιᾶ ναῦς τε καθεῖλκον καὶ ἐσβάντες κατὰ σπουδὴν καὶ πολλῷ θορύβῳ ταῖς μὲν ναυσὶν ἐπὶ τὴν Σαλαμῖνα ἔπλεον, τῷ πεζῷ δὲ φυλακὰς τοῦ Πειραιῶς καθίσταντο. οἱ δὲ Πελοποννήσιοι ὡς ᾔσθοντο τὴν βοήθειαν, καταδραμόντες τῆς Σαλαμῖνος τὰ πολλὰ καὶ ἀνθρώπους καὶ λείαν λαβόντες καὶ τὰς τρεῖς ναῦς ἐκ τοῦ Βουδόρου τοῦ φρουρίου κατὰ τάχος ἐπὶ τῆς Νισαίας ἀπέπλεον· ἔστι γὰρ ὅτι καὶ αἱ νῆες αὐτοὺς διὰ χρόνου καθελκυσθεῖσαι καὶ οὐδὲν στέγουσαι ἐφόβουν. ἀφικόμενοι δὲ ἐς τὰ Μέγαρα πάλιν ἐπὶ τῆς Κορίνθου ἀπεχώρησαν πεζῇ· οἱ δ’ Ἀθηναῖοι οὐκέτι καταλαβόντες πρὸς τῇ Σαλαμῖνι ἀπέπλευσαν καὶ αὐτοί, καὶ μετὰ τοῦτο φυλακὴν ἤδη τοῦ Πειραιῶς μᾶλλον τὸ λοιπὸν ἐποιοῦντο λιμένων τε κλῄσει καὶ τῇ ἄλλῃ ἐπιμελείᾳ.", "st": "2.94"}, {"sp": "N", "t": "ὑπὸ δὲ τοὺς αὐτοὺς χρόνους, τοῦ χειμῶνος τούτου ἀρχομένου, Σιτάλκης ὁ Τήρεω Ὀδρύσης Θρᾳκῶν βασιλεὺς ἐστράτευσεν ἐπὶ Περδίκκαν τὸν Ἀλεξάνδρου Μακεδονίας βασιλέα καὶ ἐπὶ Χαλκιδέας τοὺς ἐπὶ Θρᾴκης, δύο ὑποσχέσεις τὴν μὲν βουλόμενος ἀναπρᾶξαι, τὴν δὲ αὐτὸς ἀποδοῦναι. ὅ τε γὰρ Περδίκκας αὐτῷ ὑποσχόμενος, εἰ Ἀθηναίοις τε διαλλάξειεν ἑαυτὸν κατ’ ἀρχὰς τῷ πολέμῳ πιεζόμενον καὶ Φίλιππον τὸν ἀδελφὸν αὐτοῦ πολέμιον ὄντα μὴ καταγάγοι ἐπὶ βασιλείᾳ, ἃ ὑπεδέξατο οὐκ ἐπετέλει· τοῖς τε Ἀθηναίοις αὐτὸς ὡμολογήκει, ὅτε τὴν ξυμμαχίαν ἐποιεῖτο, τὸν ἐπὶ Θρᾴκης Χαλκιδικὸν πόλεμον καταλύσειν. ἀμφοτέρων οὖν ἕνεκα τὴν ἔφοδον ἐποιεῖτο καὶ τόν τε Φιλίππου υἱὸν Ἀμύνταν ὡς ἐπὶ βασιλείᾳ τῶν Μακεδόνων ἦγε καὶ τῶν Ἀθηναίων πρέσβεις, οἳ ἔτυχον παρόντες τούτων ἕνεκα, καὶ ἡγεμόνα Ἅγνωνα· ἔδει γὰρ καὶ τοὺς Ἀθηναίους ναυσί τε καὶ στρατιᾷ ὡς πλείστῃ ἐπὶ τοὺς Χαλκιδέας παραγενέσθαι.", "st": "2.95"}, {"sp": "N", "t": "ἀνίστησιν οὖν ἐκ τῶν Ὀδρυσῶν ὁρμώμενος πρῶτον μὲν τοὺς ἐντὸς τοῦ Αἵμου τε ὄρους καὶ τῆς Ῥοδόπης Θρᾷκας, ὅσων ἦρχε μέχρι θαλάσσης [ἐς τὸν Εὔξεινόν τε πόντον καὶ τὸν Ἑλλήσποντον], ἔπειτα τοὺς ὑπερβάντι Αἷμον Γέτας καὶ ὅσα ἄλλα μέρη ἐντὸς τοῦ Ἴστρου ποταμοῦ πρὸς θάλασσαν μᾶλλον τὴν τοῦ Εὐξείνου πόντου κατῴκητο· εἰσὶ δ’ οἱ Γέται καὶ οἱ ταύτῃ ὅμοροί τε τοῖς Σκύθαις καὶ ὁμόσκευοι, πάντες ἱπποτοξόται. παρεκάλει δὲ καὶ τῶν ὀρεινῶν Θρᾳκῶν πολλοὺς τῶν αὐτονόμων καὶ μαχαιροφόρων, οἳ Δῖοι καλοῦνται, τὴν Ῥοδόπην οἱ πλεῖστοι οἰκοῦντες· καὶ τοὺς μὲν μισθῷ ἔπειθεν, οἱ δ’ ἐθελονταὶ ξυνηκολούθουν. ἀνίστη δὲ καὶ Ἀγριᾶνας καὶ Λαιαίους καὶ ἄλλα ὅσα ἔθνη Παιονικὰ ὧν ἦρχε καὶ ἔσχατοι τῆς ἀρχῆς οὗτοι ἦσαν· μέχρι γὰρ Λαιαίων Παιόνων καὶ τοῦ Στρυμόνος ποταμοῦ, ὃς ἐκ τοῦ Σκόμβρου ὄρους δι’ Ἀγριάνων καὶ Λαιαίων ῥεῖ, [οὗ] ὡρίζετο ἡ ἀρχὴ τὰ πρὸς Παίονας αὐτονόμους ἤδη. τὰ δὲ πρὸς Τριβαλλούς, καὶ τούτους αὐτονόμους, Τρῆρες ὥριζον καὶ Τιλαταῖοι· οἰκοῦσι δ’ οὗτοι πρὸς βορέαν τοῦ Σκόμβρου ὄρους καὶ παρήκουσι πρὸς ἡλίου δύσιν μέχρι τοῦ Ὀσκίου ποταμοῦ. ῥεῖ δ’ οὗτος ἐκ τοῦ ὄρους ὅθενπερ καὶ ὁ Νέστος καὶ ὁ Ἕβρος· ἔστι δὲ ἐρῆμον τὸ ὄρος καὶ μέγα, ἐχόμενον τῆς Ῥοδόπης.", "st": "2.96"}, {"sp": "N", "t": "ἐγένετο δὲ ἡ ἀρχὴ ἡ Ὀδρυσῶν μέγεθος ἐπὶ μὲν θάλασσαν καθήκουσα ἀπὸ Ἀβδήρων πόλεως ἐς τὸν Εὔξεινον πόντον μέχρι Ἴστρου ποταμοῦ· αὕτη περίπλους ἐστὶν ἡ γῆ τὰ ξυντομώτατα, ἢν αἰεὶ κατὰ πρύμναν ἱστῆται τὸ πνεῦμα, νηὶ στρογγύλῃ τεσσάρων ἡμερῶν καὶ ἴσων νυκτῶν· ὁδῷ δὲ τὰ ξυντομώτατα ἐξ Ἀβδήρων ἐς Ἴστρον ἀνὴρ εὔζωνος ἑνδεκαταῖος τελεῖ. τὰ μὲν πρὸς θάλασσαν τοσαύτη ἦν, ἐς ἤπειρον δὲ ἀπὸ Βυζαντίου ἐς Λαιαίους καὶ ἐπὶ τὸν Στρυμόνα (ταύτῃ γὰρ διὰ πλείστου ἀπὸ θαλάσσης ἄνω ἐγίγνετο) ἡμερῶν ἀνδρὶ εὐζώνῳ τριῶν καὶ δέκα ἁνύσαι. φόρος τε ἐκ πάσης τῆς βαρβάρου καὶ τῶν Ἑλληνίδων πόλεων, ὅσον προσῆξαν ἐπὶ Σεύθου, ὃς ὕστερον Σιτάλκου βασιλεύσας πλεῖστον δὴ ἐποίησε, τετρακοσίων ταλάντων ἀργυρίου μάλιστα δύναμις, ἃ χρυσὸς καὶ ἄργυρος ᾔει· καὶ δῶρα οὐκ ἐλάσσω τούτων χρυσοῦ τε καὶ ἀργύρου προσεφέρετο, χωρὶς δὲ ὅσα ὑφαντά τε καὶ λεῖα καὶ ἡ ἄλλη κατασκευή, καὶ οὐ μόνον αὐτῷ, ἀλλὰ καὶ τοῖς παραδυναστεύουσί τε καὶ γενναίοις Ὀδρυσῶν. κατεστήσαντο γὰρ τοὐναντίον τῆς Περσῶν βασιλείας τὸν νόμον, ὄντα μὲν καὶ τοῖς ἄλλοις Θρᾳξί, λαμβάνειν μᾶλλον ἢ διδόναι (καὶ αἴσχιον ἦν αἰτηθέντα μὴ δοῦναι ἢ αἰτήσαντα μὴ τυχεῖν), ὅμως δὲ κατὰ τὸ δύνασθαι ἐπὶ πλέον αὐτῷ ἐχρήσαντο· οὐ γὰρ ἦν πρᾶξαι οὐδὲν μὴ διδόντα δῶρα. ὥστε ἐπὶ μέγα ἡ βασιλεία ἦλθεν ἰσχύος. τῶν γὰρ ἐν τῇ Εὐρώπῃ ὅσαι μεταξὺ τοῦ Ἰονίου κόλπου καὶ τοῦ Εὐξείνου πόντου μεγίστη ἐγένετο χρημάτων προσόδῳ καὶ τῇ ἄλλῃ εὐδαιμονίᾳ, ἰσχύι δὲ μάχης καὶ στρατοῦ πλήθει πολὺ δευτέρα μετὰ τὴν Σκυθῶν. ταύτῃ δὲ ἀδύνατα ἐξισοῦσθαι οὐχ ὅτι τὰ ἐν τῇ Εὐρώπῃ, ἀλλ’ οὐδ’ ἐν τῇ Ἀσίᾳ ἔθνος ἓν πρὸς ἓν οὐκ ἔστιν ὅτι δυνατὸν Σκύθαις ὁμογνωμονοῦσι πᾶσιν ἀντιστῆναι. οὐ μὴν οὐδ’ ἐς τὴν ἄλλην εὐβουλίαν καὶ ξύνεσιν περὶ τῶν παρόντων ἐς τὸν βίον ἄλλοις ὁμοιοῦνται.", "st": "2.97"}, {"sp": "N", "t": "Σιτάλκης μὲν οὖν χώρας τοσαύτης βασιλεύων παρεσκευάζετο τὸν στρατόν. καὶ ἐπειδὴ αὐτῷ ἑτοῖμα ἦν, ἄρας ἐπορεύετο ἐπὶ τὴν Μακεδονίαν πρῶτον μὲν διὰ τῆς αὑτοῦ ἀρχῆς, ἔπειτα διὰ Κερκίνης ἐρήμου ὄρους, ὅ ἐστι μεθόριον Σιντῶν καὶ Παιόνων· ἐπορεύετο δὲ δι’ αὐτοῦ τῇ ὁδῷ ἣν πρότερον αὐτὸς ἐποιήσατο τεμὼν τὴν ὕλην, ὅτε ἐπὶ Παίονας ἐστράτευσεν. τὸ δὲ ὄρος ἐξ Ὀδρυσῶν διιόντες ἐν δεξιᾷ μὲν εἶχον Παίονας, ἐν ἀριστερᾷ δὲ Σιντοὺς καὶ Μαιδούς. διελθόντες δὲ αὐτὸ ἀφίκοντο ἐς Δόβηρον τὴν Παιονικήν. πορευομένῳ δὲ αὐτῷ ἀπεγίγνετο μὲν οὐδὲν τοῦ στρατοῦ εἰ μή τι νόσῳ, προσεγίγνετο δέ· πολλοὶ γὰρ τῶν αὐτονόμων Θρᾳκῶν ἀπαράκλητοι ἐφ’ ἁρπαγὴν ἠκολούθουν, ὥστε τὸ πᾶν πλῆθος λέγεται οὐκ ἔλασσον πέντε καὶ δέκα μυριάδων γενέσθαι· καὶ τούτου τὸ μὲν πλέον πεζὸν ἦν, τριτημόριον δὲ μάλιστα ἱππικόν. τοῦ δ’ ἱππικοῦ τὸ πλεῖστον αὐτοὶ Ὀδρύσαι παρείχοντο καὶ μετ’ αὐτοὺς Γέται. τοῦ δὲ πεζοῦ οἱ μαχαιροφόροι μαχιμώτατοι μὲν ἦσαν οἱ ἐκ τῆς Ῥοδόπης αὐτόνομοι καταβάντες, ὁ δὲ ἄλλος ὅμιλος ξύμμεικτος πλήθει φοβερώτατος ἠκολούθει.", "st": "2.98"}, {"sp": "N", "t": "ξυνηθροίζοντο οὖν ἐν τῇ Δοβήρῳ καὶ παρεσκευάζοντο, ὅπως κατὰ κορυφὴν ἐσβαλοῦσιν ἐς τὴν κάτω Μακεδονίαν, ἧς ὁ Περδίκκας ἦρχεν. τῶν γὰρ Μακεδόνων εἰσὶ καὶ Λυγκησταὶ καὶ Ἐλιμιῶται καὶ ἄλλα ἔθνη ἐπάνωθεν, ἃ ξύμμαχα μέν ἐστι τούτοις καὶ ὑπήκοα, βασιλείας δ’ ἔχει καθ’ αὑτά. τὴν δὲ παρὰ θάλασσαν νῦν Μακεδονίαν Ἀλέξανδρος ὁ Περδίκκου πατὴρ καὶ οἱ πρόγονοι αὐτοῦ, Τημενίδαι τὸ ἀρχαῖον ὄντες ἐξ Ἄργους, πρῶτοι ἐκτήσαντο καὶ ἐβασίλευσαν ἀναστήσαντες μάχῃ ἐκ μὲν Πιερίας Πίερας, οἳ ὕστερον ὑπὸ τὸ Πάγγαιον πέραν Στρυμόνος ᾤκησαν Φάγρητα καὶ ἄλλα χωρία (καὶ ἔτι καὶ νῦν Πιερικὸς κόλπος καλεῖται ἡ ὑπὸ τῷ Παγγαίῳ πρὸς θάλασσαν γῆ), ἐκ δὲ τῆς Βοττίας καλουμένης Βοττιαίους, οἳ νῦν ὅμοροι Χαλκιδέων οἰκοῦσιν· τῆς δὲ Παιονίας παρὰ τὸν Ἀξιὸν ποταμὸν στενήν τινα καθήκουσαν ἄνωθεν μέχρι Πέλλης καὶ θαλάσσης ἐκτήσαντο, καὶ πέραν Ἀξιοῦ μέχρι Στρυμόνος τὴν Μυγδονίαν καλουμένην Ἠδῶνας ἐξελάσαντες νέμονται. ἀνέστησαν δὲ καὶ ἐκ τῆς νῦν Ἐορδίας καλουμένης Ἐορδούς, ὧν οἱ μὲν πολλοὶ ἐφθάρησαν, βραχὺ δέ τι αὐτῶν περὶ Φύσκαν κατῴκηται, καὶ ἐξ Ἀλμωπίας Ἄλμωπας. ἐκράτησαν δὲ καὶ τῶν ἄλλων ἐθνῶν οἱ Μακεδόνες οὗτοι, ἃ καὶ νῦν ἔτι ἔχουσι, τόν τε Ἀνθεμοῦντα καὶ Κρηστωνίαν καὶ Βισαλτίαν καὶ Μακεδόνων αὐτῶν πολλήν. τὸ δὲ ξύμπαν Μακεδονία καλεῖται, καὶ Περδίκκας Ἀλεξάνδρου βασιλεὺς αὐτῶν ἦν ὅτε Σιτάλκης ἐπῄει.", "st": "2.99"}, {"sp": "N", "t": "καὶ οἱ μὲν Μακεδόνες οὗτοι ἐπιόντος πολλοῦ στρατοῦ ἀδύνατοι ὄντες ἀμύνεσθαι ἔς τε τὰ καρτερὰ καὶ τὰ τείχη, ὅσα ἦν ἐν τῇ χώρᾳ, ἐσεκομίσθησαν. ἦν δὲ οὐ πολλά, ἀλλὰ ὕστερον Ἀρχέλαος ὁ Περδίκκου υἱὸς βασιλεὺς γενόμενος τὰ νῦν ὄντα ἐν τῇ χώρᾳ ᾠκοδόμησε καὶ ὁδοὺς εὐθείας ἔτεμε καὶ τἆλλα διεκόσμησε τά [τε] κατὰ τὸν πόλεμον ἵπποις καὶ ὅπλοις καὶ τῇ ἄλλῃ παρασκευῇ κρείσσονι ἢ ξύμπαντες οἱ ἄλλοι βασιλῆς ὀκτὼ οἱ πρὸ αὐτοῦ γενόμενοι. ὁ δὲ στρατὸς τῶν Θρᾳκῶν ἐκ τῆς Δοβήρου ἐσέβαλε πρῶτον μὲν ἐς τὴν Φιλίππου πρότερον οὖσαν ἀρχήν, καὶ εἷλεν Εἰδομενὴν μὲν κατὰ κράτος, Γορτυνίαν δὲ καὶ Ἀταλάντην καὶ ἄλλα ἄττα χωρία ὁμολογίᾳ διὰ τὴν Ἀμύντου φιλίαν προσχωροῦντα τοῦ Φιλίππου υἱέος παρόντος· Εὐρωπὸν δὲ ἐπολιόρκησαν μέν, ἑλεῖν δὲ οὐκ ἐδύναντο. ἔπειτα δὲ καὶ ἐς τὴν ἄλλην Μακεδονίαν προυχώρει τὴν ἐν ἀριστερᾷ Πέλλης καὶ Κύρρου. ἔσω δὲ τούτων ἐς τὴν Βοττιαίαν καὶ Πιερίαν οὐκ ἀφίκοντο, ἀλλὰ τήν τε Μυγδονίαν καὶ Κρηστωνίαν καὶ Ἀνθεμοῦντα ἐδῄουν. οἱ δὲ Μακεδόνες πεζῷ μὲν οὐδὲ διενοοῦντο ἀμύνεσθαι, ἵππους δὲ προσμεταπεμψάμενοι ἀπὸ τῶν ἄνω ξυμμάχων, ὅπῃ δοκοίη, ὀλίγοι πρὸς πολλοὺς ἐσέβαλλον ἐς τὸ στράτευμα τῶν Θρᾳκῶν. καὶ ᾗ μὲν προσπέσοιεν, οὐδεὶς ὑπέμενεν ἄνδρας ἱππέας τε ἀγαθοὺς καὶ τεθωρακισμένους, ὑπὸ δὲ πλήθους περικλῃόμενοι αὑτοὺς πολλαπλασίῳ τῷ ὁμίλῳ ἐς κίνδυνον καθίστασαν, ὥστε τέλος ἡσυχίαν ἦγον, οὐ νομίζοντες ἱκανοὶ εἶναι πρὸς τὸ πλέον κινδυνεύειν.", "st": "2.100"}, {"sp": "N", "t": "ὁ δὲ Σιτάλκης πρός τε τὸν Περδίκκαν λόγους ἐποιεῖτο ὧν ἕνεκα ἐστράτευσε, καὶ ἐπειδὴ οἱ Ἀθηναῖοι οὐ παρῆσαν ταῖς ναυσίν, ἀπιστοῦντες αὐτὸν μὴ ἥξειν, δῶρα δὲ καὶ πρέσβεις ἔπεμψαν αὐτῷ, ἔς τε τοὺς Χαλκιδέας καὶ Βοττιαίους μέρος τι τοῦ στρατοῦ πέμπει, καὶ τειχήρεις ποιήσας ἐδῄου τὴν γῆν. καθημένου δ’ αὐτοῦ περὶ τοὺς χώρους τούτους οἱ πρὸς νότον οἰκοῦντες Θεσσαλοὶ καὶ Μάγνητες καὶ οἱ ἄλλοι ὑπήκοοι Θεσσαλῶν καὶ οἱ μέχρι Θερμοπυλῶν Ἕλληνες ἐφοβήθησαν μὴ καὶ ἐπὶ σφᾶς ὁ στρατὸς χωρήσῃ, καὶ ἐν παρασκευῇ ἦσαν. ἐφοβήθησαν δὲ καὶ οἱ πέραν Στρυμόνος πρὸς βορέαν Θρᾷκες, ὅσοι πεδία εἶχον, Παναῖοι καὶ Ὀδόμαντοι καὶ Δρῶοι καὶ Δερσαῖοι· αὐτόνομοι δ’ εἰσὶ πάντες. παρέσχε δὲ λόγον καὶ ἐπὶ τοὺς τῶν Ἀθηναίων πολεμίους Ἕλληνας, μὴ ὑπ’ αὐτῶν ἀγόμενοι κατὰ τὸ ξυμμαχικὸν καὶ ἐπὶ σφᾶς χωρήσωσιν. ὁ δὲ τήν τε Χαλκιδικὴν καὶ Βοττικὴν καὶ Μακεδονίαν ἅμα ἐπέχων ἔφθειρε, καὶ ἐπειδὴ αὐτῷ οὐδὲν ἐπράσσετο ὧν ἕνεκα ἐσέβαλε καὶ ἡ στρατιὰ σῖτόν τε οὐκ εἶχεν αὐτῷ καὶ ὑπὸ χειμῶνος ἐταλαιπώρει, ἀναπείθεται ὑπὸ Σεύθου τοῦ Σπαραδόκου, ἀδελφιδοῦ ὄντος καὶ μέγιστον μεθ’ ἑαυτὸν δυναμένου, ὥστ’ ἐν τάχει ἀπελθεῖν. τὸν δὲ Σεύθην κρύφα Περδίκκας ὑποσχόμενος ἀδελφὴν ἑαυτοῦ δώσειν καὶ χρήματα ἐπ’ αὐτῇ προσποιεῖται. καὶ ὁ μὲν πεισθεὶς καὶ μείνας τριάκοντα τὰς πάσας ἡμέρας, τούτων δὲ ὀκτὼ ἐν Χαλκιδεῦσιν, ἀνεχώρησε τῷ στρατῷ κατὰ τάχος ἐπ’ οἴκου· Περδίκκας δὲ ὕστερον Στρατονίκην τὴν ἑαυτοῦ ἀδελφὴν δίδωσι Σεύθῃ, ὥσπερ ὑπέσχετο. τὰ μὲν οὖν κατὰ τὴν Σιτάλκου στρατείαν οὕτως ἐγένετο.", "st": "2.101"}, {"sp": "N", "t": "οἱ δὲ ἐν Ναυπάκτῳ Ἀθηναῖοι τοῦ αὐτοῦ χειμῶνος, ἐπειδὴ τὸ τῶν Πελοποννησίων ναυτικὸν διελύθη, Φορμίωνος ἡγουμένου ἐστράτευσαν, παραπλεύσαντες ἐπ’ Ἀστακοῦ καὶ ἀποβάντες, ἐς τὴν μεσόγειαν τῆς Ἀκαρνανίας τετρακοσίοις μὲν ὁπλίταις Ἀθηναίων τῶν ἀπὸ τῶν νεῶν, τετρακοσίοις δὲ Μεσσηνίων, καὶ ἔκ τε Στράτου καὶ Κορόντων καὶ ἄλλων χωρίων ἄνδρας οὐ δοκοῦντας βεβαίους εἶναι ἐξήλασαν, καὶ Κύνητα τὸν Θεολύτου ἐς Κόροντα καταγαγόντες ἀνεχώρησαν πάλιν ἐπὶ τὰς ναῦς. ἐς γὰρ Οἰνιάδας αἰεί ποτε πολεμίους ὄντας μόνους Ἀκαρνάνων οὐκ ἐδόκει δυνατὸν εἶναι χειμῶνος ὄντος στρατεύειν· ὁ γὰρ Ἀχελῷος ποταμὸς ῥέων ἐκ Πίνδου ὄρους διὰ Δολοπίας καὶ Ἀγραίων καὶ Ἀμφιλόχων καὶ διὰ τοῦ Ἀκαρνανικοῦ πεδίου, ἄνωθεν μὲν παρὰ Στράτον πόλιν, ἐς θάλασσαν δ’ ἐξιεὶς παρ’ Οἰνιάδας καὶ τὴν πόλιν αὐτοῖς περιλιμνάζων, ἄπορον ποιεῖ ὑπὸ τοῦ ὕδατος ἐν χειμῶνι στρατεύειν. κεῖνται δὲ καὶ τῶν νήσων τῶν Ἐχινάδων αἱ πολλαὶ καταντικρὺ Οἰνιαδῶν τοῦ Ἀχελῴου τῶν ἐκβολῶν οὐδὲν ἀπέχουσαι, ὥστε μέγας ὢν ὁ ποταμὸς προσχοῖ αἰεὶ καὶ εἰσὶ τῶν νήσων αἳ ἠπείρωνται, ἐλπὶς δὲ καὶ πάσας οὐκ ἐν πολλῷ τινὶ ἂν χρόνῳ τοῦτο παθεῖν· τό τε γὰρ ῥεῦμά ἐστι μέγα καὶ πολὺ καὶ θολερόν, αἵ τε νῆσοι πυκναί, καὶ ἀλλήλαις τῆς προσχώσεως [τῷ μὴ σκεδάννυσθαι] ξύνδεσμοι γίγνονται, παραλλὰξ καὶ οὐ κατὰ στοῖχον κείμεναι, οὐδ’ ἔχουσαι εὐθείας διόδους τοῦ ὕδατος ἐς τὸ πέλαγος. ἐρῆμοι δ’ εἰσὶ καὶ οὐ μεγάλαι. λέγεται δὲ καὶ Ἀλκμέωνι τῷ Ἀμφιάρεω, ὅτε δὴ ἀλᾶσθαι αὐτὸν μετὰ τὸν φόνον τῆς μητρός, τὸν Ἀπόλλω ταύτην τὴν γῆν χρῆσαι οἰκεῖν, ὑπειπόντα οὐκ εἶναι λύσιν τῶν δειμάτων πρὶν ἂν εὑρὼν ἐν ταύτῃ τῇ χώρᾳ κατοικίσηται ἥτις ὅτε ἔκτεινε τὴν μητέρα μήπω ὑπὸ ἡλίου ἑωρᾶτο μηδὲ γῆ ἦν, ὡς τῆς γε ἄλλης αὐτῷ μεμιασμένης. ὁ δ’ ἀπορῶν, ὥς φασι, μόλις κατενόησε τὴν πρόσχωσιν ταύτην τοῦ Ἀχελῴου, καὶ ἐδόκει αὐτῷ ἱκανὴ ἂν κεχῶσθαι δίαιτα τῷ σώματι ἀφ’ οὗπερ κτείνας τὴν μητέρα οὐκ ὀλίγον χρόνον ἐπλανᾶτο. καὶ κατοικισθεὶς ἐς τοὺς περὶ Οἰνιάδας τόπους ἐδυνάστευσέ τε καὶ ἀπὸ Ἀκαρνᾶνος παιδὸς ἑαυτοῦ τῆς χώρας τὴν ἐπωνυμίαν ἐγκατέλιπεν. τὰ μὲν περὶ Ἀλκμέωνα τοιαῦτα λεγόμενα παρελάβομεν.", "st": "2.102"}, {"sp": "N", "t": "οἱ δὲ Ἀθηναῖοι καὶ ὁ Φορμίων ἄραντες ἐκ τῆς Ἀκαρνανίας καὶ ἀφικόμενοι ἐς τὴν Ναύπακτον ἅμα ἦρι κατέπλευσαν ἐς τὰς Ἀθήνας, τούς τε ἐλευθέρους τῶν αἰχμαλώτων ἐκ τῶν ναυμαχιῶν ἄγοντες, οἳ ἀνὴρ ἀντ’ ἀνδρὸς ἐλύθησαν, καὶ τὰς ναῦς ἃς εἷλον. καὶ ὁ χειμὼν ἐτελεύτα οὗτος, καὶ τρίτον ἔτος τῷ πολέμῳ ἐτελεύτα τῷδε ὃν Θουκυδίδης ξυνέγραψεν.", "st": "2.103"}], []);})();
